// Runtime data dirs (plugins, mcp-configs) live under the user profile, not the
// repo. The repo only ships built-in plugin seeds in builtin-plugins/.
const SUPERVISOR_DATA_DIR = ConfigSync.SUPERVISOR_DATA_DIR;
const PLUGINS_DIR = ConfigSync.PLUGINS_DIR;
const MCP_CONFIGS_DIR = ConfigSync.MCP_CONFIGS_DIR;
const BUILTIN_PLUGINS_DIR = path.join(__dirname, 'builtin-plugins');

// One-time migration: move any legacy in-repo runtime dirs into the profile store.
(function migrateRuntimeDirs() {
  for (const dirName of ['plugins', 'mcp-configs']) {
    const legacyDir = path.join(__dirname, dirName);
    const targetDir = path.join(SUPERVISOR_DATA_DIR, dirName);
    if (!fs.existsSync(legacyDir)) continue;
    try {
      fs.mkdirSync(targetDir, { recursive: true });
      for (const entry of fs.readdirSync(legacyDir, { withFileTypes: true })) {
        // Do not migrate the retired manager plugin into the runtime store.
        if (dirName === 'plugins' && entry.name === 'manager') continue;
        const dest = path.join(targetDir, entry.name);
        if (fs.existsSync(dest)) continue; // don't clobber existing runtime data
        fs.cpSync(path.join(legacyDir, entry.name), dest, { recursive: true });
      }
      console.log(`[supervisor] Migrated legacy ${dirName}/ into runtime store`);
    } catch (e) {
      console.warn(`[supervisor] Could not migrate ${dirName}/:`, e.message);
    }
  }
})();

const upload = multer({ dest: path.join(require('os').tmpdir(), 'agent-supervisor-uploads') });

// Default to the well-known 3847 so browser users keep their bookmark. The
// desktop shell pins PORT to a stable app port (3848) so the WebView origin —
// and every localStorage-backed preference — survives restarts/upgrades; if
// that port is busy the sidecar retries then falls back to an ephemeral port
// (see bindPort below). Set PORT=0 to force an OS-assigned port. The
// actually-bound port is resolved after listen() into RESOLVED_PORT.
const PORT = (process.env.PORT !== undefined && process.env.PORT !== '')
  ? Number(process.env.PORT)
  : 3847;
// Listen interface. Defaults to all interfaces (undefined) so the LAN/mobile
// (QR-code) flow keeps working. A host shell can pin it to loopback with
// SUPERVISOR_HOST=127.0.0.1.
const HOST = process.env.SUPERVISOR_HOST || undefined;
// The port we actually bound to. Equals PORT unless PORT=0. Anything that builds
// a URL/base must read getPort() so it reflects the real port in sidecar mode.
let RESOLVED_PORT = PORT;
function getPort() { return RESOLVED_PORT; }
const DB_PATH = dataPath('supervisor.db');
const AGENTS_PATH = dataPath('agents.json');
const TASKS_PATH = dataPath('tasks.json');
const TEAMS_PATH = dataPath('teams.json');
const LEGACY_ORGANIZATIONS_PATH = dataPath('organizations.json');
const BOARDS_PATH = dataPath('boards.json');
const INSIGHTS_PATH = dataPath('insights.json');
const CODEFLOW_PATH = dataPath('codeflow-repos.json');
const CODEFLOW_WT_PATH = dataPath('codeflow-worktrees.json');

// Ensure tasks.json exists
if (!fs.existsSync(TASKS_PATH)) {
  fs.writeFileSync(TASKS_PATH, '[]');
}

// Ensure agents.json exists (it no longer ships in the repo — it is per-user
// runtime data under the profile dir). loadAgents()/fs.watch read it unguarded.
if (!fs.existsSync(AGENTS_PATH)) {
  fs.writeFileSync(AGENTS_PATH, '[]');
}

// One-time migration: "Organizations" were renamed to "Teams". Rename the data
// file and normalize the per-operation scope key orgId -> teamId across
// persisted runtime files. Reads remain
// backward-compatible (teamId ?? orgId) so any unswept/cloud-synced file still works.
(function migrateOrgsToTeams() {
  try {
    if (!fs.existsSync(TEAMS_PATH)) {
      if (fs.existsSync(LEGACY_ORGANIZATIONS_PATH)) {
        fs.copyFileSync(LEGACY_ORGANIZATIONS_PATH, TEAMS_PATH);
        console.log('[migrate] organizations.json -> teams.json');
      } else {
        fs.writeFileSync(TEAMS_PATH, '[]');
      }
    }
    const sweepKey = (file, fn) => {
      try {
        const p = dataPath(file);
        if (!fs.existsSync(p)) return;
        const data = JSON.parse(fs.readFileSync(p, 'utf-8'));
        if (!Array.isArray(data)) return;
        let changed = false;
        for (const row of data) if (fn(row)) changed = true;
        if (changed) fs.writeFileSync(p, JSON.stringify(data, null, 2));
      } catch (e) { console.warn(`[migrate] ${file} skipped:`, e.message); }
    };
    const moveOrgId = (o) => {
      if (o && typeof o === 'object' && o.orgId !== undefined && o.teamId === undefined) {
        o.teamId = o.orgId; delete o.orgId; return true;
      }
      return false;
    };
    sweepKey('tasks.json', moveOrgId);
    sweepKey('chains.json', moveOrgId);
    sweepKey('boards.json', moveOrgId);
  } catch (e) { console.warn('[migrate] orgs->teams failed:', e.message); }
})();

function loadTeams() {
  try {
    if (!fs.existsSync(TEAMS_PATH)) return [];
    const teams = JSON.parse(fs.readFileSync(TEAMS_PATH, 'utf-8'));
    return Array.isArray(teams) ? teams : [];
  } catch { return []; }
}

function saveTeams(teams) {
  fs.writeFileSync(TEAMS_PATH, JSON.stringify(teams || [], null, 2));
}

function loadBoards() {
  try {
    if (!fs.existsSync(BOARDS_PATH)) return [];
    const boards = JSON.parse(fs.readFileSync(BOARDS_PATH, 'utf-8'));
    return Array.isArray(boards) ? boards : [];
  } catch { return []; }
}

function saveBoards(boards) {
  fs.writeFileSync(BOARDS_PATH, JSON.stringify(boards || [], null, 2));
}

// One-time, idempotent import of every board's devItems[] into the global
// dev-card store (dev-store.js). READ-ONLY against boards — the raw b.devItems is
// kept as a backup while `_normalizeBoard` projects the store into each board, so
// the SPA render path is unchanged. Safe to run on every boot.
try {
  const r = devStore.migrateFromBoards(loadBoards);
  if (r && r.imported) console.log(`[dev-store] imported ${r.imported} dev card(s) from boards`);
} catch (e) { console.warn('[dev-store] boards migration failed:', e && e.message); }

// One-time, idempotent split of legacy multi-repo dev cards into one-repo-per-card.
// Dev cards are now strictly single-repo. Any card that still carries extra repos in
// d.repos[] is split: each extra repo becomes its OWN new single-repo dev card (same
// work item / title / team / home board, that slot's PR + worktree + tagged reports
// moved over) and the original keeps only its primary repo (its id is preserved so its
// board pins + worktree/PR/work-item links stay intact). Board-map dev pins (b.items,
// kind:'dev') that referenced the original are duplicated for each new card so nothing
// that was on a board disappears. Once no card has d.repos this is a no-op.
function splitMultiRepoDevCards() {
  let cards = [];
  try { cards = devStore.all() || []; } catch { return { split: 0, created: 0 }; }
  const multi = cards.filter(d => d && Array.isArray(d.repos) && d.repos.length);
  if (!multi.length) return { split: 0, created: 0 };
  let created = 0;
  const newByOrig = {}; // origId -> { newIds:[], title, org, repo }
  const _reportsFor = (d, slot) => (Array.isArray(d.reports) ? d.reports : []).filter(r => {
    if (!r) return false;
    if (slot.id && r.repoId) return r.repoId === slot.id;
    return r.repo && slot.repo && String(r.repo).toLowerCase() === String(slot.repo).toLowerCase();
  });
  for (const d of multi) {
    const extras = (Array.isArray(d.repos) ? d.repos : []).filter(s => s && s.repo);
    const newIds = [];
    for (const slot of extras) {
      const nc = devStore.create({
        title: d.title || slot.repo,
        provider: slot.provider || d.provider || 'azdo',
        org: slot.org || '', project: slot.project || '', repo: slot.repo || '',
        branch: slot.branch || '', baseBranch: slot.baseBranch || '',
        prId: slot.prId || '', pr: slot.pr || null,
        worktreePath: slot.worktreePath || '', worktreeStatus: slot.worktreeStatus || null,
        worktreeError: slot.worktreeError || null, git: slot.git || null,
        devAgentName: slot.agentName || slot.devAgentName || '',
        workItemId: d.workItemId || '', workItem: d.workItem || null,
        teamId: d.teamId !== undefined ? d.teamId : null,
        homeBoardId: d.homeBoardId || null,
        notes: '', links: [], summary: null,
        reports: _reportsFor(d, slot).map(r => ({ ...r, repoId: 'primary' })),
      });
      if (nc && nc.id) { newIds.push(nc.id); created++; }
    }
    // Original keeps only its primary repo + primary-tagged reports.
    const keepReports = (Array.isArray(d.reports) ? d.reports : []).filter(r => !r || !r.repoId || r.repoId === 'primary');
    devStore.patch(d.id, { repos: [], reports: keepReports });
    if (newIds.length) newByOrig[d.id] = { newIds, title: d.title || d.repo || 'Dev card' };
  }
  // Duplicate board-map dev pins for each new card.
  const origIds = Object.keys(newByOrig);
  if (origIds.length) {
    let boards = [];
    try { boards = loadBoards(); } catch { boards = []; }
    let touched = false;
    for (const b of boards) {
      if (!b || !Array.isArray(b.items)) continue;
      const additions = [];
      for (const it of b.items) {
        if (!it || it.kind !== 'dev' || !newByOrig[it.refId]) continue;
        for (const nid of newByOrig[it.refId].newIds) {
          if (b.items.some(x => x && x.kind === 'dev' && x.refId === nid)) continue;
          if (additions.some(x => x.refId === nid)) continue;
          additions.push({ id: _genId('pin'), kind: 'dev', refId: nid, label: newByOrig[it.refId].title, sublabel: '', addedAt: new Date().toISOString() });
        }
      }
      if (additions.length) { b.items = additions.concat(b.items); b.updatedAt = new Date().toISOString(); touched = true; }
    }
    if (touched) { try { saveBoards(boards); } catch {} }
  }
  return { split: multi.length, created };
}
try {
  const s = splitMultiRepoDevCards();
  if (s && s.split) console.log(`[dev-store] split ${s.split} multi-repo dev card(s) into ${s.created} single-repo card(s)`);
} catch (e) { console.warn('[dev-store] multi-repo split failed:', e && e.message); }

function loadInsights() {
  try {
    if (!fs.existsSync(INSIGHTS_PATH)) return [];
    const v = JSON.parse(fs.readFileSync(INSIGHTS_PATH, 'utf-8'));
    return Array.isArray(v) ? v : [];
  } catch { return []; }
}

function saveInsights(insights) {
  fs.writeFileSync(INSIGHTS_PATH, JSON.stringify(insights || [], null, 2));
}

// Code Flow: the list of Azure DevOps repos the user has chosen to monitor.
// Each entry: { id, provider?, org, project, repo, repoId?, addedAt }.
// provider defaults to 'azdo' when absent (back-compat — no migration).
function loadCodeflowRepos() {
  try {
    if (!fs.existsSync(CODEFLOW_PATH)) return [];
    const v = JSON.parse(fs.readFileSync(CODEFLOW_PATH, 'utf-8'));
    if (!Array.isArray(v)) return [];
    return v.map(r => ({ ...r, provider: providerOf(r) }));
  } catch { return []; }
}

function saveCodeflowRepos(repos) {
  fs.writeFileSync(CODEFLOW_PATH, JSON.stringify(repos || [], null, 2));
}

// Code Flow: per-PR review worktree records. A map keyed by
// prKey = `${org}|${project}|${repo}|${prId}` (lowercased). Each value:
// { org, project, repo, prId, prTitle, worktreePath, branch, baseBranch,
//   reviewAgentName, reviewAgentFile, reports[], worktreeStatus, error, ... }.
// Lives under the profile DATA_DIR — never inside the repo, never committed.
function _cfWtKey(o) {
  // AzDo keys stay byte-identical (no prefix) so existing on-disk records never
  // orphan; GitHub is namespaced (project slot is empty for GitHub).
  const base = `${o.org}|${o.project || ''}|${o.repo}|${o.prId}`.toLowerCase();
  return String(o.provider || 'azdo').toLowerCase() === 'github' ? `github|${base}` : base;
}
// Provider-aware presence guard for the Code Flow PR handlers. AzDo needs a
// project; GitHub stores the owner in `org` and leaves `project` empty.
function _cfPrOk(o) {
  if (!o || !o.org || !o.repo || !o.prId) return false;
  if (String(o.provider || 'azdo').toLowerCase() === 'github') return true;
  return !!o.project;
}
function loadCodeflowWorktrees() {
  try {
    if (!fs.existsSync(CODEFLOW_WT_PATH)) return {};
    const v = JSON.parse(fs.readFileSync(CODEFLOW_WT_PATH, 'utf-8'));
    return (v && typeof v === 'object') ? v : {};
  } catch { return {}; }
}
function saveCodeflowWorktrees(map) {
  fs.writeFileSync(CODEFLOW_WT_PATH, JSON.stringify(map || {}, null, 2));
}
function _getCfWt(key) {
  const map = loadCodeflowWorktrees();
  return map[key] || null;
}
// Merge a partial update into a record (read-modify-write so concurrent
// background work doesn't clobber the whole map).
function _saveCfWt(key, partial) {
  const map = loadCodeflowWorktrees();
  map[key] = Object.assign({}, map[key] || {}, partial, { updatedAt: new Date().toISOString() });
  saveCodeflowWorktrees(map);
  return map[key];
}
function _deleteCfWt(key) {
  const map = loadCodeflowWorktrees();
  if (map[key]) { delete map[key]; saveCodeflowWorktrees(map); }
}

// --- Stale review-agent reconciliation ------------------------------------
// A PR's review/steward run persists reviewStatus:'reviewing' BEFORE the async
// job starts, and only the SAME process that launched it can flip that to
// done/error when it finishes. So a server restart (or an SDK run that hangs or
// dies) orphans the record at 'reviewing' forever — the Code Flow card shows a
// permanent "Running…" with no escape but Recreate. We track live in-process
// runs and reconcile anything that can't possibly still be running: at boot the
// live set is empty so every 'reviewing' is by definition orphaned, and during
// the process a run that blows a generous hard cap is treated as hung.
const _cfActiveReviews = new Set();            // wt keys with a run live in THIS process
const CF_REVIEW_MAX_MS = 60 * 60 * 1000;       // hard cap: 60 min even if flagged active
// A plain "Create worktree" (no review) also persists worktreeStatus:'creating'
// BEFORE its fire-and-forget clone starts, with no reviewStatus alongside it. That
// clone can't survive a restart either, so track live creates the same way we track
// live reviews — at boot the set is empty, so any 'creating' record is by definition
// orphaned and must be unstuck (the card is otherwise pinned on "Creating worktree…"
// forever with no way to recover).
const _cfActiveWorktrees = new Set();          // wt keys with a create live in THIS process
const CF_WORKTREE_MAX_MS = 20 * 60 * 1000;     // hard cap: 20 min even if flagged active
function _reconcileStaleReviews() {
  let map;
  try { map = loadCodeflowWorktrees(); } catch { return false; }
  const now = Date.now();
  let changed = false;
  for (const k of Object.keys(map)) {
    const r = map[k];
    if (!r) continue;
    const patch = {};
    // (1) Orphaned review: persisted 'reviewing' but not live here (or blew the cap).
    if (r.reviewStatus === 'reviewing') {
      let orphaned = true;
      if (_cfActiveReviews.has(k)) {
        const started = Date.parse(r.reviewStartedAt || r.updatedAt || '') || 0;
        if (started && (now - started) < CF_REVIEW_MAX_MS) orphaned = false;
      }
      if (orphaned) {
        patch.reviewStatus = 'error';
        patch.reviewError = 'The review didn’t finish — it was interrupted (server restart) or timed out. Run it again.';
        patch.reviewFinishedAt = new Date().toISOString();
        // A worktree caught mid-create alongside the orphaned review is untrustworthy too.
        if (r.worktreeStatus === 'creating') { patch.worktreeStatus = 'error'; patch.error = r.error || 'Worktree creation was interrupted.'; }
      }
    }
    // (2) Orphaned standalone create: 'creating' with no live create in this process
    //     (independent of any review — the plain "Create worktree" path). Guard against
    //     a live review that is legitimately mid-clone (tracked in _cfActiveReviews).
    if (patch.worktreeStatus !== 'error' && r.worktreeStatus === 'creating') {
      let orphaned = true;
      if (_cfActiveWorktrees.has(k)) {
        const started = Date.parse(r.worktreeStartedAt || r.updatedAt || '') || 0;
        if (started && (now - started) < CF_WORKTREE_MAX_MS) orphaned = false;
      }
      if (orphaned && _cfActiveReviews.has(k)) {
        const started = Date.parse(r.reviewStartedAt || r.updatedAt || '') || 0;
        if (started && (now - started) < CF_REVIEW_MAX_MS) orphaned = false;
      }
      if (orphaned) { patch.worktreeStatus = 'error'; patch.error = r.error || 'Worktree creation was interrupted — it was cut off by a server restart or timed out. Retry it.'; }
    }
    if (Object.keys(patch).length) {
      patch.updatedAt = new Date().toISOString();
      map[k] = Object.assign({}, r, patch);
      changed = true;
    }
  }
  if (changed) { try { saveCodeflowWorktrees(map); } catch { return false; } }
  return changed;
}

// Code Flow: per-PR freeform notes. A map keyed by the same prKey as worktrees
// (_cfWtKey) → an array of { id, text, done, createdAt, updatedAt }. Lets you jot
// down where you're at / what matters on a PR, independent of the live provider
// data (which is fetched fresh + cached, so it can't hold user annotations).
const CODEFLOW_NOTES_PATH = dataPath('codeflow-pr-notes.json');
function loadCodeflowNotes() {
  try {
    if (!fs.existsSync(CODEFLOW_NOTES_PATH)) return {};
    const v = JSON.parse(fs.readFileSync(CODEFLOW_NOTES_PATH, 'utf-8'));
    return (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
  } catch { return {}; }
}
function saveCodeflowNotes(map) {
  fs.writeFileSync(CODEFLOW_NOTES_PATH, JSON.stringify(map || {}, null, 2));
}
function _getCfNotes(key) {
  const map = loadCodeflowNotes();
  return Array.isArray(map[key]) ? map[key] : [];
}
// Dismissed PRs ("Other PRs"): PRs the user isn't going to review but wants to
// retain access to. Keyed by _cfWtKey so it survives across fetches/providers.
// Stored as a map key -> { at, title } so the Other PRs page can render even a PR
// that has since dropped out of the normal active/reviews fetch.
const CODEFLOW_DISMISSED_PATH = dataPath('codeflow-dismissed-prs.json');
function loadCodeflowDismissed() {
  try {
    if (!fs.existsSync(CODEFLOW_DISMISSED_PATH)) return {};
    const v = JSON.parse(fs.readFileSync(CODEFLOW_DISMISSED_PATH, 'utf-8'));
    return (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
  } catch { return {}; }
}
function saveCodeflowDismissed(map) {
  fs.writeFileSync(CODEFLOW_DISMISSED_PATH, JSON.stringify(map || {}, null, 2));
}
// Read-modify-write the notes array for one PR. `fn` receives the current array
// (a copy) and returns the next array. Empty arrays are pruned to keep the map lean.
function _mutateCfNotes(key, fn) {
  const map = loadCodeflowNotes();
  const cur = Array.isArray(map[key]) ? map[key].slice() : [];
  const next = fn(cur) || [];
  if (next.length) map[key] = next; else delete map[key];
  saveCodeflowNotes(map);
  return next;
}
// Patch the notes onto any cached Code Flow PR objects so an open tab reflects a
// note change immediately without waiting out the codeflow cache TTL / a refresh.
function _patchCodeflowCacheNotes(key, notes) {
  try {
    for (const entry of _codeflowCache.values()) {
      const prs = entry && entry.data && Array.isArray(entry.data.pullRequests) ? entry.data.pullRequests : [];
      for (const pr of prs) {
        if (_cfWtKey({ org: pr.org, project: pr.project, repo: pr.repo, prId: pr.id, provider: pr.provider }) === key) {
          pr.notes = notes;
        }
      }
    }
  } catch { /* cache patch is best-effort */ }
}

// Summarize a PR worktree record into a short, human/LLM-readable status bits array
// (worktree state, branch drift, review state, ready-to-post comments, report count).
// Shared by the Board AI PR context and the "Where was I?" briefing so both describe
// a pinned PR's local state identically. Reads the freshest drift when present, else
// falls back to the git snapshot captured at worktree creation.
function _cfWtBits(wt) {
  const bits = [];
  if (!wt) { bits.push('no worktree'); return bits; }
  bits.push('worktree:' + (wt.worktreeStatus || 'unknown'));
  const g = wt.drift || wt.git || null;
  if (g && (g.ahead != null || g.behind != null || g.dirty != null)) {
    bits.push(`git:ahead ${g.ahead || 0}/behind ${g.behind || 0}${g.dirty ? '/dirty' : (g.inSync ? '/in-sync' : '')}`);
  }
  if (wt.reviewStatus) bits.push('review:' + wt.reviewStatus);
  else if (Array.isArray(wt.reports) && wt.reports.length) bits.push('review:report-ready');
  if (wt.reviewComments) bits.push(wt.reviewComments + ' comment' + (wt.reviewComments === 1 ? '' : 's') + ' to post');
  if (wt.prStatus) bits.push('pr:' + wt.prStatus);
  return bits;
}

// Resolve copilot CLI path for environments where it's not in PATH (e.g., scheduled
// tasks, the bundled desktop app). Prefers the copilot vendored inside this app's
// node_modules (shipped with the desktop build), then a global npm install, then PATH.
if (!process.env.COPILOT_PATH) {
  const candidates = [
    // App-managed copy (updatable, under the data dir) takes precedence over the
    // bundled floor so manual/scheduled updates actually take effect.
    (() => { try { return dependencies.resolveManagedCopilot(); } catch { return null; } })(),
    // Bundled platform binary (desktop resources): node_modules/@github/copilot-win32-x64/copilot.exe
    path.join(__dirname, 'node_modules', '@github', 'copilot-win32-x64', 'copilot.exe'),
    // Bundled npm shim
    path.join(__dirname, 'node_modules', '.bin', process.platform === 'win32' ? 'copilot.cmd' : 'copilot'),
    // Common global npm install (Windows)
    process.env.APPDATA ? path.join(process.env.APPDATA, 'npm', 'copilot.cmd') : null,
  ].filter(Boolean);
  let resolved = candidates.find(p => { try { return fs.existsSync(p); } catch { return false; } });
  if (!resolved) {
    // Fall back to whatever is on PATH.
    try {
      const whichCmd = process.platform === 'win32' ? 'where copilot' : 'command -v copilot';
      const found = require('child_process').execSync(whichCmd, { encoding: 'utf-8', timeout: 5000 }).split(/\r?\n/)[0].trim();
      if (found && fs.existsSync(found)) resolved = found;
    } catch { /* not on PATH */ }
  }
  if (resolved) {
    process.env.COPILOT_PATH = resolved;
    console.log(`[supervisor] Resolved copilot CLI: ${resolved}`);
  } else {
    console.warn('[supervisor] WARNING: copilot CLI not found (bundled, npm global, or PATH)');
  }
}

// Generate the board MCP's .mcp.json at startup with an absolute path to the
// committed board-mcp.js and the live server's base URL. The file is gitignored
// (the path/port are machine-specific) but the server source + skill are
// committed. capabilities.buildCatalog() scans builtin-plugins/ for .mcp.json,
// so writing this here auto-surfaces the board MCP in the per-agent attach
// picker AND in Design-with-AI's catalog with no further wiring.
function ensureBoardPlugin() {
  try {
    const boardDir = path.join(BUILTIN_PLUGINS_DIR, 'board');
    const mcpEntry = path.join(boardDir, 'mcp', 'board-mcp.js');
    if (!fs.existsSync(mcpEntry)) return;
    const mcpJsonPath = path.join(boardDir, '.mcp.json');
    const desired = {
    mcpServers: {
      board: {
        command: process.execPath,
        args: [mcpEntry],
        env: { BOARD_API_BASE: `http://127.0.0.1:${getPort()}` },
      },
    },
    };
    let current = null;
    try { current = JSON.parse(fs.readFileSync(mcpJsonPath, 'utf-8')); } catch { current = null; }
    if (JSON.stringify(current) !== JSON.stringify(desired)) {
    fs.writeFileSync(mcpJsonPath, JSON.stringify(desired, null, 2));
    console.log('[supervisor] Generated board MCP config (.mcp.json)');
    }
  } catch (e) { console.warn('[supervisor] Could not generate board MCP config:', e.message); }
}
ensureBoardPlugin();

// Runtime dir of the seeded Connect plugin (set by ensureConnectPlugin). The
// Phase-2 collector/writer/profiler runs point config.pluginDir here so the SDK
// loads the plugin's agents + skills + WorkIQ .mcp.json.
let connectPluginDir = null;

// Seed the built-in Connect plugin into the runtime store, register it, and
// (re)generate its WorkIQ .mcp.json from settings. Mirrors ensureManagerPlugin +
// ensureBoardPlugin. The plugin is skills/agents-only in the repo; the .mcp.json
// (machine/settings-specific) is generated here and gitignored.
(function ensureConnectPlugin() {
  const homeDir = process.env.USERPROFILE || process.env.HOME;
  const configPath = path.join(homeDir, '.copilot', 'config.json');
  const installedDir = path.join(homeDir, '.copilot', 'installed-plugins', '_direct');
  const builtinConnect = path.join(BUILTIN_PLUGINS_DIR, 'connect');
  const runtimeConnect = path.join(PLUGINS_DIR, 'connect');
  const targetDir = path.join(installedDir, 'connect');

  try {
    if (fs.existsSync(builtinConnect) && !fs.existsSync(runtimeConnect)) {
      fs.mkdirSync(PLUGINS_DIR, { recursive: true });
      fs.cpSync(builtinConnect, runtimeConnect, { recursive: true });
      console.log('[supervisor] Seeded connect plugin into runtime store');
    } else if (fs.existsSync(builtinConnect) && fs.existsSync(runtimeConnect)) {
      // Upgrade path: copy any agent/skill files added to the builtin plugin
      // that aren't yet in the runtime store (never clobber the generated .mcp.json).
      for (const sub of ['agents', 'skills']) {
        const src = path.join(builtinConnect, sub);
        const dst = path.join(runtimeConnect, sub);
        if (!fs.existsSync(src)) continue;
        try { fs.mkdirSync(dst, { recursive: true }); } catch { /* ignore */ }
        for (const f of fs.readdirSync(src)) {
          const sf = path.join(src, f);
          const df = path.join(dst, f);
          try {
            if (fs.statSync(sf).isFile() && !fs.existsSync(df)) {
              fs.copyFileSync(sf, df);
              console.log(`[supervisor] Synced connect ${sub}/${f} into runtime store`);
            }
          } catch { /* best-effort */ }
        }
      }
    }
  } catch (e) { console.warn('[supervisor] Could not seed connect plugin:', e.message); }

  if (!fs.existsSync(runtimeConnect)) return;
  connectPluginDir = runtimeConnect;

  // Generate the WorkIQ .mcp.json from settings so the collector/profiler agents
  // can read the user's M365 activity. Static command/args keep it overridable.
  try {
    let cmd = 'npx';
    let argsRaw = '-y @microsoft/workiq@latest mcp';
    try {
      const s = require('./settings').getSettings();
      if (s.connectWorkIqCommand) cmd = s.connectWorkIqCommand;
      if (s.connectWorkIqArgs) argsRaw = s.connectWorkIqArgs;
    } catch { /* settings not ready — use defaults */ }
    const desired = {
      mcpServers: {
        workiq: { command: cmd, args: String(argsRaw).split(/\s+/).filter(Boolean) },
      },
    };
    const mcpJsonPath = path.join(runtimeConnect, '.mcp.json');
    let current = null;
    try { current = JSON.parse(fs.readFileSync(mcpJsonPath, 'utf-8')); } catch { current = null; }
    if (JSON.stringify(current) !== JSON.stringify(desired)) {
      fs.writeFileSync(mcpJsonPath, JSON.stringify(desired, null, 2));
      console.log('[supervisor] Generated connect WorkIQ MCP config (.mcp.json)');
    }
  } catch (e) { console.warn('[supervisor] Could not generate connect MCP config:', e.message); }

  if (!fs.existsSync(targetDir)) {
    try {
      fs.mkdirSync(installedDir, { recursive: true });
      require('child_process').execSync(`mklink /J "${targetDir}" "${runtimeConnect}"`, { shell: true });
      console.log('[supervisor] Created connect plugin junction');
    } catch (e) { console.warn('[supervisor] Could not create connect plugin junction:', e.message); }
  }

  if (fs.existsSync(configPath)) {
    try {
      const raw = fs.readFileSync(configPath, 'utf-8').replace(/^\s*\/\/.*$/gm, '');
      const config = JSON.parse(raw);
      if (!config.installedPlugins) config.installedPlugins = [];
      if (!config.installedPlugins.some(p => p.name === 'connect')) {
        config.installedPlugins.push({
          name: 'connect', marketplace: '', version: '1.0.0',
          installed_at: new Date().toISOString(), enabled: true,
          cache_path: targetDir,
          source: { source: 'local', path: runtimeConnect },
        });
        fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
        console.log('[supervisor] Registered connect plugin in copilot config');
      }
    } catch (e) { console.warn('[supervisor] Could not register connect plugin:', e.message); }
  }
})();


// Runtime dir of the seeded Newsletter plugin (set by ensureNewsletterPlugin).
// Newsletter runs point config.pluginDir here so the SDK loads its writer/editor
// agents + newsletter-standards skill + WorkIQ .mcp.json.
