app.get('/api/azdo/discover', async (req, res) => {
  const { org, project, repo, branch } = req.query;
  if (!org || !project || !repo || !branch) return res.status(400).json({ error: 'org, project, repo and branch are required' });
  try {
    let registered = [];
    try { registered = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8')); } catch {}
    const isRegistered = (d) => registered.some(a => {
      const s = a.source;
      // Source-aware match: an item from THIS azdo source is registered even if
      // its id was suffixed to coexist with a same-id install from elsewhere.
      if (s && s.type === 'azdo') {
        return s.org === org && s.project === project && s.repo === repo && s.path === d.path;
      }
      return a.id === d.id;
    });
    const discovered = (await azdo.discover(org, project, repo, branch))
      .map(d => ({ ...d, registered: isRegistered(d) }));
    res.json({ discovered });
  } catch (e) { res.status(502).json({ error: e.message }); }
});

// Materialize + register an AzDO agent/plugin. Shared by /api/azdo/install and
// the marketplace install endpoint. Returns the persisted agent config.
// Two installs of the same logical item from the SAME source update in place
// (same id). Installs of the same base id from a DIFFERENT source coexist by
// suffixing the id with the source kind (e.g. "helix-ux-standup-azdo").
function sameInstallSource(a, b) {
  if (!a || !b || a.type !== b.type) return false;
  if (a.type === 'azdo') return a.org === b.org && a.project === b.project && a.repo === b.repo && a.path === b.path;
  if (a.type === 'github') return a.org === b.org && a.repo === b.repo && a.path === b.path;
  if (a.type === 'local') return String(a.path || '') === String(b.path || '');
  return false;
}
function sourceSuffix(source) {
  if (!source) return 'src';
  if (source.type === 'azdo') return 'azdo';
  if (source.type === 'github') return 'github';
  if (source.type === 'local') return 'local';
  return String(source.type || 'src');
}
// Resolve the id to persist for a new install, honoring same-source overwrite
// and different-source coexistence. Returns { id, suffixed }.
function resolveInstallId(baseId, newSource, agents) {
  const existing = agents.find(a => a.id === baseId);
  // Free, or it's the same logical source (an update/reinstall) -> reuse base id.
  if (!existing) return { id: baseId, suffixed: false };
  if (sameInstallSource(existing.source, newSource)) return { id: baseId, suffixed: false };
  // Collision with a different (or source-less) entry -> suffix by source kind.
  const suffix = sourceSuffix(newSource);
  let candidate = `${baseId}-${suffix}`;
  let n = 1;
  while (true) {
    const c = agents.find(a => a.id === candidate);
    if (!c) return { id: candidate, suffixed: true };
    if (sameInstallSource(c.source, newSource)) return { id: candidate, suffixed: true };
    n++;
    candidate = `${baseId}-${suffix}-${n}`;
  }
}

// Materialize + register an agent/plugin from a forge provider (azdo|github).
// Shared by /api/azdo/install, /api/forge/install and marketplace install.
// `provider` (missing ⇒ azdo) selects the module; GitHub uses org as the owner
// and leaves project ''. Source records carry `type: provider` so a same-id item
// from a different provider/source coexists (suffixed) rather than clobbering.
async function installForgeItem({ provider, org, project, repo, branch, item, group }) {
  const prov = providerOf({ provider });
  const mod = forge({ provider: prov });
  const isGithub = prov === 'github';
  const proj = isGithub ? '' : project;
  const source = {
    type: prov, kind: item.kind, org, project: proj, repo, branch,
    path: item.path, objectId: item.objectId || null,
    installedAt: new Date().toISOString()
  };
  const agents = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8'));
  const { id: finalId, suffixed } = resolveInstallId(item.id, source, agents);
  const baseName = item.displayName || item.name || item.id;
  const providerLabel = isGithub ? 'GitHub' : 'Azure DevOps';
  const name = suffixed ? `${baseName} (${providerLabel})` : baseName;
  const defaultGroup = isGithub ? 'GitHub' : 'Azure DevOps';
  let config;
  if (item.kind === 'plugin') {
    const { pluginDir, mcpConfig } = await mod.materializePlugin(org, proj, repo, branch, item);
    registerLocalPluginInCopilot(pluginDir);
    config = {
      id: finalId,
      name,
      cwd: mod.repoRoot(org, proj, repo, branch),
      pluginDir,
      sourceDir: pluginDir,
      agent: ensurePluginAgent(pluginDir),
      schedule: 'never',
      durable: true,
      group: group || defaultGroup,
      description: item.description || '',
      source
    };
    if (mcpConfig) config.mcpConfig = mcpConfig;
  } else {
    const { cwd, mcpConfig, skillCount } = await mod.materializeAgent(org, proj, repo, branch, item.path);
    config = {
      id: finalId,
      name,
      cwd,
      agent: item.agentRef || item.name || item.id,
      schedule: 'never',
      durable: true,
      group: group || defaultGroup,
      description: item.description || '',
      source
    };
    if (mcpConfig) config.mcpConfig = mcpConfig;
    // Co-located MCP/skills were materialized: run this agent through the
    // generated runtime package so they're actually wired at run time.
    if (mcpConfig || skillCount) config.usePackage = true;
  }
  const existing = agents.findIndex(a => a.id === config.id);
  if (existing >= 0) agents[existing] = config; else agents.push(config);
  fs.writeFileSync(AGENTS_PATH, JSON.stringify(agents, null, 2));
  supervisor.register(config);
  broadcastSSE('agent-update', { agentId: config.id });
  return config;
}

// Back-compat thin wrapper — AzDO install path (provider defaults to azdo).
async function installAzdoItem({ org, project, repo, branch, item, group }) {
  return installForgeItem({ provider: 'azdo', org, project, repo, branch, item, group });
}

app.post('/api/azdo/install', async (req, res) => {
  const { org, project, repo, branch, item, group } = req.body || {};
  if (!org || !project || !repo || !branch || !item || !item.kind || !item.id) {
    return res.status(400).json({ error: 'org, project, repo, branch and item{kind,id,path} are required' });
  }
  try {
    const config = await installAzdoItem({ org, project, repo, branch, item, group });
    res.json({ ok: true, agent: config });
  } catch (e) {
    res.status(500).json({ error: `Azure DevOps install failed: ${e.message}` });
  }
});

// Provider-aware discovery + install (mirrors /api/azdo/discover + /api/azdo/install).
// GitHub has no "project" — owner lives in `org`, project stays ''. Missing
// provider ⇒ azdo (back-compat). Source-aware "registered" match so an item from
// THIS source shows as installed even if its id was suffixed to coexist.
app.get('/api/forge/discover', async (req, res) => {
  const provider = providerOf({ provider: req.query.provider });
  const org = (req.query.org || '').trim();
  const project = (req.query.project || '').trim();
  const repo = (req.query.repo || '').trim();
  const branch = (req.query.branch || '').trim();
  if (!org || !repo || !branch || (provider === 'azdo' && !project)) {
    return res.status(400).json({ error: provider === 'github' ? 'owner (org), repo and branch are required' : 'org, project, repo and branch are required' });
  }
  const proj = provider === 'github' ? '' : project;
  try {
    let registered = [];
    try { registered = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8')); } catch {}
    const isRegistered = (d) => registered.some(a => {
      const s = a.source;
      if (s && s.type === provider) {
        if (provider === 'github') return s.org === org && s.repo === repo && s.path === d.path;
        return s.org === org && s.project === proj && s.repo === repo && s.path === d.path;
      }
      return a.id === d.id;
    });
    const discovered = (await forge({ provider, org }).discover(org, proj, repo, branch))
      .map(d => ({ ...d, registered: isRegistered(d) }));
    res.json({ discovered });
  } catch (e) { res.status(502).json({ error: e.message }); }
});

app.post('/api/forge/install', async (req, res) => {
  const provider = providerOf(req.body || {});
  const { org, project, repo, branch, item, group } = req.body || {};
  const proj = provider === 'github' ? '' : project;
  if (!org || !repo || !branch || !item || !item.kind || !item.id || (provider === 'azdo' && !project)) {
    return res.status(400).json({ error: provider === 'github' ? 'owner (org), repo, branch and item{kind,id,path} are required' : 'org, project, repo, branch and item{kind,id,path} are required' });
  }
  try {
    const config = await installForgeItem({ provider, org, project: proj, repo, branch, item, group });
    res.json({ ok: true, agent: config });
  } catch (e) {
    res.status(500).json({ error: `${provider === 'github' ? 'GitHub' : 'Azure DevOps'} install failed: ${e.message}` });
  }
});

// ============ Code Flow API Routes ============
// Monitors Azure DevOps pull requests across a user-curated set of repos.
// Auth is secretless via the locally signed-in Azure CLI (see azdo.js). The
// core surfaces "My PRs" + "Reviews needed from me" with live state (build /
// approval / comments / ready-to-merge + a Validation section); AI enrichment
// (urgency, summaries, suggested reviewers) is a deferred fast-follow.

// --- Watched repos (storage mirrors azdo-sources) ---

app.get('/api/codeflow/repos', (req, res) => {
  try { res.json({ repos: loadCodeflowRepos() }); }
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/codeflow/repos', (req, res) => {
  const provider = providerOf(req.body || {});
  const org = (req.body && req.body.org || '').trim();
  // GitHub has no "project" concept — the owner lives in `org`, project stays ''.
  const project = provider === 'github' ? '' : (req.body && req.body.project || '').trim();
  const repo = (req.body && req.body.repo || '').trim();
  if (!org || !repo || (provider === 'azdo' && !project)) {
    return res.status(400).json({ error: provider === 'github'
      ? 'owner (org) and repo are required'
      : 'org, project and repo are required' });
  }
  try {
    const repos = loadCodeflowRepos();
    const dup = repos.find(r =>
      providerOf(r) === provider &&
      r.org.toLowerCase() === org.toLowerCase() &&
      (r.project || '').toLowerCase() === project.toLowerCase() &&
      r.repo.toLowerCase() === repo.toLowerCase());
    if (dup) return res.status(409).json({ error: 'That repo is already monitored', repo: dup });
    const entry = {
      id: 'cfr-' + require('crypto').randomBytes(5).toString('hex'),
      provider, org, project, repo,
      addedAt: new Date().toISOString()
    };
    repos.push(entry);
    saveCodeflowRepos(repos);
    _codeflowCache.clear();
    res.json({ ok: true, repo: entry });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.delete('/api/codeflow/repos/:id', (req, res) => {
  try {
    const repos = loadCodeflowRepos();
    const next = repos.filter(r => r.id !== req.params.id);
    if (next.length === repos.length) return res.status(404).json({ error: 'Repo not found' });
    saveCodeflowRepos(next);
    _codeflowCache.clear();
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// The signed-in identity (per org). Needed to scope my-PRs / reviews.
// Provider is resolved from the matching monitored repo (defaults to azdo).
app.get('/api/codeflow/me', async (req, res) => {
  try {
    let org = (req.query.org || '').trim();
    const reqProvider = req.query.provider ? providerOf({ provider: req.query.provider }) : null;
    const repos = loadCodeflowRepos();
    if (!org) {
      const first = reqProvider ? repos.find(r => providerOf(r) === reqProvider) : repos[0];
      org = first && first.org;
    }
    if (!org) return res.status(400).json({ error: 'No org available — add a repo first or pass ?org=' });
    // Find the record matching org (+ provider hint) to pick the right provider.
    const rec = repos.find(r => r.org.toLowerCase() === org.toLowerCase() && (!reqProvider || providerOf(r) === reqProvider))
      || { provider: reqProvider || 'azdo', org };
    res.json({ org, provider: providerOf(rec), user: await forge(rec).getCurrentUser(org) });
  } catch (e) { res.status(502).json({ error: e.message }); }
});

// --- PR aggregation ---

const _codeflowCache = new Map(); // view -> { at, data }
const CODEFLOW_TTL_MS = 300000; // 5 min — long enough that the 3-min attention poll reuses cache most ticks (was 2 min → re-gathered every poll, a big GitHub-quota driver)
const _codeflowAiCache = new Map(); // view -> Map(prId -> { sig, at, insight })
const CODEFLOW_AI_TTL_MS = 600000; // 10 min
// Serialize codeflow AI generation. The SDK/CLI subprocess cannot service concurrent
// runChat calls — parallel streamed outputs interleave and corrupt each other, so the
// JSON fails to parse and the endpoint 502s. The page fires several AI calls at once
// (loadCodeFlow + auto-refresh + view-switch + the board-pins loop), which reliably
// triggered this. We run one generation at a time through _codeflowAiChain and coalesce
// identical in-flight non-refresh requests per view so those concurrent calls share one result.
let _codeflowAiChain = Promise.resolve();
const _codeflowAiInflight = new Map(); // view -> Promise (non-refresh only)
const _cfApproverCache = new Map(); // "org|project|repo" -> { at, entries }
const CF_APPROVER_TTL_MS = 1800000; // 30 min — PR history changes slowly

// Live PR "pieces" for the briefing + board-assistant context, pulled ONLY from the
// in-memory codeflow caches (no AzDo fetch, so it's cheap and never blocks). Given a
// pinned PR's identity meta, finds its cached record across views and returns a rich
// set of human-readable lines: state/draft, ready, age, comments, required/optional
// reviewers with votes, validation/check counts, attention reason, and the cached AI
// urgency + summary. Returns null when the PR isn't in any warm cache.
function _cfPrLive(m) {
  if (!m || m.prId == null) return null;
  const wantId = String(m.prId);
  // Composite match key: include provider (default azdo) and tolerate an empty
  // project slot (GitHub stores owner in `org`, no project). AzDo keys stay
  // symmetric — provider defaults to 'azdo' on both sides and project is present —
  // so existing matching is byte-identical.
  const idKey = p => (p && p.org && p.repo && p.id != null)
    ? [String(p.provider || 'azdo').toLowerCase(), p.org, p.project || '', p.repo, p.id].join('|').toLowerCase() : null;
  const wantKey = idKey({ provider: m.provider, org: m.org, project: m.project, repo: m.repo, id: m.prId });
  let pr = null, foundView = null;
  for (const view of ['mine', 'reviews', 'active']) {
    const cached = _codeflowCache.get(view);
    const list = cached && cached.data && Array.isArray(cached.data.pullRequests) ? cached.data.pullRequests : null;
    if (!list) continue;
    const hit = list.find(p => p && (wantKey ? idKey(p) === wantKey : String(p.id) === wantId));
    if (hit) { pr = hit; foundView = view; break; }
  }
  if (!pr) return null;
  const lines = [];
  const st = pr.isDraft ? 'draft' : (pr.status || 'active');
  lines.push('state: ' + st + (pr.readyToMerge ? ' · ready to merge' : ''));
  if (pr.ageDays != null || pr.ageHours != null) {
    const age = (pr.ageDays != null && pr.ageDays >= 1)
      ? Math.round(pr.ageDays) + 'd'
      : Math.max(1, Math.round(pr.ageHours || 0)) + 'h';
    lines.push('age: ' + age);
  }
  const c = pr.comments || {};
  if (c.activeComments || c.totalThreads) {
    lines.push('comments: ' + (c.activeComments || 0) + ' active / ' + (c.totalThreads || 0) + ' threads');
  }
  const rs = Array.isArray(pr.reviewers) ? pr.reviewers : [];
  if (rs.length) {
    const fmt = r => (r.name || r.id || '?') + (r.voteLabel ? ' (' + r.voteLabel + ')' : '');
    const req = rs.filter(r => r && r.isRequired), opt = rs.filter(r => r && !r.isRequired);
    if (req.length) lines.push('required reviewers: ' + req.map(fmt).join(', '));
    if (opt.length) lines.push('optional reviewers: ' + opt.map(fmt).join(', '));
  }
  const val = Array.isArray(pr.validation) ? pr.validation : [];
  if (val.length) {
    const fail = pr.failedChecks || 0, pend = pr.pendingChecks || 0;
    lines.push('checks: ' + (fail ? fail + ' failing' : (pend ? pend + ' pending' : 'all ' + val.length + ' passing')));
  }
  if (pr.attentionReason) lines.push('attention: ' + pr.attentionReason);
  let urgency = null, summary = '';
  try {
    const store = _codeflowAiCache.get(foundView);
    const ins = store && store.get(String(pr.id));
    if (ins && ins.insight) {
      urgency = ins.insight.urgency;
      summary = ins.insight.summary || '';
      if (summary) {
        lines.push('AI: ' + summary + (urgency != null
          ? ' (urgency ' + urgency + (ins.insight.urgencyReason ? ' — ' + ins.insight.urgencyReason : '') + ')'
          : ''));
      }
    }
  } catch { /* AI cache optional */ }
  return { lines, urgency, summary, view: foundView };
}

// Directory prefixes (truncated to `depth` path segments) for a set of changed
// file paths. e.g. depth 2 of "src/hive/tools/x.ps1" -> "src/hive". Used to gauge
// whether two PRs touched the "same space" of the repo.
function _cfDirPrefixes(files, depth) {
  const out = new Set();
  for (const f of files || []) {
    const parts = String(f || '').replace(/^\/+/, '').split('/').filter(Boolean);
    if (parts.length <= 1) continue; // a root-level file has no dir "area"
    const dir = parts.slice(0, -1); // drop the filename
    if (!dir.length) continue;
    out.add(dir.slice(0, depth).join('/').toLowerCase());
  }
  return out;
}

// Build a per-repo index of recently-COMPLETED PRs, each with the areas it touched
// and the people who APPROVED it. This is the signal behind approval-based reviewer
// suggestions: the best reviewer for a change is usually whoever has approved prior
// changes in the same part of the repo — not whoever committed the most code.
// Cached per repo (30 min); one changed-files call per completed PR, concurrency-capped.
async function _cfApproverIndex(rec) {
  const { org, project, repo } = rec;
  const F = forge(rec);
  const key = `${providerOf(rec)}|${org}|${project}|${repo}`.toLowerCase();
  const cached = _cfApproverCache.get(key);
  if (cached && (Date.now() - cached.at) < CF_APPROVER_TTL_MS) return cached.entries;

  let entries = [];
  try {
    const prs = await F.listPullRequests(org, project, repo, { status: 'completed', top: 60 });
    // Keep only PRs that actually got an approving vote (others teach us nothing),
    // most-recent first, capped so the fan-out stays bounded.
    const withApprovers = [];
    for (const pr of prs) {
      const author = ((pr.createdBy && pr.createdBy.name) || '').trim().toLowerCase();
      const approvers = (pr.reviewers || [])
        .filter(r => Number(r.vote) >= 5) // approved / approved-with-suggestions
        .map(r => ({ name: (r.name || '').trim(), email: (r.email || '').trim(), vote: Number(r.vote) }))
        .filter(r => r.name && r.name.toLowerCase() !== author);
      if (!approvers.length) continue;
      const closed = pr.closedDate ? new Date(pr.closedDate).getTime() : 0;
      withApprovers.push({ pr, approvers, closed });
    }
    withApprovers.sort((a, b) => b.closed - a.closed);
    const pick = withApprovers.slice(0, 40);

    // Fetch changed files with a small concurrency cap.
    const results = [];
    const CONC = 6;
    for (let i = 0; i < pick.length; i += CONC) {
      const chunk = pick.slice(i, i + CONC);
      const files = await Promise.all(chunk.map(x =>
        F.getPrChangedFiles(org, project, repo, x.pr.id, 100).catch(() => [])));
      chunk.forEach((x, j) => results.push({ ...x, files: files[j] || [] }));
    }
    const now = Date.now();
    entries = results
      .filter(x => x.files.length)
      .map(x => ({
        approvers: x.approvers,
        areas3: _cfDirPrefixes(x.files, 3),
        areas2: _cfDirPrefixes(x.files, 2),
        areas1: _cfDirPrefixes(x.files, 1),
        ageDays: x.closed ? Math.max(0, (now - x.closed) / 86400000) : 999
      }));
  } catch { entries = []; /* best-effort — never fatal */ }

  _cfApproverCache.set(key, { at: Date.now(), entries });
  return entries;
}

// Given the current PR's changed files and the repo approver index, score people by
// how often they approved prior PRs touching the SAME areas (deeper-path overlap +
// recency + vote strength weighted). Returns a ranked [{name,email,score,prs}].
function _cfRankApprovers(files, index) {
  if (!files || !files.length || !index || !index.length) return [];
  const cur3 = _cfDirPrefixes(files, 3);
  const cur2 = _cfDirPrefixes(files, 2);
  const cur1 = _cfDirPrefixes(files, 1);
  const inter = (a, b) => { let n = 0; for (const v of a) if (b.has(v)) n++; return n; };
  const tally = new Map();
  for (const e of index) {
    const ov3 = inter(cur3, e.areas3);
    const ov2 = inter(cur2, e.areas2);
    const ov1 = inter(cur1, e.areas1);
    const overlap = ov3 * 4 + ov2 * 2 + (ov1 > 0 ? 1 : 0);
    if (!overlap) continue;
    const recency = e.ageDays <= 180 ? 1 : Math.max(0.3, 1 - (e.ageDays - 180) / 365);
    for (const a of e.approvers) {
      const voteW = a.vote >= 10 ? 1 : 0.7;
      const w = overlap * recency * voteW;
      const lk = a.name.toLowerCase();
      const cur = tally.get(lk) || { name: a.name, email: a.email, score: 0, prs: 0 };
      cur.score += w;
      cur.prs += 1;
      if (!cur.email && a.email) cur.email = a.email;
      tally.set(lk, cur);
    }
  }
  return [...tally.values()].sort((a, b) => b.score - a.score);
}

// Enrich a compact PR with threads / statuses / policy evals + derived state.
// Index every board dev card by (org|project|repo|prId) so a Code Flow PR can
// link to its existing dev card if one is tracking the same pull request.
function _buildDevCardIndex() {
  const idx = new Map();
  try {
    const names = new Map(loadBoards().map(b => [b.id, b.name || '']));
    for (const d of devStore.all()) {
      const entry = { boardId: d.homeBoardId || null, boardName: names.get(d.homeBoardId) || '', devId: d.id, title: d.title || '' };
      // Primary repo (top-level prId/org/project/repo).
      const prId = d.prId != null ? String(d.prId).trim() : '';
      if (prId && d.org && d.project && d.repo) {
        idx.set(`${d.org}|${d.project}|${d.repo}|${prId}`.toLowerCase(), entry);
      }
      // Extra repo slots — each may carry its own linked PR.
      for (const r of (Array.isArray(d.repos) ? d.repos : [])) {
        const rPrId = r && r.prId != null ? String(r.prId).trim() : '';
        if (rPrId && r.org && r.project && r.repo) {
          idx.set(`${r.org}|${r.project}|${r.repo}|${rPrId}`.toLowerCase(), entry);
        }
      }
    }
  } catch { /* store unavailable — no dev-card links, never fatal */ }
  return idx;
}

// Forgiving match of a configured group name against a reviewer DISPLAY NAME.
// AzDO decorates group names with a scope prefix ("[internal]\\Team"); GitHub teams
// show as "org/team". Shared by the gather pre-filter (list data, ZERO API calls) and
// the per-PR enrichment so both agree on what counts as "one of my groups".
function _cfMatchesGroup(rvName, myGroups) {
  const want = (Array.isArray(myGroups) ? myGroups : [])
    .map(v => String(v == null ? '' : v).trim().toLowerCase()).filter(Boolean);
  if (!want.length) return false;
  const norm = v => String(v == null ? '' : v).trim().toLowerCase();
  const tail = v => { const s = norm(v); const i = Math.max(s.lastIndexOf('\\'), s.lastIndexOf('/')); return i >= 0 ? s.slice(i + 1).trim() : s; };
  const full = norm(rvName); const last = tail(rvName);
  return want.some(w => w && (w === full || w === last || full === tail(w) || full.includes(w) || last.includes(tail(w))));
}

// Cheap keep-decision using ONLY the PR list's reviewer array — no per-PR API calls.
// Am I a direct reviewer, or is one of my groups a reviewer? Used to pre-filter the
// broad "reviews + groups" fetch so we fully enrich only real action items instead of
// hammering GitHub's rate limit on every open PR across large repos.
function _cfListReviewerFlags(pr, me, myGroups) {
  const meId = String((me && me.id) || '').toLowerCase();
  const meName = String((me && me.name) || '').trim().toLowerCase();
  const meEmail = String((me && me.email) || '').trim().toLowerCase();
  let amReviewer = false, amGroup = false;
  for (const r of (pr.reviewers || [])) {
    const rid = String((r && r.id) || '').toLowerCase();
    const rname = String((r && r.name) || '').trim().toLowerCase();
    const remail = String(((r && r.uniqueName) || (r && r.email)) || '').trim().toLowerCase();
    if ((meId && rid === meId) || (meEmail && remail === meEmail) || (meName && rname === meName)) amReviewer = true;
    else if (_cfMatchesGroup(r && r.name, myGroups)) amGroup = true;
  }
  return { amReviewer, amGroup };
}

async function _enrichCodeflowPr(pr, viewerId, opts = {}) {
  const safe = (p) => p.catch(() => null);
  const provider = opts.provider || pr.provider;
  const F = forge({ provider, org: pr.org });
  // GitHub's PR LIST endpoint only returns still-requested reviewers, so anyone
  // who already submitted a review is missing from pr.reviewers. Pull the full
  // set (submitted + requested) so the card lists every reviewer with their vote.
  const wantReviewers = provider === 'github' && typeof F.getReviewers === 'function';
  const [threads, statuses, policy, fullReviewers] = await Promise.all([
    safe(F.getPrThreads(pr.org, pr.project, pr.repo, pr.id)),
    safe(F.getPrStatuses(pr.org, pr.project, pr.repo, pr.id)),
    safe(F.getPrPolicyEvaluations(pr.org, pr.project, pr.id, pr.repo)),
    wantReviewers ? safe(F.getReviewers(pr.org, pr.project, pr.repo, pr.id)) : Promise.resolve(null)
  ]);
  if (Array.isArray(fullReviewers)) pr.reviewers = fullReviewers;
  const ageMs = pr.creationDate ? (Date.now() - new Date(pr.creationDate).getTime()) : 0;
  const ageHours = Math.max(0, Math.round(ageMs / 3600000));
  const ageDays = Math.floor(ageHours / 24);

  const required = (pr.reviewers || []).filter(r => r.isRequired);
  const anyRejected = (pr.reviewers || []).some(r => r.vote === -10);
  const anyWaiting = (pr.reviewers || []).some(r => r.vote === -5);
  const reqApproved = required.length ? required.every(r => r.vote >= 5) : null;
  let approvalState = 'no-reviews';
  if (anyRejected) approvalState = 'rejected';
  else if (anyWaiting) approvalState = 'waiting-for-author';
  else if (reqApproved === true) approvalState = 'approved';
  else if ((pr.reviewers || []).some(r => r.vote >= 5)) approvalState = 'partially-approved';
  else if ((pr.reviewers || []).length) approvalState = 'pending';

  // Major PR build gates (Build-type policy evaluations) rendered as validation
  // entries alongside the lighter status checks, so the gating builds are visible.
  const buildGates = ((policy && policy.builds) || []).map((b, i) => {
    const map = { approved: 'succeeded', rejected: 'failed', running: 'pending',
                  queued: 'pending', canceled: 'error', partiallysucceeded: 'failed' };
    const state = map[(b.state || '').toLowerCase()] || 'notSet';
    let desc = '';
    if (b.durationMs != null) {
      const mins = Math.floor(b.durationMs / 60000), secs = Math.round((b.durationMs % 60000) / 1000);
      desc = (b.state === 'running' ? 'Running · ' : '') + (mins ? `${mins}m ${secs}s` : `${secs}s`);
    } else if (b.state) { desc = b.state; }
    if (b.isExpired) desc = (desc ? desc + ' · ' : '') + 'expired';
    return {
      id: 'build-' + (b.buildId || i),
      state, genre: 'Build', name: b.name,
      description: desc, targetUrl: b.url || '',
      kind: 'build', durationMs: b.durationMs, blocking: b.blocking,
      required: !!b.blocking
    };
  });
  // Non-build policy gates (required reviewers, minimum approver count, comment
  // resolution, work-item linking, etc.) surfaced as validation entries so the
  // merge gates — not just builds — are visible. BOTH blocking (Required) and
  // non-blocking (Optional) policies are included, mirroring the AzDO "Checks"
  // panel's Required/Optional split. Status-type policies are skipped because the
  // actual status checks are already merged below.
  const policyStateMap = { approved: 'succeeded', rejected: 'failed',
                           running: 'pending', queued: 'pending', notapplicable: 'notSet' };
  // Friendlier labels for built-in policy types (which carry no displayName).
  const policyLabel = {
    'comment requirements': 'Comments must be resolved',
    'work item linking': 'Work items must be linked',
    'require a merge strategy': 'Merge strategy',
    'proof of presence': 'Proof of presence',
    'minimum number of reviewers': 'Minimum number of reviewers'
  };
  const stateRank = { failed: 3, error: 3, pending: 2, notSet: 1, succeeded: 0 };
  const policyRaw = ((policy && policy.evaluations) || [])
    .filter(e => e && !e.isBuild
              && (e.status || '').toLowerCase() !== 'notapplicable'
              && !/status/i.test(e.type || ''))
    .map(e => {
      const name = e.displayName || policyLabel[(e.type || '').toLowerCase()] || e.type || 'Policy gate';
      return {
        state: policyStateMap[(e.status || '').toLowerCase()] || 'notSet',
        genre: 'Policy', name,
        description: (e.displayName && e.type && e.displayName !== e.type) ? e.type : '',
        targetUrl: '', kind: 'policy', blocking: !!e.blocking, required: !!e.blocking
      };
    });
  // Collapse duplicate same-named policies (e.g. several "Minimum number of
  // reviewers" configs), keeping the worst state so a single failure shows.
  const policyByName = new Map();
  for (const g of policyRaw) {
    const k = g.name + '|' + (g.required ? 'req' : 'opt');
    const prev = policyByName.get(k);
    if (!prev || (stateRank[g.state] || 0) > (stateRank[prev.state] || 0)) policyByName.set(k, g);
  }
  const policyGates = [...policyByName.values()].map((g, i) => ({ ...g, id: 'policy-' + i }));

  // Status checks (Component Governance, code coverage, FCIB, …) are gated by
  // separate "Status"-type policies that carry the gated check's genre/name and
  // whether it blocks. Build a lookup so each status check can be marked
  // Required (a blocking Status policy targets it) or Optional (everything else).
  const statusPolicyBlocking = new Map();
  for (const e of ((policy && policy.evaluations) || [])) {
    if (e && /status/i.test(e.type || '') && (e.statusGenre || e.statusName)) {
      const k = ((e.statusGenre || '') + '/' + (e.statusName || '')).toLowerCase();
      // If any matching Status policy blocks, treat the check as Required.
      statusPolicyBlocking.set(k, (statusPolicyBlocking.get(k) || false) || !!e.blocking);
    }
  }
  const statusEntries = (statuses || []).map(s => {
    const k = ((s.genre || '') + '/' + (s.name || '')).toLowerCase();
    const blocking = statusPolicyBlocking.has(k) ? statusPolicyBlocking.get(k) : false;
    return { ...s, kind: 'status', blocking, required: blocking };
  });
  const validation = [...buildGates, ...policyGates, ...statusEntries];

  // Only required (blocking) checks gate readiness; optional failures are
  // surfaced but must not be counted as blocking failures.
  const isRequired = (s) => s.required !== false;
  // "Proof of presence" is a merge-time human attestation gate — it is rejected
  // (failed) by AzDO until the actual merge, so it should NOT be counted as a
  // standard failing check. When it's the only required gate outstanding the PR
  // is effectively ready to merge, pending that one human action.
  const isProofOfPresence = (s) => /proof\s*of\s*presence/i.test(s.name || '');
  for (const s of validation) { if (isRequired(s) && isProofOfPresence(s)) s.mergeGate = true; }
  const failedChecks = validation.filter(s => isRequired(s) && !isProofOfPresence(s) && (s.state === 'failed' || s.state === 'error')).length;
  const failedOptionalChecks = validation.filter(s => !isRequired(s) && (s.state === 'failed' || s.state === 'error')).length;
  const pendingChecks = validation.filter(s => !isProofOfPresence(s) && (s.state === 'pending' || s.state === 'notSet')).length;
  // Proof of presence is still outstanding (not succeeded) — surfaced as a
  // soft "pending merge gate" rather than a hard failure.
  const proofOfPresencePending = validation.some(s => isRequired(s) && isProofOfPresence(s) && s.state !== 'succeeded');
  // It's the ONLY thing left when no real required check fails and nothing else
  // required is pending.
  const proofOfPresenceOnly = proofOfPresencePending && failedChecks === 0 && pendingChecks === 0;

  // Ready-to-merge: prefer the authoritative policy signal; else heuristic.
  let readyToMerge;
  if (policy && policy.ready !== null && policy.ready !== undefined) {
    readyToMerge = policy.ready;
  } else {
    readyToMerge = !pr.isDraft &&
      pr.mergeStatus === 'succeeded' &&
      (reqApproved === true || (reqApproved === null && approvalState === 'approved')) &&
      failedChecks === 0;
  }
  // If the authoritative signal says "not ready" purely because proof of presence
  // is outstanding (no real failing/pending required checks), treat it as ready —
  // proof of presence is a merge-time human action, not a blocker we surface as a
  // failure. The card notes the remaining gate.
  if (!readyToMerge && proofOfPresenceOnly && !pr.isDraft &&
      pr.mergeStatus === 'succeeded' &&
      (reqApproved === true || (reqApproved === null && approvalState === 'approved'))) {
    readyToMerge = true;
  }

  // My own vote (for the reviews view).
  const myReviewer = viewerId ? (pr.reviewers || []).find(r => r.id === viewerId) : null;
  const myVote = myReviewer ? myReviewer.voteLabel : null;

  // Group review: a PR can list an AzDO group / GitHub team as a reviewer (it shows
  // up as a named reviewer entry). If one of MY configured groups (opts.myGroups) is a
  // reviewer, this PR is also my action item — surfaced alongside direct reviews.
  const myGroups = Array.isArray(opts.myGroups) ? opts.myGroups : [];
  let groupReviewers = [];
  if (myGroups.length) {
    // Match a configured group name against a reviewer entry's DISPLAY NAME via the
    // shared forgiving matcher (_cfMatchesGroup): exact, trailing path segment (after
    // \\ or /), or whole-name contains — so "[internal]\\Dotnet-Core-Engineering",
    // "[TEAM FOUNDATION]\\…", and GitHub "org/team" all resolve.
    groupReviewers = (pr.reviewers || [])
      .filter(rv => rv && rv.id !== viewerId && _cfMatchesGroup(rv.name, myGroups))
      .map(rv => ({ name: rv.name, voteLabel: rv.voteLabel || null }));
  }
  const amGroupReviewer = groupReviewers.length > 0;
  // Has any of my groups already cast a (non-neutral) vote on my behalf?
  const groupVoted = groupReviewers.some(g => g.voteLabel && g.voteLabel !== 'no-vote');

  // --- Reviewer / area-expert intelligence (best-effort, deterministic) ---
  const creatorName = ((pr.createdBy && pr.createdBy.name) || '').trim().toLowerCase();
  const viewerName = (opts.viewerName || '').trim().toLowerCase();
  const viewerEmail = (opts.viewerEmail || '').trim().toLowerCase();
  const existingReviewerNames = new Set((pr.reviewers || []).map(r => (r.name || '').trim().toLowerCase()).filter(Boolean));
  const contribs = opts.repoContributors || [];
  const isViewer = (name, email) => {
    const n = (name || '').trim().toLowerCase();
    const e = (email || '').trim().toLowerCase();
    return (viewerEmail && e === viewerEmail) || (n && n === viewerName);
  };

  // Area expert: prefer approval-based signal (below); default to the top repo
  // contributor over the window who isn't the PR author or viewer.
  let areaExpert = null;
  for (const c of contribs) {
    const n = (c.name || '').trim().toLowerCase();
    if (n && n !== creatorName && !isViewer(c.name, c.email)) {
      areaExpert = { name: c.name, commits: c.count, why: `Most active in ${pr.repo || 'this repo'} (last 60 days): ${c.count} commits` };
      break;
    }
  }

  // Suggested reviewers: primarily people who APPROVED prior PRs touching the same
  // areas of the repo (a far better signal than who committed there); we fall back to
  // recent file contributors, then top repo contributors. This fans out one
  // changed-files call + several blame/contributor calls per PR, so it is skipped in
  // the broad "active" view (opts.lite) to keep that listing fast.
  let suggestedReviewers = [];
  if (!opts.lite) try {
    const files = await F.getPrChangedFiles(pr.org, pr.project, pr.repo, pr.id, 100);

    // --- Primary signal: approvers of prior PRs in the same areas ---
    const rankedApprovers = _cfRankApprovers(files, opts.approverIndex);
    const notSelf = (a) => {
      const n = (a.name || '').trim().toLowerCase();
      return n && n !== creatorName && !isViewer(a.name, a.email);
    };
    const approverCandidates = rankedApprovers.filter(notSelf);
    if (approverCandidates.length) {
      const top = approverCandidates[0];
      areaExpert = { name: top.name, approvals: top.prs, why: `Approved ${top.prs} prior PR${top.prs === 1 ? '' : 's'} in this area of ${pr.repo || 'the repo'}` };
    }
    const expertName = areaExpert ? areaExpert.name.toLowerCase() : null;
    const excludeName = (name, email) => {
      const n = (name || '').trim().toLowerCase();
      return !n || n === creatorName || n === expertName || existingReviewerNames.has(n) || isViewer(name, email);
    };
    const seen = new Set();
    for (const a of approverCandidates) {
      const lk = a.name.toLowerCase();
      if (excludeName(a.name, a.email) || seen.has(lk)) continue;
      seen.add(lk);
      suggestedReviewers.push({ name: a.name, approvals: a.prs, why: `Approved ${a.prs} prior PR${a.prs === 1 ? '' : 's'} in this area` });
      if (suggestedReviewers.length >= 3) break;
    }

    // --- Fallback signal: recent contributors to this PR's changed files (blame) ---
    if (suggestedReviewers.length < 3) {
      const pick = files.slice(0, 4);
      const perFile = await Promise.all(pick.map(p =>
        F.getFileContributors(pr.org, pr.project, pr.repo, p, 60, 30).catch(() => [])));
      const tally = new Map();
      for (const list of perFile) for (const a of list) {
        const n = (a.name || '').trim();
        if (!n) continue;
        const key = n.toLowerCase();
        const cur = tally.get(key) || { name: n, count: 0, email: a.email };
        cur.count += a.count;
        if (!cur.email && a.email) cur.email = a.email;
        tally.set(key, cur);
      }
      for (const a of [...tally.values()].sort((a, b) => b.count - a.count)) {
        const lk = a.name.toLowerCase();
        if (excludeName(a.name, a.email) || seen.has(lk)) continue;
        seen.add(lk);
        suggestedReviewers.push({ name: a.name, commits: a.count, why: `Recently changed these files: ${a.count} commits` });
        if (suggestedReviewers.length >= 3) break;
      }
    }
    // Final fallback to top repo contributors when nothing else surfaced.
    if (suggestedReviewers.length < 3 && contribs.length) {
      for (const c of contribs) {
        const n = (c.name || '').trim();
        const lk = n.toLowerCase();
        if (excludeName(c.name, c.email) || seen.has(lk)) continue;
        seen.add(lk);
        suggestedReviewers.push({ name: n, commits: c.count, why: `Most active in ${pr.repo || 'this repo'}: ${c.count} commits` });
        if (suggestedReviewers.length >= 3) break;
      }
    }
  } catch { /* reviewer enrichment is best-effort, never fatal */ }

  // Link to an existing board dev card tracking this same PR, if any.
  let devCard = null;
  if (opts.devCardIndex) {
    devCard = opts.devCardIndex.get(`${pr.org}|${pr.project}|${pr.repo}|${pr.id}`.toLowerCase()) || null;
  }

  // Volatile state signature — drives AI re-analysis only when something a human
  // would care about actually changed (cheap, deterministic, order-independent).
  const cdt = comments => comments ? `${comments.activeComments}/${comments.resolvedComments}/${comments.totalThreads}` : '0/0/0';
  const revSig = (pr.reviewers || [])
    .map(r => `${(r.name || r.id || '')}:${r.vote}`)
    .sort().join(',');
  const valSig = validation.map(v => `${v.genre}/${v.name}=${v.state}`).sort().join(',');
  const signature = [
    pr.lastMergeSourceCommit && pr.lastMergeSourceCommit.commitId || '',
    approvalState, cdt(threads),
    pr.isDraft ? 'draft' : 'open',
    readyToMerge ? 'ready' : '',
    revSig, valSig
  ].join('|');

  return {
    ...pr,
    ageHours, ageDays,
    comments: threads || { activeComments: 0, resolvedComments: 0, totalThreads: 0 },
    validation,
    failedChecks, pendingChecks, failedOptionalChecks,
    proofOfPresencePending, proofOfPresenceOnly,
    policy: policy || { evaluations: [], ready: null, builds: [] },
    approvalState,
    readyToMerge: !!readyToMerge,
    myVote,
    amReviewer: !!myReviewer,
    amGroupReviewer,
    groupReviewers,
    groupVoted,
    areaExpert,
    suggestedReviewers,
    devCard,
    signature
  };
}

// Flag a PR as needing attention (drives the banner + menu badge).
function _codeflowAttention(pr, view) {
  if (view === 'reviews' || view === 'active') {
    // In the broad "active" view, only PRs that actually list me — directly OR via one
    // of my reviewer groups — can be "awaiting your review". Everyone else's PRs aren't
    // my action item.
    if (view === 'active' && !pr.amReviewer && !pr.amGroupReviewer) return { attention: false, reason: '' };
    // Group-only reviewer (I'm not a direct reviewer): it's awaiting my group's review
    // unless the group has already voted on my behalf.
    if (!pr.amReviewer && pr.amGroupReviewer)
      return pr.groupVoted ? { attention: false, reason: '' } : { attention: true, reason: 'group-review-requested' };
    // Awaiting my review (I haven't voted) or I asked for changes and it moved on.
    if (!pr.myVote || pr.myVote === 'no-vote') return { attention: true, reason: 'awaiting-your-review' };
    if (pr.myVote === 'waiting-for-author' && pr.approvalState !== 'waiting-for-author')
      return { attention: true, reason: 'updated-since-your-review' };
    return { attention: false, reason: '' };
  }
  // mine
  if (pr.approvalState === 'rejected') return { attention: true, reason: 'changes-requested' };
  if (pr.failedChecks > 0) return { attention: true, reason: 'failing-checks' };
  if (pr.readyToMerge) return { attention: true, reason: 'ready-to-merge' };
  if (pr.approvalState === 'waiting-for-author') return { attention: true, reason: 'reviewer-waiting' };
  return { attention: false, reason: '' };
}

async function _gatherCodeflow(view) {
  const repos = loadCodeflowRepos();
  if (!repos.length) return { view, repos: [], pullRequests: [], attentionCount: 0, errors: [] };

  // Resolve identity once per distinct provider+org (a github owner and an azdo
  // org could collide on the bare name, so key on both).
  const idKey = (r) => `${providerOf(r)}::${r.org}`;
  const pairs = [...new Map(repos.map(r => [idKey(r), r])).values()];
  const userByKey = {};
  await Promise.all(pairs.map(async (r) => {
    try { userByKey[idKey(r)] = await forge(r).getCurrentUser(r.org); }
    catch { userByKey[idKey(r)] = null; }
  }));

  const errors = [];
  const devCardIndex = _buildDevCardIndex();
  const notesMap = loadCodeflowNotes();
  const dismissedMap = loadCodeflowDismissed();
  // Reviewer groups the user belongs to (case-insensitive display-name match), managed
  // separately per forge. When the user is viewing "reviews needed" AND has configured
  // groups for a repo's provider, we broaden that repo's fetch to all open PRs so we can
  // also surface PRs where one of the user's groups is a reviewer (the forge reviewerId
  // filter only returns DIRECT reviewer PRs).
  const _cfSt = settings.getSettings();
  const _cfNormGroups = (a) => (a || []).map(g => String(g || '').trim()).filter(Boolean);
  const ghGroups = _cfNormGroups(_cfSt.codeflowMyGroupsGithub);
  const adoGroups = _cfNormGroups(_cfSt.codeflowMyGroupsAzdo);
  const legacyGroups = _cfNormGroups(_cfSt.codeflowMyGroups);
  // Provider-appropriate list, falling back to the legacy combined list when a forge-specific
  // list hasn't been set (back-compat with the single-list era).
  const groupsForProvider = (provider) => {
    const specific = provider === 'github' ? ghGroups : adoGroups;
    return specific.length ? specific : legacyGroups;
  };
  const perRepo = await Promise.all(repos.map(async (r) => {
    const provider = providerOf(r);
    const F = forge(r);
    const me = userByKey[idKey(r)];
    if (!me || !me.id) { errors.push({ repo: r.repo, error: 'identity unavailable' }); return []; }
    const myGroups = groupsForProvider(provider);
    const reviewsWithGroups = view === 'reviews' && myGroups.length > 0;
    try {
      // 'mine' → PRs I authored; 'reviews' → PRs that list me as a reviewer;
      // 'active' → every open PR in the repo (no person filter — a broad listing).
      //
      // reviewsWithGroups is the rate-limit-sensitive path: with a group configured we
      // still want group-reviewer PRs, but we must NOT fully enrich every open PR (that's
      // ~8-10 GitHub calls each across large repos, run every few minutes by the attention
      // poll → blows the 5000/hr limit). Instead we fetch my DIRECT-review set (cheap,
      // server-filtered, and includes the already-reviewed-but-open union) PLUS a broad
      // LIST, then keep only the handful of PRs a group of mine reviews using list data
      // alone (zero per-PR calls). Only that small union gets enriched below.
      const runLite = view === 'active' || view === 'other' || reviewsWithGroups;
      const [repoContributors, approverIndex] = await Promise.all([
        F.getRepoContributors(r.org, r.project, r.repo).catch(() => []),
        runLite ? Promise.resolve([]) : _cfApproverIndex(r)
      ]);
      const meId0 = String(me.id || '').toLowerCase();
      let prs;
      if (reviewsWithGroups) {
        const [direct, all] = await Promise.all([
          F.listPullRequests(r.org, r.project, r.repo, { reviewerId: me.id }).catch(() => []),
          F.listPullRequests(r.org, r.project, r.repo, { top: 100 }).catch(() => [])
        ]);
        const seen = new Set(direct.map(p => String(p.id)));
        const groupPrs = all.filter(p => {
          if (seen.has(String(p.id))) return false;
          if (String((p.createdBy && p.createdBy.id) || '').toLowerCase() === meId0) return false;
          return _cfListReviewerFlags(p, me, myGroups).amGroup;
        });
        prs = direct.concat(groupPrs);
      } else {
        const filter = view === 'mine' ? { creatorId: me.id }
                     : (view === 'active' || view === 'other') ? { top: 100 }
                     : { reviewerId: me.id };
        prs = await F.listPullRequests(r.org, r.project, r.repo, filter);
      }
      const meId = String(me.id || '').toLowerCase();
      const opts = { repoContributors, approverIndex, devCardIndex, viewerName: me.name, viewerEmail: me.email, lite: runLite, provider, myGroups };
      const enriched = (await Promise.all(prs.map(async (pr) => {
        const dkey = _cfWtKey({ org: pr.org || r.org, project: pr.project || r.project, repo: pr.repo || r.repo, prId: pr.pullRequestId || pr.id, provider });
        const isDismissed = !!dismissedMap[dkey];
        // "Other PRs" (view==='other') = ONLY dismissed PRs; every other view HIDES them.
        if (view === 'other') { if (!isDismissed) return null; }
        else if (isDismissed) return null;
        // Exclude PRs I authored from any non-'mine' view — my own PR belongs only under
        // "My PRs", never under Active/Reviews (GitHub also empties requested_reviewers on
        // review submit, which could otherwise let my own PR leak into the reviews list).
        // (The Other PRs page keeps whatever the user chose to stash, incl. their own.)
        if (view !== 'mine' && view !== 'other' && String((pr.createdBy && pr.createdBy.id) || '').toLowerCase() === meId) return null;
        const e = await _enrichCodeflowPr(pr, me.id, opts);
        // reviewsWithGroups broadened the fetch to all open PRs — keep only the ones that
        // are actually mine to review (direct reviewer or one of my groups).
        if (reviewsWithGroups && !e.amReviewer && !e.amGroupReviewer) return null;
        const a = _codeflowAttention(e, view);
        const notes = notesMap[dkey];
        return { ...e, provider, dismissed: isDismissed, attention: view === 'other' ? false : a.attention, attentionReason: view === 'other' ? '' : a.reason, repoId: r.id, notes: Array.isArray(notes) ? notes : [] };
      }))).filter(Boolean);
      return enriched;
    } catch (e) {
      errors.push({ repo: r.repo, error: e.message });
      return [];
    }
  }));

  const pullRequests = perRepo.flat().sort((a, b) => {
    if (a.attention !== b.attention) return a.attention ? -1 : 1;
    return new Date(b.creationDate || 0) - new Date(a.creationDate || 0);
  });
  const attentionCount = pullRequests.filter(p => p.attention).length;
  return { view, repos, pullRequests, attentionCount, errors };
}

app.get('/api/codeflow/pullrequests', async (req, res) => {
  const view = (req.query.view === 'reviews' || req.query.view === 'active' || req.query.view === 'other') ? req.query.view : 'mine';
  const refresh = req.query.refresh === '1' || req.query.refresh === 'true';
  try {
    const cached = _codeflowCache.get(view);
    if (!refresh && cached && (Date.now() - cached.at) < CODEFLOW_TTL_MS) {
      return res.json({ ...cached.data, cached: true, fetchedAt: new Date(cached.at).toISOString() });
    }
    const data = await _gatherCodeflow(view);
    _codeflowCache.set(view, { at: Date.now(), data });
    res.json({ ...data, cached: false, fetchedAt: new Date().toISOString() });
  } catch (e) { res.status(502).json({ error: e.message }); }
});

// Lightweight attention counts for the menu badge (both views).
app.get('/api/codeflow/attention', async (req, res) => {
  try {
    const out = { mine: 0, reviews: 0, mineActive: 0 };
    for (const view of ['mine', 'reviews', 'other']) {
      const cached = _codeflowCache.get(view);
      let data;
      if (cached && (Date.now() - cached.at) < CODEFLOW_TTL_MS) data = cached.data;
      else { data = await _gatherCodeflow(view); _codeflowCache.set(view, { at: Date.now(), data }); }
      out[view] = data.attentionCount || 0;
      if (view === 'mine') out.mineActive = (data.pullRequests || []).length;
      if (view === 'reviews') out.reviewsActive = (data.pullRequests || []).length;
      if (view === 'other') out.otherActive = (data.pullRequests || []).length;
    }
    out.total = out.mine + out.reviews;
    res.json(out);
  } catch (e) { res.status(502).json({ error: e.message }); }
});

// --- Code Flow AI insights: per-PR summaries + urgency scores. ---
// One runChat over the whole view's PR list (cheaper than per-PR). Cached by
// view + PR-id signature; mirrors the "Design with AI" fenced-JSON pattern.
function _codeflowAiPrompt(view, prs) {
  const compact = prs.map(p => ({
    id: p.id,
    title: p.title,
    repo: p.repo,
    isDraft: !!p.isDraft,
    ageDays: p.ageDays,
    approvalState: p.approvalState || '',
    failedChecks: p.failedChecks || 0,
    pendingChecks: p.pendingChecks || 0,
    activeComments: (p.comments && p.comments.activeComments) || 0,
    resolvedComments: (p.comments && p.comments.resolvedComments) || 0,
    readyToMerge: !!p.readyToMerge,
    attentionReason: p.attentionReason || '',
    myVote: p.myVote || null,
    createdBy: (p.createdBy && p.createdBy.name) || '',
    description: (p.description || '').slice(0, 600)
  }));
  const role = view === 'reviews'
    ? "You are triaging pull requests that need THIS engineer's review."
    : 'You are triaging pull requests that THIS engineer authored.';
  const urgencyGuide = view === 'reviews'
    ? 'Higher urgency for: PRs awaiting your review, teammates blocked waiting on you, long-open PRs, and PRs whose checks are failing.'
    : 'Higher urgency for: ready-to-merge, failing checks, changes requested, reviewers waiting, and long-open PRs. Drafts are usually low urgency.';
  return [
    role,
    'For EACH pull request, write a concise one-sentence plain-text summary (<= 160 chars) of what the PR does and its current state, and assign an urgency score from 0-100 (higher = more time-sensitive) with a very short reason (<= 80 chars).',
    urgencyGuide,
    'Return ONLY a single fenced ```json code block containing a JSON array of objects, one per PR, shaped exactly: {"id": <number>, "summary": <string>, "urgency": <integer 0-100>, "urgencyReason": <string>}. No prose outside the code block.',
    'Pull requests:',
    '```json',
    JSON.stringify(compact),
    '```'
  ].join('\n');
}
function _parseCodeflowAi(text) {
  if (!text) return null;
  let body = text;
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) body = fence[1];
  else {
    const s = text.indexOf('['), e = text.lastIndexOf(']');
    if (s >= 0 && e > s) body = text.slice(s, e + 1);
  }
  try { const arr = JSON.parse(body); return Array.isArray(arr) ? arr : null; }
  catch { return null; }
}
async function _codeflowGenerateAi(view, refresh) {
  // Use cached view data if fresh, else gather it.
  let cached = _codeflowCache.get(view), data;
  if (cached && (Date.now() - cached.at) < CODEFLOW_TTL_MS) data = cached.data;
  else { data = await _gatherCodeflow(view); _codeflowCache.set(view, { at: Date.now(), data }); }
  const prs = data.pullRequests || [];
  if (!prs.length) return { view, insights: [], generatedAt: new Date().toISOString() };

  // Per-PR cache keyed by id, validated against the volatile signature. We only
  // pay the model for PRs that are new or whose state actually changed.
  let store = _codeflowAiCache.get(view);
  if (!store) { store = new Map(); _codeflowAiCache.set(view, store); }
  const toGenerate = prs.filter(p => {
    if (refresh) return true;
    const hit = store.get(String(p.id));
    return !hit || hit.sig !== (p.signature || '');
  });

  if (toGenerate.length) {
    const prompt = _codeflowAiPrompt(view, toGenerate);
    let arr = null, text = '';
    for (let attempt = 0; attempt < 2 && !arr; attempt++) {
      let acc = '';
      const result = await sdkRunner.runChat({
        config: null, prompt, sessionId: require('crypto').randomUUID(),
        resume: false, cwd: __dirname, availableTools: [], onChunk: (c) => { acc += c; },
        meta: { source: 'system', category: 'pull_requests' }
      });
      text = acc.trim() ? acc : (result.output || '');
      arr = _parseCodeflowAi(text);
    }
    if (!arr) {
      // Insights are best-effort — a rare parse miss must not paint the console red.
      // Return whatever we already have (possibly empty) as a soft success; the client
      // renders the PRs immediately and simply lacks AI summaries for this pass.
      const insights = prs.map(p => (store.get(String(p.id)) || {}).insight).filter(Boolean);
      return { view, insights, generatedAt: new Date().toISOString(), generated: 0, soft: true };
    }
    const byId = new Map(arr.map(x => [String(x.id), x]));
    for (const p of toGenerate) {
      const m = byId.get(String(p.id)) || {};
      let urg = parseInt(m.urgency, 10);
      if (!Number.isFinite(urg)) urg = 0;
      store.set(String(p.id), {
        sig: p.signature || '',
        at: Date.now(),
        insight: {
          id: p.id,
          summary: String(m.summary || '').slice(0, 240),
          urgency: Math.max(0, Math.min(100, urg)),
          urgencyReason: String(m.urgencyReason || '').slice(0, 120)
        }
      });
    }
  }

  // Drop cache entries for PRs no longer in the view.
  const live = new Set(prs.map(p => String(p.id)));
  for (const k of [...store.keys()]) if (!live.has(k)) store.delete(k);

  const insights = prs.map(p => (store.get(String(p.id)) || {}).insight).filter(Boolean);
  return {
    view, insights,
    generatedAt: new Date().toISOString(),
    generated: toGenerate.length,
    cached: toGenerate.length === 0
  };
}

app.post('/api/codeflow/ai', async (req, res) => {
  const bview = req.body && req.body.view;
  const view = (bview === 'reviews' || bview === 'active') ? bview : 'mine';
  const refresh = !!(req.body && req.body.refresh);
  try {
    // Coalesce identical concurrent non-refresh requests for the same view — the page
    // fires several at once and they'd otherwise all queue up behind each other.
    if (!refresh && _codeflowAiInflight.has(view)) {
      return res.json(await _codeflowAiInflight.get(view));
    }
    // Serialize every generation through one chain so concurrent runChat calls can't
    // corrupt each other's streamed output.
    const run = _codeflowAiChain.then(() => _codeflowGenerateAi(view, refresh));
    _codeflowAiChain = run.then(() => {}, () => {}); // keep the chain alive on either outcome
    if (!refresh) {
      _codeflowAiInflight.set(view, run);
      run.finally(() => { if (_codeflowAiInflight.get(view) === run) _codeflowAiInflight.delete(view); });
    }
    res.json(await run);
  } catch (e) { res.status(502).json({ error: e.message }); }
});


// --- Code Flow: per-PR "review worktree" experience. ---------------------
// Mirrors the Dev Card worktree flow but for a pull request: create a git
// worktree against the PR's source branch, scaffold a read-only REVIEW agent
// into it (understand the PR + work item + system, analyze the diff, judge
// quality, suggest validations/changes, flag concerns, write an HTML review
// report), and surface the cached report on the Code Flow card. The worktree,
// agent file, and report all live under the profile DATA_DIR and the agent +
// report are git-excluded inside the worktree, so nothing is ever committed.
const CODEFLOW_REPORT_BOARD = 'codeflow-pr'; // namespace for the report cache

// Stable, filesystem-safe id for the report cache + worktree devId.
function _cfWtDevId(o) {
  // AzDo devIds stay byte-identical; GitHub is namespaced (empty project slot
  // would otherwise collapse `org--repo`).
  const parts = String(o.provider || 'azdo').toLowerCase() === 'github'
    ? ['cfpr-gh', o.org, o.repo, o.prId]
    : ['cfpr', o.org, o.project, o.repo, o.prId];
  return parts.join('-')
    .replace(/[^A-Za-z0-9._-]+/g, '-').replace(/-+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80).toLowerCase();
}
function _cfReviewAgentSlug(o) {
  const pid = o.prId != null ? o.prId : o.id;
  return ('review-' + (o.repo || 'repo') + '-pr' + pid)
    .replace(/[^A-Za-z0-9._-]+/g, '-').replace(/-+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60).toLowerCase() || 'pr-review-agent';
}
// Slug for the STEWARD agent that tends YOUR OWN PR (mine view): reviews, then
// addresses reviewer feedback, hardens the change, and validates it.
function _cfStewardAgentSlug(o) {
  const pid = o.prId != null ? o.prId : o.id;
  return ('steward-' + (o.repo || 'repo') + '-pr' + pid)
    .replace(/[^A-Za-z0-9._-]+/g, '-').replace(/-+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60).toLowerCase() || 'pr-steward-agent';
}
// Which agent persona applies to a worktree, from its view. "mine" → steward
// (review + fix + harden), anything else → read-only reviewer.
function _cfAgentKindForView(view) {
  return String(view || '').toLowerCase() === 'mine' ? 'steward' : 'reviewer';
}
// The directory the CLI/Open buttons actually land on for a PR worktree — which
// can DIFFER from rec.worktreePath when another worktree is checked out on the
// branch (the open-dir endpoint reuses that one). Read-only resolve (never
// mutates git). Falls back to the worktree path.
function _cfUsableDir(rec) {
  const current = rec && rec.worktreePath ? rec.worktreePath : '';
  if (!current) return '';
  try {
    const r = devitems.resolveUsableWorktree({
      org: rec.org, project: rec.project, repo: rec.repo,
      provider: rec.provider, sourceBranch: rec.sourceBranch, current, readOnly: true
    });
    return (r && r.dir) || current;
  } catch { return current; }
}
// Every worktree dir the CLI could open for this PR's branch: the review/steward
// worktree itself PLUS any other worktree currently checked out on the source
// branch (e.g. a dev card's Work worktree). The `.agent.md` must exist in ALL of
// them, because the user can launch the CLI from any one — and the resolver
// (`resolveUsableWorktree`) may land on a sibling worktree that never had it.
function _cfAgentTargetDirs(rec) {
  const dirs = [];
  const seen = new Set();
  const add = (d) => {
    if (!d) return;
    let key; try { key = path.resolve(String(d)).toLowerCase(); } catch { key = String(d).toLowerCase(); }
    if (seen.has(key)) return;
    try { if (!fs.existsSync(d)) return; } catch { return; }
    seen.add(key); dirs.push(d);
  };
  add(rec && rec.worktreePath);
  const br = String((rec && rec.sourceBranch) || '').replace(/^refs\/heads\//, '').trim();
  if (br) {
    try {
      const wts = devitems.listWorktrees(rec && rec.org, rec && rec.project, rec && rec.repo, rec && rec.provider) || [];
      for (const w of wts) if (w && !w.detached && w.branch === br) add(w.path);
    } catch { /* ignore */ }
  }
  return dirs;
}

// Self-healing presence: the steward/reviewer `.agent.md` is git-excluded and
// lives only inside a worktree, so worktree churn (recreate/clean, or a NEW
// sibling worktree checked out on the branch after the agent was written) can
// leave the dir the CLI opens without it — the CLI then errors "Custom agent ...
// not found" while the card still reads "Ready". This ensures the file exists in
// EVERY on-branch worktree by copying it from whichever one still has it. Only if
// NO worktree has a copy does it report missing (so the card flips to "Agent file
// missing" + the recreate button). Cheap, best-effort, never throws. Returns
// { agentKind, agentName, agentPresent }.
function _cfEnsureAgentFile(rec) {
  const kind = _cfAgentKindForView(rec && rec.view);
  const idish = { org: rec && rec.org, project: rec && rec.project, repo: rec && rec.repo, prId: rec && rec.prId };
  const slug = kind === 'steward' ? _cfStewardAgentSlug(idish) : _cfReviewAgentSlug(idish);
  const rel = path.join('.github', 'agents', slug + '.agent.md');
  const relPosix = '.github/agents/' + slug + '.agent.md';
  const dirs = _cfAgentTargetDirs(rec);
  const fileIn = (d) => path.join(d, rel);
  const hasIn = (d) => { try { return fs.existsSync(fileIn(d)); } catch { return false; } };
  // Find a surviving copy to seed the others from.
  let src = '';
  for (const d of dirs) { if (hasIn(d)) { src = d; break; } }
  if (src) {
    let content = null;
    try { content = fs.readFileSync(fileIn(src)); } catch { /* ignore */ }
    if (content != null) {
      for (const d of dirs) {
        if (d === src || hasIn(d)) continue;
        try {
          fs.mkdirSync(path.dirname(fileIn(d)), { recursive: true });
          fs.writeFileSync(fileIn(d), content);
          try { devitems.addGitExclude(d, relPosix); } catch {}
          try { devitems.addGitExclude(d, CODEFLOW_REPORT_NAME); } catch {}
          try { devitems.addGitExclude(d, CODEFLOW_COMMENTS_NAME); } catch {}
        } catch { /* ignore */ }
      }
    }
  }
  const present = !!src && dirs.length > 0 && dirs.every(hasIn);
  return { agentKind: kind, agentName: slug, agentPresent: present };
}

// Resolve the agent that SHOULD tend a worktree's PR and whether its .agent.md is
// actually present where the CLI opens. Delegates to the self-healing ensure so a
// transient miss (a fresh sibling worktree) is fixed automatically and a "Ready"
// card never lies about an agent the CLI can't find. Returns { agentKind,
// agentName, agentPresent, agentOpenDir? }.
function _cfAgentPresence(rec) {
  let base;
  try { base = _cfEnsureAgentFile(rec); }
  catch { base = { agentKind: _cfAgentKindForView(rec && rec.view), agentName: '', agentPresent: false }; }
  const out = { agentKind: base.agentKind, agentName: base.agentName, agentPresent: base.agentPresent };
  try {
    const wt = rec && rec.worktreePath;
    const openDir = _cfUsableDir(rec);
    if (openDir && wt && openDir !== wt) out.agentOpenDir = openDir;
  } catch { /* ignore */ }
  return out;
}

// Head-repository verification protocol shared by BOTH the reviewer and steward
// personas. Cross-repository (fork) PRs are the DEFAULT assumption here: the PR's
// head can live in a fork while `origin` points only at the base repo, and a
// same-named branch on the base repo can silently mask a wrong target. This block
// forces the agent to resolve the head repo/branch/OID up front, prove the
// checkout matches by SHA (never by branch name), and treat a green `git push` as
// unproven until re-verified. Guardrail added after a cross-repo PR was edited on
// the wrong (base-repo) branch mirror. Returns an array of markdown lines.
function _cfHeadFactsBlock(pr) {
  const provider = String(pr.provider || '').toLowerCase();
  const isGh = provider === 'github';
  const cross = !!pr.isCrossRepo;
  const headRepoFull = pr.headRepoFullName || (isGh ? '(resolve it — see below)' : '');
  const baseRepoFull = pr.baseRepoFullName || [pr.org, pr.project, pr.repo].filter(Boolean).join('/');
  const headRef = pr.headRef || pr.sourceBranch || '';
  const headSha = pr.headSha || '';
  const headOwner = pr.headOwner || (headRepoFull.split('/')[0] || '');
  const headRepoName = pr.headRepo || (headRepoFull.split('/')[1] || pr.repo || '');
  const L = [];
  L.push('## Head repository & branch — VERIFY before you touch git');
  L.push('Treat this as a **cross-repository (fork) PR by default** and confirm the facts before trusting *any* remote. The single most damaging mistake here is editing/pushing the wrong branch because you assumed `origin/<branch>` was the PR head.');
  L.push('');
  L.push('- Base (target) repo: `' + (baseRepoFull || '(unknown)') + '`  ·  base branch: `' + (pr.targetBranch || 'main') + '`');
  L.push('- Head (source) repo: `' + (headRepoFull || '(unknown)') + '`  ·  head branch: `' + (headRef || '(unknown)') + '`');
  if (headSha) L.push('- Head commit (the PR\'s TRUE tip): `' + headSha + '`');
  L.push('- Cross-repository: **' + (cross ? 'YES — the head lives in a FORK, not the base repo' : (pr.isCrossRepo === false ? 'no (same repo)' : 'UNKNOWN — assume YES until you prove otherwise')) + '**');
  L.push('');
  L.push('**Do these first, every time — in order:**');
  L.push('1. **Resolve the head up front; do not assume.** Re-confirm the head repo/branch/OID from the forge itself:');
  if (isGh) {
    L.push('   ```');
    L.push('   gh pr view ' + pr.id + ' --json headRepository,headRepositoryOwner,headRefName,headRefOid,isCrossRepository');
    L.push('   ```');
  } else {
    L.push('   - Azure DevOps: read the PR\'s `sourceRefName` and its last source commit id from the PR API (`az repos pr show --id ' + pr.id + '`), and note whether the fork repo differs from the target repo.');
  }
  L.push('2. **Prove the checkout matches the PR — by SHA, not by name.** This worktree should already sit at the head commit; verify it: `git rev-parse HEAD` must equal the resolved head OID' + (headSha ? ' (`' + headSha + '`)' : '') + '. If they diverge, **STOP and warn** — do not analyze, edit, build, or commit against a mismatched checkout.');
  L.push('3. **Never assume `origin/<branch>` is the PR head.** `origin` may point only at the **base** repo. For a fork PR, add the fork as an explicit remote and work against it:');
  if (isGh && headOwner && headRepoName) {
    L.push('   ```');
    L.push('   git remote add prhead https://github.com/' + headOwner + '/' + headRepoName + '.git 2>/dev/null; git fetch prhead ' + (headRef || '<headRef>'));
    L.push('   git rev-parse prhead/' + (headRef || '<headRef>') + '   # must equal the head OID above');
    L.push('   ```');
  } else {
    L.push('   Add the head/fork repo as a distinct remote, fetch the head branch from *that* remote, and confirm its tip equals the head OID above.');
  }
  L.push('4. **Same-named branches are a hazard.** A branch with the SAME name can exist on the base repo at a DIFFERENT commit (a stale/sandbox mirror) and silently mask a wrong-target fetch or push. Always match by **commit SHA**, never by branch name alone.');
  L.push('5. **A green `git push` is NOT proof.** If you (or the human) push, treat it as unverified until you re-read the PR\'s `headRefOid` and file list and confirm the tip equals the SHA you pushed AND the expected files changed. If the PR didn\'t move, you pushed to the wrong repo/branch — surface it loudly.');
  L.push('');
  return L;
}

// The review agent persona. Read-only by design: it analyzes and reports, it
// does NOT change the PR's code or push anything.
function _buildReviewAgentMd({ agentName, pr, workItems, worktreePath, reportName, commentsName }) {
  const desc = 'Read-only PR review agent for ' + (pr.repo || 'repo') + ' #' + pr.id;
  const fm = ['---', 'name: ' + agentName, 'description: ' + JSON.stringify(desc), '---', ''].join('\n');
  return fm + _reviewPersonaBody({ pr, workItems, reportName, commentsName });
}

// The reviewer persona body (everything after the agent-file frontmatter). Shared
// by the .agent.md the user opens in VS Code/CLI AND the headless "Review with AI"
// run, so both follow the exact same disciplined review + report contract.
function _reviewPersonaBody({ pr, workItems, reportName, commentsName = CODEFLOW_COMMENTS_NAME }) {
  const ctx = [];
  ctx.push('## The pull request under review');
  ctx.push(`- **#${pr.id}** ${pr.title || ''}`);
  ctx.push('- ' + [pr.org, pr.project, pr.repo].filter(Boolean).join(' / ') +
    `  (source \`${pr.sourceBranch || ''}\` → target \`${pr.targetBranch || 'main'}\`)`);
  if (pr.status) ctx.push('- Status: ' + pr.status + (pr.isDraft ? ' (draft)' : ''));
  if (pr.createdBy && pr.createdBy.name) ctx.push('- Author: ' + pr.createdBy.name);
  if (pr.url) ctx.push('- Link: ' + pr.url);
  if (pr.description) ctx.push('- Description: ' + String(pr.description).slice(0, 600).replace(/\s+/g, ' '));
  ctx.push('');
  if (workItems && workItems.length) {
    ctx.push('## Associated work item(s)');
    for (const wi of workItems) {
      ctx.push(`- **#${wi.id} [${wi.type}]** ${wi.title} — ${wi.state}${wi.assignedTo ? ' · ' + wi.assignedTo : ''}`);
      if (wi.url) ctx.push('  - ' + wi.url);
    }
    ctx.push('');
  } else {
    ctx.push('## Associated work item');
    ctx.push('- No linked work item was detected automatically. **Look for one yourself** — check the PR description, commit messages, and branch name for a work-item id (e.g. `AB#12345`) and reason about the original intent before reviewing.');
    ctx.push('');
  }
  for (const l of _cfHeadFactsBlock(pr)) ctx.push(l);
  ctx.push('## This worktree');
  ctx.push('- This worktree is checked out to the PR\'s source branch `' + (pr.sourceBranch || '') +
    '`, so the changes are already present. Diff against the target branch to see exactly what this PR proposes:');
  ctx.push('  ```');
  ctx.push('  git fetch origin ' + (pr.targetBranch || 'main'));
  ctx.push('  git diff origin/' + (pr.targetBranch || 'main') + '...HEAD');
  ctx.push('  ```');
  ctx.push('');
  const body = `You are a meticulous, senior **code reviewer**. You are reviewing the pull request described below. You **analyze and report only** — you do not change the PR's code, commit, or push.

## Voice
Write plain, direct, familiar prose — like a colleague leaving review notes, not a chatbot. No flattery, no hedging, no "great work!" / "happy to help" / "I hope this helps". Don't open with praise or apologize. Skip filler and self-narration about being an AI. State what you found and what to do; if something is wrong, say so plainly. Brevity over politeness.

${ctx.join('\n')}
## Your review, in order
Work through this disciplined review and narrate which step you are on:
1. **Understand the goals.** Read the PR title/description and any linked work item to understand *what this change is trying to achieve* and the acceptance criteria. State the goals in your own words.
2. **Understand the associated work item.** If a work item is linked (or you find one), open it and capture the requirements/intent. If none exists, say so and infer intent from the PR + commits.
3. **Understand the system.** Before judging the diff, study the surrounding code, architecture, and existing patterns this change touches — so your review is grounded in how this codebase actually works.
4. **Analyze the changes.** Walk the full diff (use the \`git diff\` against the target branch shown above). Summarize what changed, file by file where it matters, and how the pieces fit together.
5. **Assess code quality.** Judge correctness, edge cases, error handling, security, performance, readability, naming, test coverage, and consistency with the codebase's conventions. Call out concrete issues with file/line references and severity.
6. **Suggest validations.** Recommend concrete validations that would *increase confidence* in this PR — specific tests to add or run, CI/build gates, manual repro steps, measurements/benchmarks, or data to capture. Be specific (what to test and why).
7. **Suggest additional changes.** Propose changes that would make the PR better meet its goals / the work item — missing cases, follow-ups, refactors, docs, or hardening — distinguishing must-fix from nice-to-have.
8. **Highlight concerns & risks.** Surface anything risky, ambiguous, or blocking: regressions, breaking changes, scope creep, unhandled failure modes, or things a human reviewer must decide.
9. **Write the review report (HTML).** Produce the report described below.

## Review report (HTML)
Write a **self-contained** HTML review named \`${reportName}\` at the root of this worktree (overwrite/refresh it as you learn more). Requirements:
- **Single file, inline all CSS/JS** — no external assets or CDNs, so it opens correctly from disk. Any chart must render offline (inline SVG / pure-CSS bars).
- **Theme-friendly.** The host re-themes the report for light/dark automatically, so use the standard skeleton class names below and DON'T hard-force a full-page background/color that fights re-theming. Use these semantic classes where they apply: the verdict banner \`<div class="verdict approve|needs-work|blocked">\`; severity spans \`sev-blocker\`/\`sev-major\`/\`sev-minor\`/\`sev-nit\`; the timestamp/byline line \`<p class="meta">\`; and plain \`<table>\`/\`<th>\`/\`<code>\`/\`<pre>\` for tabular/code content.
- **Cover these sections, in order:**
  1. **Overview** — the PR (id + link), the author, the associated work item (id + link), and your one-paragraph verdict (approve / approve-with-suggestions / needs-work / blocked) with a short justification.
  2. **Goals** — what the PR set out to do, and whether the change appears to meet them.
  3. **Summary of changes** — what changed across the diff, concise but specific (files/areas, approach).
  4. **File diff (by file)** — include the **complete diff this PR proposes** (from \`git diff origin/${pr.targetBranch || 'main'}...HEAD\`), **split per file**: for each changed file a \`<h3>\` heading with the repo-relative path, followed by that file's unified hunks in a \`<pre class="diff">\`. Wrap added lines in \`<span class="diff-add">\`, removed lines in \`<span class="diff-del">\`, and hunk headers (\`@@ ... @@\`) in \`<span class="diff-hunk">\`, and **HTML-escape** the code so it renders literally. Include **every** changed file; you may elide only very large generated/lock/binary files, noting the omission and the line count.
  5. **Code quality findings** — a **table** of findings with columns: *file/area · severity (blocker/major/minor/nit) · issue · suggested fix*. Color severities for fast scanning.
  6. **Suggested validations** — concrete tests/gates/measurements to raise confidence.
  7. **Suggested additional changes** — improvements to better meet the PR/work-item goals (must-fix vs nice-to-have).
  8. **Concerns & risks** — blocking or ambiguous items a human must weigh in on.
- **Lead with the verdict.** Make the bottom line obvious at the top; keep the layout calm, professional, timestamped, with the PR id/link.

## Machine-readable findings (JSON)
In addition to the HTML report, write a **second** file named \`${commentsName}\` at the root of this worktree — a machine-readable list of your concrete **code quality findings** so they can be posted to the PR as review comments. Requirements:
- **Valid JSON only**, exactly this shape:
  \`\`\`json
  {"summary": "<one-line overall verdict>", "comments": [{"file": "relative/path/from/repo/root.ext", "line": 123, "severity": "blocker|major|minor|nit", "title": "<short title>", "body": "<the finding>", "suggestion": "<concrete suggested fix, optional>"}]}
  \`\`\`
- One entry per concrete finding from your **Code quality findings** table. \`file\` is the repo-relative path (forward slashes) and \`line\` is the line number in the **new/right** version of that file. If a finding is not tied to a specific line, omit \`line\` (or set it to null) — it will be posted as a general PR comment.
- Keep \`body\` self-contained and actionable; include the suggested fix in \`suggestion\` when you have one.
- Only include real, defensible findings — do not pad. An empty \`comments\` array is fine if the PR is clean.


- **Never check yourself in.** NEVER stage, commit, push, or otherwise include your own agent definition (any file under \`.github/agents/\`), your generated review report (\`${reportName}\`), or the machine-readable findings (\`${commentsName}\`). They stay untracked.
- If you notice a \`.github/agents/*.agent.md\` file, the report file, or \`${commentsName}\` in \`git status\`, leave them untracked and never add them.
`;
  return body + _systemAgentInstr('codeflow-reviewer');
}

// The PR STEWARD persona body. For YOUR OWN pull request (Code Flow "mine"
// view): it does everything the reviewer does, but is NOT read-only — it
// addresses reviewer feedback, hardens the change, validates it, and commits
// the fixes locally (the human pushes from the card). Shared by the .agent.md
// the user opens AND the headless "Tend with AI" run, so both follow the same
// contract.
function _stewardPersonaBody({ pr, workItems, threads = [], reportName, commentsName = CODEFLOW_COMMENTS_NAME }) {
  const ctx = [];
  ctx.push('## Your pull request');
  ctx.push(`- **#${pr.id}** ${pr.title || ''}`);
  ctx.push('- ' + [pr.org, pr.project, pr.repo].filter(Boolean).join(' / ') +
    `  (source \`${pr.sourceBranch || ''}\` → target \`${pr.targetBranch || 'main'}\`)`);
  if (pr.status) ctx.push('- Status: ' + pr.status + (pr.isDraft ? ' (draft)' : ''));
  if (pr.createdBy && pr.createdBy.name) ctx.push('- Author: ' + pr.createdBy.name);
  if (pr.url) ctx.push('- Link: ' + pr.url);
  if (pr.description) ctx.push('- Description: ' + String(pr.description).slice(0, 600).replace(/\s+/g, ' '));
  ctx.push('');
  if (workItems && workItems.length) {
    ctx.push('## Associated work item(s)');
    for (const wi of workItems) {
      ctx.push(`- **#${wi.id} [${wi.type}]** ${wi.title} — ${wi.state}${wi.assignedTo ? ' · ' + wi.assignedTo : ''}`);
      if (wi.url) ctx.push('  - ' + wi.url);
    }
    ctx.push('');
  } else {
    ctx.push('## Associated work item');
    ctx.push('- No linked work item was detected automatically. **Look for one yourself** — check the PR description, commit messages, and branch name for a work-item id (e.g. `AB#12345`) and reason about the original intent.');
    ctx.push('');
  }
  // Embed the real, unresolved reviewer feedback so the steward addresses it
  // concretely rather than guessing.
  ctx.push('## Active reviewer feedback to address');
  if (threads && threads.length) {
    ctx.push('These are the **unresolved** comment threads on the PR. Address every one — fix the code where a change is warranted, or draft a clear reply where it is a question or you disagree:');
    ctx.push('');
    let n = 0;
    for (const t of threads) {
      n++;
      const where = t.file ? ('`' + t.file + '`' + (t.line ? ':' + t.line : '')) : '(general discussion)';
      ctx.push(`${n}. **${where}** — thread #${t.id} (${t.status})`);
      for (const c of (t.comments || [])) {
        ctx.push(`   - **${c.author}:** ${String(c.text).slice(0, 800).replace(/\s+/g, ' ')}`);
      }
    }
    ctx.push('');
  } else {
    ctx.push('- No unresolved review comments were detected automatically. **Still check yourself** (`git log`, the PR page) and treat your own self-review findings as the feedback to resolve.');
    ctx.push('');
  }
  for (const l of _cfHeadFactsBlock(pr)) ctx.push(l);
  ctx.push('## This worktree');
  ctx.push('- This worktree is checked out to **your PR\'s source branch** `' + (pr.sourceBranch || '') +
    '`, so your changes are already present and you may edit, build, test, and commit here.');
  ctx.push('- See exactly what your PR proposes by diffing against the target branch:');
  ctx.push('  ```');
  ctx.push('  git fetch origin ' + (pr.targetBranch || 'main'));
  ctx.push('  git diff origin/' + (pr.targetBranch || 'main') + '...HEAD');
  ctx.push('  ```');
  ctx.push('');

  const body = `You are a senior engineer **tending your own pull request**. This PR is *yours*: your job is not only to review it, but to make it genuinely excellent — resolve reviewer feedback, raise the quality bar, add the validation it needs, and guard against regressions. You **may edit, build, run, test, and commit** in this worktree. You do **not** push (the human pushes from the Code Flow card), and you **never** commit your own agent/report/scratch files.

## Voice
Write plain, direct, familiar prose — like a colleague working through their own PR, not a chatbot. No flattery, no hedging, no "great work!" / "happy to help" / "I hope this helps". Don't open with praise or apologize, and don't narrate being an AI. When replying to a reviewer, be straight and matter-of-fact: say what you changed or why you disagree, nothing more. Brevity over politeness.

${ctx.join('\n')}
## How to work, in order
Narrate which step you are on as you go:
1. **Understand the goals.** Read the PR title/description and any linked work item to understand what this change must achieve and its acceptance criteria. State the goals in your own words.
2. **Understand the system.** Study the surrounding code, architecture, and existing patterns this change touches so every change you make fits how this codebase actually works.
3. **Analyze the change.** Walk the full diff (\`git diff\` against the target branch above). Summarize what it does and how the pieces fit.
4. **Address every piece of reviewer feedback.** For each active thread above: understand the intent, then **make the code change** that resolves it. If it is a question or you genuinely disagree, draft a clear, respectful reply explaining your reasoning instead of changing code. Track, per thread, exactly what you did (resolved-by-change / replied / deferred-with-reason).
5. **Go above and beyond — harden the change.** Don't stop at the literal feedback. Proactively improve quality: add or extend **tests**, add **input validation** and **error handling**, cover **edge cases**, tighten naming/readability where it aids correctness, and remove foot-guns. Be deliberate — every change must be justified and in scope; do not gold-plate unrelated code.
6. **Prevent regressions.** Identify what this change could break (callers, contracts, data shapes, concurrency, performance) and add guards/tests that would catch a future regression. Call out anything you cannot fully cover.
7. **Validate.** Discover the repo's **existing** build/lint/test commands (package.json scripts, Makefile, CI yaml, README) and run the relevant ones. Iterate until they pass. Do **not** introduce new tooling/frameworks — use what the repo already has. Capture the exact commands you ran and their results.
8. **Self-review to the reviewer's bar.** Re-judge correctness, edge cases, error handling, security, performance, readability, test coverage, and convention-consistency. Fix what you find.
9. **Commit your work locally.** Stage only the real source/test/doc changes and commit with clear messages (split into logical commits if it helps). **Do NOT push** — the human pushes from the card. **Never** stage \`.github/agents/*\`, the report, or the findings file.
10. **Write the report + machine-readable file** described below.

## Steward report (HTML)
Write a **self-contained** HTML report named \`${reportName}\` at the root of this worktree (overwrite/refresh it as you learn more). Requirements:
- **Single file, inline all CSS/JS** — no external assets or CDNs, so it opens correctly from disk. Any chart must render offline (inline SVG / pure-CSS bars).
- **Theme-friendly.** The host re-themes the report for light/dark automatically, so use the standard skeleton class names and DON'T hard-force a full-page background/color. Use these semantic classes where they apply: the verdict banner \`<div class="verdict approve|needs-work|blocked">\`; severity spans \`sev-blocker\`/\`sev-major\`/\`sev-minor\`/\`sev-nit\`; the byline line \`<p class="meta">\`; and plain \`<table>\`/\`<th>\`/\`<code>\`/\`<pre>\` for tabular/code content.
- **Cover these sections, in order:**
  1. **Overview** — the PR (id + link), the author, the associated work item (id + link), and a one-paragraph bottom line: is the PR now ready to push / what still blocks it.
  2. **Goals** — what the PR set out to do, and whether it now meets them.
  3. **Feedback addressed** — a **table** with columns: *thread (file·line or "general") · reviewer comment · what you did · status (resolved-by-change / replied / deferred)*. One row per active thread above.
  4. **Changes made** — what you changed and why, concise but specific (files/areas, approach), and the commit message(s) you created.
  5. **File diff (by file)** — include the **complete diff** of the PR as it now stands after your commits (from \`git diff origin/${pr.targetBranch || 'main'}...HEAD\`), **split per file**: for each changed file a \`<h3>\` heading with the repo-relative path, followed by that file's unified hunks in a \`<pre class="diff">\`. Wrap added lines in \`<span class="diff-add">\`, removed lines in \`<span class="diff-del">\`, and hunk headers (\`@@ ... @@\`) in \`<span class="diff-hunk">\`, and **HTML-escape** the code so it renders literally. Include **every** changed file; you may elide only very large generated/lock/binary files, noting the omission and the line count.
  6. **Hardening & regression guards** — the above-and-beyond improvements: tests added, validation/error-handling added, edge cases covered, regression risks identified and how you guarded them.
  7. **Validations run** — the exact build/lint/test commands you ran and their results (pass/fail), in a \`<pre>\` or table.
  8. **Remaining risks & follow-ups** — anything still risky, deferred, or needing a human decision before merge.
- **Lead with the bottom line.** Make "ready to push?" obvious at the top; keep the layout calm, professional, timestamped, with the PR id/link.

## Machine-readable findings (JSON)
Also write a **second** file named \`${commentsName}\` at the root of this worktree — a machine-readable list of any **remaining recommendations** (things you did NOT change but a human should consider) so they can be surfaced. Requirements:
- **Valid JSON only**, exactly this shape:
  \`\`\`json
  {"summary": "<one-line: ready to push? what's left>", "comments": [{"file": "relative/path/from/repo/root.ext", "line": 123, "severity": "blocker|major|minor|nit", "title": "<short title>", "body": "<the recommendation>", "suggestion": "<concrete suggested fix, optional>"}]}
  \`\`\`
- One entry per remaining recommendation (NOT the things you already fixed). \`file\` is the repo-relative path (forward slashes) and \`line\` is the line number in the **new/right** version of that file; omit \`line\` (or null) for a general note.
- An empty \`comments\` array is fine if you fully addressed everything.

- **Push is the human's call.** Commit locally so your work is ready, but do **not** \`git push\` — the user pushes from the Code Flow card after reviewing your report.
- **Never check yourself in.** NEVER stage, commit, or otherwise include your own agent definition (any file under \`.github/agents/\`), your generated report (\`${reportName}\`), or the machine-readable findings (\`${commentsName}\`). If you notice any of them in \`git status\`, leave them untracked and never add them.
`;
  return body + _systemAgentInstr('codeflow-author');
}

// Build the steward agent .agent.md (frontmatter + steward persona body).
function _buildStewardAgentMd({ agentName, pr, workItems, threads, reportName, commentsName }) {
  const desc = 'PR steward for ' + (pr.repo || 'repo') + ' #' + pr.id + ' — reviews, fixes feedback, hardens & validates your own PR';
  const fm = ['---', 'name: ' + agentName, 'description: ' + JSON.stringify(desc), '---', ''].join('\n');
  return fm + _stewardPersonaBody({ pr, workItems, threads, reportName, commentsName });
}

// Write the per-PR agent into the worktree and git-exclude the agent file AND
// the report/findings it will generate, so none of them can land in the PR
// branch. The persona depends on the worktree's `view`: "mine" → STEWARD (review
// + fix feedback + harden + validate, may commit), anything else → read-only
// REVIEWER. `threads` (active reviewer feedback) is only used by the steward.
const CODEFLOW_REPORT_NAME = 'pr-review-report.html';
const CODEFLOW_COMMENTS_NAME = 'pr-review-comments.json';
function _writeCfReviewAgentFile(rec, pr, workItems, opts = {}) {
  const wt = rec.worktreePath;
  if (!wt || !fs.existsSync(wt)) return null;
  const kind = _cfAgentKindForView(opts.view != null ? opts.view : rec.view);
  const steward = kind === 'steward';
  const slug = steward ? _cfStewardAgentSlug(pr) : _cfReviewAgentSlug(pr);
  const rel = '.github/agents/' + slug + '.agent.md';
  const md = steward
    ? _buildStewardAgentMd({ agentName: slug, pr, workItems, threads: opts.threads || [], reportName: CODEFLOW_REPORT_NAME, commentsName: CODEFLOW_COMMENTS_NAME })
    : _buildReviewAgentMd({ agentName: slug, pr, workItems, worktreePath: wt, reportName: CODEFLOW_REPORT_NAME, commentsName: CODEFLOW_COMMENTS_NAME });
  // Write into EVERY worktree the CLI could open for this branch — the review
  // worktree plus any sibling worktree checked out on the same branch — so the CLI
  // always resolves the agent no matter which dir it lands in.
  const dirs = _cfAgentTargetDirs(rec);
  if (!dirs.length) dirs.push(wt);
  for (const d of dirs) {
    try {
      const agentsDir = path.join(d, '.github', 'agents');
      fs.mkdirSync(agentsDir, { recursive: true });
      fs.writeFileSync(path.join(agentsDir, slug + '.agent.md'), md);
      try { devitems.addGitExclude(d, rel); } catch {}
      try { devitems.addGitExclude(d, CODEFLOW_REPORT_NAME); } catch {}
      try { devitems.addGitExclude(d, CODEFLOW_COMMENTS_NAME); } catch {}
    } catch {}
  }
  return { reviewAgentName: slug, reviewAgentFile: rel, agentKind: kind };
}

// All review-worktree records (for frontend hydration). Returns an array.
// Opportunistically refreshes each record's prStatus from AzDO (throttled) so a
// PR that has since closed/merged correctly drops out of the "open" buckets and
// an active review PR is never mislabeled as closed. Best-effort; never throws.
const CF_PRSTATUS_TTL_MS = 45000;
app.get('/api/codeflow/pr/worktrees', async (req, res) => {
  _reconcileStaleReviews();   // unstick any orphaned "Running…" reviews before listing
  const map = loadCodeflowWorktrees();
  const now = Date.now();
  const stale = Object.keys(map).filter(k => {
    const r = map[k];
    return _cfPrOk(r) &&
      (!r.prStatusCheckedAt || (now - r.prStatusCheckedAt) > CF_PRSTATUS_TTL_MS);
  });
  await Promise.allSettled(stale.map(async k => {
    const r = map[k];
    try {
      const pr = await forge(r).getPullRequest(r.org, r.project, r.repo, r.prId);
      const save = { prStatusCheckedAt: now };
      if (pr && pr.status) {
        save.prStatus = String(pr.status).toLowerCase();
        if (pr.title) save.prTitle = pr.title;
        if (pr.url) save.prUrl = pr.url;
      }
      _saveCfWt(k, save);
    } catch {
      try { _saveCfWt(k, { prStatusCheckedAt: now }); } catch {}
    }
  }));
  const fresh = loadCodeflowWorktrees();
  res.json({ worktrees: Object.keys(fresh).map(k => ({ key: k, ...fresh[k] })) });
});

// Read the machine-readable review findings the AI reviewer writes alongside the
// HTML report. Returns { summary, comments[] } or null. Never throws.
function _readCfReviewComments(wtPath) {
  try {
    if (!wtPath) return null;
    const f = path.join(wtPath, CODEFLOW_COMMENTS_NAME);
    if (!fs.existsSync(f)) return null;
    const parsed = JSON.parse(fs.readFileSync(f, 'utf8'));
    const comments = Array.isArray(parsed && parsed.comments) ? parsed.comments : [];
    return { summary: (parsed && parsed.summary) || '', comments };
  } catch { return null; }
}

// Stable content fingerprint for a single review finding. The findings file has
// no IDs and its array indices shift whenever the reviewer regenerates it, so we
// content-address each finding (file/line/severity/title/body) to recognize the
// ones the user already posted to the PR. Same content => same fp across re-reads.
function _cfCommentFp(c) {
  try {
    const norm = (s) => String(s == null ? '' : s).replace(/\r\n/g, '\n').trim();
    const file = norm(c && c.file).replace(/^[\\/]+/, '').replace(/\\/g, '/');
    const line = (c && c.line != null && Number.isFinite(Number(c.line))) ? String(Number(c.line)) : '';
    const raw = [file, line, norm(c && c.severity).toLowerCase(), norm(c && c.title), norm(c && c.body)].join('\u0001');
    return require('crypto').createHash('sha1').update(raw).digest('hex').slice(0, 16);
  } catch { return ''; }
}
// The set of finding fingerprints already posted to a PR (persisted on the wt record).
function _cfPostedSet(rec) {
  return new Set(Array.isArray(rec && rec.postedComments) ? rec.postedComments : []);
}
// The set of finding fingerprints the user explicitly dismissed (won't post). Kept
// separate from posted so the card count and modal drop them without claiming they
// were sent to the PR.
function _cfDismissedSet(rec) {
  return new Set(Array.isArray(rec && rec.dismissedComments) ? rec.dismissedComments : []);
}
// Best-effort reconciliation: recognize findings the user posted to the PR before
// we tracked them (or from another machine) by matching our own posted format
// (the "_Posted from AI code review._" footer + the finding's title/body) against
// the PR's existing comment threads. Persists any newly-recognized fingerprints so
// the card count and modal stop re-offering them. Returns the (possibly updated) rec.
async function _cfReconcilePosted(o, key, rec, comments) {
  try {
    if (!Array.isArray(comments) || !comments.length) return rec;
    const threads = await forge(o).getPrActiveThreads(o.org, o.project, o.repo, o.prId, { max: 200 });
    const texts = [];
    for (const t of (threads || [])) for (const c of (t.comments || [])) {
      const tx = String(c.text || '');
      if (/Posted from AI code review/i.test(tx)) texts.push(tx.toLowerCase());
    }
    if (!texts.length) return rec;
    const have = _cfPostedSet(rec);
    let changed = false;
    for (const c of comments) {
      const fp = _cfCommentFp(c);
      if (!fp || have.has(fp)) continue;
      const title = String(c.title || '').trim().toLowerCase();
      const body = String(c.body || '').trim().toLowerCase();
      const probe = title.length >= 4 ? title : body.slice(0, 40);
      if (probe && texts.some(tx => tx.includes(probe))) { have.add(fp); changed = true; }
    }
    if (changed) return _saveCfWt(key, { postedComments: Array.from(have), postedCommentsAt: new Date().toISOString() });
  } catch {}
  return rec;
}

// Per-worktree throttle for origin fetches during drift polling. The 2s status poll
// must not `git fetch` every tick, but it also must not compare against an
// indefinitely-stale local `origin/<src>` ref (which reports a false "In sync" after
// someone pushes to the PR branch). So we fetch on ?refresh=1 OR at most once per
// this interval, letting a stale in-sync reading self-heal within ~a minute.
const _cfDriftFetchAt = new Map(); // wtKey -> last fetch epoch ms
const CF_DRIFT_FETCH_TTL_MS = 60000;

// One record (status poll). Re-scans + caches reports if the worktree is ready,
// so a review report written by the agent after opening gets picked up. Also
// surfaces PR-branch drift (local worktree vs origin/<sourceBranch>) and the
// count of AI review findings ready to post. Pass ?refresh=1 to force an immediate
// origin fetch; otherwise the poll fetches at most once per minute so drift stays
// accurate without a fetch on every 2s tick.
app.get('/api/codeflow/pr/worktree', (req, res) => {
  const o = { org: req.query.org, project: req.query.project, repo: req.query.repo, prId: req.query.prId, provider: req.query.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const key = _cfWtKey(o);
  _reconcileStaleReviews();   // an orphaned "Running…" self-heals on the next poll
  let rec = _getCfWt(key);
  if (!rec) return res.json({ worktree: null });
  if (rec.worktreeStatus === 'ready' && rec.worktreePath && fs.existsSync(rec.worktreePath)) {
    try {
      const reports = devitems.findAndCacheReports(CODEFLOW_REPORT_BOARD, _cfWtDevId(o), rec.worktreePath);
      const save = { reports: reports || [] };
      // The review worktree is a detached snapshot at the old PR tip, so its own
      // HEAD never reflects new local commits (which land on the branch inside a
      // sibling branch-attached worktree — e.g. a dev card's Work worktree). Measure
      // sync + uncommitted against that branch-attached dir so the card's Git section
      // shows real "N to push" / dirty state instead of a false "In sync / Clean".
      const branchDir = _cfUsableDir(rec) || rec.worktreePath;
      if (rec.sourceBranch) {
        try {
          const lastFetch = _cfDriftFetchAt.get(key) || 0;
          const doFetch = req.query.refresh === '1' || (Date.now() - lastFetch) > CF_DRIFT_FETCH_TTL_MS;
          if (doFetch) _cfDriftFetchAt.set(key, Date.now());
          const drift = devitems.prDrift(branchDir, rec.sourceBranch, { fetch: doFetch });
          if (drift) save.drift = drift;
        } catch {}
      }
      const rc = _readCfReviewComments(rec.worktreePath);
      if (rc) {
        const posted = _cfPostedSet(rec);
        const dismissed = _cfDismissedSet(rec);
        save.reviewComments = rc.comments.filter(c => { const fp = _cfCommentFp(c); return !posted.has(fp) && !dismissed.has(fp); }).length;
      } else {
        save.reviewComments = 0;
      }
      rec = _saveCfWt(key, save);
    } catch {}
  }
  // Computed (not persisted) enrichments for the card: agent-file presence,
  // cached review-report history, and the uncommitted-change breakdown.
  const extra = {};
  try { Object.assign(extra, _cfAgentPresence(rec)); } catch {}
  try { extra.reportHistory = devitems.listReportHistory(CODEFLOW_REPORT_BOARD, _cfWtDevId(o)) || []; } catch { extra.reportHistory = []; }
  try {
    const branchDir = _cfUsableDir(rec) || rec.worktreePath;
    if (branchDir && fs.existsSync(branchDir)) {
      const ch = devitems.worktreeChanges(branchDir);
      extra.changeCount = (ch.changed || []).length;
    }
  } catch {}
  res.json({ worktree: { key, ...rec, ...extra } });
});

// Resolve a directly-usable (branch-attached) worktree directory for a PR before
// opening it in a terminal / editor / Explorer. Code Flow review worktrees are
// detached read-only snapshots (so they never collide with a dev card on the same
// branch), which is useless for actually updating the PR. This points "Open" at the
// real branch worktree: an existing one (e.g. a dev card's Work worktree) if present,
// otherwise the review worktree attached onto the branch when it's free. Falls back
// to the review worktree path. Returns { dir, branch, reused, attached, detached }.
app.post('/api/codeflow/pr/worktree/open-dir', (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const rec = _getCfWt(_cfWtKey(o));
  const current = rec && rec.worktreePath ? rec.worktreePath : '';
  if (!current) return res.json({ dir: '' });
  // Seed the agent file into every on-branch worktree before handing a dir to the
  // CLI, so the resolved dir always has the steward/reviewer .agent.md.
  try { _cfEnsureAgentFile(rec); } catch { /* best-effort */ }
  let r;
  try {
    r = devitems.resolveUsableWorktree({
      org: o.org, project: o.project, repo: o.repo,
      sourceBranch: rec.sourceBranch, current
    });
  } catch { r = { dir: current, branch: rec.sourceBranch || '', reused: false, attached: false }; }
  res.json({ dir: (r && r.dir) || current, branch: r && r.branch, reused: !!(r && r.reused), attached: !!(r && r.attached) });
});

// ---- Code Flow PR notes --------------------------------------------------
// Freeform per-PR notes (add / list / edit / toggle done / delete). Keyed by the
// same prKey as worktrees so a note survives cache refreshes and worktree churn.
// Body for all: { org, project, repo, prId, provider, ... }.
app.get('/api/codeflow/pr/notes', (req, res) => {
  const q = req.query || {};
  const o = { org: q.org, project: q.project, repo: q.repo, prId: q.prId, provider: q.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  res.json({ ok: true, notes: _getCfNotes(_cfWtKey(o)) });
});

app.post('/api/codeflow/pr/notes', (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const text = String(b.text || '').trim();
  if (!text) return res.status(400).json({ error: 'Note text is required.' });
  const key = _cfWtKey(o);
  const now = new Date().toISOString();
  const notes = _mutateCfNotes(key, arr => {
    arr.push({ id: 'note-' + Math.random().toString(36).slice(2, 9), text, done: false, createdAt: now, updatedAt: now });
    return arr;
  });
  _patchCodeflowCacheNotes(key, notes);
  res.json({ ok: true, notes });
});

app.post('/api/codeflow/pr/notes/update', (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const id = String(b.id || '');
  if (!id) return res.status(400).json({ error: 'A note id is required.' });
  let notFound = false, empty = false;
  const key = _cfWtKey(o);
  const notes = _mutateCfNotes(key, arr => {
    const i = arr.findIndex(n => n && n.id === id);
    if (i < 0) { notFound = true; return arr; }
    const patch = { updatedAt: new Date().toISOString() };
    if (typeof b.text === 'string') {
      const t = b.text.trim();
      if (!t) { empty = true; return arr; }
      patch.text = t;
    }
    if (typeof b.done === 'boolean') patch.done = b.done;
    arr[i] = { ...arr[i], ...patch };
    return arr;
  });
  if (notFound) return res.status(404).json({ error: 'Note not found' });
  if (empty) return res.status(400).json({ error: 'Note text cannot be empty.' });
  _patchCodeflowCacheNotes(key, notes);
  res.json({ ok: true, notes });
});

app.post('/api/codeflow/pr/notes/delete', (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const id = String(b.id || '');
  const key = _cfWtKey(o);
  const notes = _mutateCfNotes(key, arr => arr.filter(n => n && n.id !== id));
  _patchCodeflowCacheNotes(key, notes);
  res.json({ ok: true, notes });
});

// Create (or re-attach) a review worktree for a PR. Fire-and-forget like the
// dev-card worktree route; the blocking clone runs in a worker thread.
// Lightweight single-PR lifecycle state, for cards whose PR is NOT in the live
// mine/reviews lists (e.g. a completed/merged PR pinned to a board). Returns just
// { status, isDraft } so the client can show an accurate state badge instead of a
// generic "Open" (which would mask the real state). Lightly cached to avoid re-hitting
// the forge on every board repaint. On failure returns { status:null } so the client
// shows NO badge rather than a wrong one.
const _cfPrStateCache = new Map(); // key -> { at, status, isDraft }
app.get('/api/codeflow/pr/state', async (req, res) => {
  const q = req.query || {};
  const o = { org: q.org, project: q.project, repo: q.repo, prId: q.prId, provider: q.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const key = [o.org, o.project || '', o.repo, o.prId, o.provider || ''].join('|').toLowerCase();
  const now = Date.now();
  const hit = _cfPrStateCache.get(key);
  if (hit && (now - hit.at) < CF_PRSTATUS_TTL_MS) {
    return res.json({ ok: true, status: hit.status, isDraft: hit.isDraft, cached: true });
  }
  try {
    const pr = await forge(o).getPullRequest(o.org, o.project, o.repo, o.prId);
    const status = pr && pr.status ? String(pr.status).toLowerCase() : null;
    const isDraft = !!(pr && pr.isDraft);
    _cfPrStateCache.set(key, { at: now, status, isDraft });
    res.json({ ok: true, status, isDraft });
  } catch (e) {
    res.json({ ok: true, status: null, isDraft: false, error: (e && e.message) || 'lookup failed' });
  }
});

app.post('/api/codeflow/pr/worktree', async (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const view = String(b.view || '').toLowerCase() === 'mine' ? 'mine' : 'reviews';
  // Resolve the PR fresh (don't trust client branch); require it to be OPEN.
  let pr;
  try { pr = await forge(o).getPullRequest(o.org, o.project, o.repo, o.prId); }
  catch (e) { return res.status(502).json({ error: (e && e.message) || 'Could not load the pull request.' }); }
  if (!pr || !pr.sourceBranch) return res.status(400).json({ error: 'PR has no source branch to review.' });
  if (String(pr.status || '').toLowerCase() !== 'active') return res.status(400).json({ error: 'PR is not open (active).' });
  const key = _cfWtKey(o);
  const devId = _cfWtDevId(o);
  _saveCfWt(key, {
    org: o.org, project: o.project, repo: o.repo, prId: pr.id, view, provider: o.provider || 'azdo',
    prTitle: pr.title || '', prUrl: pr.url || '',
    sourceBranch: pr.sourceBranch, targetBranch: pr.targetBranch || '',
    prStatus: String(pr.status || '').toLowerCase(),
    worktreeStatus: 'creating', error: null, worktreeStartedAt: new Date().toISOString()
  });
  res.json({ ok: true, status: 'creating', key });
  _cfActiveWorktrees.add(key);   // mark live so the watchdog leaves it alone until done
  (async () => {
    try {
      const r = await devitems.createWorktreeAsync({
        org: o.org, project: o.project, repo: o.repo, provider: o.provider,
        baseBranch: pr.targetBranch, branch: pr.sourceBranch, devId, detach: true
      });
      let rec = _saveCfWt(key, {
        worktreePath: r.worktreePath, branch: r.branch,
        worktreeStatus: 'ready', error: null, git: r.git || null
      });
      // Gather linked work items (best-effort) so the agent file is grounded.
      let workItems = [];
      try { workItems = await forge(o).getPrWorkItems(o.org, o.project, o.repo, o.prId); } catch {}
      // For your own PR (mine), ground the steward with the actual unresolved
      // reviewer feedback so it can address each thread concretely.
      let threads = [];
      if (view === 'mine') { try { threads = await forge(o).getPrActiveThreads(o.org, o.project, o.repo, o.prId); } catch {} }
      const agent = _writeCfReviewAgentFile(rec, { ...pr, org: o.org, project: o.project, repo: o.repo, createdBy: pr.createdBy }, workItems, { view, threads });
      const save = {};
      if (agent) Object.assign(save, agent);
      try { save.reports = devitems.findAndCacheReports(CODEFLOW_REPORT_BOARD, devId, r.worktreePath); } catch {}
      _saveCfWt(key, save);
    } catch (e) {
      _saveCfWt(key, { worktreeStatus: 'error', error: (e && e.message) || 'Worktree failed' });
    } finally {
      _cfActiveWorktrees.delete(key);   // create is over — watchdog may now reconcile if needed
    }
  })();
});

// "Review with AI": ensure a worktree exists for the PR (create detached if
// missing — allowed even for closed PRs), write the review agent, then run the
// reviewer headlessly in the worktree to produce pr-review-report.html and cache
// it so it surfaces on the Code Flow PR card. Fire-and-forget; the client polls
// the worktree record's reviewStatus.
app.post('/api/codeflow/pr/review', async (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  let pr;
  try { pr = await forge(o).getPullRequest(o.org, o.project, o.repo, o.prId); }
  catch (e) { return res.status(502).json({ error: (e && e.message) || 'Could not load the pull request.' }); }
  if (!pr || !pr.sourceBranch) return res.status(400).json({ error: 'PR has no source branch to review.' });
  const key = _cfWtKey(o);
  const devId = _cfWtDevId(o);
  let rec = _getCfWt(key);
  // View decides the persona: explicit body.view wins, else the worktree's
  // remembered view, else default to read-only review.
  const view = String(b.view || (rec && rec.view) || '').toLowerCase() === 'mine' ? 'mine' : 'reviews';
  const steward = view === 'mine';
  const haveWt = !!(rec && rec.worktreeStatus === 'ready' && rec.worktreePath && fs.existsSync(rec.worktreePath));
  rec = _saveCfWt(key, {
    org: o.org, project: o.project, repo: o.repo, prId: pr.id, view, provider: o.provider || 'azdo',
    prTitle: pr.title || (rec && rec.prTitle) || '', prUrl: pr.url || (rec && rec.prUrl) || '',
    sourceBranch: pr.sourceBranch, targetBranch: pr.targetBranch || '',
    prStatus: String(pr.status || '').toLowerCase(),
    reviewStatus: 'reviewing', reviewError: null, reviewStartedAt: new Date().toISOString(),
    ...(haveWt ? {} : { worktreeStatus: 'creating', error: null })
  });
  res.json({ ok: true, status: 'reviewing', key });
  _cfActiveReviews.add(key);   // mark live so the stale-review watchdog leaves it alone
  (async () => {
    try {
      // 1. Ensure the worktree (create detached if we don't already have one).
      if (!haveWt) {
        const r = await devitems.createWorktreeAsync({
          org: o.org, project: o.project, repo: o.repo, provider: o.provider,
          baseBranch: pr.targetBranch, branch: pr.sourceBranch, devId, detach: true
        });
        rec = _saveCfWt(key, {
          worktreePath: r.worktreePath, branch: r.branch,
          worktreeStatus: 'ready', error: null, git: r.git || null
        });
      }
      const wtPath = rec.worktreePath;
      if (!wtPath || !fs.existsSync(wtPath)) throw new Error('Worktree is not available.');
      // 2. Write/refresh the agent file (grounded with linked work items; the
      //    steward also gets the actual unresolved reviewer feedback to address).
      let workItems = [];
      try { workItems = await forge(o).getPrWorkItems(o.org, o.project, o.repo, o.prId); } catch {}
      let threads = [];
      if (steward) { try { threads = await forge(o).getPrActiveThreads(o.org, o.project, o.repo, o.prId); } catch {} }
      const prCtx = { ...pr, org: o.org, project: o.project, repo: o.repo, createdBy: pr.createdBy };
      const agent = _writeCfReviewAgentFile(rec, prCtx, workItems, { view, threads });
      if (agent) rec = _saveCfWt(key, agent);
      // 3. Run the agent in the worktree. Prefer the resolved agent; fall back to
      //    a plain prompt run (same persona body) if it can't resolve.
      const slug = (agent && agent.reviewAgentName) || rec.reviewAgentName ||
        (steward ? _cfStewardAgentSlug({ ...o, id: pr.id }) : _cfReviewAgentSlug({ ...o, id: pr.id }));
      const kickoff = steward
        ? 'Tend your pull request now. Work through every step in order: understand the goals, analyze the diff, ADDRESS EVERY active reviewer comment (fix the code or draft a reply), go above and beyond to harden the change and prevent regressions, then VALIDATE by running the repo\'s existing build/lint/tests until they pass. COMMIT your changes locally (do NOT push). Finally WRITE the self-contained HTML report `' + CODEFLOW_REPORT_NAME + '` AND the machine-readable file `' + CODEFLOW_COMMENTS_NAME + '` at the ROOT of this worktree (overwrite them if they exist). When everything is committed and both files are written, reply with the single word DONE.'
        : 'Perform your COMPLETE code review of this pull request now. Work through every review step in order, then WRITE the self-contained HTML report `' + CODEFLOW_REPORT_NAME + '` AND the machine-readable findings file `' + CODEFLOW_COMMENTS_NAME + '` at the ROOT of this worktree (overwrite them if they exist). When both files are written and saved, reply with the single word DONE.';
      const model = (settings.resolveModel && settings.resolveModel('execution', null)) || undefined;
      const sid = require('crypto').randomUUID();
      let acc = '';
      let run = await sdkRunner.runAgent({
        config: { cwd: wtPath, agent: slug, allowAll: true },
        prompt: kickoff, sessionId: sid, model, onChunk: (c) => { acc += c; },
        meta: { source: 'system', category: 'pull_requests' }
      });
      if (!run || run.fallback) {
        // Agent didn't resolve — run the persona body directly with full tools.
        const body = steward
          ? _stewardPersonaBody({ pr: prCtx, workItems, threads, reportName: CODEFLOW_REPORT_NAME })
          : _reviewPersonaBody({ pr: prCtx, workItems, reportName: CODEFLOW_REPORT_NAME });
        acc = '';
        run = await sdkRunner.runPrompt({
          prompt: body + '\n\n---\n\n' + kickoff,
          cwd: wtPath, sessionId: require('crypto').randomUUID(), model,
          onChunk: (c) => { acc += c; },
          meta: { source: 'system', category: 'pull_requests' }
        });
      }
      // 4. Cache whatever report was produced and resolve the review status.
      let reports = [];
      try { reports = devitems.findAndCacheReports(CODEFLOW_REPORT_BOARD, devId, wtPath) || []; } catch {}
      const ok = reports.length > 0;
      _saveCfWt(key, {
        reports,
        reviewStatus: ok ? 'done' : 'error',
        reviewError: ok ? null : 'The run finished but no report file was produced.',
        reviewFinishedAt: new Date().toISOString()
      });
    } catch (e) {
      _saveCfWt(key, { reviewStatus: 'error', reviewError: (e && e.message) || 'Review failed', worktreeStatus: (_getCfWt(key) || {}).worktreeStatus === 'creating' ? 'error' : undefined });
    } finally {
      _cfActiveReviews.delete(key);   // run is over — watchdog may now reconcile if needed
    }
  })();
});

// Remove a review worktree but PRESERVE the PR's AI artifacts. Deletes the git
// worktree/checkout, yet keeps the durable report cache intact. If any cached
// reports/history remain, a slim "artifacts-only" record is kept (no worktree
// fields) so the card still lists + serves them; otherwise the record is dropped.
app.post('/api/codeflow/pr/worktree/remove', (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const key = _cfWtKey(o);
  const rec = _getCfWt(key);
  const devId = _cfWtDevId(o);
  try { if (rec) devitems.removeWorktree(o.org, o.project, o.repo, devId, rec.worktreePath, o.provider); } catch {}
  // Keep the durable report cache (do NOT clearReportCache) so artifacts survive.
  let reports = []; try { reports = devitems.listCachedReports(CODEFLOW_REPORT_BOARD, devId) || []; } catch {}
  let reportHistory = []; try { reportHistory = devitems.listReportHistory(CODEFLOW_REPORT_BOARD, devId) || []; } catch {}
  _deleteCfWt(key);
  if (reports.length || reportHistory.length) {
    const slim = {
      org: o.org, project: o.project || '', repo: o.repo, prId: o.prId, provider: o.provider || '',
      prStatus: (rec && rec.prStatus) || undefined, prTitle: (rec && rec.prTitle) || undefined,
      prUrl: (rec && rec.prUrl) || undefined, sourceBranch: (rec && rec.sourceBranch) || undefined,
      agentKind: (rec && rec.agentKind) || undefined, reviewAgentName: (rec && rec.reviewAgentName) || undefined,
      artifactsOnly: true, worktreePath: '', worktreeStatus: null,
      reports, reportHistory, artifactsSavedAt: new Date().toISOString()
    };
    const saved = _saveCfWt(key, slim);
    return res.json({ ok: true, worktree: { key, ...saved } });
  }
  res.json({ ok: true });
});

// Sync the review worktree to the latest origin/<sourceBranch> (fetch + hard
// reset). Refuses to discard local commits/changes unless force=true.
app.post('/api/codeflow/pr/worktree/sync', (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const key = _cfWtKey(o);
  const rec = _getCfWt(key);
  if (!rec || !rec.worktreePath || !fs.existsSync(rec.worktreePath)) return res.status(400).json({ error: 'No worktree to sync.' });
  if (!rec.sourceBranch) return res.status(400).json({ error: 'No PR source branch on record.' });
  try {
    const workDir = _cfUsableDir(rec) || rec.worktreePath;
    const r = devitems.syncToPrBranch(workDir, { sourceBranch: rec.sourceBranch, force: !!b.force });
    if (!r || r.ok === false) return res.status(409).json({ error: (r && r.message) || 'Sync refused.', needsForce: !!(r && r.needsForce), drift: r && r.drift });
    const updated = _saveCfWt(key, r.drift ? { drift: r.drift } : {});
    res.json({ ok: true, message: r.message, drift: r.drift || null, worktree: { key, ...updated } });
  } catch (e) {
    res.status(500).json({ error: (e && e.message) || 'Sync failed' });
  }
});

// Update the PR/source branch FROM its target (base) branch — merge or rebase
// origin/<targetBranch> into the local worktree ("my PR is behind main, catch it
// up"). This is the opposite direction of /worktree/sync. Does NOT push; the user
// pushes afterwards via /pr/push. On conflict returns 409 {conflict:true} so the
// client can offer the other strategy or manual resolution.
app.post('/api/codeflow/pr/worktree/update-from-target', (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const targetBranch = String(b.targetBranch || '').trim();
  if (!targetBranch) return res.status(400).json({ error: 'targetBranch is required' });
  const strategy = b.strategy === 'rebase' ? 'rebase' : 'merge';
  const key = _cfWtKey(o);
  const rec = _getCfWt(key);
  if (!rec || !rec.worktreePath || !fs.existsSync(rec.worktreePath)) return res.status(400).json({ error: 'No worktree to update.' });
  if (!rec.sourceBranch) return res.status(400).json({ error: 'No PR source branch on record.' });
  try {
    const workDir = _cfUsableDir(rec) || rec.worktreePath;
    const r = devitems.updateFromTargetBranch(workDir, { sourceBranch: rec.sourceBranch, targetBranch, strategy });
    if (!r || r.ok === false) {
      return res.status(409).json({
        error: (r && r.message) || 'Update failed.',
        conflict: !!(r && r.conflict), needsClean: !!(r && r.needsClean),
        strategy: (r && r.strategy) || strategy, drift: r && r.drift
      });
    }
    const updated = _saveCfWt(key, r.drift ? { drift: r.drift } : {});
    res.json({ ok: true, message: r.message, noop: !!r.noop, drift: r.drift || null, worktree: { key, ...updated } });
  } catch (e) {
    res.status(500).json({ error: (e && e.message) || 'Update failed' });
  }
});

// Update the PR/source branch FROM its own remote tip — merge or rebase
// origin/<sourceBranch> INTO the local worktree, keeping local commits ("the PR
// branch moved on the server, pull those changes down"). The non-destructive
// counterpart to /worktree/sync (which hard-resets and discards local work). Does
// NOT push. On conflict returns 409 {conflict:true} so the client can offer the
// other strategy or manual resolution.
app.post('/api/codeflow/pr/worktree/update-from-pr', (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const strategy = b.strategy === 'rebase' ? 'rebase' : 'merge';
  const key = _cfWtKey(o);
  const rec = _getCfWt(key);
  if (!rec || !rec.worktreePath || !fs.existsSync(rec.worktreePath)) return res.status(400).json({ error: 'No worktree to update.' });
  if (!rec.sourceBranch) return res.status(400).json({ error: 'No PR source branch on record.' });
  try {
    const workDir = _cfUsableDir(rec) || rec.worktreePath;
    const r = devitems.pullPrBranch(workDir, { sourceBranch: rec.sourceBranch, strategy });
    if (!r || r.ok === false) {
      return res.status(409).json({
        error: (r && r.message) || 'Update failed.',
        conflict: !!(r && r.conflict), needsClean: !!(r && r.needsClean),
        strategy: (r && r.strategy) || strategy, drift: r && r.drift
      });
    }
    const updated = _saveCfWt(key, r.drift ? { drift: r.drift } : {});
    res.json({ ok: true, message: r.message, noop: !!r.noop, drift: r.drift || null, worktree: { key, ...updated } });
  } catch (e) {
    res.status(500).json({ error: (e && e.message) || 'Update failed' });
  }
});

// Push the local worktree's commits to the PR's source branch (commits any dirty
// changes first). Used for "my PRs" where the user worked locally in the review
// worktree and wants to update the PR branch.
app.post('/api/codeflow/pr/push', async (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const key = _cfWtKey(o);
  const rec = _getCfWt(key);
  if (!rec || !rec.worktreePath || !fs.existsSync(rec.worktreePath)) return res.status(400).json({ error: 'No worktree to push from.' });
  if (!rec.sourceBranch) return res.status(400).json({ error: 'No PR source branch on record.' });
  // Work happens on the branch-attached worktree (e.g. a dev card's Work dir), not
  // the detached review snapshot — push/commit from there so the user's real commits
  // and uncommitted edits land on the PR, not the frozen review-tip HEAD.
  const workDir = _cfUsableDir(rec) || rec.worktreePath;
  try {
    let message = String(b.message || '').trim();
    if (!message) {
      let dirty = false;
      try { dirty = !!devitems.worktreeChanges(workDir).dirty; } catch {}
      if (dirty) { try { message = await _cfGenerateCommitMessage(workDir); } catch {} }
    }
    const r = devitems.pushPrBranch(workDir, { sourceBranch: rec.sourceBranch, message });
    if (!r || r.ok === false) return res.status(409).json({ error: (r && r.message) || 'Push failed.', drift: r && r.drift });
    const updated = _saveCfWt(key, r.drift ? { drift: r.drift } : {});
    res.json({ ok: true, committed: r.files || 0, message: r.message, commitMessage: message || '', drift: r.drift || null, worktree: { key, ...updated } });
  } catch (e) {
    res.status(500).json({ error: (e && e.message) || 'Push failed' });
  }
});

// (Re)write the per-PR review/steward agent file into the worktree WITHOUT
// running it. Used to restore a steward/reviewer agent that went missing (the
// git-excluded .agent.md can vanish when a worktree is recreated/cleaned, which
// makes the CLI error "Custom agent ... not found"). Re-fetches the PR, linked
// work items, and (for your own PR) active threads so the persona is grounded.
app.post('/api/codeflow/pr/agent', async (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const key = _cfWtKey(o);
  const rec = _getCfWt(key);
  if (!rec || !rec.worktreePath || !fs.existsSync(rec.worktreePath)) return res.status(400).json({ error: 'No worktree to add the agent to.' });
  const view = String(b.view || rec.view || '').toLowerCase() === 'mine' ? 'mine' : 'reviews';
  let pr;
  try { pr = await forge(o).getPullRequest(o.org, o.project, o.repo, o.prId); }
  catch (e) { return res.status(502).json({ error: (e && e.message) || 'Could not load the pull request.' }); }
  if (!pr) return res.status(404).json({ error: 'Pull request not found.' });
  let workItems = [];
  try { workItems = await forge(o).getPrWorkItems(o.org, o.project, o.repo, o.prId); } catch {}
  let threads = [];
  if (view === 'mine') { try { threads = await forge(o).getPrActiveThreads(o.org, o.project, o.repo, o.prId); } catch {} }
  const prCtx = { ...pr, org: o.org, project: o.project, repo: o.repo, createdBy: pr.createdBy };
  const agent = _writeCfReviewAgentFile(rec, prCtx, workItems, { view, threads });
  if (!agent) return res.status(500).json({ error: 'Could not write the agent file.' });
  const updated = _saveCfWt(key, agent);
  res.json({ ok: true, ...agent, worktree: { key, ...updated, ..._cfAgentPresence(updated) } });
});

// List a review worktree's uncommitted changes (committable vs. ignored agent
// reports). Powers the "out of sync — view changes" affordance on the PR card.
app.get('/api/codeflow/pr/changes', (req, res) => {
  const o = { org: req.query.org, project: req.query.project, repo: req.query.repo, prId: req.query.prId, provider: req.query.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const rec = _getCfWt(_cfWtKey(o));
  if (!rec || !rec.worktreePath || !fs.existsSync(rec.worktreePath)) return res.status(400).json({ error: 'No worktree found.' });
  try {
    const workDir = _cfUsableDir(rec) || rec.worktreePath;
    const ch = devitems.worktreeChanges(workDir);
    res.json({ ok: true, dirty: ch.dirty, changed: ch.changed, ignored: ch.ignored });
  } catch (e) { res.status(500).json({ error: (e && e.message) || 'Could not read changes.' }); }
});

// Auto-generate a concise git commit message for a worktree's uncommitted
// changes. Feeds the diff (truncated) + changed-file list to the model and asks
// for a conventional-commit subject (+ optional body). Falls back to a heuristic
// built from the file list if the model is unavailable or returns nothing. The
// committable set already excludes git-excluded agent reports (they don't show in
// `git status`), so the message reflects only what will actually be committed.
async function _cfGenerateCommitMessage(wt) {
  const { execFileSync } = require('child_process');
  const git = (args) => {
    try { return String(execFileSync('git', args, { cwd: wt, encoding: 'utf-8', maxBuffer: 12 * 1024 * 1024 }) || '').trim(); }
    catch { return ''; }
  };
  const status = git(['status', '--porcelain', '-uall']);
  const files = status
    ? status.split(/\r?\n/).filter(Boolean).map(l => l.slice(3).replace(/^"|"$/g, '').trim()).filter(Boolean)
    : [];
  const heuristic = () => {
    if (!files.length) return 'Update local changes';
    const names = files.slice(0, 3).map(f => f.split('/').pop());
    return 'Update ' + names.join(', ') + (files.length > 3 ? ` and ${files.length - 3} more` : '');
  };
  const diffstat = git(['diff', 'HEAD', '--stat']);
  let patch = git(['diff', 'HEAD']);
  if (patch.length > 6000) patch = patch.slice(0, 6000) + '\n… (diff truncated)';
  if (!files.length && !patch) return heuristic();
  try {
    const prompt = [
      'Write ONE git commit message for the staged changes below.',
      'Rules: imperative mood; a Conventional Commits prefix (feat/fix/docs/refactor/chore/test/perf) when it clearly applies; subject line ≤ 72 chars with no trailing period; add a short body only if it genuinely helps. Output ONLY the commit message — no code fences, no quotes, no "Commit message:" label.',
      '',
      'Changed files:',
      files.join('\n') || '(none)',
      '',
      'Diffstat:',
      diffstat || '(n/a)',
      '',
      'Diff (may be truncated):',
      patch || '(no textual diff — likely new or binary files)'
    ].join('\n');
    let acc = '';
    await sdkRunner.runChat({
      config: null, prompt, sessionId: require('crypto').randomUUID(),
      cwd: wt, availableTools: [], onChunk: (c) => { acc += c; },
      model: (settings.resolveModel && settings.resolveModel('execution', null)) || undefined,
      meta: { source: 'system', category: 'pull_requests' }
    });
    let msg = String(acc || '').trim()
      .replace(/^```[\w-]*\s*/, '').replace(/\s*```$/, '')
      .replace(/^(commit message|message)\s*[:\-]\s*/i, '')
      .trim();
    return msg || heuristic();
  } catch { return heuristic(); }
}

// Commit the review worktree's uncommitted changes locally (does NOT push).
// When no message is supplied, one is auto-generated from the diff.
app.post('/api/codeflow/pr/commit', async (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const key = _cfWtKey(o);
  const rec = _getCfWt(key);
  if (!rec || !rec.worktreePath || !fs.existsSync(rec.worktreePath)) return res.status(400).json({ error: 'No worktree to commit.' });
  try {
    const workDir = _cfUsableDir(rec) || rec.worktreePath;
    let message = String(b.message || '').trim();
    if (!message) {
      let dirty = true;
      try { dirty = !!devitems.worktreeChanges(workDir).dirty; } catch {}
      if (dirty) { try { message = await _cfGenerateCommitMessage(workDir); } catch {} }
    }
    const r = devitems.commitAll(workDir, { message });
    if (!r || r.ok === false) return res.status(409).json({ error: (r && r.message) || 'Commit failed.' });
    const save = {};
    try { if (rec.sourceBranch) { const d = devitems.prDrift(workDir, rec.sourceBranch, { fetch: false }); if (d) save.drift = d; } } catch {}
    const updated = _saveCfWt(key, save);
    res.json({ ok: true, committed: r.committed, files: r.files || 0, message: r.message, commitMessage: message || '', worktree: { key, ...updated } });
  } catch (e) { res.status(500).json({ error: (e && e.message) || 'Commit failed' }); }
});

// Discard the review worktree's uncommitted changes (reset --hard + clean).
// Agent reports (git-excluded) are preserved.
app.post('/api/codeflow/pr/discard', (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const key = _cfWtKey(o);
  const rec = _getCfWt(key);
  if (!rec || !rec.worktreePath || !fs.existsSync(rec.worktreePath)) return res.status(400).json({ error: 'No worktree to clean.' });
  try {
    const workDir = _cfUsableDir(rec) || rec.worktreePath;
    const r = devitems.discardWorktreeChanges(workDir);
    if (!r || r.ok === false) return res.status(409).json({ error: (r && r.message) || 'Discard failed.' });
    const save = {};
    try { if (rec.sourceBranch) { const d = devitems.prDrift(workDir, rec.sourceBranch, { fetch: false }); if (d) save.drift = d; } } catch {}
    const updated = _saveCfWt(key, save);
    res.json({ ok: true, message: r.message, worktree: { key, ...updated } });
  } catch (e) { res.status(500).json({ error: (e && e.message) || 'Discard failed' }); }
});

// Return the AI reviewer's findings (parsed pr-review-comments.json), enriched
// with a small code snippet around each anchored finding so the user can preview
// exactly what each comment applies to before choosing which ones to post.
app.get('/api/codeflow/pr/comments', async (req, res) => {
  const o = { org: req.query.org, project: req.query.project, repo: req.query.repo, prId: req.query.prId, provider: req.query.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const key = _cfWtKey(o);
  let rec = _getCfWt(key);
  if (!rec || !rec.worktreePath || !fs.existsSync(rec.worktreePath)) return res.status(400).json({ error: 'No review worktree found.' });
  const rc = _readCfReviewComments(rec.worktreePath);
  if (!rc) return res.json({ summary: '', comments: [] });
  // Recognize findings already posted to the PR (including before we tracked them).
  rec = await _cfReconcilePosted(o, key, rec, rc.comments);
  const wt = rec.worktreePath;
  const postedSet = _cfPostedSet(rec);
  const dismissedSet = _cfDismissedSet(rec);
  const enrich = (c, i) => {
    const rel = c.file ? String(c.file).replace(/^[\\/]+/, '') : '';
    const line = (c.line != null && Number.isFinite(Number(c.line))) ? Number(c.line) : null;
    const anchored = !!(rel && line);
    let snippet = null;
    if (anchored) {
      try {
        const fp = path.join(wt, rel);
        if (fp.startsWith(wt) && fs.existsSync(fp) && fs.statSync(fp).isFile()) {
          const lines = fs.readFileSync(fp, 'utf8').split(/\r?\n/);
          const from = Math.max(1, line - 3);
          const to = Math.min(lines.length, line + 3);
          snippet = [];
          for (let n = from; n <= to; n++) snippet.push({ n, text: lines[n - 1], target: n === line });
        }
      } catch {}
    }
    const fingerprint = _cfCommentFp(c);
    return {
      index: i, fp: fingerprint, posted: postedSet.has(fingerprint), dismissed: dismissedSet.has(fingerprint),
      file: rel, line, severity: String(c.severity || '').toLowerCase(),
      title: c.title || '', body: c.body || '', suggestion: c.suggestion || '', anchored, snippet
    };
  };
  res.json({ summary: rc.summary || '', comments: rc.comments.map(enrich) });
});

// Post the AI reviewer's findings (pr-review-comments.json) to the PR as review
// comment threads — one per finding, anchored to file/line when known. Pass an
// optional `indices` array (into pr-review-comments.json's comments[]) to post
// only the chosen findings; omit it to post all.
app.post('/api/codeflow/pr/comments/post', async (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const key = _cfWtKey(o);
  const rec = _getCfWt(key);
  if (!rec || !rec.worktreePath || !fs.existsSync(rec.worktreePath)) return res.status(400).json({ error: 'No review worktree found.' });
  const rc = _readCfReviewComments(rec.worktreePath);
  if (!rc || !rc.comments.length) return res.status(400).json({ error: 'No review findings to post. Run "Review with AI" first.' });
  const sevTag = (s) => {
    const v = String(s || '').toLowerCase();
    return v === 'blocker' ? '🚫 Blocker' : v === 'major' ? '⚠️ Major' : v === 'minor' ? '🔹 Minor' : v === 'nit' ? '💬 Nit' : '💬 Comment';
  };
  // Optional selection: post only the chosen indices into rc.comments[]. Omit
  // (or pass a non-array) to post every finding, preserving the old behavior.
  let picked = rc.comments.map((c, i) => ({ c, i }));
  if (Array.isArray(b.indices)) {
    const want = new Set(b.indices.map(Number).filter(n => Number.isInteger(n) && n >= 0));
    picked = picked.filter(p => want.has(p.i));
  }
  if (!picked.length) return res.status(400).json({ error: 'No comments selected to post.' });
  const results = [];
  const postedFps = [];
  for (const { c } of picked) {
    try {
      const parts = ['**' + sevTag(c.severity) + (c.title ? ' — ' + c.title : '') + '**', ''];
      if (c.body) parts.push(c.body);
      if (c.suggestion) parts.push('', '**Suggested fix:** ' + c.suggestion);
      parts.push('', '_Posted from AI code review._');
      const file = c.file ? (String(c.file).startsWith('/') ? String(c.file) : '/' + String(c.file)) : null;
      const line = (c.line != null && Number.isFinite(Number(c.line))) ? Number(c.line) : null;
      await forge(o).createPrThread(o.org, o.project, o.repo, o.prId, {
        content: parts.join('\n'),
        filePath: file && line ? file : null,
        rightLine: file && line ? line : null,
        status: 'active'
      });
      results.push({ ok: true, title: c.title || '', anchored: !!(file && line) });
      const fp = _cfCommentFp(c);
      if (fp) postedFps.push(fp);
    } catch (e) {
      results.push({ ok: false, title: c.title || '', error: (e && e.message) || 'failed' });
    }
  }
  const posted = results.filter(r => r.ok).length;
  // Remember which findings we posted so the card count and the modal don't keep
  // re-offering comments the user already approved and applied through the app.
  if (postedFps.length) {
    try {
      const merged = _cfPostedSet(_getCfWt(key) || rec);
      for (const fp of postedFps) merged.add(fp);
      _saveCfWt(key, { postedComments: Array.from(merged), postedCommentsAt: new Date().toISOString() });
    } catch {}
  }
  res.json({ ok: posted > 0, posted, total: picked.length, results });
});
// Dismiss (or restore) individual AI review findings so they stop counting toward the
// card's "Add N review comments" label and get filtered in the modal — without ever
// posting them to the PR. Body: { ...pr, fps:[fingerprint], undo?:bool }.
app.post('/api/codeflow/pr/comments/dismiss', (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const key = _cfWtKey(o);
  const rec = _getCfWt(key);
  if (!rec) return res.status(400).json({ error: 'No review worktree found.' });
  const fps = Array.isArray(b.fps) ? b.fps.map(String).filter(Boolean) : [];
  if (!fps.length) return res.status(400).json({ error: 'No findings specified.' });
  const have = _cfDismissedSet(rec);
  if (b.undo) { for (const fp of fps) have.delete(fp); }
  else { for (const fp of fps) have.add(fp); }
  const saved = _saveCfWt(key, { dismissedComments: Array.from(have), dismissedCommentsAt: new Date().toISOString() });
  // Recompute the remaining postable count so the caller can refresh the card label.
  let remaining = null;
  try {
    const rc = _readCfReviewComments(rec.worktreePath);
    if (rc) { const posted = _cfPostedSet(saved); remaining = rc.comments.filter(c => { const fp = _cfCommentFp(c); return !posted.has(fp) && !have.has(fp); }).length; }
  } catch {}
  res.json({ ok: true, dismissed: Array.from(have), remaining });
});

// Dismiss a PR into the "Other PRs" bucket (or restore it). PRs you won't review but
// want to keep access to. Keyed by _cfWtKey so it survives across fetches/providers.
app.post('/api/codeflow/pr/dismiss', (req, res) => {
  const b = req.body || {};
  const o = { org: b.org, project: b.project, repo: b.repo, prId: b.prId, provider: b.provider };
  if (!_cfPrOk(o)) return res.status(400).json({ error: 'org, repo and prId are required' });
  const key = _cfWtKey(o);
  const map = loadCodeflowDismissed();
  if (b.undo) { delete map[key]; }
  else {
    map[key] = {
      at: new Date().toISOString(),
      title: String(b.title || '').slice(0, 240),
      org: o.org, project: o.project || '', repo: o.repo, prId: o.prId,
      provider: String(o.provider || 'azdo').toLowerCase(),
    };
  }
  saveCodeflowDismissed(map);
  // Bust the PR-list cache so the PR moves in/out of Active/Reviews/Other immediately.
  _codeflowCache.clear();
  res.json({ ok: true, dismissed: !b.undo, count: Object.keys(map).length });
});
// Reports are free-form HTML the review agent writes, so we inject (idempotently):
//   1. a theme-detection <script> right after <head> that reads ?scoutTheme=
//      (passed by the SPA) or falls back to the OS prefers-color-scheme, and
//   2. a dark-mode override <style> right before </head> that re-themes the
//      review template's known skeleton (body/headings/code/tables/verdict/etc.).
// Reports that opt into their own theming mark themselves with data-cp-themed and
// are left untouched.
function _themeReportHtml(html) {
  if (Buffer.isBuffer(html)) html = html.toString('utf8');
  if (typeof html !== 'string') return html;
  if (!/<html[\s>]/i.test(html) || /data-cp-themed/i.test(html)) return html;
  const detect = `<script>(function(){try{var p=new URLSearchParams(location.search).get('scoutTheme');var t=p||((window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches)?'dark':'light');document.documentElement.setAttribute('data-theme',t==='dark'?'dark':'light');}catch(e){}})();</script>`;
  const darkCss = `<style id="cp-report-theme">
html[data-theme="dark"] body{background:#1f1f1f;color:#dedede;}
html[data-theme="dark"] h1,html[data-theme="dark"] h3{color:#f0f0f0;}
html[data-theme="dark"] h2{color:#f0f0f0;border-bottom-color:#3a3a3a;}
html[data-theme="dark"] a{color:#7cb7ff;}
html[data-theme="dark"] code,html[data-theme="dark"] pre{background:#2a2a2a;color:#e6e6e6;}
html[data-theme="dark"] table,html[data-theme="dark"] th,html[data-theme="dark"] td{border-color:#3a3a3a;}
html[data-theme="dark"] th{background:#262626;color:#e6e6e6;}
html[data-theme="dark"] .meta{color:#9a9a9a;}
html[data-theme="dark"] .verdict{background:#262626;}
html[data-theme="dark"] .verdict.approve,html[data-theme="dark"] .approve{background:#0f2e22;border-left-color:#16a34a;}
html[data-theme="dark"] .verdict.needs-work,html[data-theme="dark"] .verdict.blocked,html[data-theme="dark"] .needs-work,html[data-theme="dark"] .blocked{background:#321a1a;}
html[data-theme="dark"] .tag-approve{background:#0f2e22;color:#8ff0c0;}
html[data-theme="dark"] .sev-blocker{color:#f87171;}
html[data-theme="dark"] .sev-major{color:#fbbf24;}
html[data-theme="dark"] .sev-minor{color:#60a5fa;}
html[data-theme="dark"] .sev-nit{color:#a0a0a0;}
html[data-theme="dark"] pre.diff,html[data-theme="dark"] .diff pre{background:#232323;color:#dcdcdc;}
html[data-theme="dark"] .diff-add{background:#0f2e22;color:#8ff0c0;display:block;}
html[data-theme="dark"] .diff-del{background:#3a1d1d;color:#f7a8a8;display:block;}
html[data-theme="dark"] .diff-hunk{color:#7cb7ff;display:block;}
</style>`;
  let out = html.replace(/<head([^>]*)>/i, (m) => m + detect);
  if (/<\/head>/i.test(out)) out = out.replace(/<\/head>/i, darkCss + '</head>');
  else out = detect + darkCss + out;
  return out;
}

app.get('/api/codeflow/pr/report', (req, res) => {
  const o = { org: req.query.org, project: req.query.project, repo: req.query.repo, prId: req.query.prId, provider: req.query.provider };
  if (!_cfPrOk(o)) return res.status(400).send('org, repo and prId are required');
  const key = _cfWtKey(o);
  const rec = _getCfWt(key);
  const devId = _cfWtDevId(o);
  const file = req.query.file;
  try {
    let r;
    try { r = devitems.readReport(rec && rec.worktreePath, file); }
    catch (e1) { r = devitems.readReportCached(CODEFLOW_REPORT_BOARD, devId, file); }
    res.setHeader('Content-Type', r.contentType);
    res.setHeader('Cache-Control', 'no-store');
    const isHtml = /text\/html/i.test(r.contentType || '');
    res.send(isHtml ? _themeReportHtml(r.content) : r.content);
  } catch (e) {
    res.status(e && e.status ? e.status : 404).send((e && e.message) || 'Failed to read report');
  }
});


// Sources (local folders / AzDO repos) are scanned greedily for agents,
// plugins, skills and MCP servers; the catalog merges scanned entries with an
// implicit "installed" view. Capabilities can be added to any agent (reusing
// the Phase 2 overlay attach), and agents/plugins installed via the existing
// AzDO / local register paths.

app.get('/api/marketplace/sources', (req, res) => {
  try { res.json({ sources: marketplace.listSources() }); }
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/marketplace/sources', (req, res) => {
  try { res.json({ ok: true, source: marketplace.addSource(req.body || {}) }); }
  catch (e) { res.status(400).json({ error: e.message }); }
});

// Preview a repo/branch's skills WITHOUT adding it as a permanent source. Used
// by the "browse other source" step of Create Agent. Returns entries carrying
// the same azdo/github + repoPath fields as a real scan, so the client can
// attach them to a draft agent; on create the client prompts to add the source.
app.post('/api/marketplace/sources/preview', async (req, res) => {
  try { res.json({ ok: true, ...(await marketplace.previewSource(req.body || {})) }); }
  catch (e) {
    const msg = e.message || 'Preview failed';
    const code = /required|unknown|not a directory/i.test(msg) ? 400 : 502;
    res.status(code).json({ error: msg });
  }
});

// Suggest marketplace sources derived from the source locations of installed
// agents/plugins (azdo repos + local folders). Preview only — nothing is added.
app.get('/api/marketplace/sources/suggested', (req, res) => {
  try {
    const agents = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8'));
    res.json({ suggested: marketplace.suggestSources(agents) });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Add (and optionally scan) the suggested sources that aren't already present.
app.post('/api/marketplace/sources/autopopulate', async (req, res) => {
  const scan = (req.body && req.body.scan) !== false; // default true
  try {
    const agents = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8'));
    const suggestions = marketplace.suggestSources(agents).filter(s => !s.exists);
    const added = [];
    const errors = [];
    for (const s of suggestions) {
      const { id, exists, from, ...input } = s;
      let source;
      try { source = marketplace.addSource(input); }
      catch (e) { errors.push({ id, label: s.label, error: e.message }); continue; }
      added.push(source);
      if (scan) {
        try { await marketplace.scanSource(source.id); }
        catch (e) { errors.push({ id: source.id, label: source.label, error: `scan: ${e.message}` }); }
      }
    }
    res.json({ ok: true, added, errors, sources: marketplace.listSources() });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.delete('/api/marketplace/sources/:id', (req, res) => {
  try {
    const ok = marketplace.removeSource(req.params.id);
    if (!ok) return res.status(404).json({ error: 'Source not found' });
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/marketplace/sources/:id/scan', async (req, res) => {
  try { res.json({ ok: true, ...(await marketplace.scanSource(req.params.id)) }); }
  catch (e) { res.status(502).json({ error: e.message }); }
});

app.get('/api/marketplace/catalog', (req, res) => {
  try {
    const result = marketplace.getCatalog({
      type: req.query.type || null,
      q: req.query.q || null,
      sourceId: req.query.sourceId || null,
    });
    decorateCatalogInstallState(result);
    res.json(result);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// What's new in the marketplace since the user last viewed it. Guarded so the
// very first visit (no baseline) never flags the whole catalog as "new".
app.get('/api/marketplace/updates', (req, res) => {
  try {
    const meta = marketplace.getMeta();
    const upd = marketplace.newSince(meta.lastViewedAt);
    res.json({ newCount: upd.count, byType: upd.byType, items: upd.items, lastViewedAt: meta.lastViewedAt, lastAutoScanAt: meta.lastAutoScanAt });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Clear the "new" indicator by stamping the marketplace as viewed now.
app.post('/api/marketplace/seen', (req, res) => {
  try { res.json({ ok: true, ...marketplace.markViewed() }); }
  catch (e) { res.status(500).json({ error: e.message }); }
});

// Mark catalog entries with whether they're already part of our system:
//  - agent|plugin  -> installed: true if a registered agent matches it
//  - skill|mcp     -> inUse: true if the capability catalog already has it
// Matching is done on normalized identity tokens (name/ref/plugin folder).
function decorateCatalogInstallState(result) {
  if (!result || !Array.isArray(result.entries)) return result;
  const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
  const baseName = (p) => norm(String(p || '').split(/[\\/]/).filter(Boolean).pop());

  // Installed agents/plugins -> identity tokens.
  const installedTokens = new Set();
  let agents = [];
  try { agents = supervisor.getAllStatus() || []; } catch (_) {}
  for (const a of agents) {
    const cfg = a.config || {};
    const ref = cfg.agent || a.agent || '';
    [a.agent_id, cfg.name, cfg.displayName, ref].forEach(v => { if (v) installedTokens.add(norm(v)); });
    if (ref && ref.includes(':')) {
      installedTokens.add(norm(ref.split(':')[0]));
      installedTokens.add(norm(ref.split(':').pop()));
    }
    const pdir = cfg.pluginDir || a.pluginDir;
    if (pdir) installedTokens.add(baseName(pdir));
  }

  // Skills/MCP already present in our capability catalog.
  const skillNames = new Set();
  const mcpNames = new Set();
  try {
    const cat = capabilities.buildCatalog();
    for (const s of cat.skills || []) skillNames.add(norm(s.name));
    for (const m of cat.mcp || []) mcpNames.add(norm(m.name));
  } catch (_) {}

  for (const e of result.entries) {
    if (e.type === 'agent' || e.type === 'plugin') {
      const tokens = [e.name, e.displayName];
      if (e.plugin && e.plugin.dir) tokens.push(baseName(e.plugin.dir));
      if (e.agent && e.agent.ref) { tokens.push(e.agent.ref); tokens.push(String(e.agent.ref).split(':')[0]); }
      e.installed = tokens.some(t => t && installedTokens.has(norm(t)));
    } else if (e.type === 'skill') {
      e.inUse = skillNames.has(norm(e.name));
    } else if (e.type === 'mcp') {
      const server = (e.mcp && e.mcp.server) || e.name;
      e.inUse = mcpNames.has(norm(server));
    }
  }
  return result;
}

// Install / add a catalog entry.
//  - agent|plugin from an azdo source -> materialize + register (reuse azdo install)
//  - agent|plugin from a local source -> register an agents.json entry
//  - skill|mcp + agentId -> attach to that agent's overlay (Phase 2)
app.post('/api/marketplace/install', async (req, res) => {
  const { entryId, agentId, group } = req.body || {};
  if (!entryId) return res.status(400).json({ error: 'entryId is required' });
  const entry = marketplace.findEntry(entryId);
  if (!entry) return res.status(404).json({ error: 'Catalog entry not found' });
  try {
    if (entry.type === 'skill' || entry.type === 'mcp') {
      if (!agentId) return res.status(400).json({ error: 'agentId is required to add a capability to an agent' });
      const agents = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8'));
      const target = agents.find(a => a.id === agentId);
      if (!target) return res.status(404).json({ error: 'Target agent not found' });
      const mat = await marketplace.materializeForAttach(entry);
      let result;
      if (mat.kind === 'mcp') {
        const cfg = capabilities.resolveCatalogMcp(mat.sourcePath, mat.name);
        if (!cfg) return res.status(400).json({ error: 'Could not resolve MCP server config' });
        result = capabilities.attachMcp(agentId, mat.name, cfg);
      } else {
        const dir = capabilities.resolveCatalogSkill(mat.sourceDir);
        if (!dir) return res.status(400).json({ error: 'Could not resolve skill source' });
        result = capabilities.attachSkill(agentId, { name: mat.name, sourceDir: dir });
      }
      broadcastSSE('agent-update', { agentId });
      try { recordActivity({ kind: 'marketplace', category: 'marketplace', title: `Added ${entry.type === 'mcp' ? 'MCP server' : 'skill'} “${mat.name}”`, detail: `Attached to agent ${agentId}.`, entityId: agentId, entityName: mat.name, status: 'success', route: '#/marketplace' }); } catch (_) {}
      return res.json({ ok: true, attached: { type: entry.type, name: mat.name, agentId }, result });
    }

    // agent | plugin install
    if (entry.sourceKind === 'azdo' && entry.install && entry.azdo) {
      const { org, project, repo, branch } = entry.azdo;
      const config = await installForgeItem({ provider: 'azdo', org, project, repo, branch, item: entry.install.item, group });
      try { recordActivity({ kind: 'marketplace', category: 'marketplace', title: `Installed ${entry.type || 'agent'} “${entry.displayName || entry.name || config.name}”`, detail: `From Azure DevOps ${org}/${repo}.`, entityId: config.id, entityName: config.name, status: 'success', route: '#/marketplace' }); } catch (_) {}
      return res.json({ ok: true, agent: config });
    }
    if (entry.sourceKind === 'github' && entry.install && entry.github) {
      const { org, repo, branch } = entry.github;
      const config = await installForgeItem({ provider: 'github', org, project: '', repo, branch, item: entry.install.item, group });
      try { recordActivity({ kind: 'marketplace', category: 'marketplace', title: `Installed ${entry.type || 'agent'} “${entry.displayName || entry.name || config.name}”`, detail: `From GitHub ${org}/${repo}.`, entityId: config.id, entityName: config.name, status: 'success', route: '#/marketplace' }); } catch (_) {}
      return res.json({ ok: true, agent: config });
    }
    if (entry.sourceKind === 'local') {
      const config = installLocalCatalogEntry(entry, group);
      try { recordActivity({ kind: 'marketplace', category: 'marketplace', title: `Installed ${entry.type || 'agent'} “${entry.displayName || entry.name || config.name}”`, detail: 'From a local marketplace source.', entityId: config.id, entityName: config.name, status: 'success', route: '#/marketplace' }); } catch (_) {}
      return res.json({ ok: true, agent: config });
    }
    return res.status(400).json({ error: 'This entry cannot be installed directly' });
  } catch (e) {
    res.status(500).json({ error: `Install failed: ${e.message}` });
  }
});

// Marker embedded in agents we synthesize for skills/MCP-only plugins, so the
// update path can tell our stand-in apart from an agent the publisher ships.
const GENERATED_AGENT_MARKER = 'Auto-generated by TheOffice.AI';

function isGeneratedAgentFile(text) {
  return typeof text === 'string' && text.includes(GENERATED_AGENT_MARKER);
}

// Determine the "<pluginName>:<agentSlug>" custom-agent reference a plugin
// exposes by reading its plugin.json + agents/ folder. Returns '' when the
// plugin ships no custom agent (a skills/MCP-only bundle) — those run under the
// default copilot agent with capabilities loaded via --plugin-dir. Fabricating
// a "<name>:<name>" ref for such plugins breaks chat ("Custom agent not found").
function resolvePluginAgentRef(pluginDir) {
  let pluginName = '';
  try {
    const pj = JSON.parse(fs.readFileSync(path.join(pluginDir, 'plugin.json'), 'utf-8'));
    pluginName = (pj && pj.name) || '';
  } catch (_) { /* ignore */ }
  let files = [];
  try {
    files = fs.readdirSync(path.join(pluginDir, 'agents')).filter(f => /\.agent\.md$/i.test(f));
  } catch (_) { return ''; }
  if (!files.length || !pluginName) return '';
  const slugs = files.map(f => f.replace(/\.agent\.md$/i, ''));
  const chosen = slugs.find(s => s.toLowerCase() === pluginName.toLowerCase()) || slugs[0];
  return `${pluginName}:${chosen}`;
}

// Read the bundled skills of a plugin as { name, description } (from each
// skills/*/SKILL.md frontmatter). Best-effort; returns [] on any problem.
function readPluginSkills(pluginDir) {
  const out = [];
  const tryDir = (skillsRoot) => {
    let dirs = [];
    try { dirs = fs.readdirSync(skillsRoot, { withFileTypes: true }).filter(e => e.isDirectory()); } catch (_) { return; }
    for (const d of dirs) {
      const md = path.join(skillsRoot, d.name, 'SKILL.md');
      if (!fs.existsSync(md)) continue;
      let name = d.name, description = '';
      try {
        const raw = fs.readFileSync(md, 'utf-8');
        const fm = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
        if (fm) {
          const nm = fm[1].match(/^name:\s*(.+)$/im); if (nm) name = nm[1].replace(/^["']|["']$/g, '').trim();
          const dm = fm[1].match(/^description:\s*(.+)$/im); if (dm) description = dm[1].replace(/^["']|["']$/g, '').trim();
        }
      } catch (_) {}
      out.push({ name, description });
    }
  };
  tryDir(path.join(pluginDir, 'skills'));
  return out;
}

// MCP server names declared by a plugin's .mcp.json (best-effort).
function readPluginMcpServers(pluginDir) {
  try {
    const cfg = JSON.parse(fs.readFileSync(path.join(pluginDir, '.mcp.json'), 'utf-8'));
    return Object.keys((cfg && cfg.mcpServers) || {});
  } catch (_) { return []; }
}

// Pull the "What it does" / overview bullets from a plugin README (best-effort).
function readPluginReadmeBullets(pluginDir) {
  let raw = '';
  for (const f of ['README.md', 'readme.md', 'Readme.md']) {
    try { raw = fs.readFileSync(path.join(pluginDir, f), 'utf-8'); break; } catch (_) {}
  }
  if (!raw) return [];
  const lines = raw.replace(/\r\n/g, '\n').split('\n');
  const bullets = [];
  let capture = false;
  for (const ln of lines) {
    if (/^#{1,6}\s/.test(ln)) {
      // Start capturing after a "What it does"/"Overview"/"Features" heading.
      capture = /what it does|overview|features|capabilit/i.test(ln);
      if (!capture && bullets.length) break; // next heading ends the section
      continue;
    }
    if (capture) {
      const m = ln.match(/^\s*[-*]\s+(.+)$/);
      if (m) bullets.push(m[1].trim());
      else if (bullets.length && ln.trim() === '') break;
    }
  }
  return bullets.slice(0, 12);
}

// Intelligently synthesize an .agent.md for a plugin that ships skills/MCP but
// no agent of its own. Reads the plugin's real context (plugin.json, README,
// skills, MCP) and writes agents/<slug>.agent.md INSIDE the plugin so Copilot
// discovers it natively as "<pluginName>:<slug>". Idempotent: if an agent
// already exists it is reused. Returns the agent ref, or '' on failure.
function ensurePluginAgent(pluginDir) {
  const existing = resolvePluginAgentRef(pluginDir);
  if (existing) return existing;
  let meta = {};
  try { meta = JSON.parse(fs.readFileSync(path.join(pluginDir, 'plugin.json'), 'utf-8')) || {}; } catch (_) {}
  const pluginName = meta.name;
  if (!pluginName) return '';
  const slug = String(pluginName).toLowerCase().replace(/[^a-z0-9._-]+/g, '-').replace(/^-+|-+$/g, '') || 'agent';
  const description = (meta.description || `Assistant powered by the ${pluginName} plugin.`).replace(/\s+/g, ' ').trim();
  const skills = readPluginSkills(pluginDir);
  const servers = readPluginMcpServers(pluginDir);
  const bullets = readPluginReadmeBullets(pluginDir);
  const pretty = String(meta.displayName || pluginName)
    .replace(/[-_]+/g, ' ').replace(/\b\w/g, c => c.toUpperCase());

  // YAML single-quoted scalar (double any embedded single quotes).
  const yq = (s) => "'" + String(s).replace(/'/g, "''") + "'";
  const lines = [];
  lines.push('---');
  lines.push(`name: ${slug}`);
  lines.push(`description: ${yq(description)}`);
  lines.push('---');
  lines.push('');
  lines.push(`# ${pretty} Agent`);
  lines.push('');
  lines.push(`<!-- ${GENERATED_AGENT_MARKER}: this plugin shipped skills/MCP but no agent of its own. Edit freely; delete to regenerate on reinstall. -->`);
  lines.push('');
  lines.push(`You are **${pretty}**, an assistant powered by the \`${pluginName}\` Copilot plugin. ${description}`);
  lines.push('');
  if (bullets.length) {
    lines.push('## What you can do');
    lines.push('');
    for (const b of bullets) lines.push(`- ${b}`);
    lines.push('');
  }
  if (skills.length) {
    lines.push('## Skills');
    lines.push('');
    lines.push('Use these bundled skills — they encode the correct steps, queries, and data sources. Prefer them over improvising:');
    lines.push('');
    for (const s of skills) lines.push(`- **${s.name}**${s.description ? ' — ' + s.description : ''}`);
    lines.push('');
  }
  if (servers.length) {
    lines.push('## Tools');
    lines.push('');
    lines.push('You have access to these MCP servers bundled with the plugin:');
    lines.push('');
    for (const sv of servers) lines.push(`- \`${sv}\``);
    lines.push('');
  }
  lines.push('## How to work');
  lines.push('');
  lines.push("- Clarify the user's goal, then carry it out using the skills and tools above.");
  if (skills.length) lines.push('- For domain tasks, drive the work through the bundled skills rather than guessing.');
  if (servers.length) lines.push('- Query live data through the MCP servers above when the user needs current information.');
  lines.push('- Be concise, show your findings clearly, and cite the data sources you used.');
  lines.push('');

  const agentsDir = path.join(pluginDir, 'agents');
  try {
    fs.mkdirSync(agentsDir, { recursive: true });
    fs.writeFileSync(path.join(agentsDir, `${slug}.agent.md`), lines.join('\n'));
  } catch (e) {
    console.warn('[install] could not generate plugin agent for', pluginName, '-', e.message);
    return '';
  }
  console.log(`[install] generated agent "${pluginName}:${slug}" for skills/MCP-only plugin`);
  return `${pluginName}:${slug}`;
}

// Reconcile a plugin's agent on (re)install/update. Handles the two cases the
// auto-generate feature must survive across updates:
//   1. The new plugin version now ships a real agent of its own -> delete any
//      stand-in we generated previously (so there are no duplicates) and bind to
//      the publisher's agent.
//   2. The plugin is still agent-less -> regenerate our stand-in from the new
//      version's context (description/skills/MCP may have changed) so it stays
//      current, then bind to it.
// Returns the agent ref to persist ('' only if generation fails).
function reconcilePluginAgent(pluginDir) {
  const agentsDir = path.join(pluginDir, 'agents');
  let files = [];
  try { files = fs.readdirSync(agentsDir).filter(f => /\.agent\.md$/i.test(f)); } catch (_) { files = []; }
  const generated = [];
  let hasReal = false;
  for (const f of files) {
    let txt = '';
    try { txt = fs.readFileSync(path.join(agentsDir, f), 'utf-8'); } catch (_) {}
    if (isGeneratedAgentFile(txt)) generated.push(f); else hasReal = true;
  }
  if (hasReal) {
    // Publisher now ships a real agent — remove our generated stand-ins.
    for (const g of generated) {
      try { fs.unlinkSync(path.join(agentsDir, g)); console.log(`[update] removed generated stand-in agent ${g} (plugin now ships its own)`); } catch (_) {}
    }
    return resolvePluginAgentRef(pluginDir);
  }
  // No real agent: drop stale generated files so ensurePluginAgent regenerates
  // from the current plugin context.
  for (const g of generated) { try { fs.unlinkSync(path.join(agentsDir, g)); } catch (_) {} }
  return ensurePluginAgent(pluginDir);
}

// Register a local agent/plugin catalog entry as an agent.
function installLocalCatalogEntry(entry, group) {
  const baseId = slugifyId(entry.displayName || entry.name || entry.id);
  const agents = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8'));
  let config;
  if (entry.type === 'plugin' && entry.plugin && entry.plugin.dir) {
    const source = { type: 'local', kind: 'plugin', path: entry.plugin.dir, installedAt: new Date().toISOString() };
    const { id: finalId, suffixed } = resolveInstallId(baseId, source, agents);
    const baseName = entry.displayName || entry.name || baseId;
    registerLocalPluginInCopilot(entry.plugin.dir);
    config = {
      id: finalId,
      name: suffixed ? `${baseName} (Local)` : baseName,
      cwd: path.dirname(entry.plugin.dir),
      pluginDir: entry.plugin.dir,
      sourceDir: entry.plugin.dir,
      agent: ensurePluginAgent(entry.plugin.dir),
      schedule: 'never',
      durable: true,
      group: group || 'Marketplace',
      description: entry.description || '',
      source,
    };
  } else if (entry.type === 'agent' && entry.agent) {
    const source = { type: 'local', kind: 'agent', path: entry.path, installedAt: new Date().toISOString() };
    const { id: finalId, suffixed } = resolveInstallId(baseId, source, agents);
    const baseName = entry.displayName || entry.name || baseId;
    config = {
      id: finalId,
      name: suffixed ? `${baseName} (Local)` : baseName,
      cwd: entry.agent.cwd || path.dirname(entry.path || '.'),
      agent: entry.agent.ref || entry.name || baseId,
      schedule: 'never',
      durable: true,
      group: group || 'Marketplace',
      description: entry.description || '',
      source,
    };
  } else {
    throw new Error('Unsupported local entry');
  }
  const existing = agents.findIndex(a => a.id === config.id);
  if (existing >= 0) agents[existing] = config; else agents.push(config);
  fs.writeFileSync(AGENTS_PATH, JSON.stringify(agents, null, 2));
  supervisor.register(config);
  broadcastSSE('agent-update', { agentId: config.id });
  return config;
}

function slugifyId(v) {
  return String(v || 'agent').toLowerCase().replace(/[^a-z0-9._-]+/g, '-').replace(/^-+|-+$/g, '') || 'agent';
}

// ---- Marketplace: Design with AI ----
// Propose creative capability attachments for an existing agent (enhance) or a
// brand-new agent composed from the catalog (create). Mirrors the execution
// "Design with AI" mechanism: one-shot runChat -> fenced JSON -> normalize.
app.post('/api/marketplace/design/generate', async (req, res) => {
  const mode = (req.body && req.body.mode) === 'create' ? 'create' : 'enhance';
  const hint = String((req.body && req.body.hint) || '').trim();
  try {
    const catalog = marketplaceDesign.compactCatalog();
    if (!catalog.skills.length && !catalog.mcp.length) {
      return res.status(400).json({ error: 'No marketplace capabilities to design with. Add and scan a source first.' });
    }

    let prompt, agentId = null;
    if (mode === 'enhance') {
      agentId = String((req.body && req.body.agentId) || '').trim();
      if (!agentId) return res.status(400).json({ error: 'agentId is required for enhance mode' });
      const agents = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8'));
      const target = agents.find(a => a.id === agentId);
      if (!target) return res.status(404).json({ error: 'Target agent not found' });
      let caps = { mcp: [], skills: [] };
      try { caps = capabilities.getEffectiveCapabilities(target); } catch (_) {}
      prompt = marketplaceDesign.enhancePrompt(
        { name: target.name || target.id, description: target.description || '' }, caps, catalog, hint);
    } else {
      let inspiration = [];
      try {
        inspiration = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8'))
          .slice(0, 20).map(a => ({ name: a.name || a.id, description: String(a.description || '').slice(0, 120) }));
      } catch (_) {}
      prompt = marketplaceDesign.createPrompt(catalog, inspiration, hint);
    }

    // One-shot generation with a single retry — model output is occasionally
    // unparseable; a fresh attempt usually succeeds.
    let arr = null, text = '';
    for (let attempt = 0; attempt < 2 && !arr; attempt++) {
      let acc = '';
      const result = await sdkRunner.runChat({
        config: null, prompt, sessionId: require('crypto').randomUUID(), resume: false, cwd: __dirname,
        onChunk: (c) => { acc += c; },
        meta: { source: 'system', category: 'agent_authoring' }
      });
      text = acc.trim() ? acc : (result.output || '');
      arr = marketplaceDesign.parseProposals(text);
    }
    if (!arr) return res.status(502).json({ error: 'Could not parse AI proposals. Try again.', raw: text.slice(0, 500) });
    const proposals = arr
      .map(p => mode === 'enhance' ? marketplaceDesign.normalizeEnhance(p, agentId) : marketplaceDesign.normalizeCreate(p))
      .filter(Boolean);
    if (!proposals.length) return res.status(502).json({ error: 'AI returned no usable proposals. Try again.' });
    try { saveMktDesignLatest({ mode, hint, agentId: agentId || '', proposals, generatedAt: new Date().toISOString() }); } catch (_) {}
    res.json({ mode, proposals });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// Cached Design-with-AI state for the marketplace: latest generated set + pins.
app.get('/api/marketplace/design/cache', (req, res) => {
  res.json({ latest: loadMktDesignLatest(), pinned: loadMktDesignPins() });
});
app.post('/api/marketplace/design/pin', (req, res) => {
  const p = req.body && req.body.proposal;
  if (!p || !p.id) return res.status(400).json({ error: 'proposal with an id is required' });
  const list = loadMktDesignPins();
  if (!list.some(x => x.id === p.id)) { list.unshift({ ...p, pinnedAt: new Date().toISOString() }); saveMktDesignPins(list); }
  res.json({ ok: true, pinned: list });
});
app.delete('/api/marketplace/design/pin/:id', (req, res) => {
  const id = req.params.id;
  const next = loadMktDesignPins().filter(x => x.id !== id);
  saveMktDesignPins(next);
  res.json({ ok: true, pinned: next });
});

// ---- Guided "Create Agent" draft helpers (Agents page) --------------------
// These power the interactive Create Agent flow: turn a name+description into a
// solid system prompt, and recommend skills from the marketplace catalog. Both
// are one-shot text generations (availableTools:[]) so the model just writes —
// it can't wander off inspecting the filesystem and leak tool-planning prose.
// The draft chat preview and the final create reuse the existing design test /
// apply routes with a client-built { kind:'create', agent:{name,description,body} }
// proposal, so nothing new is needed there.

// Generate a good agent system prompt from a name + description.
app.post('/api/agents/draft/generate-prompt', async (req, res) => {
  const name = String((req.body && req.body.name) || '').trim();
  const description = String((req.body && req.body.description) || '').trim();
  if (!name && !description) return res.status(400).json({ error: 'name or description is required' });
  const prompt = [
    'You are an expert at authoring system prompts for autonomous AI agents.',
    'Write the SYSTEM PROMPT / core instructions for a single agent described below.',
    '',
    'AGENT NAME: ' + (name || '(unnamed)'),
    'WHAT IT SHOULD DO: ' + (description || '(no description provided)'),
    '',
    'Requirements for the prompt you write:',
    '- Address the agent in the second person ("You are …").',
    '- Give it a clear role, scope, and the outcomes it is responsible for.',
    '- Include concise operating guidance: how it should approach tasks, any',
    '  important do/don\'t rules, and how it should communicate results.',
    '- Keep it practical and specific to this agent — no generic filler.',
    '- Use short Markdown sections/bullets where helpful. Aim for 120-350 words.',
    '',
    'Output ONLY the prompt text itself (Markdown). Do NOT wrap it in code fences,',
    'do NOT add a preamble like "Here is the prompt", and do NOT include commentary.',
  ].join('\n');
  try {
    let acc = '';
    const result = await sdkRunner.runChat({
      config: null, prompt, sessionId: require('crypto').randomUUID(), resume: false,
      cwd: __dirname, availableTools: [], onChunk: (c) => { acc += c; },
      meta: { source: 'system', category: 'agent_authoring' },
    });
    let text = (acc.trim() ? acc : (result.output || '')).trim();
    // Strip an accidental surrounding code fence if the model added one.
    const fence = text.match(/^```(?:markdown|md)?\s*\n([\s\S]*?)\n```\s*$/i);
    if (fence) text = fence[1].trim();
    if (!text) return res.status(502).json({ error: 'The model returned an empty prompt. Try again.' });
    res.json({ prompt: text });
  } catch (e) {
    res.status(500).json({ error: e.message || 'Prompt generation failed' });
  }
});

// Recommend skills from the marketplace catalog for a draft agent.
app.post('/api/agents/draft/recommend-skills', async (req, res) => {
  const name = String((req.body && req.body.name) || '').trim();
  const description = String((req.body && req.body.description) || '').trim();
  const draftPrompt = String((req.body && req.body.prompt) || '').trim();
  try {
    const catalog = marketplaceDesign.compactCatalog();
    const skills = catalog.skills || [];
    if (!skills.length) return res.json({ recommended: [], reasons: {}, note: 'No skills in the catalog yet.' });
    const valid = new Set(skills.map(s => s.name));
    const prompt = [
      'You help configure an AI agent by choosing which SKILLS to attach to it.',
      'A skill is focused domain know-how (a SKILL.md doc) that teaches the agent HOW to do something.',
      '',
      'AGENT NAME: ' + (name || '(unnamed)'),
      'DESCRIPTION: ' + (description || '(none)'),
      draftPrompt ? ('SYSTEM PROMPT:\n' + draftPrompt.slice(0, 2000)) : '',
      '',
      'AVAILABLE SKILLS (choose ONLY from this list, by exact "name"):',
      JSON.stringify(skills.map(s => ({ name: s.name, description: s.description })), null, 2),
      '',
      'Pick the skills that would genuinely make THIS agent more capable at its job.',
      'Recommend only strong fits (typically 1-6). If none fit, return an empty array.',
      '',
      'Respond with ONLY a JSON object (no prose, no code fence) in this exact shape:',
      '{ "recommended": [ { "name": "exact-skill-name", "why": "one short reason" } ] }',
    ].filter(Boolean).join('\n');
    let arr = null, text = '';
    for (let attempt = 0; attempt < 2 && !arr; attempt++) {
      let acc = '';
      const result = await sdkRunner.runChat({
        config: null, prompt, sessionId: require('crypto').randomUUID(), resume: false,
        cwd: __dirname, availableTools: [], onChunk: (c) => { acc += c; },
        meta: { source: 'system', category: 'agent_authoring' },
      });
      text = (acc.trim() ? acc : (result.output || '')).trim();
      try {
        const m = text.match(/\{[\s\S]*\}/);
        const obj = JSON.parse(m ? m[0] : text);
        arr = Array.isArray(obj.recommended) ? obj.recommended : [];
      } catch (_) { arr = null; }
    }
    if (!arr) return res.status(502).json({ error: 'Could not parse recommendations. Try again.', raw: text.slice(0, 300) });
    const recommended = [];
    const reasons = {};
    for (const r of arr) {
      const nm = String((r && r.name) || '').trim();
      if (!valid.has(nm) || recommended.includes(nm)) continue;
      recommended.push(nm);
      reasons[nm] = String((r && r.why) || '').trim();
    }
    res.json({ recommended, reasons });
  } catch (e) {
    res.status(500).json({ error: e.message || 'Skill recommendation failed' });
  }
});

// ---- Design proposal helpers (shared by apply + test) ----

// Allocate an agent id that doesn't collide with an existing one.
function uniqueAgentId(agents, base) {
  const slug = marketplaceDesign.slugify(base || 'agent');
  if (!agents.some(a => a.id === slug)) return slug;
  let i = 2;
  while (agents.some(a => a.id === `${slug}-${i}`)) i++;
  return `${slug}-${i}`;
}

// Copy a source agent's marketplace overlay (attached caps) onto a new id so a
// cloned/test agent inherits everything the original already had.
function copyOverlay(srcId, dstId) {
  const src = agentPackage.overlayDir(srcId);
  const dst = agentPackage.overlayDir(dstId);
  if (src === dst) return;
  if (fs.existsSync(src)) fs.cpSync(src, dst, { recursive: true });
}

// Attach a proposal's capabilities (re-resolved by type:name against the live
// catalog) onto an agent's overlay. Returns { attached, failed }.
async function attachCapsToAgent(agentId, attachArr) {
  const attached = [];
  const failed = [];
  for (const a of Array.isArray(attachArr) ? attachArr : []) {
    try {
      // Temp-source skills (from the "browse other source" step) carry their full
      // catalog entry inline because they're NOT in the persisted catalog, so
      // resolveByTypeName can't find them. Fall back to it for normal caps.
      const entry = a.entry || marketplace.resolveByTypeName(a.type, a.name);
      if (!entry) { failed.push({ ...a, error: 'not found in catalog' }); continue; }
      const mat = await marketplace.materializeForAttach(entry);
      if (mat.kind === 'mcp') {
        const cfg = capabilities.resolveCatalogMcp(mat.sourcePath, mat.name);
        if (!cfg) { failed.push({ ...a, error: 'could not resolve MCP config' }); continue; }
        capabilities.attachMcp(agentId, mat.name, cfg);
      } else {
        const dir = capabilities.resolveCatalogSkill(mat.sourceDir);
        if (!dir) { failed.push({ ...a, error: 'could not resolve skill source' }); continue; }
        capabilities.attachSkill(agentId, { name: mat.name, sourceDir: dir });
      }
      attached.push({ type: a.type, name: mat.name });
    } catch (e) {
      failed.push({ ...a, error: e.message });
    }
  }
  return { attached, failed };
}

// The generated agent's frontmatter `tools:` is an AUTHORITATIVE allowlist: when
// present it restricts the agent to ONLY the listed tools. Marketplace-attached
// MCP servers / skills are wired via the overlay, and the SDK runner widens the
// allowlist at launch (see sdk-runner _applyOverlayCaps) — but the raw Copilot
// CLI never sees the overlay, so a CLI-run agent is forbidden from calling its
// attached tools ("I don't have the WorkIQ integration available"). Patch the
// frontmatter allowlist in place so attached caps work under BOTH runtimes: grant
// each attached MCP server's tools via a `<server>/*` wildcard (the CLI honours
// it), plus the built-in `skill` tool when any skill is attached. No-op when the
// frontmatter carries no tools array (a null allowlist already permits all).
function grantAttachedToolsInFrontmatter(agentMdPath, { mcpServers = [], hasSkills = false } = {}) {
  try {
    if (!agentMdPath || !fs.existsSync(agentMdPath)) return;
    const additions = [];
    for (const s of mcpServers) if (s) additions.push(String(s) + '/*');
    if (hasSkills) additions.push('skill');
    if (!additions.length) return;
    const raw = fs.readFileSync(agentMdPath, 'utf8');
    const fmMatch = raw.match(/^---\n([\s\S]*?)\n---/);
    if (!fmMatch) return;
    const fm = fmMatch[1];
    const tm = fm.match(/^tools:[ \t]*(\[[\s\S]*?\])[ \t]*$/m);
    if (!tm) return; // null allowlist = all tools already permitted
    let tools;
    try { tools = JSON.parse(tm[1]); } catch (_) { return; }
    if (!Array.isArray(tools)) return;
    const have = new Set(tools.map(t => String(t).toLowerCase()));
    let changed = false;
    for (const a of additions) {
      if (!have.has(a.toLowerCase())) { tools.push(a); have.add(a.toLowerCase()); changed = true; }
    }
    if (!changed) return;
    const newFm = fm.replace(/^tools:[ \t]*\[[\s\S]*?\][ \t]*$/m, 'tools: ' + JSON.stringify(tools));
    fs.writeFileSync(agentMdPath, raw.replace(fmMatch[0], '---\n' + newFm + '\n---'));
  } catch (e) {
    console.error('[design] frontmatter tool-grant failed:', e.message);
  }
}
//  - persist (apply): write each skill into the catalog-scanned _generated-skills
//    dir (so it surfaces in the marketplace catalog for reuse) AND attach it to
//    the new agent's overlay.
//  - !persist (test): attach the skill inline to the throwaway overlay only, so
//    it's reaped with the overlay and never pollutes the shared catalog.
// Returns { generated:[{name,catalog}], failed:[{name,error}] }.
function materializeProposalSkills(agentId, newSkills, { persist } = {}) {
  const generated = [];
  const failed = [];
  for (const s of Array.isArray(newSkills) ? newSkills : []) {
    try {
      if (!s || !s.slug || !s.name) { failed.push({ name: (s && s.name) || '?', error: 'invalid skill spec' }); continue; }
      if (persist) {
        const w = marketplaceDesign.writeGeneratedSkill(s);
        capabilities.attachSkill(agentId, { name: w.name, sourceDir: w.dir });
        generated.push({ name: w.name, catalog: true });
      } else {
        capabilities.attachSkill(agentId, { name: s.slug, description: s.description, body: s.body });
        generated.push({ name: s.slug, catalog: false });
      }
    } catch (e) {
      failed.push({ name: (s && s.slug) || '?', error: e.message });
    }
  }
  return { generated, failed };
}
// agents.json. Used by the "test" flow so a suggestion can be exercised live
// before the user commits to creating the agent. Returns { config, id }.
const DESIGN_TEST_PREFIX = 'dtest-';
async function buildProposalConfig(proposal, { persist } = {}) {
  const agents = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8'));
  let id, config;

  if (proposal.kind === 'create') {
    const spec = proposal.agent || {};
    if (!spec.name || !spec.body) throw new Error('proposal.agent missing name/body');
    if (proposal.newName) spec.name = String(proposal.newName).trim();
    // Fold the user's (possibly edited) test prompt into the agent's core
    // instructions so the created agent embodies the behavior they validated.
    const testPrompt = String(proposal.testPrompt || '').trim();
    if (testPrompt) {
      const objective = ['## Primary Objective', '', testPrompt, ''].join('\n');
      if (!String(spec.body).includes(testPrompt)) {
        spec.body = String(spec.body).trimEnd() + '\n\n' + objective;
      }
    }
    const w = marketplaceDesign.writeGeneratedAgent(spec);
    id = persist ? uniqueAgentId(agents, w.slug) : DESIGN_TEST_PREFIX + require('crypto').randomBytes(4).toString('hex');
    config = {
      id, name: spec.name, cwd: w.dir, agent: w.slug,
      schedule: 'never', durable: true, group: 'Marketplace',
      description: spec.description || '',
      source: { type: 'design', kind: 'agent', path: w.agentMdPath, createdAt: new Date().toISOString() },
    };
  } else if (proposal.kind === 'enhance') {
    const targetId = String(proposal.agentId || '').trim();
    const target = agents.find(a => a.id === targetId);
    if (!target) throw new Error('Target agent not found');
    const newName = (proposal.newName || `${target.name} (enhanced)`).trim();
    id = persist ? uniqueAgentId(agents, marketplaceDesign.slugify(newName))
                 : DESIGN_TEST_PREFIX + require('crypto').randomBytes(4).toString('hex');
    config = {
      ...target,
      id,
      name: newName,
      autoStart: false,
      schedule: 'never',
      durable: true,
      group: target.group || 'Marketplace',
      source: { type: 'design', kind: 'enhanced-clone', from: targetId, createdAt: new Date().toISOString() },
    };
    // Inherit the target's already-attached capabilities, then layer the new ones.
    copyOverlay(targetId, id);
  } else {
    throw new Error('Unknown proposal kind');
  }
  return { config, id };
}

// Apply a design proposal. Both kinds now CREATE a new agent:
//   create  -> write + register a brand-new generated agent
//   enhance -> clone the target into a new agent (original is left untouched)
// then attach the proposed capabilities. The new agent can be exported to AzDO.
app.post('/api/marketplace/design/apply', async (req, res) => {
  const proposal = req.body && req.body.proposal;
  if (!proposal || !proposal.kind) return res.status(400).json({ error: 'proposal is required' });
  if (req.body.name) proposal.newName = String(req.body.name).trim();
  if (req.body.testPrompt != null) proposal.testPrompt = String(req.body.testPrompt);
  try {
    const { config, id: agentId } = await buildProposalConfig(proposal, { persist: true });
    const agents = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8'));
    agents.push(config);
    fs.writeFileSync(AGENTS_PATH, JSON.stringify(agents, null, 2));
    supervisor.register(config);

    const { attached, failed } = await attachCapsToAgent(agentId, proposal.attach);
    const skills = materializeProposalSkills(agentId, proposal.newSkills, { persist: true });
    // Grant attached MCP/skill tools in the new agent's frontmatter allowlist so
    // they're callable under the raw Copilot CLI runtime, not just the SDK runner.
    if (proposal.kind === 'create' && config.source && config.source.path) {
      grantAttachedToolsInFrontmatter(config.source.path, {
        mcpServers: attached.filter(a => a.type === 'mcp').map(a => a.name),
        hasSkills: attached.some(a => a.type === 'skill') || !!(skills.generated && skills.generated.length),
      });
    }
    broadcastSSE('agent-update', { agentId });
    res.json({ ok: true, kind: proposal.kind, agentId, created: config, attached, failed, generatedSkills: skills.generated, skillsFailed: skills.failed });
  } catch (e) {
    const msg = e.message || 'Apply failed';
    const code = /not found/i.test(msg) ? 404 : (/missing|required/i.test(msg) ? 400 : 500);
    res.status(code).json({ error: `Apply failed: ${msg}` });
  }
});

// Test a design proposal LIVE before committing. Stages the would-be agent to a
// throwaway id, attaches the proposed caps, and runs a single chat turn the
// client streams via GET /api/sessions/:sessionId/poll?verbose=1. Nothing is
// written to agents.json; throwaway overlays/packages are reaped here.
app.post('/api/marketplace/design/test', async (req, res) => {
  const proposal = req.body && req.body.proposal;
  if (!proposal || !proposal.kind) return res.status(400).json({ error: 'proposal is required' });
  const prompt = String((req.body && req.body.prompt) || '').trim()
    || 'Briefly: what tools and skills do you currently have access to? List them by name, then confirm you can use them.';
  try {
    // Reap prior throwaway test artifacts (best-effort).
    reapDesignTestArtifacts();

    const { config, id: testId } = await buildProposalConfig(proposal, { persist: false });
    const { attached, failed } = await attachCapsToAgent(testId, proposal.attach);
    const skills = materializeProposalSkills(testId, proposal.newSkills, { persist: false });
    config.name = `${config.name} (test)`;

    const sessionId = require('crypto').randomUUID();
    designTestSessions.set(sessionId, testId);
    runChatTurn({ sessionId, message: prompt, config, resume: false, agentId: testId });
    res.json({ ok: true, sessionId, testId, prompt, attached, failed, generatedSkills: skills.generated, skillsFailed: skills.failed });
  } catch (e) {
    const msg = e.message || 'Test failed';
    const code = /not found/i.test(msg) ? 404 : (/missing|required/i.test(msg) ? 400 : 500);
    res.status(code).json({ error: `Test failed: ${msg}` });
  }
});

const designTestSessions = new Map(); // sessionId -> testId
function reapDesignTestArtifacts() {
  for (const root of [agentPackage.OVERLAYS_ROOT, agentPackage.PACKAGES_ROOT]) {
    let entries = [];
    try { entries = fs.readdirSync(root, { withFileTypes: true }); } catch (_) { continue; }
    for (const e of entries) {
      if (!e.isDirectory()) continue;
      const n = e.name;
      if (n.startsWith(DESIGN_TEST_PREFIX) || n.startsWith('gen-' + DESIGN_TEST_PREFIX)) {
        try { fs.rmSync(path.join(root, n), { recursive: true, force: true }); } catch (_) {}
      }
    }
  }
}
// ============ End Marketplace API Routes ============

// SPA — serve new unified app for all page routes
function serveSpa(req, res) {
  if (fs.existsSync(SPA_PATH)) {
    // The SPA is a single ~2.5MB HTML file that changes constantly in dev; if the
    // browser caches it, edits appear to "not take" no matter how many times the user
    // reloads. Force a fresh fetch every time.
    res.set('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
    res.set('Pragma', 'no-cache');
    res.set('Expires', '0');
    try {
      res.type('html').send(renderSpaHtml());
    } catch (err) {
      console.error('serveSpa render failed, falling back to raw file:', err && err.message);
      res.sendFile(SPA_PATH);
    }
  } else {
    // SPA asset missing (degraded state). The legacy embedded dashboard has been removed.
    res.status(503).send('<!DOCTYPE html><html><head><meta charset="utf-8"><title>TheOffice.AI</title></head><body style="font-family:system-ui;padding:40px"><h1>TheOffice.AI</h1><p>The SPA bundle (<code>public/app.html</code>) was not found. Please restore it and reload.</p></body></html>');
  }
}
['/', '/agents', '/dashboard', '/tasks', '/chat', '/activity', '/marketplace'].forEach(route => {
  app.get(route, serveSpa);
});

// Version/health endpoint for verifying deployed version
app.get('/api/version', (req, res) => {
  res.json({
    version: GIT_VERSION.version || '',
    commit: GIT_VERSION.hash,
    builtAt: GIT_VERSION.builtAt || '',
    gitHash: GIT_VERSION.hash,
    gitMessage: GIT_VERSION.message,
    dirty: GIT_VERSION.dirty,
    fileHash: GIT_VERSION.fileHash || 'unknown',
    pid: PROCESS_PID,
    startedAt: PROCESS_START,
    uptime: Math.round(process.uptime()) + 's',
    desktop: updater.isDesktop()
  });
});

// --- What's New (release notes) --------------------------------------------
// Serves the curated changelog so the SPA can greet users after an upgrade.
function cmpWhatsNewVer(a, b) {
  // Numeric compare on dot/dash-split segments; mirrors the SPA's semverGt so
  // the server, generator, and UI all agree on ordering (handles X.Y.Z-preview.N).
  const pa = String(a || '').split(/[.\-+]/).map(n => parseInt(n, 10)).map(n => Number.isNaN(n) ? 0 : n);
  const pb = String(b || '').split(/[.\-+]/).map(n => parseInt(n, 10)).map(n => Number.isNaN(n) ? 0 : n);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const x = pa[i] || 0, y = pb[i] || 0;
    if (x !== y) return x - y;
  }
  return 0;
}
function readWhatsNew() {
  try {
    const raw = fs.readFileSync(path.join(__dirname, 'whats-new.json'), 'utf-8');
    const parsed = JSON.parse(raw);
    const entries = Array.isArray(parsed) ? parsed : (parsed.entries || []);
    // Newest-first so the dialog and home feed render in a predictable order
    // regardless of how the file happens to be ordered on disk.
    return entries.slice().sort((a, b) => cmpWhatsNewVer(b && b.version, a && a.version));
  } catch { return []; }
}

// When running from source in a plain browser (i.e. NOT the packaged desktop app),
// there is no shipped version to "update" to — the bundled whats-new.json changelog
// is tied to desktop releases. Instead, surface the recent git commits as the
// release notes so "What's new" reflects what actually changed on this checkout.
// Returns [] on a packaged build or anywhere git is unavailable.
function readRecentCommitNotes(limit = 40) {
  try {
    const { execSync } = require('child_process');
    const out = execSync(`git --no-pager log -${limit} --no-merges --format=%h%x09%cs%x09%s`, { cwd: __dirname, encoding: 'utf-8' }).trim();
    if (!out) return [];
    const rows = out.split('\n').map((l) => {
      const parts = l.split('\t');
      return { hash: parts[0] || '', date: parts[1] || '', subject: (parts.slice(2).join('\t') || '').trim() };
    }).filter((r) => r.subject);
    if (!rows.length) return [];
    const subjects = rows.map((r) => r.subject);
    const items = rows.map((r) => r.subject + (r.hash ? ' (' + r.hash + ')' : ''));
    return [{
      version: GIT_VERSION.version || 'dev',
      date: rows[0].date || new Date().toISOString().slice(0, 10),
      title: 'Recent changes',
      summary: 'You\u2019re running from source, so here are the latest commits on this build \u2014 there\u2019s no packaged version to update to.',
      highlights: subjects.slice(0, 5),
      details: [{ heading: 'Latest commits', items }],
    }];
  } catch { return []; }
}

app.get('/api/whats-new', (req, res) => {
  const current = GIT_VERSION.version || '';
  if (!updater.isDesktop()) {
    const commitNotes = readRecentCommitNotes();
    if (commitNotes.length) return res.json({ current: commitNotes[0].version, entries: commitNotes, source: 'commits' });
  }
  let entries = readWhatsNew();
  // Safety net: never hand the UI an empty changelog. If the file is missing or
  // yields nothing (e.g. a build that skipped note generation), synthesize a
  // minimal entry for the running version so "What's new" is never blank.
  if (!entries.length && current) {
    entries = [{
      version: current,
      date: (GIT_VERSION.builtAt || '').slice(0, 10) || new Date().toISOString().slice(0, 10),
      title: 'Latest update',
      summary: 'You are on the latest version. Detailed release notes were not bundled with this build.',
      highlights: ['Improvements, fixes, and behind-the-scenes updates.'],
      details: [],
    }];
  }
  res.json({ current, entries });
});

// Maintainer helper (dev only, where git is available): draft a changelog entry
// for HEAD from the commit log since a given ref, using the same AI one-shot the
// rest of the app uses. Returns a { version, ...entry } object to paste into
// whats-new.json — it does NOT write the file.
app.post('/api/whats-new/generate', async (req, res) => {
  try {
    const { execSync } = require('child_process');
    let sinceRef = (req.body && req.body.since || '').trim();
    if (!sinceRef) {
      // Default: the most recent tag, else the last 20 commits.
      try { sinceRef = execSync('git describe --tags --abbrev=0', { cwd: __dirname, encoding: 'utf-8' }).trim(); } catch {}
    }
    const range = sinceRef ? `${sinceRef}..HEAD` : '-20';
    let log = '';
    try { log = execSync(`git --no-pager log ${range} --format=%s`, { cwd: __dirname, encoding: 'utf-8' }).trim(); } catch (e) {
      return res.status(502).json({ error: 'git log failed (is git available?): ' + e.message });
    }
    if (!log) return res.json({ error: 'No commits found in range ' + range });
    const version = GIT_VERSION.version || '';
    const prompt = [
      'You are drafting a user-facing "What\'s New" changelog entry for a desktop/web app.',
      'Given the raw git commit subjects below, produce ONE JSON object (no markdown, no code fence) with this exact shape:',
      '{ "version": string, "date": "YYYY-MM-DD", "title": string, "summary": string, "highlights": string[], "details": [{ "heading": string, "items": string[] }] }',
      'Write for end users, not developers: describe capabilities and fixes in plain language, group related work under headings, omit purely internal/mechanical commits.',
      '"title" is a short phrase; "summary" is 1-2 sentences; 2-4 highlights; 1-3 detail groups.',
      'Use version "' + version + '" and today\'s date.',
      '',
      'Commit subjects:',
      log.slice(0, 8000),
      '',
      'JSON:'
    ].join('\n');
    let acc = '';
    await sdkRunner.runChat({ config: null, prompt, sessionId: require('crypto').randomUUID(), cwd: __dirname, availableTools: [], onChunk: (c) => { acc += c; }, meta: { source: 'system', category: 'release_notes' } });
    let entry = null;
    try {
      const m = acc.match(/\{[\s\S]*\}/);
      entry = JSON.parse(m ? m[0] : acc);
    } catch {
      return res.json({ error: 'Could not parse AI output as JSON', raw: acc.trim().slice(0, 4000) });
    }
    if (!entry.version) entry.version = version;
    res.json({ entry });
  } catch (e) { res.status(500).json({ error: (e && e.message) || 'generate failed' }); }
});

// AI-summarized "What's new". Rather than dumping raw commit subjects, this asks
// the AI to read the recent commit log and produce a short, user-facing digest
// that highlights the most impactful changes. Cached in-memory keyed on HEAD so
// we don't re-run the model every time the dialog is opened.
let _whatsNewSummaryCache = { key: '', data: null, at: 0 };
app.get('/api/whats-new/summary', async (req, res) => {
  try {
    const { execSync } = require('child_process');
    let log = '';
    try {
      log = execSync('git --no-pager log -50 --no-merges --format=%h%x09%s', { cwd: __dirname, encoding: 'utf-8' }).trim();
    } catch {
      return res.json({ available: false, reason: 'git-unavailable' });
    }
    if (!log) return res.json({ available: false, reason: 'no-commits' });
    const rows = log.split('\n').map((l) => l.split('\t'));
    const headHash = (rows[0] && rows[0][0]) || '';
    const cacheKey = headHash + ':' + rows.length;
    if (!req.query.refresh && _whatsNewSummaryCache.key === cacheKey && _whatsNewSummaryCache.data) {
      return res.json({ available: true, cached: true, ...(_whatsNewSummaryCache.data) });
    }
    const subjects = rows.map((r) => (r.slice(1).join('\t') || '').trim()).filter(Boolean);
    if (!subjects.length) return res.json({ available: false, reason: 'no-commits' });
    const prompt = [
      'You are writing a short, user-facing "What\'s new" digest for a desktop/web productivity app.',
      'Below is the recent git commit log (newest first). Read ALL of it, then synthesize what actually changed for the user.',
      'Respond with ONE JSON object only (no markdown, no code fence) of this exact shape:',
      '{ "headline": string, "summary": string, "highlights": [ { "text": string, "impact": "high" | "normal" } ] }',
      'Rules:',
      '- Write for end users, not developers. Describe capabilities, improvements, and fixes in plain language.',
      '- "headline": a punchy 3-7 word phrase capturing the theme of recent work.',
      '- "summary": 1-2 sentences giving the overall gist of what changed.',
      '- "highlights": 3-6 items, each a single clear sentence. Mark the genuinely notable, user-visible changes as impact "high"; routine tweaks/fixes as "normal". Order most impactful first.',
      '- Group related commits into one highlight; omit purely internal/mechanical churn (build tweaks, lint, refactors with no user impact).',
      '',
      'Recent commits (newest first):',
      subjects.slice(0, 60).map((s) => '- ' + s).join('\n').slice(0, 8000),
      '',
      'JSON:'
    ].join('\n');
    let acc = '';
    await sdkRunner.runChat({ config: null, prompt, sessionId: require('crypto').randomUUID(), cwd: __dirname, availableTools: [], onChunk: (c) => { acc += c; }, meta: { source: 'system', category: 'release_notes' } });
    let data = null;
    try {
      const m = acc.match(/\{[\s\S]*\}/);
      data = JSON.parse(m ? m[0] : acc);
    } catch {
      return res.json({ available: false, reason: 'parse-failed' });
    }
    // Normalize shape defensively so the client can render without guards.
    const out = {
      headline: String(data.headline || 'Recent changes').slice(0, 120),
      summary: String(data.summary || '').slice(0, 600),
      highlights: (Array.isArray(data.highlights) ? data.highlights : []).slice(0, 8).map((h) => {
        if (typeof h === 'string') return { text: h.slice(0, 300), impact: 'normal' };
        return { text: String((h && h.text) || '').slice(0, 300), impact: (h && h.impact === 'high') ? 'high' : 'normal' };
      }).filter((h) => h.text),
    };
    _whatsNewSummaryCache = { key: cacheKey, data: out, at: Date.now() };
    res.json({ available: true, cached: false, ...out });
  } catch (e) {
    res.json({ available: false, reason: 'error', error: (e && e.message) || 'summary failed' });
  }
});

// --- Feedback -> GitHub issue ----------------------------------------------
const FEEDBACK_OWNER = 'chcosta';
const FEEDBACK_REPO = 'TheOffice.AI';
const FEEDBACK_ASSET_BRANCH = 'feedback-assets';

app.post('/api/feedback', async (req, res) => {
  try {
    const b = req.body || {};
    const topic = String(b.topic || 'General').trim();
    const mood = String(b.mood || '').trim();
    const text = String(b.text || '').trim();
    if (!text) return res.status(400).json({ error: 'Feedback text is required.' });

    // Gather lightweight context to make the issue reproducible.
    const ctxLines = [];
    if (b.route) ctxLines.push('Screen/route: ' + String(b.route).slice(0, 200));
    if (b.version || GIT_VERSION.version) ctxLines.push('App version: ' + (b.version || GIT_VERSION.version));
    if (b.commit || GIT_VERSION.hash) ctxLines.push('Commit: ' + (b.commit || GIT_VERSION.hash));
    if (b.userAgent) ctxLines.push('User agent: ' + String(b.userAgent).slice(0, 300));
    if (b.platform) ctxLines.push('Platform: ' + String(b.platform).slice(0, 120));
    const contextBlock = ctxLines.join('\n');

    // Ask the AI to turn the raw note into a clean issue. Structure is topic-aware:
    // bugs/requests get useful sections when the info is present; General stays faithful.
    const moodNote = mood ? `The user's overall sentiment was "${mood}".` : '';
    const isBug = /bug/i.test(topic);
    const isIdea = /request|idea|feature/i.test(topic);
    let shapeRule;
    if (isBug) {
      shapeRule = '- This is a BUG report. Where the user supplied the information, organize the body with "### What happened", "### Expected behavior", and "### Steps to reproduce" headings. OMIT any of those sections the user did not actually address — never add a heading only to fill it with "N/A", "Not provided", or a guess.';
    } else if (isIdea) {
      shapeRule = '- This is a feature request / idea. Where the user supplied the information, organize the body with "### Summary" and "### Why it helps" headings. OMIT a section the user did not address — never add a heading only to fill it with a placeholder or a guess.';
    } else {
      shapeRule = '- This is general feedback. Do NOT impose a template or add headings/sections. Convey only what the user actually said, lightly cleaned up. If it is one or two sentences, keep the body one or two sentences.';
    }
    const prompt = [
      'Convert the following in-app user feedback into a clear GitHub issue.',
      'Respond with ONE JSON object (no markdown, no code fence) of shape:',
      '{ "title": string, "body": string }',
      'Rules:',
      '- "title" is a concise, specific summary (max ~90 chars), no leading label.',
      '- "body" is GitHub-flavored markdown that faithfully conveys ONLY what the user actually said. Do not invent details, placeholders, or speculation.',
      shapeRule,
      '- Do NOT include the raw context block or screenshots in your output; those are appended separately.',
      '',
      'Topic: ' + topic,
      moodNote,
      'User feedback:',
      text,
      '',
      'JSON:'
    ].filter(Boolean).join('\n');

    let acc = '';
    try {
      await sdkRunner.runChat({ config: null, prompt, sessionId: require('crypto').randomUUID(), cwd: __dirname, availableTools: [], onChunk: (c) => { acc += c; }, meta: { source: 'system', category: 'feedback' } });
    } catch { /* fall through to templated fallback */ }
    let gen = null;
    try { const m = acc.match(/\{[\s\S]*\}/); if (m) gen = JSON.parse(m[0]); } catch {}
    let title = (gen && gen.title || '').trim();
    let body = (gen && gen.body || '').trim();
    if (!title) title = `[${topic}] ` + text.split('\n')[0].slice(0, 80);
    if (!body) body = text;

    // Try to attach a screenshot (raw.githubusercontent URLs render inline).
    let shotNote = '';
    if (b.screenshot) {
      try {
        const base64 = String(b.screenshot).replace(/^data:image\/\w+;base64,/, '');
        const name = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}.png`;
        const up = await github.uploadImageToBranch(FEEDBACK_OWNER, FEEDBACK_REPO, {
          branch: FEEDBACK_ASSET_BRANCH,
          path: `screenshots/${name}`,
          base64,
          message: 'Add feedback screenshot ' + name
        });
        shotNote = `\n\n### Screenshot\n\n![screenshot](${up.url})`;
      } catch (e) {
        shotNote = `\n\n_(A screenshot was attached in-app but could not be uploaded: ${(e && e.message || 'unknown error').slice(0, 160)}.)_`;
      }
    }

    let fullBody = body;
    if (shotNote) fullBody += shotNote;
    if (contextBlock) fullBody += `\n\n---\n<sub>Submitted via in-app feedback.</sub>\n\n<details><summary>Environment</summary>\n\n\`\`\`\n${contextBlock}\n\`\`\`\n</details>`;

    // Topic -> labels.
    const labels = ['feedback'];
    if (/bug/i.test(topic)) labels.push('bug');
    else if (/request|idea/i.test(topic)) labels.push('enhancement');
    try { await github.ensureLabel(FEEDBACK_OWNER, FEEDBACK_REPO, 'feedback', '5319e7', 'Submitted via in-app feedback'); } catch {}

    const issue = await github.createIssue(FEEDBACK_OWNER, FEEDBACK_REPO, { title, body: fullBody, labels });
    res.json({ ok: true, number: issue.number, url: issue.url, screenshotAttached: !!(b.screenshot && shotNote && shotNote.includes('![')) });
  } catch (e) {
    res.status(500).json({ error: (e && e.message) || 'Failed to submit feedback' });
  }
});

// --- In-app self-updater (desktop build only) ------------------------------
// No-ops (supported:false) outside the packaged Tauri sidecar so browser/LAN
// and `npm start` are unaffected.
app.get('/api/update/check', async (req, res) => {
  if (!updater.isDesktop()) return res.json({ supported: false });
  try {
    const r = await updater.checkForUpdate(GIT_VERSION.version || '', { serverDir: __dirname });
    const { _best, ...pub } = r;
    res.json(pub);
  } catch (e) {
    res.json({ supported: true, error: (e && e.message) || String(e), updateAvailable: false });
  }
});

app.post('/api/update/download', async (req, res) => {
  if (!updater.isDesktop()) return res.json({ supported: false });
  try {
    const r = await updater.checkForUpdate(GIT_VERSION.version || '', { serverDir: __dirname });
    if (!r.updateAvailable || !r._best) return res.json({ started: false, error: 'No update available.' });
    res.json(updater.startDownload(r._best, { serverDir: __dirname }));
  } catch (e) {
    res.status(500).json({ started: false, error: (e && e.message) || String(e) });
  }
});

