// Open agent source in VS Code
app.post('/api/agents/:id/edit-source', (req, res) => {
  const entry = supervisor.agents.get(req.params.id);
  if (!entry) return res.status(404).json({ error: 'Agent not found' });
  const { spawnSync, spawn } = require('child_process');
  const config = entry.config;
  // Prefer sourceDir (original source), then infer from cwd, then pluginDir, then cwd
  let targetDir = config.sourceDir;
  if (!targetDir && config.pluginDir && config.pluginDir.includes(PLUGINS_DIR)) {
    const pluginName = path.basename(config.pluginDir);
    const candidate = path.join(config.cwd || '', '.github', 'plugin', pluginName);
    if (fs.existsSync(candidate)) targetDir = candidate;
  }
  if (!targetDir) targetDir = config.pluginDir || config.cwd;
  // Try VS Code Insiders first, fall back to VS Code
  const insiders = spawnSync('where', ['code-insiders'], { shell: true, encoding: 'utf-8' });
  const editor = insiders.status === 0 ? 'code-insiders' : 'code';
  spawn(editor, [targetDir], { shell: true, detached: true, stdio: 'ignore' }).unref();
  res.json({ ok: true, editor, path: targetDir });
});

// Check if agent's installed plugin is out of date compared to source
// Compute update status for a single agent/plugin entry. Returns { upToDate, ... }.
// Shared by the per-item check-update route and the aggregate available-count route.
async function computeUpdateStatus(entry) {
  const config = entry.config;

  // Azure DevOps source: compare the stored objectId against the current one on the branch.
  if (config.source && config.source.type === 'azdo') {
    const s = config.source;
    try {
      let current = null;
      if (s.kind === 'plugin') {
        // fresh.objectId is now a composite signature over all plugin files
        // (see azdo.pluginSignature), so any file change is detected.
        try {
          const items = await azdo.discover(s.org, s.project, s.repo, s.branch);
          const fresh = items.find(it => it.kind === 'plugin' && it.path === s.path);
          current = (fresh && fresh.objectId) || null;
        } catch {}
        // No plugin.json-only fallback: comparing a single blob against the
        // composite would mis-report. If discovery fails we treat it as
        // indeterminate (upToDate) rather than nag with a false positive.
      } else {
        current = await azdo.getObjectId(s.org, s.project, s.repo, s.branch, s.path);
      }
      return {
        upToDate: !current || !s.objectId || current === s.objectId,
        reason: 'azdo',
        source: s,
        currentObjectId: current
      };
    } catch (e) {
      return { upToDate: true, reason: 'azdo-error', error: e.message };
    }
  }

  let sourceDir = config.sourceDir;
  const pluginDir = config.pluginDir;

  // If no explicit sourceDir, try to infer: if pluginDir is under our plugins/ folder,
  // check if there's a matching .github/plugin/<name> in the agent's cwd
  if (!sourceDir && pluginDir && pluginDir.includes(PLUGINS_DIR)) {
    const pluginName = path.basename(pluginDir);
    const candidate = path.join(config.cwd || '', '.github', 'plugin', pluginName);
    if (fs.existsSync(candidate)) sourceDir = candidate;
  }

  // No sourceDir means either the pluginDir IS the source or there's no plugin
  if (!sourceDir || !pluginDir) return { upToDate: true, reason: 'no-overlay' };
  // If sourceDir === pluginDir, no comparison needed
  if (path.resolve(sourceDir) === path.resolve(pluginDir)) return { upToDate: true, reason: 'same-dir' };
  // Both must exist
  if (!fs.existsSync(sourceDir)) return { upToDate: true, reason: 'source-missing' };
  if (!fs.existsSync(pluginDir)) return { upToDate: false, reason: 'installed-missing' };

  // Compare key files recursively (shallow: plugin.json mtime, agents/*.md sizes)
  function getFingerprint(dir) {
    const files = {};
    function walk(d, prefix) {
      try {
        for (const entry of fs.readdirSync(d, { withFileTypes: true })) {
          const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
          if (entry.isDirectory()) {
            walk(path.join(d, entry.name), rel);
          } else {
            const stat = fs.statSync(path.join(d, entry.name));
            files[rel] = { size: stat.size, mtime: stat.mtimeMs };
          }
        }
      } catch {}
    }
    walk(dir, '');
    return files;
  }

  const srcFiles = getFingerprint(sourceDir);
  const instFiles = getFingerprint(pluginDir);
  const diffs = [];
  for (const [file, info] of Object.entries(srcFiles)) {
    if (!instFiles[file]) {
      diffs.push({ file, reason: 'new-in-source' });
    } else if (instFiles[file].size !== info.size) {
      diffs.push({ file, reason: 'size-changed' });
    } else if (info.mtime > instFiles[file].mtime) {
      diffs.push({ file, reason: 'source-newer' });
    }
  }

  return { upToDate: diffs.length === 0, diffs: diffs.slice(0, 10), sourceDir, pluginDir };
}

app.get('/api/agents/:id/check-update', async (req, res) => {
  const entry = supervisor.agents.get(req.params.id);
  if (!entry) return res.status(404).json({ error: 'Agent not found' });
  try {
    res.json(await computeUpdateStatus(entry));
  } catch (e) {
    res.json({ upToDate: true, reason: 'error', error: e.message });
  }
});

// Browse for folder using Windows folder picker
app.post('/api/browse-folder', (req, res) => {
  const { exec } = require('child_process');
  const tmpFile = path.join(__dirname, '.browse-result.txt');
  try { fs.unlinkSync(tmpFile); } catch {}
  const psScript = `
Add-Type -AssemblyName System.Windows.Forms
$f = New-Object System.Windows.Forms.FolderBrowserDialog
$f.Description = 'Select agent directory'
$f.RootFolder = 'MyComputer'
$f.SelectedPath = 'C:\\repos'
$topForm = New-Object System.Windows.Forms.Form
$topForm.TopMost = $true
$result = $f.ShowDialog($topForm)
$topForm.Dispose()
if ($result -eq 'OK') { Set-Content -Path '${tmpFile.replace(/\\/g, '\\\\')}' -Value $f.SelectedPath }
`;
  const psFile = path.join(__dirname, '.browse-folder.ps1');
  fs.writeFileSync(psFile, psScript);
  // Use 'start /wait' to run powershell in a visible (but minimized) process
  exec(`start /wait powershell -NoProfile -ExecutionPolicy Bypass -File "${psFile}"`, { cwd: __dirname }, () => {
    let folder = null;
    try { folder = fs.readFileSync(tmpFile, 'utf-8').trim(); fs.unlinkSync(tmpFile); } catch {}
    try { fs.unlinkSync(psFile); } catch {}
    res.json({ folder: folder || null });
  });
});

// Get recent directories from existing agents
app.get('/api/recent-dirs', (req, res) => {
  const agents = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8'));
  const seen = new Set();
  const dirs = agents.map(a => a.cwd).filter(Boolean).filter(d => {
    const key = d.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  res.json(dirs);
});

// Email agent output via default mail client
app.post('/api/agents/:id/email', (req, res) => {
  const status = supervisor.getStatus(req.params.id);
  if (!status || !status.lastRun?.output) return res.status(404).json({ error: 'No output to email' });
  const agentName = status.config?.name || req.params.id;
  const subject = `Agent Report: ${agentName} — ${new Date(status.lastRun.started_at).toLocaleDateString()}`;
  const markdown = status.lastRun.output;
  
  // Convert markdown to HTML and create a .eml file for rich formatting
  const { marked } = require('marked');
  const htmlBody = marked.parse(markdown);
  const htmlEmail = `<html><head><style>
body { font-family: Segoe UI, Arial, sans-serif; font-size: 14px; color: #222; padding: 16px; }
h1, h2, h3 { color: #333; }
a { color: #0078d4; }
hr { border: none; border-top: 1px solid #ddd; margin: 16px 0; }
ul, ol { padding-left: 24px; }
li { margin-bottom: 4px; }
code { background: #f4f4f4; padding: 2px 4px; border-radius: 3px; font-size: 13px; }
pre { background: #f4f4f4; padding: 12px; border-radius: 4px; overflow-x: auto; }
</style></head><body>${htmlBody}</body></html>`;

  // Build .eml (RFC 2822) with HTML content
  const boundary = `----=_Part_${Date.now()}`;
  const eml = [
    `Subject: ${subject}`,
    `MIME-Version: 1.0`,
    `Content-Type: multipart/alternative; boundary="${boundary}"`,
    `X-Unsent: 1`,
    ``,
    `--${boundary}`,
    `Content-Type: text/plain; charset="utf-8"`,
    `Content-Transfer-Encoding: 8bit`,
    ``,
    markdown,
    ``,
    `--${boundary}`,
    `Content-Type: text/html; charset="utf-8"`,
    `Content-Transfer-Encoding: 8bit`,
    ``,
    htmlEmail,
    ``,
    `--${boundary}--`
  ].join('\r\n');

  const os = require('os');
  const emlPath = path.join(os.tmpdir(), `agent-email-${req.params.id}-${Date.now()}.eml`);
  fs.writeFileSync(emlPath, eml, 'utf8');
  const { exec } = require('child_process');
  exec(`start "" "${emlPath}"`);
  res.json({ ok: true });
});

// Email a session's content (full conversation or last response only)
app.post('/api/sessions/:id/email', (req, res) => {
  const { mode } = req.body; // 'full' or 'last'
  const sessionDir = path.join(SESSION_STATE_DIR, req.params.id);
  if (!fs.existsSync(sessionDir)) return res.status(404).json({ error: 'Session not found' });

  const conversation = readSessionConversation(sessionDir);
  const eventsPath = path.join(sessionDir, 'events.jsonl');
  let agentName = 'Agent';
  if (fs.existsSync(eventsPath)) {
    for (const line of fs.readFileSync(eventsPath, 'utf-8').split('\n').filter(Boolean)) {
      try {
        const ev = JSON.parse(line);
        if (ev.type === 'subagent.selected' && ev.data?.agentDisplayName) { agentName = ev.data.agentDisplayName; break; }
      } catch {}
    }
  }

  let markdown = '';
  const subject = `Session: ${agentName} — ${new Date().toLocaleDateString()}`;
  if (mode === 'last') {
    // Last agent response only
    const lastTurn = [...conversation.turns].reverse().find(t => t.assistant);
    markdown = lastTurn?.assistant || 'No agent response found.';
  } else {
    // Full conversation
    for (const turn of conversation.turns) {
      markdown += `**You:** ${turn.content}\n\n`;
      if (turn.assistant) markdown += `**Agent:** ${turn.assistant}\n\n---\n\n`;
    }
  }

  const { marked } = require('marked');
  const htmlBody = marked.parse(markdown);
  const htmlEmail = `<html><head><style>
body { font-family: Segoe UI, Arial, sans-serif; font-size: 14px; color: #222; padding: 16px; }
h1, h2, h3 { color: #333; }
a { color: #0078d4; }
hr { border: none; border-top: 1px solid #ddd; margin: 16px 0; }
ul, ol { padding-left: 24px; }
li { margin-bottom: 4px; }
code { background: #f4f4f4; padding: 2px 4px; border-radius: 3px; font-size: 13px; }
pre { background: #f4f4f4; padding: 12px; border-radius: 4px; overflow-x: auto; }
</style></head><body>${htmlBody}</body></html>`;

  const boundary = `----=_Part_${Date.now()}`;
  const eml = [
    `Subject: ${subject}`,
    `MIME-Version: 1.0`,
    `Content-Type: multipart/alternative; boundary="${boundary}"`,
    `X-Unsent: 1`,
    ``,
    `--${boundary}`,
    `Content-Type: text/plain; charset="utf-8"`,
    `Content-Transfer-Encoding: 8bit`,
    ``,
    markdown,
    ``,
    `--${boundary}`,
    `Content-Type: text/html; charset="utf-8"`,
    `Content-Transfer-Encoding: 8bit`,
    ``,
    htmlEmail,
    ``,
    `--${boundary}--`
  ].join('\r\n');

  const os = require('os');
  const emlPath = path.join(os.tmpdir(), `session-email-${req.params.id.substring(0,8)}-${Date.now()}.eml`);
  fs.writeFileSync(emlPath, eml, 'utf8');
  const { exec } = require('child_process');
  exec(`start "" "${emlPath}"`);
  res.json({ ok: true });
});

// Share content via email (.eml file)
app.post('/api/share/email', (req, res) => {
  const { content, subject } = req.body;
  if (!content) return res.status(400).json({ error: 'No content to share' });

  const { marked } = require('marked');
  const htmlBody = marked.parse(content);
  const htmlEmail = `<html><head><style>
body { font-family: Segoe UI, Arial, sans-serif; font-size: 14px; color: #222; padding: 16px; }
h1, h2, h3 { color: #333; }
a { color: #0078d4; }
hr { border: none; border-top: 1px solid #ddd; margin: 16px 0; }
code { background: #f4f4f4; padding: 2px 4px; border-radius: 3px; font-size: 13px; }
pre { background: #f4f4f4; padding: 12px; border-radius: 4px; overflow-x: auto; }
table { border-collapse: collapse; }
th, td { border: 1px solid #ddd; padding: 6px 10px; }
</style></head><body>${htmlBody}</body></html>`;

  const boundary = `----=_Part_${Date.now()}`;
  const eml = [
    `Subject: ${subject || 'Shared from TheOffice.AI'}`,
    `MIME-Version: 1.0`,
    `Content-Type: multipart/alternative; boundary="${boundary}"`,
    `X-Unsent: 1`,
    ``,
    `--${boundary}`,
    `Content-Type: text/plain; charset="utf-8"`,
    `Content-Transfer-Encoding: 8bit`,
    ``,
    content,
    ``,
    `--${boundary}`,
    `Content-Type: text/html; charset="utf-8"`,
    `Content-Transfer-Encoding: 8bit`,
    ``,
    htmlEmail,
    ``,
    `--${boundary}--`
  ].join('\r\n');

  const draftDir = path.join(__dirname, '.share-drafts');
  fs.mkdirSync(draftDir, { recursive: true });
  const emlPath = path.join(draftDir, `share-${Date.now()}.eml`);
  fs.writeFileSync(emlPath, eml, 'utf8');
  const { exec } = require('child_process');
  exec(`start "" "${emlPath}"`);
  res.json({ ok: true });
});

// Share content to Teams channel
app.post('/api/share/teams', (req, res) => {
  const { content, subject } = req.body;
  if (!content) return res.status(400).json({ error: 'No content to share' });

  const webhookUrl = process.env.TEAMS_WEBHOOK_URL;
  if (!webhookUrl) {
    return res.status(400).json({ error: 'Teams webhook not configured. Set TEAMS_WEBHOOK_URL environment variable.' });
  }

  const card = {
    '@type': 'MessageCard',
    '@context': 'http://schema.org/extensions',
    themeColor: 'b11f4b',
    summary: subject || 'Shared from TheOffice.AI',
    sections: [{
      activityTitle: subject || 'Shared from TheOffice.AI',
      activitySubtitle: new Date().toLocaleString(),
      text: content.length > 5000 ? `${content.substring(0, 5000)}\n\n...(truncated)` : content,
      markdown: true
    }]
  };

  const https = require('https');
  const url = new URL(webhookUrl);
  const postData = JSON.stringify(card);
  const options = {
    hostname: url.hostname,
    port: 443,
    path: url.pathname + url.search,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(postData) }
  };

  const request = https.request(options, (response) => {
    let data = '';
    response.on('data', chunk => data += chunk);
    response.on('end', () => {
      if (response.statusCode >= 200 && response.statusCode < 300) {
        res.json({ ok: true });
      } else {
        res.status(502).json({ error: `Teams returned ${response.statusCode}: ${data}` });
      }
    });
  });
  request.on('error', (e) => res.status(502).json({ error: e.message }));
  request.write(postData);
  request.end();
});

// ---- Session History & Chat ----
const SESSION_STATE_DIR = path.join(process.env.USERPROFILE || process.env.HOME, '.copilot', 'session-state');

function parseYamlSimple(text) {
  const obj = {};
  for (const line of text.split('\n')) {
    const m = line.match(/^(\w[\w_]*)\s*:\s*(.+)/);
    if (m) obj[m[1]] = m[2].trim();
  }
  return obj;
}

function readSessionMeta(sessionDir) {
  const wsPath = path.join(sessionDir, 'workspace.yaml');
  if (!fs.existsSync(wsPath)) return null;
  const yaml = parseYamlSimple(fs.readFileSync(wsPath, 'utf-8'));
  return {
    id: yaml.id || path.basename(sessionDir),
    name: yaml.name || '(unnamed)',
    cwd: yaml.cwd || '',
    repository: yaml.repository || '',
    branch: yaml.branch || '',
    client: yaml.client_name || '',
    createdAt: yaml.created_at || '',
    updatedAt: yaml.updated_at || ''
  };
}

function readSessionConversation(sessionDir, opts = {}) {
  const eventsPath = path.join(sessionDir, 'events.jsonl');
  if (!fs.existsSync(eventsPath)) return { turns: [], summary: '' };
  const lines = fs.readFileSync(eventsPath, 'utf-8').split('\n').filter(Boolean);
  const turns = [];
  let currentAssistant = '';
  let currentSteps = [];
  let subTurnCount = 0;
  let currentModel = null;
  let sessionMeta = null;
  let tokenStats = null;
  for (const line of lines) {
    try {
      const ev = JSON.parse(line);
      if (ev.type === 'session.start' && ev.data) {
        sessionMeta = {
          cwd: ev.data.context?.cwd,
          branch: ev.data.context?.branch,
          repo: ev.data.context?.repository,
          agent: ev.data.context?.agentName,
          copilotVersion: ev.data.copilotVersion
        };
      }
      if (ev.type === 'session.resume' && ev.data) {
        if (!sessionMeta) sessionMeta = {};
        sessionMeta.cwd = sessionMeta.cwd || ev.data.context?.cwd;
        sessionMeta.branch = sessionMeta.branch || ev.data.context?.branch;
        sessionMeta.repo = sessionMeta.repo || ev.data.context?.repository;
      }
      if (ev.type === 'subagent.selected' && ev.data) {
        if (!sessionMeta) sessionMeta = {};
        sessionMeta.agent = ev.data.agentDisplayName || ev.data.agentName;
      }
      if (ev.type === 'session.model_change' && ev.data) {
        currentModel = ev.data.newModel;
      }
      if (ev.type === 'session.shutdown' && ev.data) {
        tokenStats = {
          premiumRequests: ev.data.totalPremiumRequests,
          apiDurationMs: ev.data.totalApiDurationMs,
          input: ev.data.tokenDetails?.input?.tokenCount || 0,
          cacheRead: ev.data.tokenDetails?.cache_read?.tokenCount || 0,
          cacheWrite: ev.data.tokenDetails?.cache_write?.tokenCount || 0,
          output: ev.data.tokenDetails?.output?.tokenCount || 0,
          linesAdded: ev.data.codeChanges?.linesAdded,
          linesRemoved: ev.data.codeChanges?.linesRemoved
        };
      }
      if (ev.type === 'user.message' && ev.data?.content) {
        if (currentAssistant) {
          if (turns.length > 0) {
            turns[turns.length - 1].assistant = currentAssistant;
            turns[turns.length - 1].model = currentModel;
            turns[turns.length - 1].steps = [...currentSteps];
          }
          currentAssistant = '';
          currentSteps = [];
        }
        subTurnCount = 0;
        turns.push({ role: 'user', content: ev.data.content, timestamp: ev.timestamp, assistant: '', model: null, steps: [] });
      } else if (ev.type === 'assistant.turn_start') {
        subTurnCount++;
      } else if (ev.type === 'assistant.message' && ev.data?.content) {
        if (ev.data.model) currentModel = ev.data.model;
        if (subTurnCount > 1 || currentSteps.length > 0) {
          currentSteps.push({ type: 'comment', content: ev.data.content });
        }
        currentAssistant = ev.data.content;
      } else if (ev.type === 'tool.execution_start' && ev.data) {
        currentSteps.push({ type: 'tool_start', tool: ev.data.toolName, args: ev.data.arguments, toolCallId: ev.data.toolCallId });
      } else if (ev.type === 'tool.execution_complete' && ev.data) {
        const step = currentSteps.find(s => s.toolCallId === ev.data.toolCallId);
        if (step) {
          step.type = 'tool';
          step.success = ev.data.success;
          step.result = (ev.data.result?.content || '').substring(0, 2000);
          if (ev.data.result?.detailedContent) step.detail = ev.data.result.detailedContent.substring(0, 500);
        } else {
          currentSteps.push({ type: 'tool', tool: ev.data.toolName || '?', success: ev.data.success, result: (ev.data.result?.content || '').substring(0, 2000) });
        }
      }
    } catch { /* skip malformed lines */ }
  }
  // Assign last assistant response
  if (currentAssistant && turns.length > 0) {
    turns[turns.length - 1].assistant = currentAssistant;
    turns[turns.length - 1].model = currentModel;
    turns[turns.length - 1].steps = [...currentSteps];
  }
  // Remove duplicate: if last step is a comment matching the final assistant response
  for (const turn of turns) {
    if (turn.steps && turn.steps.length > 0 && turn.assistant) {
      const lastStep = turn.steps[turn.steps.length - 1];
      if (lastStep.type === 'comment' && lastStep.content === turn.assistant) {
        turn.steps.pop();
      }
    }
  }
  const lastAssistant = currentAssistant || (turns.length > 0 ? turns[turns.length - 1].assistant : '');
  const summary = lastAssistant.substring(0, 500);
  return { turns, summary, sessionMeta, tokenStats };
}

// Convert readSessionConversation() step objects (tool/tool_start/comment) into
// the {type,label,text} activity shape the chat message renderer expects.
function cliStepsToActivity(steps) {
  const out = [];
  for (const s of steps || []) {
    if (s.type === 'comment') {
      out.push({ type: 'thinking', label: '💬 Note', text: String(s.content || '').slice(0, 4000) });
    } else {
      const ok = s.success !== false;
      const name = s.tool || 'tool';
      let text = '';
      if (s.args) {
        try { text = typeof s.args === 'string' ? s.args : JSON.stringify(s.args); } catch { text = ''; }
      }
      if (!text && s.result) text = String(s.result).slice(0, 1500);
      out.push({ type: ok ? 'tool' : 'error', label: '🔧 ' + name + (ok ? ' ✓' : ' ✗'), text: String(text).slice(0, 2000) });
    }
  }
  return out;
}

// Flatten parsed session turns into chat messages (user + assistant pairs).
function cliTurnsToMessages(turns) {
  const msgs = [];
  for (const t of turns || []) {
    if (t.content) msgs.push({ role: 'user', content: t.content, timestamp: t.timestamp });
    if (t.assistant || (t.steps && t.steps.length)) {
      const m = { role: 'assistant', content: t.assistant || '', timestamp: t.timestamp, model: t.model || '' };
      const act = cliStepsToActivity(t.steps);
      if (act.length) m.activity = act;
      msgs.push(m);
    }
  }
  return msgs;
}

// Mirror a CLI-backed chat's bound copilot session (events.jsonl) into the
// chat's messages[] so the read-only SPA view reflects the live terminal.
// Returns the (possibly updated) chat object.
function syncCliChat(chat) {
  if (!chat || chat.source !== 'cli' || !chat.cliSessionId) return chat;
  const dir = path.join(STATE_DIR, chat.cliSessionId);
  if (!fs.existsSync(dir)) return chat;
  let conv;
  try { conv = readSessionConversation(dir); } catch { return chat; }
  const msgs = cliTurnsToMessages(conv.turns || []);
  const prevLen = (chat.messages || []).length;
  const prevLast = JSON.stringify((chat.messages || [])[prevLen - 1] || null);
  const newLast = JSON.stringify(msgs[msgs.length - 1] || null);
  const changed = msgs.length !== prevLen || newLast !== prevLast;
  if (!changed) return chat;
  chat.messages = msgs;
  chat.updatedAt = new Date().toISOString();
  if (conv.sessionMeta && conv.sessionMeta.agent && !chat.agentName) chat.agentName = conv.sessionMeta.agent;
  try { fs.writeFileSync(path.join(CHATS_DIR, `${chat.id}.json`), JSON.stringify(chat, null, 2)); } catch { /* ignore */ }
  broadcastSSE('chat-message', { chatId: chat.id, message: msgs[msgs.length - 1] || null });
  return chat;
}

app.get('/api/sessions', (req, res) => {
  const hoursBack = parseInt(req.query.hours) || 24;
  const cutoff = new Date(Date.now() - hoursBack * 60 * 60 * 1000);
  try {
    if (!fs.existsSync(SESSION_STATE_DIR)) return res.json([]);
    const dirs = fs.readdirSync(SESSION_STATE_DIR, { withFileTypes: true })
      .filter(d => d.isDirectory());
    const sessions = [];
    for (const d of dirs) {
      const fullPath = path.join(SESSION_STATE_DIR, d.name);
      const stat = fs.statSync(fullPath);
      if (stat.mtime < cutoff) continue;
      const meta = readSessionMeta(fullPath);
      if (!meta) continue;
      // Get a quick summary without full conversation
      const eventsPath = path.join(fullPath, 'events.jsonl');
      let lastResult = '';
      let turnCount = 0;
      let agentName = '';
      if (fs.existsSync(eventsPath)) {
        const lines = fs.readFileSync(eventsPath, 'utf-8').split('\n').filter(Boolean);
        for (const line of lines) {
          try {
            const ev = JSON.parse(line);
            if (ev.type === 'user.message') turnCount++;
            if (ev.type === 'assistant.message' && ev.data?.content) lastResult = ev.data.content;
            if (ev.type === 'subagent.selected' && ev.data?.agentDisplayName) agentName = ev.data.agentDisplayName;
          } catch { }
        }
      }
      sessions.push({
        ...meta,
        agentName: agentName || '',
        lastResult: lastResult.substring(0, 800),
        turnCount,
        lastModified: stat.mtime.toISOString()
      });
    }
    sessions.sort((a, b) => new Date(b.lastModified) - new Date(a.lastModified));
    res.json(sessions);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/sessions/:id', (req, res) => {
  const sessionDir = path.join(SESSION_STATE_DIR, req.params.id);
  if (!fs.existsSync(sessionDir)) return res.status(404).json({ error: 'Session not found' });
  const meta = readSessionMeta(sessionDir);
  const conversation = readSessionConversation(sessionDir);
  // Extract agent name from events
  let agentName = '';
  const eventsPath = path.join(sessionDir, 'events.jsonl');
  if (fs.existsSync(eventsPath)) {
    for (const line of fs.readFileSync(eventsPath, 'utf-8').split('\n').filter(Boolean)) {
      try {
        const ev = JSON.parse(line);
        if (ev.type === 'subagent.selected' && ev.data?.agentDisplayName) {
          agentName = ev.data.agentDisplayName;
          break;
        }
      } catch { }
    }
  }
  res.json({ ...meta, agentName, ...conversation });
});

app.post('/api/sessions/:id/chat', (req, res) => {
  const { message } = req.body;
  if (!message) return res.status(400).json({ error: 'message required' });
  const sessionDir = path.join(SESSION_STATE_DIR, req.params.id);
  if (!fs.existsSync(sessionDir)) return res.status(404).json({ error: 'Session not found' });

  const meta = readSessionMeta(sessionDir);
  // Resume the existing SDK session by id. The agent/tools are already baked
  // into the persisted session, so only the working directory is supplied.
  runChatTurn({
    sessionId: req.params.id,
    message,
    config: { cwd: meta.cwd || undefined },
    resume: true,
  });
  // Return immediately — client polls /poll for live updates.
  res.json({ ok: true, started: true });
});

// Poll a session for latest state (turn count + last assistant message)
app.get('/api/sessions/:id/poll', (req, res) => {
  const sessionId = req.params.id;
  const verbose = req.query.verbose === '1';
  const buf = liveChatBuffers.get(sessionId);

  // While a chat turn is streaming the SDK has not flushed events.jsonl to disk,
  // so serve the in-progress turn from the live in-memory buffer (prior turns
  // were snapshotted from the flushed file when the turn started).
  if (buf && buf.running) {
    const turns = [...(buf.priorTurns || [])];
    turns.push({
      content: buf.userPrompt || '',
      assistant: buf.acc || null,
      model: buf.requestedModel || undefined,
      steps: verbose ? (buf.steps || []) : undefined,
    });
    return res.json({
      turnCount: turns.length,
      lastAssistant: buf.acc || '',
      isActive: true,
      lastModified: new Date(buf.lastUpdate || buf.startedAt).toISOString(),
      turns,
    });
  }

  // A finished chat turn. Prefer the flushed events.jsonl, which carries the rich
  // step shape (including the 'comment' preamble steps the agent-chat retry
  // heuristic depends on). But treat the completed live buffer as authoritative
  // for done-ness, final text, and errors: force isActive:false (don't wait out
  // the 30s mtime window that leaves the UI spinning), backfill the response from
  // buf.acc when the parser found none (tool-only turns emit no assistant.message),
  // and surface buf.error. Fall back to a buffer-only turn when the SDK never
  // flushed a file (crash / no-disk case). The one-shot buffer is reaped here.
  const sessionDir = path.join(SESSION_STATE_DIR, sessionId);
  const eventsPath = path.join(sessionDir, 'events.jsonl');
  const haveEvents = fs.existsSync(sessionDir) && fs.existsSync(eventsPath);

  if (!haveEvents) {
    if (buf && !buf.running) {
      const turns = [...(buf.priorTurns || [])];
      turns.push({
        content: buf.userPrompt || '',
        assistant: buf.acc || null,
        model: buf.usedModel || buf.requestedModel || undefined,
        steps: verbose ? (buf.steps || []) : undefined,
      });
      const response = {
        turnCount: turns.length,
        lastAssistant: buf.acc || '',
        isActive: false,
        lastModified: new Date(buf.finishedAt || Date.now()).toISOString(),
        turns,
      };
      if (buf.error) response.chatError = buf.error;
      liveChatBuffers.delete(sessionId);
      return res.json(response);
    }
    if (!fs.existsSync(sessionDir)) return res.status(404).json({ error: 'Session not found' });
    return res.json({ turnCount: 0, lastAssistant: '', isActive: false, turns: [] });
  }

  const stat = fs.statSync(eventsPath);
  const lines = fs.readFileSync(eventsPath, 'utf-8').split('\n').filter(Boolean);
  const parsed = buildPollTurns(lines, verbose);

  let isActive = (Date.now() - stat.mtime.getTime()) < 30000;
  let lastAssistant = parsed.lastAssistant;
  const turns = parsed.turns;
  if (buf && !buf.running) {
    isActive = false;
    if (!lastAssistant && buf.acc) {
      lastAssistant = buf.acc;
      if (turns && turns.length) {
        const lt = turns[turns.length - 1];
        if (lt && !lt.assistant) lt.assistant = buf.acc;
      }
    }
  }

  const response = {
    turnCount: parsed.turnCount,
    lastAssistant,
    isActive,
    lastModified: stat.mtime.toISOString(),
    turns,
  };
  if (verbose) {
    if (parsed.sessionMeta) response.sessionMeta = parsed.sessionMeta;
    if (parsed.tokenStats) response.tokenStats = parsed.tokenStats;
  }
  let chatErrMsg = null;
  const chatErr = chatErrors.get(sessionId);
  if (chatErr) { chatErrMsg = chatErr.error; chatErrors.delete(sessionId); }
  if (buf && !buf.running && buf.error && !chatErrMsg) chatErrMsg = buf.error;
  if (chatErrMsg) response.chatError = chatErrMsg;
  if (buf && !buf.running) liveChatBuffers.delete(sessionId);
  res.json(response);
});

app.post('/api/sessions/:id/terminal', (req, res) => {
  const sessionDir = path.join(SESSION_STATE_DIR, req.params.id);
  if (!fs.existsSync(sessionDir)) return res.status(404).json({ error: 'Session not found' });
  const meta = readSessionMeta(sessionDir);
  const cwd = req.body?.cwd || meta.cwd || __dirname;

  const copilotCmd = process.env.COPILOT_PATH || 'copilot';
  const { exec } = require('child_process');
  // NOTE: avoid parenthesized cmd blocks like `if exist "x" ( ... )` / `|| ( ... )`.
  // cmd expands %PATH% while parsing the whole block, and PATH entries that
  // contain ")" (e.g. "C:\Program Files (x86)\...") prematurely close the block,
  // producing errors such as "\Microsoft was unexpected at this time." Use goto
  // labels instead so each statement is parsed independently.
  //
  // Guard: `where <pattern>` only works for a bare command name; when COPILOT_PATH
  // is an absolute path (e.g. ...\copilot.cmd) `where` returns errorlevel 2 even
  // though the file exists. Use `if not exist` for path-qualified launchers.
  const copilotIsPath = /[\\/:]/.test(copilotCmd);
  const guardLines = copilotIsPath
    ? [`if not exist "${copilotCmd}" goto nocopilot`]
    : [`where "${copilotCmd}" >nul 2>&1`, 'if errorlevel 1 goto nocopilot'];
  const batContent = [
    '@echo off',
    `if not exist "${cwd}" goto nodir`,
    `cd /d "${cwd}"`,
    ...guardLines,
    `"${copilotCmd}" --resume=${req.params.id} --yolo`,
    'pause',
    'exit /b 0',
    ':nodir',
    `echo ERROR: Working directory not found: ${cwd}`,
    'pause',
    'exit /b 1',
    ':nocopilot',
    'echo ERROR: copilot not found in PATH',
    'echo PATH=%PATH%',
    'pause',
    'exit /b 1',
  ].join('\r\n');
  const batPath = path.join(__dirname, `temp-terminal-${req.params.id}.bat`);
  fs.writeFileSync(batPath, batContent);
  exec(`start "Copilot Session" "${batPath}"`);
  res.json({ ok: true });
});

// Open copilot in a directory without resuming a session
app.post('/api/terminal/open', (req, res) => {
  const { cwd } = req.body || {};
  if (!cwd) return res.status(400).json({ error: 'cwd required' });

  const copilotCmd = process.env.COPILOT_PATH || 'copilot';
  const { exec } = require('child_process');
  // See note above: no parenthesized cmd blocks (PATH may contain ")" ), and use
  // `if not exist` rather than `where` when COPILOT_PATH is a path-qualified launcher.
  const copilotIsPath = /[\\/:]/.test(copilotCmd);
  const guardLines = copilotIsPath
    ? [`if not exist "${copilotCmd}" goto nocopilot`]
    : [`where "${copilotCmd}" >nul 2>&1`, 'if errorlevel 1 goto nocopilot'];
  const batContent = [
    '@echo off',
    `if not exist "${cwd}" goto nodir`,
    `cd /d "${cwd}"`,
    ...guardLines,
    `"${copilotCmd}" --yolo`,
    'pause',
    'exit /b 0',
    ':nodir',
    `echo ERROR: Working directory not found: ${cwd}`,
    'pause',
    'exit /b 1',
    ':nocopilot',
    'echo ERROR: copilot not found in PATH',
    'echo PATH=%PATH%',
    'pause',
    'exit /b 1',
  ].join('\r\n');
  const batPath = path.join(__dirname, `temp-terminal-${Date.now().toString(36)}.bat`);
  fs.writeFileSync(batPath, batContent);
  exec(`start "Copilot Session" "${batPath}"`);
  res.json({ ok: true });
});

// ============ CLI Sessions page ============
// Lists every known Copilot CLI/SDK session (workspace.yaml present), with a
// derived title and any cached AI summary. "Resume" reuses the existing
// POST /api/sessions/:id/terminal endpoint above.
const SPA_SUMMARY_FILE = '.spa-summary.json';
// Incremental in-memory cache for the CLI sessions list. Keyed by session dir name;
// each value is { sig, entry } where sig is a composite of file mtimes. Repeat loads
// reuse entries whose underlying files are unchanged, so the page loads instantly.
const _cliSessCache = new Map();

// Persistent cache of CLI-session topic-cluster results. Generating a grouping is a
// slow LLM call, so we key each result by a hash of the included sessions plus each
// one's content signature. A grouping is then reused verbatim until one of its
// sessions changes (its signature shifts) or the set itself changes — at which point
// the key no longer matches and we re-index. Bounded to the few most-recent keys and
// persisted to disk so groupings survive restarts and load instantly the next time.
const SPA_CLUSTER_CACHE_FILE = path.join(SESSION_STATE_DIR, '.spa-cluster-cache.json');
let _clusterCache = null;
function _loadClusterCache() {
  if (_clusterCache) return _clusterCache;
  try { _clusterCache = JSON.parse(fs.readFileSync(SPA_CLUSTER_CACHE_FILE, 'utf-8')); } catch { _clusterCache = { entries: [] }; }
  if (!_clusterCache || !Array.isArray(_clusterCache.entries)) _clusterCache = { entries: [] };
  return _clusterCache;
}
function _clusterCacheGet(key) {
  return _loadClusterCache().entries.find(e => e.key === key) || null;
}
function _clusterCachePut(key, payload) {
  const c = _loadClusterCache();
  c.entries = c.entries.filter(e => e.key !== key);
  c.entries.unshift({ key, ...payload });
  if (c.entries.length > 8) c.entries = c.entries.slice(0, 8);
  try { fs.writeFileSync(SPA_CLUSTER_CACHE_FILE, JSON.stringify(c)); } catch {}
}
// Order-independent content key for a set of sessions: each session's id paired with
// its content signature, sorted so reordering the same set never invalidates.
function _clusterKey(picked) {
  const parts = picked.map(e => `${e.id}:${e.contentSig || ''}`).sort();
  return require('crypto').createHash('sha1').update(parts.join('|')).digest('hex');
}

// Session-origin classification. A CLI session counts as "system"-initiated when
// it was launched by TheOffice.AI itself — either through our SDK runner (the CLI
// writes client_name='sdk') or as an interactive CLI session whose UUID we pinned
// (recorded as `cliSessionId` on a chat). Everything else (a raw `copilot` run in
// a terminal, VS Code, the cloud autopilot agent, …) is "external".
let _launchedCliCache = { ids: new Set(), at: 0 };
function _systemLaunchedCliSessionIds() {
  const now = Date.now();
  if (now - _launchedCliCache.at < 10000) return _launchedCliCache.ids;
  const ids = new Set();
  try {
    const dir = dataPath('chats');
    if (fs.existsSync(dir)) {
      for (const f of fs.readdirSync(dir)) {
        if (!f.endsWith('.json')) continue;
        try {
          const data = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf-8'));
          if (data && data.cliSessionId) ids.add(data.cliSessionId);
        } catch {}
      }
    }
  } catch {}
  _launchedCliCache = { ids, at: now };
  return ids;
}
function _sessionOrigin(entry, launchedIds) {
  if (entry.client === 'sdk') return 'system';
  if (launchedIds && launchedIds.has(entry.id)) return 'system';
  return 'external';
}

function deriveSessionTitle(meta, agentName, lastUser) {
  if (meta && meta.name && meta.name !== '(unnamed)' && String(meta.name).trim()) return String(meta.name).trim();
  const t = String(lastUser || '').replace(/\s+/g, ' ').trim();
  if (t) return t.length > 70 ? t.slice(0, 70) + '…' : t;
  if (agentName) return agentName + ' run';
  return '(untitled session)';
}

// Build the CLI-session index (id, title, agent, cwd, repo, branch, origin,
// summary, preview, dates). Cheap thanks to a per-session mtime cache. Reused by
// the list endpoint and the AI search assistant so both see the same shape.
function _listCliSessions() {
  if (!fs.existsSync(SESSION_STATE_DIR)) return [];
  const dirs = fs.readdirSync(SESSION_STATE_DIR, { withFileTypes: true }).filter(d => d.isDirectory());
  const out = [];
  const seen = new Set();
  for (const d of dirs) {
    const full = path.join(SESSION_STATE_DIR, d.name);
    let stat; try { stat = fs.statSync(full); } catch { continue; }
    seen.add(d.name);
    // Cheap signature from file mtimes; skip the expensive parse if unchanged.
    const ep = path.join(full, 'events.jsonl');
    const sp = path.join(full, SPA_SUMMARY_FILE);
    let epm = 0, spm = 0;
    try { epm = fs.statSync(ep).mtimeMs; } catch {}
    try { spm = fs.statSync(sp).mtimeMs; } catch {}
    const sig = `${stat.mtimeMs}:${epm}:${spm}`;
    const cached = _cliSessCache.get(d.name);
    if (cached && cached.sig === sig) { out.push(cached.entry); continue; }
    const meta = readSessionMeta(full);
    if (!meta) continue; // require workspace.yaml
    let turnCount = 0, agentName = '', lastUser = '';
    const promptSet = new Set();
    if (epm) {
      try {
        for (const line of fs.readFileSync(ep, 'utf-8').split('\n')) {
          if (!line) continue;
          const ev = JSON.parse(line);
          if (ev.type === 'user.message') {
            turnCount++;
            if (ev.data && ev.data.content) {
              lastUser = String(ev.data.content);
              promptSet.add(lastUser.toLowerCase().replace(/\s+/g, ' ').trim().slice(0, 200));
            }
          }
          else if (ev.type === 'subagent.selected' && ev.data && ev.data.agentDisplayName) agentName = ev.data.agentDisplayName;
          else if (ev.type === 'session.start' && ev.data && ev.data.context && ev.data.context.agentName && !agentName) agentName = ev.data.context.agentName;
        }
      } catch {}
    }
    let summary = null, summaryAt = null;
    if (spm) { try { const s = JSON.parse(fs.readFileSync(sp, 'utf-8')); summary = s.summary; summaryAt = s.generatedAt; } catch {} }
    const entry = {
      id: meta.id,
      title: deriveSessionTitle(meta, agentName, lastUser),
      agentName,
      cwd: meta.cwd,
      repository: meta.repository,
      branch: meta.branch,
      client: meta.client,
      turnCount,
      distinctTurns: promptSet.size,
      lastUserPreview: lastUser.replace(/\s+/g, ' ').trim().slice(0, 160),
      createdAt: meta.createdAt,
      lastModified: stat.mtime.toISOString(),
      summary,
      summaryAt,
      contentSig: sig
    };
    _cliSessCache.set(d.name, { sig, entry });
    out.push(entry);
  }
  // Drop cache entries for sessions that no longer exist.
  if (_cliSessCache.size > seen.size) {
    for (const k of _cliSessCache.keys()) if (!seen.has(k)) _cliSessCache.delete(k);
  }
  // Tag each session with its origin (system vs external). Computed outside the
  // per-entry cache so it always reflects the current launched-session set.
  const launchedIds = _systemLaunchedCliSessionIds();
  for (const e of out) e.origin = _sessionOrigin(e, launchedIds);
  out.sort((a, b) => new Date(b.lastModified) - new Date(a.lastModified));
  return out;
}

app.get('/api/cli/sessions', (req, res) => {
  try {
    res.json(_listCliSessions());
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Generate (or return cached) a brief AI summary of a session. Cached on disk so
// it persists and is cheap to re-fetch. Pass {force:true} to regenerate.
app.post('/api/cli/sessions/:id/summarize', async (req, res) => {
  const sessionDir = path.join(SESSION_STATE_DIR, req.params.id);
  if (!fs.existsSync(sessionDir)) return res.status(404).json({ error: 'Session not found' });
  const force = !!(req.body && req.body.force);
  const sp = path.join(sessionDir, SPA_SUMMARY_FILE);
  if (!force && fs.existsSync(sp)) {
    try { const s = JSON.parse(fs.readFileSync(sp, 'utf-8')); return res.json({ summary: s.summary, generatedAt: s.generatedAt, cached: true }); } catch {}
  }
  let conv;
  try { conv = readSessionConversation(sessionDir); } catch (e) { return res.status(500).json({ error: 'read failed: ' + e.message }); }
  const turns = (conv && conv.turns) || [];
  const lines = [];
  for (const t of turns.slice(-30)) {
    if (t.content) lines.push('USER: ' + String(t.content).replace(/\s+/g, ' ').trim().slice(0, 600));
    if (t.assistant) lines.push('ASSISTANT: ' + String(t.assistant).replace(/\s+/g, ' ').trim().slice(0, 600));
  }
  // Fallback for agent-run sessions: user.message has no inline content (prompt is
  // delivered via file), so readSessionConversation() yields no turns. Pull the raw
  // assistant messages, the kickoff prompt, and tool activity straight from the log.
  if (!lines.length) {
    try {
      const ep = path.join(sessionDir, 'events.jsonl');
      if (fs.existsSync(ep)) {
        const tools = [];
        for (const ln of fs.readFileSync(ep, 'utf-8').split('\n')) {
          if (!ln) continue;
          let ev; try { ev = JSON.parse(ln); } catch { continue; }
          const d = ev.data || {};
          if (ev.type === 'session.start' && d.context && d.context.agentName) lines.push('AGENT: ' + d.context.agentName);
          else if (ev.type === 'subagent.selected' && (d.agentDisplayName || d.agentName)) lines.push('AGENT: ' + (d.agentDisplayName || d.agentName));
          else if (ev.type === 'user.message' && d.content) lines.push('PROMPT: ' + String(d.content).replace(/\s+/g, ' ').trim().slice(0, 800));
          else if (ev.type === 'assistant.message' && d.content) lines.push('ASSISTANT: ' + String(d.content).replace(/\s+/g, ' ').trim().slice(0, 800));
          else if (ev.type === 'tool.execution_start' && d.toolName) tools.push(d.toolName);
        }
        if (tools.length) {
          const counts = {};
          for (const t of tools) counts[t] = (counts[t] || 0) + 1;
          const top = Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 12).map(([k, v]) => v > 1 ? `${k}×${v}` : k);
          lines.push('TOOLS USED: ' + top.join(', '));
        }
      }
    } catch {}
  }
  if (!lines.length) return res.status(400).json({ error: 'No conversation content to summarize' });
  const transcript = lines.join('\n').slice(0, 9000);
  const prompt = [
    'Summarize the following Copilot CLI session in 2-4 sentences.',
    'Focus on: what the user was trying to do, what was accomplished, and the current state or any next steps.',
    'Be concrete and specific. Plain prose, no preamble, no bullet list, no surrounding quotes.',
    '',
    'Transcript:',
    transcript,
    '',
    'Summary:'
  ].join('\n');
  try {
    let acc = '';
    const result = await sdkRunner.runChat({ config: null, prompt, sessionId: require('crypto').randomUUID(), cwd: __dirname, onChunk: (c) => { acc += c; }, meta: { source: 'system', category: 'chat' } });
    let summary = (acc.trim() || (result && result.output) || '').trim();
    if (!summary) return res.status(500).json({ error: 'Empty summary returned' });
    const payload = { summary, generatedAt: new Date().toISOString(), turnCount: turns.length };
    try { fs.writeFileSync(sp, JSON.stringify(payload, null, 2)); } catch {}
    res.json({ summary, generatedAt: payload.generatedAt, cached: false });
  } catch (e) { res.status(500).json({ error: (e && e.message) || 'summarize failed' }); }
});

// ── CLI session AI search assistant ────────────────────────────────────────
// A conversational "find my session" helper. Scales to thousands of sessions by
// first scoring every session lexically against the query (title / preview /
// summary / repo / branch / agent / cwd), then handing only the top candidates
// to the model to semantically rank, filter, and answer in natural language.
// Returns { answer, matches:[{id,reason}], consideredCount, totalCount }.

// Tokenize a query into meaningful lowercase terms (drop tiny stopwords).
function _searchTokens(q) {
  const stop = new Set(['the','a','an','to','of','in','on','for','and','or','is','it','my','me','that','this','was','with','where','which','find','session','sessions','show','about','did','i']);
  return String(q || '').toLowerCase().split(/[^a-z0-9#._/-]+/).filter(t => t && t.length > 1 && !stop.has(t));
}
// Lexical score of one session against the query tokens. Weights the strongest
// signals (title, summary) highest; recency is a light tiebreaker.
function _scoreSession(e, tokens) {
  if (!tokens.length) return 0;
  const fields = [
    [String(e.title || ''), 5],
    [String(e.summary || ''), 4],
    [String(e.lastUserPreview || ''), 3],
    [String(e.repository || ''), 3],
    [String(e.branch || ''), 2],
    [String(e.agentName || ''), 2],
    [String(e.cwd || ''), 1],
    [String(e.id || ''), 2],
  ];
  let score = 0;
  for (const [raw, w] of fields) {
    const hay = raw.toLowerCase();
    if (!hay) continue;
    for (const t of tokens) if (hay.includes(t)) score += w;
  }
  return score;
}

app.post('/api/cli/sessions/search', async (req, res) => {
  const query = String((req.body && req.body.query) || '').trim();
  const history = Array.isArray(req.body && req.body.history) ? req.body.history : [];
  if (!query) return res.status(400).json({ error: 'Empty query' });
  let sessions;
  try { sessions = _listCliSessions(); } catch (e) { return res.status(500).json({ error: 'list failed: ' + e.message }); }
  const totalCount = sessions.length;

  // Stage 1 — lexical pre-filter. Score and keep the strongest candidates; when
  // the query has no usable tokens (e.g. "what did I do recently"), fall back to
  // the most recently-modified sessions so the model still has context to reason.
  const tokens = _searchTokens(query);
  let ranked = sessions.map(e => ({ e, s: _scoreSession(e, tokens) }));
  const anyHits = ranked.some(r => r.s > 0);
  if (anyHits) ranked = ranked.filter(r => r.s > 0);
  ranked.sort((a, b) => (b.s - a.s) || (new Date(b.e.lastModified) - new Date(a.e.lastModified)));
  const CANDIDATE_LIMIT = 60;
  const candidates = ranked.slice(0, CANDIDATE_LIMIT).map(r => r.e);

  // Compact, model-friendly index of the candidates (numbered for easy reference).
  const fmtDate = (d) => { try { return new Date(d).toISOString().slice(0, 10); } catch { return ''; } };
  const indexLines = candidates.map((e, i) => {
    const bits = [
      `[${i + 1}] id=${e.id}`,
      `title="${String(e.title || '').replace(/\s+/g, ' ').slice(0, 90)}"`,
      e.agentName ? `agent="${e.agentName}"` : '',
      e.repository ? `repo=${e.repository}` : '',
      e.branch ? `branch=${e.branch}` : '',
      e.origin ? `origin=${e.origin}` : '',
      `modified=${fmtDate(e.lastModified)}`,
      e.summary ? `summary="${String(e.summary).replace(/\s+/g, ' ').slice(0, 200)}"`
        : (e.lastUserPreview ? `lastPrompt="${String(e.lastUserPreview).replace(/\s+/g, ' ').slice(0, 160)}"` : ''),
    ].filter(Boolean);
    return bits.join('  ');
  });

  const convo = history.slice(-6).map(m => `${m.role === 'assistant' ? 'ASSISTANT' : 'USER'}: ${String(m.content || '').slice(0, 500)}`).join('\n');
  const prompt = [
    'You are a search assistant for a developer\'s Copilot CLI session history. The user is trying to FIND specific past sessions among many. Below is an indexed list of candidate sessions (already pre-filtered for relevance). Each line has an id, title, optional agent/repo/branch/origin, last-modified date, and a summary or last prompt.',
    'Decide which candidates genuinely match what the user is looking for. Be selective — only include real matches, ranked best-first. If nothing fits, return an empty matches list and say so.',
    'Respond with STRICT JSON only (no markdown, no code fence) of the form: {"answer":"<one short paragraph addressed to the user, plain prose>","matches":[{"id":"<session id>","reason":"<short why-it-matches>"}]}.',
    'Use ONLY ids that appear in the list. Keep "answer" concise and helpful; mention how many you found and, if useful, how to narrow further.',
    '',
    convo ? 'Recent conversation:\n' + convo + '\n' : '',
    `User is looking for: ${query}`,
    '',
    `Candidate sessions (${candidates.length} of ${totalCount} total):`,
    indexLines.join('\n').slice(0, 22000),
    '',
    'JSON:'
  ].filter(Boolean).join('\n');

  try {
    let acc = '';
    const result = await sdkRunner.runChat({ config: null, prompt, sessionId: require('crypto').randomUUID(), cwd: __dirname, availableTools: [], onChunk: (c) => { acc += c; }, meta: { source: 'system', category: 'chat' } });
    let raw = (acc.trim() || (result && result.output) || '').trim();
    // Strip an accidental code fence and isolate the JSON object.
    raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    const a = raw.indexOf('{'), b = raw.lastIndexOf('}');
    let parsed = null;
    if (a >= 0 && b > a) { try { parsed = JSON.parse(raw.slice(a, b + 1)); } catch {} }
    const validIds = new Set(candidates.map(e => e.id));
    let matches = [];
    if (parsed && Array.isArray(parsed.matches)) {
      matches = parsed.matches
        .filter(m => m && validIds.has(m.id))
        .map(m => ({ id: m.id, reason: String(m.reason || '').slice(0, 300) }));
    }
    // Fallback: if the model returned prose but no usable matches, surface the
    // top lexical candidates so the user still gets a useful result.
    if (!matches.length && anyHits) {
      matches = candidates.slice(0, 8).map(e => ({ id: e.id, reason: 'Lexical match' }));
    }
    const answer = (parsed && parsed.answer) ? String(parsed.answer).slice(0, 1200)
      : (matches.length ? `Found ${matches.length} session(s) that look relevant.` : 'No sessions matched that — try different keywords (a repo, branch, agent, or what the work was about).');
    res.json({ answer, matches, consideredCount: candidates.length, totalCount });
  } catch (e) {
    res.status(500).json({ error: (e && e.message) || 'search failed' });
  }
});

// ── CLI session topic clustering ───────────────────────────────────────────
// Given a set of session ids (the client sends its currently-filtered list,
// capped to the most recent ~150), ask the model to organize them into a small
// number of labeled topic clusters so the user can navigate by theme instead of
// scrolling a flat list. Uses each session's summary when present, else its
// title + last prompt (same signal the search endpoint uses).
// Returns { groups:[{emoji,label,blurb,sessionIds[]}], consideredCount, totalCount }.
app.post('/api/cli/sessions/cluster', async (req, res) => {
  const ids = Array.isArray(req.body && req.body.ids) ? req.body.ids.map(String) : [];
  let all;
  try { all = _listCliSessions(); } catch (e) { return res.status(500).json({ error: 'list failed: ' + e.message }); }
  const byId = new Map(all.map(e => [e.id, e]));
  // Preserve the client's order (already filtered + recency-sorted) and cap.
  const LIMIT = 150;
  let picked = (ids.length ? ids.map(id => byId.get(id)).filter(Boolean) : all)
    .slice(0, LIMIT);
  if (picked.length < 2) return res.status(400).json({ error: 'Need at least 2 sessions to group' });

  // Fast path: a grouping for this exact set + content was computed before and none
  // of the sessions have changed since. Return it instantly unless the client forces
  // a fresh re-index (the ↻ Re-group button).
  const force = !!(req.body && req.body.force);
  const cacheKey = _clusterKey(picked);
  if (!force) {
    const hit = _clusterCacheGet(cacheKey);
    if (hit) return res.json({ groups: hit.groups, consideredCount: hit.consideredCount, totalCount: all.length, generatedAt: hit.generatedAt, cached: true });
  }

  const fmtDate = (d) => { try { return new Date(d).toISOString().slice(0, 10); } catch { return ''; } };
  const indexLines = picked.map((e, i) => {
    const bits = [
      `[${i + 1}] id=${e.id}`,
      `title="${String(e.title || '').replace(/\s+/g, ' ').slice(0, 90)}"`,
      e.agentName ? `agent="${e.agentName}"` : '',
      e.repository ? `repo=${e.repository}` : '',
      `modified=${fmtDate(e.lastModified)}`,
      e.summary ? `summary="${String(e.summary).replace(/\s+/g, ' ').slice(0, 220)}"`
        : (e.lastUserPreview ? `lastPrompt="${String(e.lastUserPreview).replace(/\s+/g, ' ').slice(0, 160)}"` : ''),
    ].filter(Boolean);
    return bits.join('  ');
  });

  const prompt = [
    'You are organizing a developer\'s Copilot CLI session history into a small set of intuitive TOPIC GROUPS so they can navigate by theme. Below is a numbered list of sessions; each line has an id, title, optional agent/repo, last-modified date, and a summary or last prompt.',
    'Cluster these sessions into roughly 4-10 coherent groups by what the work was ABOUT (feature area, subsystem, bug-fix theme, exploration, etc.) — not merely by repo or agent. Every session id must be placed in exactly one group. Order groups by how many sessions they contain (largest first), and order session ids within a group most-recent first when possible. Prefer specific, human labels (e.g. "Board UI & layout", "Scheduling / triggers", "RBAC & permissions") over generic ones; use a catch-all like "Miscellaneous / one-offs" only for genuine leftovers.',
    'Respond with STRICT JSON only (no markdown, no code fence) of the form: {"groups":[{"emoji":"<one emoji>","label":"<short topic label>","blurb":"<one short sentence describing the group>","sessionIds":["<id>", ...]}]}.',
    'Use ONLY ids that appear in the list, and include every id exactly once.',
    '',
    `Sessions (${picked.length}):`,
    indexLines.join('\n').slice(0, 24000),
    '',
    'JSON:'
  ].join('\n');

  try {
    let acc = '';
    const result = await sdkRunner.runChat({ config: null, prompt, sessionId: require('crypto').randomUUID(), cwd: __dirname, availableTools: [], onChunk: (c) => { acc += c; }, meta: { source: 'system', category: 'chat' } });
    let raw = (acc.trim() || (result && result.output) || '').trim();
    raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    const a = raw.indexOf('{'), b = raw.lastIndexOf('}');
    let parsed = null;
    if (a >= 0 && b > a) { try { parsed = JSON.parse(raw.slice(a, b + 1)); } catch {} }
    const validIds = new Set(picked.map(e => e.id));
    const seen = new Set();
    let groups = [];
    if (parsed && Array.isArray(parsed.groups)) {
      groups = parsed.groups.map(g => {
        const sessionIds = (Array.isArray(g && g.sessionIds) ? g.sessionIds : [])
          .filter(id => validIds.has(id) && !seen.has(id));
        sessionIds.forEach(id => seen.add(id));
        return {
          emoji: String((g && g.emoji) || '🗂').slice(0, 4),
          label: String((g && g.label) || 'Group').slice(0, 80),
          blurb: String((g && g.blurb) || '').slice(0, 200),
          sessionIds,
        };
      }).filter(g => g.sessionIds.length);
    }
    // Any ids the model dropped go into a trailing catch-all so nothing disappears.
    const leftover = picked.map(e => e.id).filter(id => !seen.has(id));
    if (leftover.length) {
      groups.push({ emoji: '🗂', label: 'Other sessions', blurb: 'Not assigned to a topic group.', sessionIds: leftover });
    }
    if (!groups.length) return res.status(500).json({ error: 'Could not cluster sessions' });
    const generatedAt = new Date().toISOString();
    _clusterCachePut(cacheKey, { groups, consideredCount: picked.length, totalCount: all.length, generatedAt });
    res.json({ groups, consideredCount: picked.length, totalCount: all.length, generatedAt, cached: false });
  } catch (e) {
    res.status(500).json({ error: (e && e.message) || 'cluster failed' });
  }
});

// ============ Agent / Plugin Updates page ============
// A single normalized inventory of every installed agent/plugin with its origin,
// type, last-updated time, and commit id. Update-availability is checked per-row
// by the existing GET /api/agents/:id/check-update; reinstall via POST .../reinstall.
app.get('/api/updates/inventory', (req, res) => {
  try {
    const agents = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8'));
    const out = agents.map(a => {
      const s = a.source || null;
      const kind = (s && s.kind) || (a.pluginDir ? 'plugin' : 'agent');
      const originType = (s && s.type) || (a.pluginDir ? 'local' : 'builtin');
      let originLabel = 'Local project';
      let sourceDetail = '';
      if (s && s.type === 'azdo') {
        originLabel = `${s.org}/${s.project}/${s.repo}`;
        sourceDetail = `${s.repo}@${s.branch} · ${s.path}`;
      } else if (s && s.type === 'local') {
        originLabel = 'Local folder';
        sourceDetail = s.path || a.pluginDir || a.cwd || '';
      } else if (a.pluginDir) {
        originLabel = 'Local plugin';
        sourceDetail = a.pluginDir;
      } else if (a.cwd) {
        originLabel = 'Local project';
        sourceDetail = a.cwd;
      }
      let lastUpdated = (s && s.installedAt) || null;
      if (!lastUpdated) {
        const probe = a.pluginDir || a.cwd;
        if (probe) { try { if (fs.existsSync(probe)) lastUpdated = fs.statSync(probe).mtime.toISOString(); } catch {} }
      }
      return {
        id: a.id,
        name: a.name || a.id,
        kind,
        originType,
        originLabel,
        sourceDetail,
        lastUpdated,
        commitId: (s && s.objectId) || null,
        reinstallable: !!(s || a.pluginDir),
        checkable: !!((s && s.type === 'azdo') || a.pluginDir || a.sourceDir)
      };
    });
    out.sort((a, b) => String(a.name || '').localeCompare(String(b.name || '')));
    res.json(out);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ============ Backup / export discovery ============
// Find agents/plugins/skills/mcp that are NOT backed by a git repo and therefore
// can only be shared or restored by exporting them. "Backed" means one of:
//   - remote git   : an AzDO source we can re-fetch from (source.type==='azdo')
//   - app repo      : lives inside this application's own committed tree (__dirname)
//   - local git     : resides inside any local git working tree (a .git ancestor)
// Everything else (AI-designed agents, generated skills, ad-hoc local items) lives
// only on this box and is at risk if lost — these are the export candidates.
function _isInside(child, parent) {
  if (!child || !parent) return false;
  try {
    const c = path.resolve(child), p = path.resolve(parent);
    return c === p || c.startsWith(p + path.sep);
  } catch { return false; }
}
function _isInGitRepo(p) {
  if (!p) return false;
  try {
    let dir = path.resolve(p);
    if (fs.existsSync(dir) && !fs.statSync(dir).isDirectory()) dir = path.dirname(dir);
    for (let i = 0; i < 14 && dir; i++) {
      if (fs.existsSync(path.join(dir, '.git'))) return true;
      const up = path.dirname(dir);
      if (up === dir) break;
      dir = up;
    }
  } catch {}
  return false;
}
// Returns 'remote-git' | 'app-repo' | 'local-git' | 'none'.
function _agentBacking(a) {
  const s = a.source || null;
  if (s && s.type === 'azdo') return 'remote-git';
  const cands = [s && s.type === 'local' ? s.path : null, a.pluginDir, a.sourceDir, a.cwd].filter(Boolean);
  if (cands.some(c => _isInside(c, __dirname))) return 'app-repo';
  if (cands.some(c => _isInGitRepo(c))) return 'local-git';
  return 'none';
}
const _BACKING_LABEL = { 'remote-git': 'Azure DevOps repo', 'app-repo': 'App repository', 'local-git': 'Local git repo', 'none': 'Not backed up' };

app.get('/api/export/unbacked', (req, res) => {
  try {
    const agents = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8'));
    const backedDirs = []; // install dirs of every backed agent (to cover their bundled skills/mcp)
    const backedPluginNames = new Set(); // plugin folder names of backed agents (covers materialized copies under PLUGINS_DIR)
    const unbackedAgents = [];
    let backedCount = 0;
    for (const a of agents) {
      const backing = _agentBacking(a);
      const s = a.source || null;
      const kind = (s && s.kind) || (a.pluginDir ? 'plugin' : 'agent');
      if (backing !== 'none') {
        backedCount++;
        for (const d of [a.pluginDir, a.sourceDir, a.cwd]) if (d) backedDirs.push(d);
        if (a.pluginDir) backedPluginNames.add(path.basename(a.pluginDir).toLowerCase());
        continue;
      }
      let originLabel = 'Local';
      if (s && s.type === 'design') originLabel = s.kind === 'enhanced-clone' ? 'AI-enhanced clone' : 'Designed with AI';
      else if (s && s.type === 'local') originLabel = 'Local folder';
      else if (a.pluginDir) originLabel = 'Local plugin';
      else if (a.cwd) originLabel = 'Local project';
      unbackedAgents.push({
        id: a.id,
        name: a.name || a.id,
        kind,
        originType: (s && s.type) || (a.pluginDir ? 'local' : 'builtin'),
        originLabel,
        sourceDetail: a.pluginDir || a.cwd || '',
        exportable: !!(a.pluginDir || a.cwd)
      });
    }

    // Standalone catalog skills + MCP not covered by a backed agent's package.
    const capBacked = (label, p) => {
      const l = String(label || '');
      if (l.startsWith('azdo:') || l.startsWith('builtin:')) return true;
      // A plugin:<name> cap is backed when <name> belongs to a backed agent's
      // plugin, even if the catalog found a materialized copy elsewhere.
      const pm = l.match(/^plugin:(.+)$/);
      if (pm && backedPluginNames.has(pm[1].toLowerCase())) return true;
      if (!p) return false;
      if (_isInside(p, __dirname)) return true;
      if (backedDirs.some(d => _isInside(p, d))) return true;
      return _isInGitRepo(p);
    };
    let catalog = { skills: [], mcp: [] };
    try { catalog = capabilities.buildCatalog() || catalog; } catch {}
    const caps = [];
    for (const sk of (catalog.skills || [])) {
      if (!capBacked(sk.source, sk.sourceDir)) {
        caps.push({ type: 'skill', name: sk.name, source: sk.source || '', sourcePath: sk.sourceDir || '', description: sk.description || '' });
      }
    }
    for (const m of (catalog.mcp || [])) {
      if (!capBacked(m.source, m.sourcePath)) {
        caps.push({ type: 'mcp', name: m.name, source: m.source || '', sourcePath: m.sourcePath || '' });
      }
    }

    unbackedAgents.sort((a, b) => String(a.name).localeCompare(String(b.name)));
    caps.sort((a, b) => (a.type + a.name).localeCompare(b.type + b.name));
    res.json({
      agents: unbackedAgents,
      caps,
      counts: { agents: unbackedAgents.length, caps: caps.length, agentsBacked: backedCount, agentsTotal: agents.length },
      backingLabels: _BACKING_LABEL
    });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Aggregate count of agents/plugins with an update available. Server-cached for
// 5 minutes since azdo checks are network-bound; pass ?force=1 to bypass.
let _updAvailCache = null; // { at, data }
app.get('/api/updates/available-count', async (req, res) => {
  const force = req.query.force === '1';
  if (!force && _updAvailCache && (Date.now() - _updAvailCache.at) < 5 * 60 * 1000) {
    return res.json({ ..._updAvailCache.data, cached: true });
  }
  try {
    const entries = [...supervisor.agents.entries()]; // [id, { config, ... }]
    const total = entries.length;
    const checkables = entries.filter(([, e]) => {
      const c = (e && e.config) || {};
      return !!((c.source && c.source.type === 'azdo') || c.pluginDir || c.sourceDir);
    });
    const results = await Promise.all(checkables.map(async ([id, e]) => {
      try { const st = await computeUpdateStatus(e); return { id, up: st.upToDate }; }
      catch { return { id, up: null }; }
    }));
    const checked = results.filter(r => r.up !== null).length;
    const availItems = results.filter(r => r.up === false).map(r => r.id);
    const data = { available: availItems.length, items: availItems, checked, total, checkedAt: new Date().toISOString() };
    _updAvailCache = { at: Date.now(), data };
    res.json(data);
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// Summarize what an available update would change for an agent/plugin. Gathers a
// textual diff of the installed files vs. the newest source (azdo repo or local
// source folder), then asks the LLM for a 1-3 sentence description of the changes.
const TEXT_EXTS = new Set(['.md', '.markdown', '.json', '.yml', '.yaml', '.txt', '.js', '.ts', '.py', '.ps1', '.sh']);
function isTextFile(p) { return TEXT_EXTS.has(path.extname(p).toLowerCase()); }
function readTextSafe(p) { try { return fs.existsSync(p) ? fs.readFileSync(p, 'utf-8') : ''; } catch { return ''; } }
function lineDiff(oldText, newText) {
  const oldLines = String(oldText || '').split('\n');
  const newLines = String(newText || '').split('\n');
  const oldSet = new Set(oldLines);
  const newSet = new Set(newLines);
  const added = newLines.filter(l => l.trim() && !oldSet.has(l));
  const removed = oldLines.filter(l => l.trim() && !newSet.has(l));
  return { added, removed };
}

app.post('/api/updates/:id/summarize-changes', async (req, res) => {
  try {
    const agents = JSON.parse(fs.readFileSync(AGENTS_PATH, 'utf-8'));
    const agent = agents.find(a => a.id === req.params.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    const s = agent.source || null;
    const files = []; // { path, added:[], removed:[] }

    if (s && s.type === 'azdo') {
      // Collect repo blob paths under the source path, fetch new content, diff vs installed.
      let blobs = [];
      try {
        const tree = await azdo.getTree(s.org, s.project, s.repo, s.branch);
        const base = '/' + String(s.path || '').replace(/^\/+/, '').replace(/\/+$/, '');
        blobs = tree.filter(it => {
          const p = it.path || '';
          return isTextFile(p) && (p === base || p.startsWith(base + '/') || p.startsWith(base));
        });
      } catch (e) { return res.status(502).json({ error: 'Could not read source repo: ' + e.message }); }
      if (!blobs.length) {
        // Agent definitions are often a single file at s.path.
        if (isTextFile(s.path || '')) blobs = [{ path: '/' + String(s.path).replace(/^\/+/, '') }];
      }
      const installRoot = s.kind === 'plugin' ? (agent.pluginDir || agent.sourceDir) : agent.cwd;
      for (const b of blobs.slice(0, 8)) {
        const repoPath = b.path;
        let newText = '';
        try { newText = await azdo.getFileText(s.org, s.project, s.repo, s.branch, repoPath); } catch {}
        // Map repo path to the installed file on disk.
        let oldText = '';
        if (installRoot) {
          const baseClean = String(s.path || '').replace(/^\/+/, '').replace(/\/+$/, '');
          const rp = repoPath.replace(/^\/+/, '');
          let rel = rp.startsWith(baseClean) ? rp.slice(baseClean.length).replace(/^\/+/, '') : path.basename(rp);
          let candidate = path.join(installRoot, rel || path.basename(rp));
          if (!fs.existsSync(candidate)) {
            // Agents materialize under .github/agents/<file>.
            const alt = path.join(installRoot, '.github', 'agents', path.basename(rp));
            if (fs.existsSync(alt)) candidate = alt;
          }
          oldText = readTextSafe(candidate);
        }
        const d = lineDiff(oldText, newText);
        if (d.added.length || d.removed.length) files.push({ path: repoPath, added: d.added, removed: d.removed });
      }
    } else {
      // Local plugin/agent: compare source folder vs installed folder. Resolve the
      // source the SAME way GET /api/agents/:id/check-update does, so an item that
      // shows "update available" always has a source to diff against.
      let sourceDir = agent.sourceDir || (s && s.path) || null;
      const installDir = agent.pluginDir || agent.cwd || null;
      if (!sourceDir && agent.pluginDir && String(agent.pluginDir).includes(PLUGINS_DIR)) {
        const cand = path.join(agent.cwd || '', '.github', 'plugin', path.basename(agent.pluginDir));
        if (fs.existsSync(cand)) sourceDir = cand;
      }
      if (!sourceDir || !installDir || path.resolve(sourceDir) === path.resolve(installDir)) {
        return res.json({ summary: 'This item is installed directly from its source folder, so there are no pending changes to describe.', changedFiles: [], upToDate: true });
      }
      if (!fs.existsSync(sourceDir)) return res.json({ summary: 'The update source folder is no longer available.', changedFiles: [], upToDate: true });
      const collect = (dir, prefix, acc) => {
        try {
          for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
            const rel = prefix ? `${prefix}/${e.name}` : e.name;
            if (e.isDirectory()) collect(path.join(dir, e.name), rel, acc);
            else if (isTextFile(e.name)) acc.push(rel);
          }
        } catch {}
        return acc;
      };
      const relFiles = collect(sourceDir, '', []);
      for (const rel of relFiles.slice(0, 12)) {
        const newText = readTextSafe(path.join(sourceDir, rel));
        const oldText = readTextSafe(path.join(installDir, rel));
        if (newText === oldText) continue;
        const d = lineDiff(oldText, newText);
        if (d.added.length || d.removed.length) files.push({ path: rel, added: d.added, removed: d.removed });
        if (files.length >= 8) break;
      }
    }

    if (!files.length) {
      return res.json({ summary: 'No content changes detected — this item appears up to date.', changedFiles: [], upToDate: true });
    }

    // Build a compact diff text for the LLM (cap size).
    const parts = [];
    for (const f of files) {
      parts.push('FILE: ' + f.path);
      for (const l of f.removed.slice(0, 25)) parts.push('- ' + l.trim().slice(0, 200));
      for (const l of f.added.slice(0, 25)) parts.push('+ ' + l.trim().slice(0, 200));
      parts.push('');
    }
    const diffText = parts.join('\n').slice(0, 9000);
    const prompt = [
      'Briefly describe what changed in this update to an AI agent/plugin, in 1-3 plain-prose sentences.',
      'Focus on the substance of the changes (new capabilities, instruction tweaks, config or tool changes), not file mechanics.',
      'No preamble, no bullet list, no surrounding quotes.',
      '',
      'Changed lines (- removed, + added):',
      diffText,
      '',
      'Summary of changes:'
    ].join('\n');
    let acc = '';
    const result = await sdkRunner.runChat({ config: null, prompt, sessionId: require('crypto').randomUUID(), cwd: __dirname, onChunk: (c) => { acc += c; }, meta: { source: 'system', category: 'agent_authoring' } });
    const summary = (acc.trim() || (result && result.output) || '').trim();
    if (!summary) return res.status(500).json({ error: 'Empty summary returned' });
    res.json({ summary, changedFiles: files.map(f => f.path), upToDate: false });
  } catch (e) { res.status(500).json({ error: (e && e.message) || 'summarize-changes failed' }); }
});

// Export configuration as zip
app.get('/api/export', (req, res) => {
  const zip = new yazl.ZipFile();

  // agents.json
  zip.addFile(AGENTS_PATH, 'agents.json');

  // events-config.json
  const eventsConfigPath = dataPath('events-config.json');
  if (fs.existsSync(eventsConfigPath)) {
    zip.addFile(eventsConfigPath, 'events-config.json');
  }

  // plugins directory (runtime store in user profile)
  const pluginsDir = PLUGINS_DIR;
  if (fs.existsSync(pluginsDir)) {
    const addDir = (dir, prefix) => {
      for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const fullPath = path.join(dir, entry.name);
        const zipPath = prefix + '/' + entry.name;
        if (entry.isDirectory()) addDir(fullPath, zipPath);
        else zip.addFile(fullPath, zipPath);
      }
    };
    addDir(pluginsDir, 'plugins');
  }

  // mcp-configs directory (runtime store in user profile)
  const mcpDir = MCP_CONFIGS_DIR;
  if (fs.existsSync(mcpDir)) {
    const addDir = (dir, prefix) => {
      for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const fullPath = path.join(dir, entry.name);
        const zipPath = prefix + '/' + entry.name;
        if (entry.isDirectory()) addDir(fullPath, zipPath);
        else zip.addFile(fullPath, zipPath);
      }
    };
    addDir(mcpDir, 'mcp-configs');
  }

  // Export agent state (enabled/disabled, schedules) from DB
  const agentStates = [];
  const allStatus = supervisor.getAllStatus();
  for (const agent of allStatus) {
    agentStates.push({
      agent_id: agent.agent_id,
      enabled: agent.enabled,
      schedule: agent.schedule,
      group: agent.config?.group || null,
      autoStart: agent.autoStart
    });
  }
  zip.addBuffer(Buffer.from(JSON.stringify(agentStates, null, 2)), 'agent-state.json');

  // package.json for dependency reference
  const pkgPath = path.join(__dirname, 'package.json');
  if (fs.existsSync(pkgPath)) {
    zip.addFile(pkgPath, 'package.json');
  }

  res.setHeader('Content-Type', 'application/zip');
  res.setHeader('Content-Disposition', `attachment; filename="agent-supervisor-config-${new Date().toISOString().slice(0,10)}.zip"`);
  zip.outputStream.pipe(res);
  zip.end();
});

// Import configuration from zip
app.post('/api/import', upload.single('file'), async (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No file uploaded' });

  const results = { imported: [], warnings: [], errors: [] };

  try {
    const entries = await new Promise((resolve, reject) => {
      const files = {};
      yauzl.open(req.file.path, { lazyEntries: true }, (err, zipfile) => {
        if (err) return reject(err);
        zipfile.readEntry();
        zipfile.on('entry', entry => {
          if (/\/$/.test(entry.fileName)) { zipfile.readEntry(); return; }
          zipfile.openReadStream(entry, (err, stream) => {
            if (err) return reject(err);
            const chunks = [];
            stream.on('data', c => chunks.push(c));
            stream.on('end', () => { files[entry.fileName] = Buffer.concat(chunks); zipfile.readEntry(); });
          });
        });
        zipfile.on('end', () => resolve(files));
      });
    });

    // Discover copilot on this machine
    const { execSync } = require('child_process');
    let copilotPath = null;
    try {
      copilotPath = execSync('where copilot', { encoding: 'utf8', timeout: 5000 }).trim().split('\n')[0].trim();
      results.imported.push(`Copilot found: ${copilotPath}`);
    } catch {
      results.warnings.push('copilot not found in PATH. Install GitHub Copilot CLI or set COPILOT_PATH env var.');
    }

    // Import agents.json
    if (entries['agents.json']) {
      const agents = JSON.parse(entries['agents.json'].toString());
      for (const agent of agents) {
        // Remove hardcoded copilotPath — rely on PATH resolution
        delete agent.copilotPath;
        // Rewrite pluginDir to local plugins/ directory if it's an absolute path from another machine
        if (agent.pluginDir) {
          const pluginName = path.basename(agent.pluginDir);
          const localPluginDir = path.join(PLUGINS_DIR, pluginName);
          if (agent.pluginDir !== localPluginDir) {
            agent.pluginDir = localPluginDir;
          }
        }
      }
      // Validate CWDs
      for (const agent of agents) {
        if (agent.cwd && !fs.existsSync(agent.cwd)) {
          results.warnings.push(`Agent "${agent.name || agent.id}": CWD does not exist: ${agent.cwd}`);
        }
      }
      fs.writeFileSync(AGENTS_PATH, JSON.stringify(agents, null, 2));
      results.imported.push(`agents.json: ${agents.length} agents`);
    }

    // Import events-config.json
    if (entries['events-config.json']) {
      const eventsPath = dataPath('events-config.json');
      fs.writeFileSync(eventsPath, entries['events-config.json'].toString());
      results.imported.push('events-config.json imported');
    }

    // Import plugins
    let pluginCount = 0;
    for (const [filePath, content] of Object.entries(entries)) {
      if (filePath.startsWith('plugins/')) {
        const destPath = path.join(SUPERVISOR_DATA_DIR, filePath.replace(/\//g, path.sep));
        fs.mkdirSync(path.dirname(destPath), { recursive: true });
        fs.writeFileSync(destPath, content);
        pluginCount++;
      }
    }
    if (pluginCount > 0) results.imported.push(`plugins: ${pluginCount} files`);

    // Install extracted plugins into copilot (with tools restriction patching)
    if (pluginCount > 0 && copilotPath) {
      const { execSync } = require('child_process');
      const os = require('os');
      const pluginsDir = PLUGINS_DIR;
      const pluginDirs = fs.readdirSync(pluginsDir, { withFileTypes: true })
        .filter(d => d.isDirectory())
        .map(d => path.join(pluginsDir, d.name));
      for (const pDir of pluginDirs) {
        if (!fs.existsSync(path.join(pDir, 'plugin.json'))) continue;
        const pluginName = path.basename(pDir);
        try {
          // Create patched copy (remove tools restrictions)
          const patchedDir = path.join(os.tmpdir(), `plugin-import-${pluginName}-${Date.now()}`);
          fs.cpSync(pDir, patchedDir, { recursive: true });
          const agentsDir = path.join(patchedDir, 'agents');
          if (fs.existsSync(agentsDir)) {
            for (const f of fs.readdirSync(agentsDir).filter(f => f.endsWith('.md'))) {
              const agentFile = path.join(agentsDir, f);
              let content = fs.readFileSync(agentFile, 'utf-8').replace(/\r\n/g, '\n');
              content = content.replace(/^(---\n[\s\S]*?)(tools:\n(?:\s+-[^\n]*\n)*)([\s\S]*?---)/m, '$1$3');
              fs.writeFileSync(agentFile, content);
            }
          }
          // Uninstall first (ignore errors if not installed)
          try { execSync(`"${copilotPath}" plugin uninstall "${pluginName}"`, { encoding: 'utf-8', shell: true, timeout: 30000 }); } catch {}
          execSync(`"${copilotPath}" plugin install "${patchedDir}"`, { encoding: 'utf-8', shell: true, timeout: 30000 });
          try { fs.rmSync(patchedDir, { recursive: true }); } catch {}
          results.imported.push(`plugin installed: ${pluginName}`);
        } catch (e) {
          results.warnings.push(`plugin install failed for ${pluginName}: ${(e.stderr || e.message).trim().split('\n')[0]}`);
        }
      }
    }

    // Import mcp-configs
    let mcpCount = 0;
    for (const [filePath, content] of Object.entries(entries)) {
      if (filePath.startsWith('mcp-configs/')) {
        const destPath = path.join(SUPERVISOR_DATA_DIR, filePath.replace(/\//g, path.sep));
        fs.mkdirSync(path.dirname(destPath), { recursive: true });
        fs.writeFileSync(destPath, content);
        mcpCount++;
      }
    }
    if (mcpCount > 0) results.imported.push(`mcp-configs: ${mcpCount} files`);

    // Apply agent state (enabled/disabled flags)
    if (entries['agent-state.json']) {
      const states = JSON.parse(entries['agent-state.json'].toString());
      for (const state of states) {
        if (state.enabled === 0 || state.enabled === false) {
          db.prepare('UPDATE agent_state SET enabled = 0 WHERE agent_id = ?').run(state.agent_id);
        }
      }
      results.imported.push(`agent-state.json: ${states.length} states applied`);
    }

    // Reload supervisor with new config
    loadAgents();
    results.imported.push('Supervisor reloaded');

  } catch (e) {
    results.errors.push(`Import failed: ${e.message}`);
  } finally {
    try { fs.unlinkSync(req.file.path); } catch {}
  }

  res.json(results);
});

// ============ Config Sync API Routes ============

// Get sync status
// --- Global settings: model selection (chat / executions / system AI) --------
// Persisted server-side (settings.json) so schedules, triggers, chat and the
// system AI all honor the chosen models — not just the browser.

// List available models from the SDK (id, name, cost multiplier, reasoning).
app.get('/api/models', async (req, res) => {
  try {
    const models = await sdkRunner.listModels();
    res.json({
      models: (models || []).map(m => ({
        id: m.id,
        name: m.name || m.id,
        multiplier: (m.billing && typeof m.billing.multiplier === 'number') ? m.billing.multiplier : null,
        reasoningEfforts: Array.isArray(m.supportedReasoningEfforts) ? m.supportedReasoningEfforts : [],
        defaultReasoningEffort: m.defaultReasoningEffort || null,
      })),
    });
  } catch (err) {
    res.status(500).json({ models: [], error: err.message });
  }
});

// Read the global settings (model selections).
app.get('/api/settings', (req, res) => {
  // Reflect the authoritative external-access state (may be hard-locked off by the
  // build) so the UI shows the switch as disabled/locked rather than the stored value.
  res.json({
    ...settings.getSettings(),
    externalAccessDisabled: settings.isExternalAccessDisabled(),
    externalAccessLocked: settings.isExternalAccessLocked(),
  });
});

// Update the global settings. Body may include chatModel/executionModel/systemModel.
app.put('/api/settings', (req, res) => {
  try {
    const body = { ...(req.body || {}) };
    // External access is hard-locked off by the build — never let a settings write
    // turn it on (or off); the kill-switch is authoritative via isExternalAccessDisabled().
    if (settings.isExternalAccessLocked()) delete body.externalAccessDisabled;
    const before = settings.isExternalAccessDisabled();
    const _grpKeys = ['codeflowMyGroups', 'codeflowMyGroupsGithub', 'codeflowMyGroupsAzdo'];
    const beforeGroups = JSON.stringify(_grpKeys.map(k => (settings.getSettings()[k]) || []));
    const next = settings.updateSettings(body);
    // If any of the user's reviewer-group lists changed, the cached Code Flow PR lists were
    // built against the OLD group set (group-reviewer detection is per-gather) — bust the
    // cache so newly-configured group PRs surface immediately instead of after the TTL.
    try {
      if (_grpKeys.some(k => k in body) &&
          JSON.stringify(_grpKeys.map(k => (next[k]) || [])) !== beforeGroups) {
        _codeflowCache.clear();
      }
    } catch {}
    // If the external-access kill-switch flipped, apply it to the live subsystems
    // (relay poller + Service Bus) immediately — no restart required.
    if (settings.isExternalAccessDisabled() !== before) {
      Promise.resolve(applyExternalAccessState()).catch(e => console.warn('[external-access] apply failed:', e.message));
    }
    // Persist into this machine's cloud config too, if sync is on and we lead.
    try { if (configSync && configSync.enabled && configSync.isLeader && configSync.pushConfig) configSync.pushConfig(); } catch {}
    // Re-arm the managed-dependency auto-update job if its schedule changed.
    try { scheduleDependencyAutoUpdate(); } catch (e) { console.warn('[deps] reschedule failed:', e.message); }
    // Re-arm the Connect collection job if its schedule/enable/consent changed.
    try { scheduleConnectCollection(); } catch (e) { console.warn('[connect] reschedule failed:', e.message); }
    // If collection was just enabled and a scheduled run is already overdue, catch up.
    try { setTimeout(connectCatchUpCheck, 2_000); } catch {}
    // Re-arm the newsletter auto-generation job if its schedule/enable changed.
    try { scheduleNewsletterGeneration(); } catch (e) { console.warn('[newsletter] reschedule failed:', e.message); }
    try { setTimeout(newsletterCatchUpCheck, 2_500); } catch {}
    res.json({
      ...next,
      externalAccessDisabled: settings.isExternalAccessDisabled(),
      externalAccessLocked: settings.isExternalAccessLocked(),
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// --- System agents: read the registry + save per-agent behavior overrides ------
// GET returns each built-in AI system agent (role, where-used, tools, model
// category, output contract) merged with the user's saved override (custom
// instructions + optional pinned model). PUT saves ONE agent's override.
app.get('/api/system-agents', (req, res) => {
  try {
    const overrides = settings.getSettings().systemAgentOverrides || {};
    const models = { chat: settings.getSettings().chatModel || '', execution: settings.getSettings().executionModel || '', system: settings.getSettings().systemModel || '' };
    const agents = SYSTEM_AGENTS.map(a => {
      const o = overrides[a.id] && typeof overrides[a.id] === 'object' ? overrides[a.id] : {};
      return {
        ...a,
        defaultModel: models[a.modelCategory] || '',
        override: { instructions: String(o.instructions || ''), model: String(o.model || '') },
      };
    });
    res.json({ agents });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.put('/api/system-agents/:id', (req, res) => {
  try {
    const id = String(req.params.id || '');
    if (!SYSTEM_AGENT_IDS.has(id)) return res.status(404).json({ error: 'Unknown system agent' });
    const agent = SYSTEM_AGENTS.find(a => a.id === id);
    const b = req.body || {};
    const instructions = String(b.instructions || '').trim().slice(0, 8000);
    // Model pinning is only meaningful for agents that run via a runChat config.
    const model = agent.canModel ? String(b.model || '').trim().slice(0, 200) : '';
    // Full-object replace on update: read the current map, set/clear this id, write back.
    const cur = settings.getSettings().systemAgentOverrides || {};
    const nextMap = { ...cur };
    if (!instructions && !model) delete nextMap[id];
    else nextMap[id] = { instructions, model };
    settings.updateSettings({ systemAgentOverrides: nextMap });
    try { if (configSync && configSync.enabled && configSync.isLeader && configSync.pushConfig) configSync.pushConfig(); } catch {}
    res.json({ ok: true, id, override: { instructions, model } });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// The SPA keeps theme/palette/icon-set/experience-level/app-mode/basic-features/
// sidebar-widths in browser localStorage, which is wiped on a WebView2 reinstall.
// We mirror a whitelist of durable keys here (under the reinstall-durable profile
// dir, and roamed by config-sync) so they persist across installs + machines.
app.get('/api/ui-prefs', (req, res) => {
  try {
    res.json({ prefs: uiPrefs.get() });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Replace the stored durable prefs wholesale (the SPA sends a full snapshot of
// its durable keys, so replace lets key removals propagate).
app.put('/api/ui-prefs', (req, res) => {
  try {
    const prefs = uiPrefs.replace((req.body && req.body.prefs) || {});
    // Roam to this machine's cloud config too, if sync is on and we lead.
    try { if (configSync && configSync.enabled && configSync.isLeader && configSync.pushConfig) configSync.pushConfig(); } catch {}
    res.json({ prefs });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Lets the user point their settings/config store at OneDrive or another folder.
// Changing it requires an app restart (the DB + cached paths are opened at boot).
app.get('/api/data-location', (req, res) => {
  try {
    res.json(getLocationInfo());
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/data-location', (req, res) => {
  try {
    const target = (req.body && req.body.path || '').trim();
    if (!target) return res.status(400).json({ error: 'A destination path is required.' });
    const move = req.body && req.body.move !== false;
    const info = setLocation(target, { move });
    res.json({ ...info, restartRequired: true });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.post('/api/data-location/reset', (req, res) => {
  try {
    const info = clearLocation();
    res.json({ ...info, restartRequired: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// --- Connect (living impact / performance diary) ------------------------------
// Phase 2 — automation. A seeded `connect` plugin (WorkIQ MCP + collector/
// profiler/writer agents) powers three flows, all consent- and user-gated:
//   collect  — WorkIQ reads recent Teams(channel/group)/email/meeting activity
//              → diary evidence (connect.addEvidenceBatch).
//   generate — writer agent turns evidence+role+guidance into an HR-standard
//              draft the user then personalizes (saved source:'ai').
//   autofill — profiler agent infers the "My current role" fields.
// The AI is a drafting assistant only — never the author or a performance rater.

let connectCollectJob = null;

// Pull the first JSON value (array or object) out of a model response that may
// wrap it in a ```json fence or surround it with prose.
function _connectExtractJson(text) {
  if (!text || typeof text !== 'string') return null;
  let t = text.trim();
  const fence = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) t = fence[1].trim();
  try { return JSON.parse(t); } catch {}
  // Fall back to the first balanced array/object in the text.
  for (const [open, close] of [['[', ']'], ['{', '}']]) {
    const start = t.indexOf(open);
    if (start === -1) continue;
    let depth = 0;
    for (let i = start; i < t.length; i++) {
      if (t[i] === open) depth++;
      else if (t[i] === close) { depth--; if (depth === 0) {
        try { return JSON.parse(t.slice(start, i + 1)); } catch { break; }
      } }
    }
  }
  return null;
}

// Run one of the Connect plugin agents (collector|profiler|writer) as a one-off
// SDK chat and return the accumulated text output.
async function _connectRunAgent(agentName, prompt) {
  if (!connectPluginDir || !fs.existsSync(connectPluginDir)) {
    throw new Error('Connect plugin is not available yet — restart the server.');
  }
  // Only the writer/editor produce the actual Connect deliverable; collector/profiler
  // are background diary collection and shouldn't be charged against "Connect" savings.
  const cat = (agentName === 'writer' || agentName === 'editor') ? 'connect' : 'diary';
  let acc = '';
  const result = await sdkRunner.runChat({
    config: { pluginDir: connectPluginDir, agent: agentName, cwd: __dirname },
    prompt,
    sessionId: require('crypto').randomUUID(),
    resume: false,
    cwd: __dirname,
    meta: { source: 'connect', category: cat },
    onChunk: (c) => { acc += c; },
  });
  if (result && result.fallback) throw new Error(result.error || 'Connect agent runtime unavailable');
  return acc.trim() ? acc : ((result && result.output) || '');
}

function _connectDateWindow(days) {
  const end = new Date();
  const start = new Date();
  start.setDate(start.getDate() - Math.max(1, Number(days) || 1));
  const iso = d => d.toISOString().slice(0, 10);
  return { start: iso(start), end: iso(end) };
}

// Turn objective review signals into a compact detail string + an impact phrase
// (the "how useful was my feedback" read). Deterministic — no AI call.
function _connectReviewSummary({ vlabel, myComments, myThreads, myThreadsResolved, merged, authorName }) {
  const bits = [];
  bits.push(vlabel === 'no-vote' ? 'reviewed' : vlabel);
  if (myComments) bits.push(`${myComments} comment${myComments === 1 ? '' : 's'}`);
  if (myThreads) bits.push(`${myThreadsResolved}/${myThreads} thread${myThreads === 1 ? '' : 's'} resolved`);
  let impact = '';
  if (myThreads && myThreadsResolved >= myThreads && merged) impact = 'Raised review feedback that was fully addressed; PR merged.';
  else if (myThreads && myThreadsResolved > 0) impact = `Review feedback partly addressed (${myThreadsResolved}/${myThreads} threads resolved).`;
  else if (myThreads) impact = 'Raised review feedback for the author to address.';
  else if (vlabel === 'approved' || vlabel === 'approved-with-suggestions') impact = merged ? 'Approved and unblocked the author; PR merged.' : 'Approved to unblock the author.';
  else if (vlabel === 'rejected' || vlabel === 'waiting-for-author') impact = 'Requested changes before merge.';
  return { detail: bits.join(' · '), impact };
}

// Collect REAL Azure DevOps evidence (PRs authored + work items assigned/created)
// for the given window, straight from the Azure DevOps REST API via the Azure CLI
// token — not WorkIQ. Returns Connect-shaped evidence items with stable ext: tags.
// Best-effort per project: one project's failure never sinks the rest.
// Build the normalized list of Azure DevOps collection targets. Prefers the
// multi-org list (connectAdoOrgs: [{org, projects}]); when that is empty, falls
// back to the single connectAdoOrg/connectAdoProjects, then the dev/export org.
// Each returned target is { org, projects: [names] } with everything trimmed and
// empties dropped, so an incompletely-filled row never reaches the API.
function _connectAdoTargets(s) {
  const targets = [];
  const seen = new Set();
  const add = (org, projStr) => {
    org = String(org || '').trim();
    const projects = String(projStr || '').split(',').map(p => p.trim()).filter(Boolean);
    if (!org || !projects.length) return;
    const key = org.toLowerCase();
    if (seen.has(key)) return; // one entry per org — merge duplicates
    seen.add(key);
    targets.push({ org, projects });
  };
  const list = Array.isArray(s.connectAdoOrgs) ? s.connectAdoOrgs : [];
  for (const entry of list) add(entry && entry.org, entry && entry.projects);
  if (!targets.length) {
    add(s.connectAdoOrg || s.devOrg || s.exportOrg, s.connectAdoProjects || s.devProject || s.exportProject);
  }
  return targets;
}

async function runConnectAdoCollection({ days } = {}) {
  const s = settings.getSettings();
  const targets = _connectAdoTargets(s);
  if (!targets.length) return { skipped: 'no-ado-config', items: [] };

  const win = _connectDateWindow(days);
  const inWin = (iso) => { const d = String(iso || '').slice(0, 10); return d && d >= win.start && d <= win.end; };
  const DONE = new Set(['closed', 'done', 'resolved', 'completed']);
  const items = [];
  const errors = [];
  const orgsSeen = [];
  const projectsSeen = [];

  for (const { org, projects } of targets) {
    // Identity is per-org (AAD vs MSA can differ across orgs), so resolve the
    // caller for each org. A failed org is skipped, never sinking the others.
    let me;
    try { me = await azdo.getCurrentUser(org); }
    catch (e) { errors.push(`auth ${org}: ${e.message}`); continue; }
    const creatorId = me && me.id;
    orgsSeen.push(org);

    for (const project of projects) {
    projectsSeen.push(`${org}/${project}`);
    // --- Work items (assigned-or-created by me, changed in window) ---
    try {
      const wis = await azdo.listMyWorkItems(org, project, { start: win.start, end: win.end });
      for (const w of wis) {
        const done = DONE.has(String(w.state || '').toLowerCase());
        const date = String((done && w.closedDate) || w.changedDate || w.createdDate || win.end).slice(0, 10);
        // Explain WHY this item is in the diary: listMyWorkItems returns items
        // assigned to me OR created by me, so make that relationship explicit
        // (e.g. one I opened for someone else vs. one on my own plate).
        const meId = String(creatorId || '');
        const createdMine = !!meId && String(w.createdById || '') === meId;
        const assignedMine = !!meId && String(w.assignedToId || '') === meId;
        let rel;
        if (assignedMine && createdMine) rel = 'created & assigned to you';
        else if (assignedMine) rel = 'assigned to you';
        else if (createdMine) rel = `created by you · ${w.assignedTo ? `assigned to ${w.assignedTo}` : 'unassigned'}`;
        else rel = w.assignedTo ? `assigned to ${w.assignedTo}` : '';
        items.push({
          date,
          source: 'ado',
          title: `${done ? 'Completed ' : ''}${w.type || 'Work item'} #${w.id}: ${w.title}`.trim(),
          detail: `${project} · state: ${w.state || 'unknown'}${rel ? ` · ${rel}` : ''}`,
          impact: '',
          links: w.url ? [w.url] : [],
          tags: [`ext:ado:${org}/${w.id}`, 'source:azdo']
        });
      }
    } catch (e) { errors.push(`workitems ${org}/${project}: ${e.message}`); }

    // --- Pull requests I authored (completed in window + opened in window) ---
    for (const [status, verb, dateField] of [['completed', 'Merged', 'closedDate'], ['active', 'Opened', 'creationDate']]) {
      try {
        const prs = await azdo.listProjectPullRequests(org, project, { creatorId, status, top: 100 });
        for (const pr of prs) {
          if (!inWin(pr[dateField])) continue;
          items.push({
            date: String(pr[dateField]).slice(0, 10),
            source: 'pr',
            title: `${verb} PR !${pr.id}: ${pr.title}`,
            detail: `${pr.repo || project}${pr.sourceBranch ? ` · ${pr.sourceBranch} → ${pr.targetBranch}` : ''}`,
            impact: '',
            links: pr.url ? [pr.url] : [],
            tags: [`ext:pr:${org}/${project}/${pr.id}`, 'source:azdo']
          });
        }
      } catch (e) { errors.push(`prs ${org}/${project}/${status}: ${e.message}`); }
    }

    // --- Pull requests I REVIEWED for others (helping others flow code) ---
    // PRs where I was a reviewer, not the author. We capture my vote and my
    // comment/thread participation as the "usefulness" signal. One threads call
    // per candidate PR, so cap the number we inspect per project.
    let reviewedInspected = 0;
    const REVIEW_INSPECT_CAP = 60;
    for (const [status, dateField] of [['completed', 'closedDate'], ['active', 'creationDate']]) {
      if (reviewedInspected >= REVIEW_INSPECT_CAP) break;
      try {
        const prs = await azdo.listProjectPullRequests(org, project, { reviewerId: creatorId, status, top: 100 });
        for (const pr of prs) {
          if (reviewedInspected >= REVIEW_INSPECT_CAP) break;
          if (pr.createdBy && String(pr.createdBy.id) === String(creatorId)) continue; // my own PR — already captured as authored
          const when = pr[dateField] || pr.creationDate;
          if (!inWin(when)) continue;
          const mine = (pr.reviewers || []).find(r => String(r.id) === String(creatorId));
          const vote = mine ? Number(mine.vote) : 0;
          const vlabel = azdo.voteLabel(vote);
          reviewedInspected++;
          let stats = { myComments: 0, myThreads: 0, myThreadsResolved: 0 };
          try { stats = await azdo.getPrMyReview(org, project, pr.repo, pr.id, creatorId); } catch (_) { /* best-effort */ }
          // I was listed as a reviewer but did nothing actionable — skip (no signal).
          if (vote === 0 && stats.myComments === 0) continue;
          const merged = status === 'completed';
          const sum = _connectReviewSummary({
            vlabel, myComments: stats.myComments, myThreads: stats.myThreads,
            myThreadsResolved: stats.myThreadsResolved, merged,
            authorName: pr.createdBy && pr.createdBy.name
          });
          items.push({
            date: String(when).slice(0, 10),
            source: 'pr-review',
            title: `Reviewed PR !${pr.id}: ${pr.title}`,
            detail: `${pr.repo || project}${pr.createdBy && pr.createdBy.name ? ` · by ${pr.createdBy.name}` : ''} · ${sum.detail}`,
            impact: sum.impact,
            links: pr.url ? [pr.url] : [],
            tags: [`ext:pr-review:${org}/${project}/${pr.id}`, 'source:azdo']
          });
        }
      } catch (e) { errors.push(`reviewed-prs ${org}/${project}/${status}: ${e.message}`); }
    }
    }
  }
  if (errors.length) console.warn('[connect] ADO collection partial errors:', errors.join('; '));
  return { items, orgs: orgsSeen, projects: projectsSeen, window: win, errors };
}

// Build the meeting-analyst prompt for one window. `now` lets the agent reliably
// drop future/in-progress meetings (the date window alone is date-only). `skipIds`
// are eventIds we already fully analyzed (have a transcript recap) — the agent
// skips re-opening those transcripts, which makes backfill re-runs cheap.
function _meetingPrompt(win, nowIso, skipIds) {
  let p =
    `Analyze the meetings I actually attended for the Connect diary, over the date range ` +
    `${win.start} to ${win.end} (inclusive). The current datetime ("now") is ${nowIso} — ` +
    `NEVER record a meeting whose end time is after "now" (future or in-progress). ` +
    `For each past meeting, read the transcript recap and record my real contributions and ` +
    `action items; if there is no recap, record a light "attended — no recap" entry only when ` +
    `I organized or accepted the meeting. Return only the JSON array of evidence items exactly ` +
    `as specified.`;
  if (Array.isArray(skipIds) && skipIds.length) {
    p += ` These meeting eventIds are already fully recorded with a transcript recap — do NOT ` +
      `re-open their transcripts or re-emit them: ${skipIds.slice(0, 200).join(', ')}.`;
  }
  return p;
}

// Split a date-only window {start,end} into newest-first slices of at most
// `sliceDays` days each. Small slices keep each meeting-analyst pass short enough
// to finish reliably, and let one slow slice fail without sinking the rest.
function _sliceWindow({ start, end }, sliceDays) {
  const out = [];
  const s = new Date(`${start}T00:00:00Z`);
  let cur = new Date(`${end}T00:00:00Z`);
  const span = Math.max(1, Number(sliceDays) || 1);
  let guard = 0;
  while (cur >= s && guard++ < 1000) {
    const wEnd = new Date(cur);
    const wStart = new Date(cur);
    wStart.setUTCDate(wStart.getUTCDate() - (span - 1));
    if (wStart < s) wStart.setTime(s.getTime());
    out.push({ start: wStart.toISOString().slice(0, 10), end: wEnd.toISOString().slice(0, 10) });
    cur = new Date(wStart);
    cur.setUTCDate(cur.getUTCDate() - 1);
  }
  return out;
}

// eventIds of meetings we already captured WITH a transcript recap (so we can tell
// the analyst to skip them). Parsed from evidence tags: ext:meeting:<eventId> paired
// with a meeting:recap classification tag.
function _connectRecordedMeetingIds() {
  try {
    const ids = [];
    for (const e of connect.listEvidence({ includeHidden: true })) {
      if (e.source !== 'meeting') continue;
      const tags = Array.isArray(e.tags) ? e.tags : [];
      if (!tags.some(t => t === 'meeting:recap')) continue; // only skip fully-analyzed ones
      const ext = tags.find(t => typeof t === 'string' && t.startsWith('ext:meeting:'));
      if (ext) ids.push(ext.slice('ext:meeting:'.length));
    }
    return ids;
  } catch { return []; }
}

// Run ONE meeting-analyst pass over [win] with adaptive, progress-aware timing.
// The SDK has no cancel, so instead of a hard race that abandons a healthy run we
// watch agent activity (streamed deltas + tool/step events). If the agent goes
// silent for `stallMs` we treat the pass as stalled; while activity keeps flowing
// we let it run up to `hardCapMs`. Returns {status:'ok'|'stalled'|'capped', items,
// producedOutput}. A stalled/capped run is left to finish unawaited (with a no-op
// catch) rather than killed.
async function _runMeetingSlice(win, nowIso, skipIds, { hardCapMs, stallMs }) {
  let acc = '';
  let lastActivity = Date.now();
  const startedAt = Date.now();
  const bump = () => { lastActivity = Date.now(); };
  const prompt = _meetingPrompt(win, nowIso, skipIds);

  const runP = (async () => {
    if (!connectPluginDir || !fs.existsSync(connectPluginDir)) {
      throw new Error('Connect plugin is not available yet — restart the server.');
    }
    const result = await sdkRunner.runChat({
      config: { pluginDir: connectPluginDir, agent: 'meeting-analyst', cwd: __dirname },
      prompt,
      sessionId: require('crypto').randomUUID(),
      resume: false,
      cwd: __dirname,
      meta: { source: 'connect', category: 'diary' },
      onChunk: (c) => { acc += c; bump(); },
      onStep: () => { bump(); },
    });
    if (result && result.fallback) throw new Error(result.error || 'Connect agent runtime unavailable');
    return acc.trim() ? acc : ((result && result.output) || '');
  })();
  // Prevent an unhandledRejection if we stop awaiting a slow/failed run.
  runP.catch(() => {});

  let watchdogTimer = null;
  const watchdog = new Promise((resolve) => {
    const tick = () => {
      const silent = Date.now() - lastActivity;
      const total = Date.now() - startedAt;
      if (silent >= stallMs) return resolve({ __end: 'stalled' });
      if (total >= hardCapMs) return resolve({ __end: 'capped' });
      watchdogTimer = setTimeout(tick, 4000);
    };
    watchdogTimer = setTimeout(tick, 4000);
  });

  try {
    const res = await Promise.race([runP.then(t => ({ __text: t })), watchdog]);
    if (res && res.__text != null) {
      const arr = _connectExtractJson(res.__text);
      return { status: 'ok', items: Array.isArray(arr) ? arr : [], producedOutput: String(res.__text).trim().length > 0 };
    }
    return { status: res.__end, items: [], producedOutput: acc.trim().length > 0 };
  } finally {
    if (watchdogTimer) clearTimeout(watchdogTimer);
  }
}

// Collect REAL meeting evidence via the WorkIQ-driven meeting-analyst agent, over
// the whole window — but sliced for reliability. Each slice is retried with a
// larger budget when it stalls WHILE STILL PRODUCING OUTPUT ("working but slow"),
// and surfaced (never silently dropped) when it stalls with nothing. Manual runs
// get a generous budget; scheduled runs stay bounded so the leader isn't hogged.
// `onProgress(state)` (optional) is called after each slice for live UI updates.
async function runConnectMeetingCollection({ days, manual = false, onProgress } = {}) {
  const s = settings.getSettings();
  const full = _connectDateWindow(days);
  if (s.connectMeetingsEnabled === false) {
    return { items: [], window: full, slices: { total: 0, ok: 0, retried: 0, failed: 0 }, failedWindows: [] };
  }
  const nowIso = new Date().toISOString();
  const skipIds = _connectRecordedMeetingIds();
  const pol = manual
    ? { sliceDays: 5, hardCapMs: 12 * 60_000, stallMs: 150_000, maxRetries: 2, overallCapMs: 20 * 60_000 }
    : { sliceDays: 4, hardCapMs: 4 * 60_000, stallMs: 120_000, maxRetries: 1, overallCapMs: 9 * 60_000 };
  // Self-healing: retry any windows a previous (time-boxed) run could not finish
  // BEFORE the current window, then the current window's slices. Dedup by key so
  // an overlapping parked window isn't processed twice.
  const backlog = (() => { try { return connect.getMeetingBacklog(); } catch { return []; } })();
  const baseSlices = _sliceWindow(full, pol.sliceDays);
  const seenKey = new Set();
  const slices = [];
  const pushSlice = (w) => { const k = `${w.start}..${w.end}`; if (!w || !w.start || !w.end || seenKey.has(k)) return; seenKey.add(k); slices.push({ start: w.start, end: w.end }); };
  for (const w of backlog) pushSlice(w);
  for (const w of baseSlices) pushSlice(w);
  const items = [];
  const failedWindows = [];
  let ok = 0, retried = 0, failed = 0;
  const runStart = Date.now();

  for (let i = 0; i < slices.length; i++) {
    const win = slices[i];
    if (Date.now() - runStart >= pol.overallCapMs) {
      // Out of overall budget — surface the rest as not-yet-gathered so a later
      // (idempotent) run can finish the backfill; do not silently omit.
      for (let j = i; j < slices.length; j++) { failedWindows.push({ ...slices[j], reason: 'overall-cap' }); failed++; }
      break;
    }
    let attempt = 0, cap = pol.hardCapMs, done = false;
    while (!done) {
      const r = await _runMeetingSlice(win, nowIso, skipIds, { hardCapMs: cap, stallMs: pol.stallMs });
      if (r.status === 'ok') {
        for (const it of r.items) items.push(it);
        ok++; done = true;
      } else if (r.producedOutput && attempt < pol.maxRetries) {
        // Working but slow — give the SAME slice more time rather than drop it.
        retried++; attempt++; cap = Math.round(cap * 1.75);
        console.log(`[connect] meeting slice ${win.start}..${win.end} ${r.status} but producing output — retrying with a larger budget (attempt ${attempt + 1})`);
      } else {
        failedWindows.push({ ...win, reason: r.status });
        failed++; done = true;
        console.warn(`[connect] meeting slice ${win.start}..${win.end} gave up (${r.status}${r.producedOutput ? ', partial output' : ', no output'})`);
      }
    }
    if (typeof onProgress === 'function') {
      try { onProgress({ total: slices.length, done: i + 1, ok, retried, failed, added: items.length }); } catch (_) { /* */ }
    }
  }
  // Persist the remaining backlog. failedWindows contains every window that did not
  // complete this run — whether a freshly-sliced window that ran out of budget or a
  // previously-parked one that failed again — so this both clears the healed windows
  // and enrolls newly-starved ones for the next run. Nothing is ever silently dropped.
  try { connect.setMeetingBacklog(failedWindows); } catch (_) { /* best-effort */ }
  return { items, window: full, slices: { total: slices.length, ok, retried, failed }, failedWindows };
}

// Collect recent M365 activity into diary evidence. Scheduled runs are leader-,
// consent- and enable-gated and never fire mid agent-run; manual runs bypass the
// enable/leader gates but still require consent.
// AI diary search — given a free-text query, ask the model which diary entries
// match by meaning (not just keywords) and return their ids, most relevant first.
async function runConnectSearch(query) {
  const q = String(query || '').trim();
  if (!q) return { ids: [] };
  const items = connect.listEvidence({ includeHidden: true });
  if (!items.length) return { ids: [] };
  const compact = items.slice(0, 400).map(e => ({
    id: e.id,
    date: e.date,
    source: e.source,
    title: e.title || '',
    detail: (e.detail || '').slice(0, 300),
    impact: (e.impact || '').slice(0, 200),
    tags: Array.isArray(e.tags) ? e.tags.join(', ') : '',
  }));
  const prompt =
    `You are a search assistant for a personal work diary. The user is searching for entries that match:\n\n` +
    `"${q}"\n\n` +
    `Here are the diary entries as a JSON array (each has an "id"):\n` +
    JSON.stringify(compact) + `\n\n` +
    `Return ONLY a JSON object {"ids":["id1","id2",...]} listing the ids that genuinely match the query, ` +
    `most relevant first. Match on meaning, not just exact words (e.g. "reliability work" should match ` +
    `entries about incidents, on-call, uptime, or SLAs). Include an entry only if it is truly relevant. ` +
    `If nothing matches, return {"ids":[]}. No prose, no code fence.`;
  let acc = '';
  const result = await sdkRunner.runChat({
    config: null, prompt, sessionId: require('crypto').randomUUID(),
    resume: false, cwd: __dirname, availableTools: [], onChunk: (c) => { acc += c; },
    meta: { source: 'connect', category: 'diary' },
  });
  let raw = (acc.trim() || (result && result.output) || '').trim();
  raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const a = raw.indexOf('{'), b = raw.lastIndexOf('}');
  let ids = [];
  if (a >= 0 && b > a) {
    try { const parsed = JSON.parse(raw.slice(a, b + 1)); if (Array.isArray(parsed.ids)) ids = parsed.ids.map(String); } catch {}
  }
  const valid = new Set(items.map(e => e.id));
  return { ids: ids.filter(id => valid.has(id)) };
}

async function runConnectCollection({ manual = false, days, bgMeetings = false } = {}) {
  const s = settings.getSettings();
  if (!s.connectConsent) return { skipped: 'no-consent' };
  if (!manual) {
    if (!leaderCheck()) return { skipped: 'not-leader' };
    if (!s.connectCollectionEnabled) return { skipped: 'collection-off' };
    if (_anyAgentBusy()) { console.log('[connect] collection deferred — agent run in flight'); return { skipped: 'busy' }; }
  }
  // Determine the collection window. An explicit `days` always wins. Otherwise
  // collect incrementally from the last successful collection forward (with a
  // 1-day overlap so late-arriving same-day items aren't missed), rather than a
  // fixed lookback — so nothing between runs is dropped and re-runs stay cheap.
  let effDays = days;
  if (effDays == null) {
    const last = (() => {
      try { return connect.getState().meta.lastCollectedAt; } catch { return null; }
    })();
    const lastMs = last ? Date.parse(last) : NaN;
    if (Number.isFinite(lastMs)) {
      const spanDays = Math.ceil((Date.now() - lastMs) / 86400000) + 1; // +1 = same-day overlap
      effDays = Math.min(45, Math.max(1, spanDays));
    } else {
      effDays = manual ? 7 : 1; // first-ever run seed
    }
  }
  const win = _connectDateWindow(effDays);
  const prompt =
    `Collect my Connect diary evidence for the date range ${win.start} to ${win.end} (inclusive). ` +
    `Gather MY OWN activity across Teams channel/group posts and email I sent — ` +
    `never one-on-one private chats, and do NOT collect meetings (those are handled separately). ` +
    `Return only the JSON array of evidence items exactly as specified.`;

  // Source 1: M365 (Teams/email) via the WorkIQ-driven collector agent.
  // Wrapped in a timeout so a WorkIQ stall (auth prompt, hung MCP) can never block
  // the ADO source or the request. Runs CONCURRENTLY with ADO below.
  const m365Task = (async () => {
    const TIMEOUT_MS = 4 * 60_000;
    let timer;
    try {
      const text = await Promise.race([
        _connectRunAgent('collector', prompt),
        new Promise((_, rej) => { timer = setTimeout(() => rej(new Error('WorkIQ collector timed out')), TIMEOUT_MS); }),
      ]);
      const arr = _connectExtractJson(text);
      if (Array.isArray(arr)) return arr;
      console.warn('[connect] M365 collector returned no parseable evidence:', String(text).slice(0, 200));
    } catch (e) { console.warn('[connect] M365 collection failed:', e.message); }
    finally { clearTimeout(timer); }
    return [];
  })();

  // Source 2: Azure DevOps (PRs + work items) queried directly for real evidence.
  const adoTask = (async () => {
    if (!s.connectAdoEnabled) return [];
    try {
      const r = await runConnectAdoCollection({ days: effDays });
      if (r && r.skipped) console.log(`[connect] ADO collection ${r.skipped}`);
      if (r && r.error) console.warn('[connect] ADO collection error:', r.error);
      return (r && Array.isArray(r.items)) ? r.items : [];
    } catch (e) { console.warn('[connect] ADO collection failed:', e.message); return []; }
  })();

  // Source 3: Meetings via the WorkIQ-driven meeting-analyst agent (transcript-driven,
  // records only meetings that have already ended). Uses the sliced, progress-aware
  // engine: no single hard timeout — slow-but-working slices are retried with a larger
  // budget, truly-stalled slices are surfaced (never silently omitted), and the whole
  // pass is bounded by an overall wall-clock cap. Manual runs get a generous budget.
  let meetingMeta = { slices: { total: 0, ok: 0, retried: 0, failed: 0 }, failedWindows: [] };
  const meetingTask = (async () => {
    if (!s.connectMeetingsEnabled) return [];
    // For a wide manual backfill the caller can defer meetings to the async
    // background sweep (startConnectMeetingBackfill, kicked below) so the HTTP
    // request returns promptly with the fast M365+ADO evidence instead of
    // blocking for the full (up to 20-min) synchronous meeting pass.
    if (bgMeetings) return [];
    try {
      const r = await runConnectMeetingCollection({ days: effDays, manual });
      meetingMeta = { slices: r.slices, failedWindows: r.failedWindows };
      return (r && Array.isArray(r.items)) ? r.items : [];
    } catch (e) { console.warn('[connect] meeting collection failed:', e.message); return []; }
  })();

  // Persist each source's evidence AS SOON AS it resolves rather than waiting for
  // all three. A slow/stuck source (typically the sliced meeting-analyst pass) must
  // never starve an already-gathered source — e.g. ADO PR reviews or M365 activity —
  // from landing in the diary. addEvidenceBatch is synchronous and idempotent (by
  // ext: tag), so these sequential per-source writes are safe and dedupe cleanly.
  let added = 0, skipped = 0, updated = 0;
  const counts = { m365: 0, ado: 0, meetings: 0 };
  const persist = (items) => {
    const arr = Array.isArray(items) ? items : [];
    if (!arr.length) return 0;
    const r = connect.addEvidenceBatch(arr, { origin: 'auto' });
    added += r.added; skipped += r.skipped; updated += r.updated;
    return arr.length;
  };
  await Promise.all([
    (async () => { let it = []; try { it = await m365Task; } catch { it = []; } counts.m365 = persist(it); })(),
    (async () => { let it = []; try { it = await adoTask; } catch { it = []; } counts.ado = persist(it); })(),
    (async () => { let it = []; try { it = await meetingTask; } catch { it = []; } counts.meetings = persist(it); })(),
  ]);
  connect.markCollected();
  // Wide manual backfill: hand the (slow) meeting sweep to the background poller
  // so the diary's fast sources are already visible while meetings stream in.
  let meetingBackfillStarted = false;
  if (bgMeetings && s.connectMeetingsEnabled) {
    try { startConnectMeetingBackfill(effDays); meetingBackfillStarted = true; }
    catch (e) { console.warn('[connect] background meeting backfill failed to start:', e.message); }
  }
  const sl = meetingMeta.slices;
  const slInfo = sl.total ? ` [meeting slices ${sl.ok}/${sl.total} ok, ${sl.retried} retried, ${sl.failed} failed]` : '';
  console.log(`[connect] collection ran: +${added} evidence (${skipped} dupes, ${updated} enriched) — ${counts.m365} M365 + ${counts.ado} ADO + ${counts.meetings} meetings, ${win.start}..${win.end}${slInfo}`);
  let generated = false;
  if (!manual && s.connectGenerateDaily && (added > 0 || updated > 0)) {
    try { await runConnectGeneration(); generated = true; } catch (e) { console.warn('[connect] auto-generate failed:', e.message); }
  }
  return { ran: true, added, skipped, updated, m365: counts.m365, ado: counts.ado, meetings: counts.meetings, window: win, generated, meetingSlices: meetingMeta.slices, meetingFailedWindows: meetingMeta.failedWindows, meetingBackfillStarted };
}

// Format the user's guiding memories for prompt injection. Returns null when
// there are none so callers can omit the section entirely.
function _connectMemoryLines() {
  let mems = [];
  try { mems = connect.listMemories(); } catch { mems = []; }
  if (!mems.length) return null;
  return mems.slice(0, 60).map(m => `- ${String(m.text || '').trim()}`).filter(Boolean).join('\n');
}

// Draft an HR-standard Connect from the user's (non-hidden) evidence, role, and
// guidance. Saved as source:'ai' — an editable draft the user personalizes.
// ---- Connect section locking --------------------------------------------------
// A Connect draft is Markdown organized by headings. Users can "lock" individual
// sections (by heading) so a full regeneration preserves them verbatim. We parse
// the body into heading-keyed blocks and, after the writer returns a fresh draft,
// splice the previously-locked blocks back in. The client and server MUST derive
// the section key identically — see `connectSectionKey` in public/app.html.
function _connectSectionKey(heading) {
  return String(heading || '').replace(/^#+\s*/, '').trim().toLowerCase().replace(/\s+/g, ' ');
}
// Split Markdown into { preamble, blocks:[{ key, heading, text }] }. `text` is the
// full block including its heading line and everything up to the next heading.
function _connectSplitSections(md) {
  const lines = String(md || '').split('\n');
  const blocks = [];
  let preamble = [];
  let cur = null;
  const headingRe = /^(#{1,6})\s+(.+?)\s*$/;
  for (const line of lines) {
    const m = line.match(headingRe);
    if (m) {
      if (cur) blocks.push(cur);
      cur = { key: _connectSectionKey(m[2]), heading: m[2].trim(), lines: [line] };
    } else if (cur) {
      cur.lines.push(line);
    } else {
      preamble.push(line);
    }
  }
  if (cur) blocks.push(cur);
  return {
    preamble: preamble.join('\n'),
    blocks: blocks.map(b => ({ key: b.key, heading: b.heading, text: b.lines.join('\n').replace(/\s+$/, '') })),
  };
}
// Produce a merged draft: start from `newMd`, but for any locked key replace the
// new block with the old (locked) one. Locked blocks that vanished from the new
// draft are appended so their content is never lost.
function _connectMergeLocked(newMd, oldMd, lockedKeys) {
  const locked = new Set((lockedKeys || []).map(_connectSectionKey).filter(Boolean));
  if (!locked.size) return newMd;
  const oldParsed = _connectSplitSections(oldMd);
  const oldByKey = new Map(oldParsed.blocks.map(b => [b.key, b]));
  const newParsed = _connectSplitSections(newMd);
  const usedKeys = new Set();
  const outBlocks = newParsed.blocks.map(b => {
    if (locked.has(b.key) && oldByKey.has(b.key)) {
      usedKeys.add(b.key);
      return oldByKey.get(b.key).text;
    }
    return b.text;
  });
  // Append any locked sections that the new draft dropped entirely.
  for (const key of locked) {
    if (!usedKeys.has(key) && oldByKey.has(key)) outBlocks.push(oldByKey.get(key).text);
  }
  const parts = [];
  if (newParsed.preamble.trim()) parts.push(newParsed.preamble.replace(/\s+$/, ''));
  parts.push(...outBlocks);
  return parts.join('\n\n').replace(/\n{3,}/g, '\n\n').trim();
}

// The writer is fed only the most-recent slice of diary evidence (newest-first),
// not the entire corpus — this cap bounds the prompt. Surfaced honestly by the
// transparency endpoint so a large diary's older entries aren't silently dropped
// without the user knowing. Kept as one constant so generation + transparency
// can never report a different number than what is actually sent.
const CONNECT_DRAFT_EVIDENCE_CAP = 80;

// Assemble the EXACT drafting context the writer sees for a given lookback window:
// the guidance scaffold (role + tone/framing/focus + remembered preferences +
// optional locked sections), the capped evidence slice, and the full corpus for
// coverage reporting. Shared by runConnectGeneration and the read-only
// /api/connect/transparency endpoint so the two never drift. No AI, no gather.
function _connectDraftContext({ lookbackDays = 0, lockedHeadings = [] } = {}) {
  const st = connect.getState();
  const g = st.guidance || {};
  const p = st.profile || {};
  // Lookback window: 0 = all-time. Otherwise only draft from evidence on/after `since`.
  let since = '';
  const days = Math.max(0, parseInt(lookbackDays, 10) || 0);
  if (days) { const d = new Date(); d.setDate(d.getDate() - days); since = d.toISOString().slice(0, 10); }
  const allEvidence = connect.listEvidence({ includeHidden: false, since: since || undefined });
  const evidence = allEvidence.slice(0, CONNECT_DRAFT_EVIDENCE_CAP);
  const memLines = _connectMemoryLines();
  const scaffoldParts = [
    'Draft my Connect from the material below. Follow the connect-standards skill and output only the Connect Markdown body.',
    '',
    '## My current role',
    `Role: ${p.role || '(unspecified)'}${p.level ? ' (level ' + p.level + ')' : ''}`,
    `Responsibilities: ${p.responsibilities || '(unspecified)'}`,
    `Priorities: ${p.priorities || '(unspecified)'}`,
    '',
    '## Guidance',
    `Tone: ${g.tone || 'professional'}`,
    `Framing: ${g.positivity || 'balanced'}`,
    `Focus areas: ${(g.focusAreas || []).join(', ') || '(none specified)'}`,
    `Extra instructions: ${g.instructions || '(none)'}`,
    ...(memLines ? [
      '',
      '## Remembered preferences (durable guidance from past sessions — honor these)',
      memLines,
    ] : []),
    ...(lockedHeadings.length ? [
      '',
      '## Locked sections (reproduce these headings EXACTLY, keep their content stable)',
      'The user has locked the following sections — keep each heading verbatim and preserve its content; only refine surrounding sections:',
      ...lockedHeadings.map(h => `- ${h}`),
    ] : []),
  ];
  const evLines = evidence.map(e =>
    `- [${e.date}] (${e.source}) ${e.title}${e.detail ? ' — ' + e.detail : ''}${e.impact ? ' | Impact: ' + e.impact : ''}`
  ).join('\n');
  const prompt = [
    ...scaffoldParts,
    '',
    '## Diary evidence' + (since ? ` (covering ${since} → today)` : ''),
    evLines,
  ].join('\n');
  return {
    prompt, scaffold: scaffoldParts.join('\n'),
    since, days, evidence, allEvidence,
    profile: p, guidance: g,
  };
}

async function runConnectGeneration({ lookbackDays = 0, lockedSections = [] } = {}) {
  const st = connect.getState();
  const prevBody = (st.draft && st.draft.markdown) || '';
  // Locked section headings (from the current draft) the user wants preserved.
  const lockedKeys = Array.isArray(lockedSections)
    ? lockedSections.map(_connectSectionKey).filter(Boolean)
    : [];
  const lockedHeadings = lockedKeys.length
    ? _connectSplitSections(prevBody).blocks.filter(b => lockedKeys.includes(b.key)).map(b => b.heading)
    : [];
  const ctx = _connectDraftContext({ lookbackDays, lockedHeadings });
  if (!ctx.evidence.length) throw new Error(ctx.since
    ? `No diary evidence in the last ${ctx.days} days to draft from. Widen the lookback window, add entries, or run a collection.`
    : 'No diary evidence to draft from yet. Add entries or run a collection first.');
  const text = await _connectRunAgent('writer', ctx.prompt);
  let md = String(text || '').trim();
  const fence = md.match(/```(?:markdown|md)?\s*([\s\S]*?)```/i);
  if (fence && fence[1].trim()) md = fence[1].trim();
  if (!md) throw new Error('The writer returned an empty draft. Try again.');
  // Authoritatively restore locked sections from the previous draft (belt-and-suspenders
  // on top of the prompt instruction) so a lock is never silently broken.
  if (lockedKeys.length) md = _connectMergeLocked(md, prevBody, lockedKeys);
  return connect.saveDraft({ markdown: md }, { source: 'ai' });
}

// Feature #3 — conversational revision of the current draft. Returns the assistant's
// short reply plus an OPTIONAL fully-revised draft (parsed from a sentinel block).
// Never saves — the caller loads any returned draft unsaved for the user to review.
async function runConnectDraftChat({ message, history, draft }) {
  const msg = String(message || '').trim();
  if (!msg) throw new Error('Say what you would like to change or ask about the draft.');
  const st = connect.getState();
  const evidence = connect.listEvidence({ includeHidden: false }).slice(0, 60);
  const g = st.guidance || {};
  const p = st.profile || {};
  const curDraft = String(draft != null ? draft : ((st.draft && st.draft.markdown) || '')).trim();
  const evLines = evidence.map(e =>
    `- [${e.date}] (${e.source}) ${e.title}${e.detail ? ' — ' + e.detail : ''}${e.impact ? ' | Impact: ' + e.impact : ''}`
  ).join('\n') || '(no diary evidence)';
  const histLines = (Array.isArray(history) ? history : []).slice(-8).map(h => {
    const role = h && h.role === 'assistant' ? 'Assistant' : 'User';
    return `${role}: ${String((h && h.content) || '').trim()}`;
  }).filter(Boolean).join('\n') || '(none)';
  const memLines = _connectMemoryLines();
  const prompt = [
    'You are revising my Connect draft through conversation. Follow your output protocol exactly.',
    '',
    '## My current role',
    `Role: ${p.role || '(unspecified)'}${p.level ? ' (level ' + p.level + ')' : ''}`,
    `Responsibilities: ${p.responsibilities || '(unspecified)'}`,
    `Priorities: ${p.priorities || '(unspecified)'}`,
    '',
    '## Guidance',
    `Tone: ${g.tone || 'professional'}`,
    `Framing: ${g.positivity || 'balanced'}`,
    `Focus areas: ${(g.focusAreas || []).join(', ') || '(none specified)'}`,
    `Extra instructions: ${g.instructions || '(none)'}`,
    ...(memLines ? [
      '',
      '## Remembered preferences (durable guidance from past sessions — honor these)',
      memLines,
    ] : []),
    '',
    '## Diary evidence',
    evLines,
    '',
    '## Current draft',
    curDraft || '(the draft is empty)',
    '',
    '## Conversation so far',
    histLines,
    '',
    '## My latest message',
    msg,
  ].join('\n');
  const text = await _connectRunAgent('editor', prompt);
  const raw = String(text || '').trim();
  let reply = raw;
  let newDraft = null;
  const m = raw.match(/===DRAFT===\s*([\s\S]*?)\s*===END DRAFT===/i);
  if (m) {
    reply = raw.slice(0, m.index).trim();
    let d = m[1].trim();
    const fence = d.match(/```(?:markdown|md)?\s*([\s\S]*?)```/i);
    if (fence && fence[1].trim()) d = fence[1].trim();
    if (d) newDraft = d;
  }
  if (!reply) reply = newDraft ? 'Updated the draft below — review the changes.' : 'Done.';
  // Detect a "save the draft" intent so the client can persist it AND capture a
  // guiding memory in one step (see saveConnectDraftWithMemory).
  const saveRequested = /\b(save|keep|commit|finali[sz]e|lock in|apply)\b/i.test(msg)
    && /\b(draft|connect|it|this|that|changes?)\b/i.test(msg);
  return { reply, draft: newDraft, saveRequested };
}

// Distill 0..N durable guiding "memories" from an Ask-AI editing conversation.
// Called when the user saves a draft. Memories capture the user's lasting
// preferences (tone, framing, work areas to emphasize, phrasings) — NOT one-off
// edits — so future drafts and "Generate from diary" stay aligned. Existing
// memories are passed in so the model only proposes genuinely NEW guidance.
async function extractConnectMemories({ history, message } = {}) {
  const hist = (Array.isArray(history) ? history : []).slice(-14).map(h => {
    const role = h && h.role === 'assistant' ? 'Assistant' : 'User';
    return `${role}: ${String((h && h.content) || '').trim()}`;
  }).filter(Boolean);
  if (message && String(message).trim()) hist.push(`User: ${String(message).trim()}`);
  if (!hist.length) return [];
  let existing = [];
  try { existing = connect.listMemories().map(m => m.text); } catch { existing = []; }
  const prompt =
    `You maintain a short list of DURABLE guiding preferences for how my Connect (a Microsoft ` +
    `self-review) should be drafted. From the editing conversation below, extract ONLY lasting ` +
    `preferences worth remembering for FUTURE drafts — e.g. tone/voice rules, framing choices, ` +
    `work areas to emphasize or downplay, phrasings to prefer or avoid, structural preferences. ` +
    `Do NOT capture one-off wording tweaks, factual corrections, or anything specific to a single ` +
    `sentence. Each memory must be a concise, self-contained instruction (max ~140 chars).\n\n` +
    `Preferences I already remember (do NOT repeat or restate these):\n` +
    (existing.length ? existing.map(t => `- ${t}`).join('\n') : '(none yet)') + `\n\n` +
    `Editing conversation:\n${hist.join('\n')}\n\n` +
    `Return ONLY a JSON object {"memories":["...","..."]} with the NEW durable preferences (0 to 4). ` +
    `If nothing lasting is worth remembering, return {"memories":[]}. No prose, no code fence.`;
  let acc = '';
  let result;
  try {
    result = await sdkRunner.runChat({
      config: null, prompt, sessionId: require('crypto').randomUUID(),
      resume: false, cwd: __dirname, availableTools: [], onChunk: (c) => { acc += c; },
      meta: { source: 'connect', category: 'diary' },
    });
  } catch (e) { console.warn('[connect] memory extraction failed:', e.message); return []; }
  let rawOut = (acc.trim() || (result && result.output) || '').trim();
  rawOut = rawOut.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const a = rawOut.indexOf('{'), b = rawOut.lastIndexOf('}');
  let mems = [];
  if (a >= 0 && b > a) {
    try {
      const parsed = JSON.parse(rawOut.slice(a, b + 1));
      if (Array.isArray(parsed.memories)) mems = parsed.memories.map(s => String(s || '').trim()).filter(Boolean);
    } catch {}
  }
  return mems.slice(0, 4);
}

// Save the draft AND capture guiding memories distilled from the Ask-AI session.
// Returns the new state plus the memories that were newly remembered.
async function saveConnectDraftWithMemory({ markdown, source, history, message } = {}) {
  const src = source === 'manual' ? 'manual' : 'ai';
  const state = connect.saveDraft({ markdown: String(markdown || '') }, { source: src });
  let added = [];
  try {
    const mems = await extractConnectMemories({ history, message });
    added = mems.length ? connect.addMemoryBatch(mems, { source: 'ai' }) : [];
  } catch (e) { console.warn('[connect] save-with-memory extraction failed:', e.message); }
  return { state, memories: added };
}

// Infer the "My current role" fields from recent activity. Only fills fields the
// user has left blank; returns both the merged state and the raw suggestion.
async function runConnectProfileAutofill() {
  const s = settings.getSettings();
  if (!s.connectConsent) throw new Error('Auto-fill needs collection consent (enable it in Connect → Settings).');
  const text = await _connectRunAgent('profiler',
    'Infer my current role from my recent Microsoft 365 activity and return only the JSON object specified.');
  const obj = _connectExtractJson(text);
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
    throw new Error('Could not infer your role from the available activity.');
  }
  const cur = connect.getState().profile || {};
  const patch = {};
  for (const k of ['role', 'level', 'responsibilities', 'priorities', 'summary']) {
    const v = typeof obj[k] === 'string' ? obj[k].trim() : '';
    if (v && !(cur[k] && String(cur[k]).trim())) patch[k] = v;
  }
  const state = Object.keys(patch).length ? connect.saveProfile(patch) : connect.getState();
  return { state, suggestion: obj, applied: Object.keys(patch) };
}

// --- Connect assistant (Board-AI-style propose→confirm agent) -----------------
// A conversational assistant with full read access to the Connect workspace (draft,
// diary evidence, guidance, profile, remembered preferences) that PROPOSES concrete,
// user-confirmable actions. It never mutates on its own — the client applies a
// confirmed action through the existing /api/connect/* CRUD endpoints. Read-only
// diary searches (find_entries) auto-run server-side and fold back into the context
// so the model can propose precise edits against real entry ids.
const CONNECT_ASSISTANT_MAX_SEARCH_DEPTH = 3;
async function runConnectAssistant({ message, history, extraContext, allowSearch = true, depth = 0 } = {}) {
  const msg = String(message || '').trim();
  if (!msg && !extraContext) throw new Error('Ask a question or say what you would like to change.');

  const st = connect.getState();
  const g = st.guidance || {};
  const p = st.profile || {};
  const draft = String((st.draft && st.draft.markdown) || '').trim();
  const evidence = connect.listEvidence({ includeHidden: true });
  const validIds = new Set(evidence.map(e => e.id));
  const evById = new Map(evidence.map(e => [e.id, e]));
  const memLines = _connectMemoryLines();

  const clip = (s, n) => { s = String(s == null ? '' : s).replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
  const multiline = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n) + '…' : s; };

  // --- context blocks ---------------------------------------------------------
  const blocks = [];
  blocks.push('## CURRENT DRAFT\n' + (draft ? multiline(draft, 6000) : '(the draft is empty)'));
  blocks.push('## PROFILE\n' +
    `Role: ${p.role || '(unspecified)'}${p.level ? ' (level ' + p.level + ')' : ''}\n` +
    `Responsibilities: ${p.responsibilities || '(unspecified)'}\n` +
    `Priorities: ${p.priorities || '(unspecified)'}`);
  blocks.push('## GUIDANCE\n' +
    `Tone: ${g.tone || 'professional'}\n` +
    `Framing: ${g.positivity || 'balanced'}\n` +
    `Focus areas: ${(g.focusAreas || []).join(', ') || '(none specified)'}\n` +
    `Extra instructions: ${g.instructions || '(none)'}`);
  if (memLines) blocks.push('## REMEMBERED PREFERENCES (durable guidance — honor these)\n' + memLines);
  const recent = evidence.slice(0, 60);
  const evLines = recent.map(e => {
    const flags = [];
    if (e.hidden) flags.push('hidden');
    if (e.pinned) flags.push('pinned');
    const meta = flags.length ? ' [' + flags.join(', ') + ']' : '';
    return `- (${e.id}) [${e.date || '?'}] (${e.source || 'manual'})${meta} ${clip(e.title, 120)}` +
      `${e.detail ? ' — ' + clip(e.detail, 220) : ''}${e.impact ? ' | Impact: ' + clip(e.impact, 160) : ''}`;
  }).join('\n') || '(no diary entries yet)';
  blocks.push(`## DIARY ENTRIES (${recent.length} most recent of ${evidence.length}; reference an entry by its (id))\n` + evLines);
  if (extraContext) blocks.push(String(extraContext));

  const histLines = (Array.isArray(history) ? history : []).slice(-8).map(h => {
    const role = h && h.role === 'assistant' ? 'Assistant' : 'User';
    return `${role}: ${clip((h && h.content) || '', 500)}`;
  }).filter(Boolean).join('\n') || '(none)';

  const sys = [
    'You are the Connect assistant embedded in a personal Microsoft "Connect" (self-review) workspace.',
    'You help the user manage every part of their Connect: the draft, the diary of evidence entries,',
    'drafting guidance, their role profile, and durable remembered preferences.',
    'You ALWAYS propose changes for the user to confirm — you NEVER claim a change was already made.',
    '',
    'Respond with ONLY a single JSON object (no prose outside it, no markdown code fence):',
    '{ "reply": "<a short, friendly message to the user>", "actions": [ <zero or more action objects> ] }',
    '',
    'Action objects (propose only the ones the user actually needs):',
    '- Find diary entries (read-only; runs immediately, results come back to you): {"type":"find_entries","query":"<what to search for>"}',
    '- Edit the whole draft: {"type":"edit_draft","markdown":"<COMPLETE new draft markdown>","summary":"<one-line description>"}',
    '- Create a diary entry: {"type":"create_entry","date":"YYYY-MM-DD","source":"<teams|email|meeting|ado|manual>","title":"...","detail":"...","impact":"...","tags":["..."]}',
    '- Edit a diary entry: {"type":"edit_entry","id":"<entry id>", ...any of date, source, title, detail, impact, tags, hidden}',
    '- Delete a diary entry: {"type":"delete_entry","id":"<entry id>"}',
    '- Update drafting guidance: {"type":"update_guidance", ...any of tone, positivity, instructions, focusAreas (array)}',
    '- Update role profile: {"type":"update_profile", ...any of role, level, responsibilities, priorities}',
    '- Remember a durable preference: {"type":"add_memory","text":"..."}',
    '- Regenerate the draft from the diary evidence: {"type":"generate_draft"}',
    '',
    'Rules:',
    '- Reference diary entries ONLY by the (id) shown in ## DIARY ENTRIES. Never invent ids.',
    '- If you need entries you cannot see in the list, propose a find_entries action FIRST; its',
    '  results are returned to you and you can then propose concrete create/edit/delete actions.',
    '- For edit_draft, output the COMPLETE new markdown body — not a diff or a fragment.',
    '- Keep "reply" concise and in the user\'s voice. If no change is needed, return "actions": [] and just answer.',
    '- Propose at most a handful of actions per turn.',
    '',
    blocks.join('\n\n'),
    '',
    '## CONVERSATION',
    histLines,
    '',
    '## USER MESSAGE',
    msg || '(continuing from the search results above)',
  ].join('\n');

  let acc = '';
  const result = await sdkRunner.runChat({
    config: _systemAgentCfg('connect', null), prompt: sys + _systemAgentInstr('connect'), sessionId: require('crypto').randomUUID(),
    resume: false, cwd: __dirname, availableTools: [], onChunk: (c) => { acc += c; },
    meta: { source: 'connect', category: 'diary' },
  });
  let raw = (acc.trim() || (result && result.output) || '').trim();

  // --- parse the model's JSON envelope ---------------------------------------
  const parseModel = (text) => {
    let t = String(text || '').trim();
    t = t.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    const a = t.indexOf('{'), b = t.lastIndexOf('}');
    if (a < 0 || b <= a) return null;
    try { return JSON.parse(t.slice(a, b + 1)); } catch { return null; }
  };
  const parsed = parseModel(raw);
  if (!parsed || typeof parsed !== 'object') {
    return { reply: raw || 'Sorry, I could not put together a response — try rephrasing.', actions: [] };
  }

  const proposed = Array.isArray(parsed.actions) ? parsed.actions : [];

  // --- auto-run a read-only find_entries and recurse -------------------------
  if (allowSearch && depth < CONNECT_ASSISTANT_MAX_SEARCH_DEPTH) {
    const search = proposed.find(a => a && a.type === 'find_entries' && String(a.query || '').trim());
    if (search) {
      let found = { ids: [] };
      try { found = await runConnectSearch(search.query); } catch (e) { console.warn('[connect] assistant search failed:', e.message); }
      const matched = (found.ids || []).map(id => evById.get(id)).filter(Boolean);
      const resultLines = matched.length
        ? matched.map(e => `- (${e.id}) [${e.date || '?'}] (${e.source || 'manual'}) ${clip(e.title, 120)}` +
            `${e.detail ? ' — ' + clip(e.detail, 220) : ''}${e.impact ? ' | Impact: ' + clip(e.impact, 160) : ''}`).join('\n')
        : '(no diary entries matched)';
      const searchBlock = `## SEARCH RESULT for "${clip(search.query, 120)}"\n` + resultLines;
      const foldedHistory = (Array.isArray(history) ? history.slice() : []);
      foldedHistory.push({ role: 'user', content: msg });
      foldedHistory.push({ role: 'assistant', content: String(parsed.reply || 'Searching your diary…') });
      return runConnectAssistant({
        message: '', history: foldedHistory,
        extraContext: searchBlock, allowSearch: true, depth: depth + 1,
      });
    }
  }

  // --- validate + normalize proposed mutating actions ------------------------
  const resolveAction = (a) => {
    if (!a || typeof a !== 'object') return null;
    const type = String(a.type || '').trim();
    switch (type) {
      case 'edit_draft': {
        const md = String(a.markdown || '').trim();
        if (!md) return null;
        return { type, markdown: md, summary: clip(a.summary || 'Rewrite the draft', 140),
          label: 'Edit draft', preview: clip(a.summary || 'Replace the draft with a revised version', 160) };
      }
      case 'create_entry': {
        const title = String(a.title || '').trim();
        const detail = String(a.detail || '').trim();
        if (!title && !detail) return null;
        const tags = Array.isArray(a.tags) ? a.tags.map(t => String(t).trim()).filter(Boolean).slice(0, 12) : [];
        const entry = { date: String(a.date || '').trim() || new Date().toISOString().slice(0, 10),
          source: String(a.source || 'manual').trim() || 'manual', title, detail,
          impact: String(a.impact || '').trim(), tags };
        return { type, entry, label: 'New diary entry',
          preview: clip(`[${entry.date}] ${entry.title || entry.detail}`, 160) };
      }
      case 'edit_entry': {
        const id = String(a.id || '').trim();
        if (!validIds.has(id)) return null;
        const patch = {};
        for (const k of ['date', 'source', 'title', 'detail', 'impact']) {
          if (a[k] != null) patch[k] = String(a[k]).trim();
        }
        if (Array.isArray(a.tags)) patch.tags = a.tags.map(t => String(t).trim()).filter(Boolean).slice(0, 12);
        if (typeof a.hidden === 'boolean') patch.hidden = a.hidden;
        if (!Object.keys(patch).length) return null;
        const cur = evById.get(id);
        return { type, id, patch, label: 'Edit entry',
          preview: clip((cur && cur.title) || id, 120) + ' — ' + Object.keys(patch).join(', ') };
      }
      case 'delete_entry': {
        const id = String(a.id || '').trim();
        if (!validIds.has(id)) return null;
        const cur = evById.get(id);
        return { type, id, destructive: true, label: 'Delete entry',
          preview: clip((cur && cur.title) || id, 140) };
      }
      case 'update_guidance': {
        const patch = {};
        for (const k of ['tone', 'positivity', 'instructions']) {
          if (a[k] != null) patch[k] = String(a[k]).trim();
        }
        if (Array.isArray(a.focusAreas)) patch.focusAreas = a.focusAreas.map(t => String(t).trim()).filter(Boolean).slice(0, 20);
        if (!Object.keys(patch).length) return null;
        return { type, patch, label: 'Update guidance', preview: clip(Object.keys(patch).join(', '), 140) };
      }
      case 'update_profile': {
        const patch = {};
        for (const k of ['role', 'level', 'responsibilities', 'priorities']) {
          if (a[k] != null) patch[k] = String(a[k]).trim();
        }
        if (!Object.keys(patch).length) return null;
        return { type, patch, label: 'Update profile', preview: clip(Object.keys(patch).join(', '), 140) };
      }
      case 'add_memory': {
        const text = String(a.text || '').trim();
        if (!text) return null;
        return { type, text, label: 'Remember preference', preview: clip(text, 160) };
      }
      case 'generate_draft':
        return { type, label: 'Regenerate draft', preview: 'Draft a fresh Connect from your diary evidence' };
      default:
        return null;
    }
  };

  const actions = proposed
    .filter(a => a && a.type !== 'find_entries')
    .map(resolveAction)
    .filter(Boolean)
    .slice(0, 8)
    .map((a, i) => ({ id: 'cact-' + Date.now().toString(36) + '-' + i, ...a }));

  const reply = String(parsed.reply || '').trim() || (actions.length ? 'Here is what I can do — review and confirm below.' : 'Done.');
  return { reply, actions };
}

function scheduleConnectCollection() {
  if (connectCollectJob) { try { connectCollectJob.stop(); } catch {} connectCollectJob = null; }
  const s = settings.getSettings();
  if (!s.connectCollectionEnabled || !s.connectConsent) return;
  const sched = (s.connectSchedule || '').trim();
  if (!sched || sched.toLowerCase() === 'never') return;
  let parsed;
  try { parsed = parseTaskSchedule(sched); }
  catch (e) { console.warn(`[connect] bad connectSchedule "${sched}": ${e.message}`); return; }
  const fire = () => { if (!featureEnabled('connect')) return; runConnectCollection().catch(e => console.warn('[connect] collection job error:', e.message)); };
  if (parsed.type === 'cron') {
    connectCollectJob = new TaskCron(parsed.cron, fire);
  } else if (parsed.type === 'interval') {
    const timer = setInterval(fire, parsed.ms);
    connectCollectJob = { stop: () => clearInterval(timer) };
  } else return;
  console.log(`[connect] collection scheduled: ${parsed.description}`);
}

// Catch up a collection that was DUE while the app was offline. croner (like any
// cron) only fires at the scheduled instant — if the machine was asleep/off then,
// that day's run is silently skipped. On startup (and whenever the schedule
// changes) we compare the most recent scheduled occurrence against when we last
// actually collected; if a run was missed, we fire one catch-up collection.
function connectCatchUpCheck() {
  try {
    if (!featureEnabled('connect')) return;
    const s = settings.getSettings();
    if (!s.connectCollectionEnabled || !s.connectConsent) return;
    const sched = (s.connectSchedule || '').trim();
    if (!sched || sched.toLowerCase() === 'never') return;
    let parsed;
    try { parsed = parseTaskSchedule(sched); } catch { return; }
    let prevRun = null;
    if (parsed.type === 'cron') {
      // croner v10's previousRun() only reports an instance's actual prior fire (null here),
      // so compute the most recent scheduled occurrence by stepping forward from a bounded
      // floor (≤ a handful of iterations for daily/hourly schedules).
      try {
        const cron = new TaskCron(parsed.cron);
        const floor = new Date(Date.now() - 8 * 86400000);
        let guard = 0, n = cron.nextRun(floor);
        while (n && n.getTime() <= Date.now() && guard++ < 100000) { prevRun = n; n = cron.nextRun(n); }
      } catch {}
    } else if (parsed.type === 'interval') {
      prevRun = new Date(Date.now() - parsed.ms);
    }
    if (!prevRun) return;
    const meta = connect.getState().meta || {};
    const last = meta.lastCollectedAt ? new Date(meta.lastCollectedAt) : null;
    const missed = !last || last.getTime() < prevRun.getTime();
    if (!missed) return;
    console.log(`[connect] missed scheduled collection (last=${last ? last.toISOString() : 'never'}, due=${prevRun.toISOString()}) — running catch-up`);
    runConnectCollection().catch(e => console.warn('[connect] catch-up collection error:', e.message));
  } catch (e) { console.warn('[connect] catch-up check failed:', e.message); }
}

scheduleConnectCollection();
// Give the app ~90s to settle (leader election, WorkIQ auth) before any catch-up.
setTimeout(connectCatchUpCheck, 90_000);

// --- Newsletter scheduled auto-generation ------------------------------------
// Mirrors the Connect collection scheduler: a settings-driven schedule string
// arms a croner/interval job that regenerates the newsletter from the diary,
// leader-gated and deferred while an agent run is in flight. On success it flags
// the draft "review pending" (in-app banner) and — unless the user opted out —
// opens a review-ready .eml in the mail client. A startup catch-up covers runs
// missed while the machine was off.
let newsletterGenJob = null;

async function runScheduledNewsletter() {
  try {
    const s = settings.getSettings();
    if (!s.newsletterAutoGenerate) return;
    if (!leaderCheck()) return;
    // Defer if an agent run is in flight; a later tick (or catch-up) will retry.
    if (_anyAgentBusy()) { console.log('[newsletter] scheduled run deferred — an agent is busy'); return; }
    // Skip silently when there's no diary evidence in the window (don't spam an
    // error email) — the user may not have collected/added anything this period.
    try {
      const { items } = _newsletterContext();
      if (!items.length) { console.log('[newsletter] scheduled run skipped — no diary evidence in window'); return; }
    } catch (_) { return; }
    const runId = require('crypto').randomUUID();
    console.log('[newsletter] scheduled generation starting');
    await runNewsletterGeneration(runId);
    try { broadcastSSE('newsletter-progress', { runId, icon: '✅', text: 'Newsletter ready', done: true, at: Date.now() }); } catch (_) { /* ignore */ }
    newsletter.markAutoGenerated();
    try { broadcastSSE('newsletter-ready', { at: Date.now() }); } catch (_) { /* ignore */ }
    if (s.newsletterNotifyEmail !== false) {
      try {
        const { emlPath } = await _newsletterBuildEml({
          bannerNote: 'Your newsletter is ready — review below, then forward to publish.',
        });
        require('child_process').exec(`start "" "${emlPath}"`);
        newsletter.markEmailed();
      } catch (e) { console.warn('[newsletter] notify email failed:', e.message); }
    }
    console.log('[newsletter] scheduled generation complete');
  } catch (e) {
    console.warn('[newsletter] scheduled generation error:', e.message);
  }
}

function scheduleNewsletterGeneration() {
  if (newsletterGenJob) { try { newsletterGenJob.stop(); } catch {} newsletterGenJob = null; }
  const s = settings.getSettings();
  if (!s.newsletterAutoGenerate) return;
  const sched = (s.newsletterSchedule || '').trim();
  if (!sched || sched.toLowerCase() === 'never') return;
  let parsed;
  try { parsed = parseTaskSchedule(sched); }
  catch (e) { console.warn(`[newsletter] bad newsletterSchedule "${sched}": ${e.message}`); return; }
  const fire = () => { if (!featureEnabled('newsletter')) return; runScheduledNewsletter().catch(e => console.warn('[newsletter] job error:', e.message)); };
  if (parsed.type === 'cron') {
    newsletterGenJob = new TaskCron(parsed.cron, fire);
  } else if (parsed.type === 'interval') {
    const timer = setInterval(fire, parsed.ms);
    newsletterGenJob = { stop: () => clearInterval(timer) };
  } else return;
  console.log(`[newsletter] auto-generation scheduled: ${parsed.description}`);
}

function newsletterCatchUpCheck() {
  try {
    if (!featureEnabled('newsletter')) return;
    const s = settings.getSettings();
    if (!s.newsletterAutoGenerate) return;
    const sched = (s.newsletterSchedule || '').trim();
    if (!sched || sched.toLowerCase() === 'never') return;
    let parsed;
    try { parsed = parseTaskSchedule(sched); } catch { return; }
    let prevRun = null;
    if (parsed.type === 'cron') {
      try {
        const cron = new TaskCron(parsed.cron);
        const floor = new Date(Date.now() - 8 * 86400000);
        let guard = 0, n = cron.nextRun(floor);
        while (n && n.getTime() <= Date.now() && guard++ < 100000) { prevRun = n; n = cron.nextRun(n); }
      } catch {}
    } else if (parsed.type === 'interval') {
      prevRun = new Date(Date.now() - parsed.ms);
    }
    if (!prevRun) return;
    const meta = newsletter.getState().meta || {};
    const last = meta.lastAutoGeneratedAt ? new Date(meta.lastAutoGeneratedAt) : null;
    const missed = !last || last.getTime() < prevRun.getTime();
    if (!missed) return;
    console.log(`[newsletter] missed scheduled generation (last=${last ? last.toISOString() : 'never'}, due=${prevRun.toISOString()}) — running catch-up`);
    runScheduledNewsletter().catch(e => console.warn('[newsletter] catch-up error:', e.message));
  } catch (e) { console.warn('[newsletter] catch-up check failed:', e.message); }
}

scheduleNewsletterGeneration();
// Settle slightly after Connect's catch-up so the two don't race for the agent.
setTimeout(newsletterCatchUpCheck, 95_000);


// --- Marketplace daily auto-scan ---------------------------------------------
// Rescan every user-added marketplace source once a day so newly-published
// agents/plugins/skills/MCPs are discovered without a manual rescan. Leader-gated
// (only one node in a synced cluster scans) and honors the marketplaceAutoScan
// setting. A startup catch-up fires if the last auto-scan is stale (> ~1 day).
const MARKETPLACE_SCAN_INTERVAL_MS = 24 * 60 * 60 * 1000;
function marketplaceAutoScanEnabled() {
  try { return settings.getSettings().marketplaceAutoScan !== false; } catch { return true; }
}
async function runMarketplaceAutoScan(reason) {
  if (!marketplaceAutoScanEnabled()) return;
  if (!leaderCheck()) return;
  try {
    const r = await marketplace.scanAllSources();
    console.log(`[marketplace] auto-scan (${reason}): ${r.scanned} source(s), ${r.errors} error(s)`);
  } catch (e) { console.warn('[marketplace] auto-scan error:', e.message); }
}
setInterval(() => { runMarketplaceAutoScan('interval'); }, MARKETPLACE_SCAN_INTERVAL_MS);
setTimeout(() => {
  try {
    if (!marketplaceAutoScanEnabled()) return;
    const meta = marketplace.getMeta();
    const last = meta.lastAutoScanAt ? Date.parse(meta.lastAutoScanAt) : 0;
    if (!last || (Date.now() - last) >= MARKETPLACE_SCAN_INTERVAL_MS) runMarketplaceAutoScan('startup catch-up');
  } catch (e) { console.warn('[marketplace] startup scan check failed:', e.message); }
}, 90_000);

// --- Connect (living impact / performance diary) ------------------------------
app.get('/api/connect', (req, res) => {
  try {
    const s = settings.getSettings();
    res.json({
      state: connect.getState(),
      evidence: connect.listEvidence(),
      memories: connect.listMemories(),
      config: {
        collectionEnabled: s.connectCollectionEnabled === true,
        consent: s.connectConsent === true,
        schedule: s.connectSchedule || '',
        generateDaily: s.connectGenerateDaily === true,
        storageDir: connect.storageDir(),
        emailTo: s.connectEmailTo || '',
        adoEnabled: s.connectAdoEnabled === true,
        adoOrg: s.connectAdoOrg || '',
        adoProjects: s.connectAdoProjects || '',
        adoOrgs: Array.isArray(s.connectAdoOrgs) ? s.connectAdoOrgs.map(o => ({ org: (o && o.org) || '', projects: (o && o.projects) || '' })) : [],
        meetingsEnabled: s.connectMeetingsEnabled !== false,
        lastCollectedAt: (connect.getState().meta || {}).lastCollectedAt || null,
      },
      backfill: connectBackfillState,
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

