function _meAiPlaybookStorePath() { return dataPath('me-ai/playbooks.json'); }
function _meAiLoadPlaybookStore() {
  try {
    const p = _meAiPlaybookStorePath();
    if (!fs.existsSync(p)) return {};
    const j = JSON.parse(fs.readFileSync(p, 'utf8'));
    return (j && typeof j === 'object') ? j : {};
  } catch (_) { return {}; }
}
function _meAiSavePlaybookStore(map) {
  try {
    const p = _meAiPlaybookStorePath();
    fs.mkdirSync(require('path').dirname(p), { recursive: true });
    fs.writeFileSync(p, JSON.stringify(map || {}, null, 2));
    return true;
  } catch (e) { console.error('[me-ai] playbook store save failed', e && e.message); return false; }
}
// Normalize a definition to the canonical editable shape.
function _meAiNormPlaybookDef(d) {
  const g = (d && d.gating && typeof d.gating === 'object') ? d.gating : {};
  return {
    label: String((d && d.label) || '').slice(0, 80),
    icon: String((d && d.icon) || '📓').slice(0, 8),
    description: String((d && d.description) || '').slice(0, 300),
    goal: String((d && d.goal) || '').slice(0, 800),
    steps: Array.isArray(d && d.steps) ? d.steps.map(s => String(s || '').slice(0, 500)).filter(Boolean).slice(0, 12) : [],
    constraints: Array.isArray(d && d.constraints) ? d.constraints.map(s => String(s || '').slice(0, 400)).filter(Boolean).slice(0, 12) : [],
    gating: { pursuit: !!g.pursuit, code: !!g.code, external: g.external === 'confirm' ? 'confirm' : 'none' },
  };
}
// The merged, current definition for an id: seed overlaid by any stored edits, or a
// stored custom playbook. Returns null for an unknown id.
function _meAiPlaybookDef(id) {
  const key = String(id || '').trim().toLowerCase();
  if (!key) return null;
  const store = _meAiLoadPlaybookStore();
  const seed = ME_AI_PLAYBOOK_SEED[key];
  const rec = store[key];
  if (!seed && !rec) return null;
  const base = seed ? _meAiNormPlaybookDef(seed) : null;
  const over = rec ? _meAiNormPlaybookDef(rec) : null;
  const merged = base && over
    ? { ...base, ...over, gating: { ...base.gating, ...over.gating } }
    : (over || base);
  merged.id = key;
  merged.kind = seed ? 'builtin' : 'custom';
  merged.edited = !!(seed && rec);
  return merged;
}
function _meAiPlaybookList() {
  const store = _meAiLoadPlaybookStore();
  const out = [];
  for (const id of ME_AI_PLAYBOOK_SEED_ORDER) out.push(_meAiPlaybookDef(id));
  for (const id of Object.keys(store)) {
    if (!ME_AI_PLAYBOOK_SEED[id]) { const d = _meAiPlaybookDef(id); if (d) out.push(d); }
  }
  return out.filter(Boolean);
}
// Gating routed through the def overlay, falling back to the code constant so behavior
// is unchanged until a playbook is actually edited.
function _meAiIsPursuitPlaybook(pb) {
  const d = _meAiPlaybookDef(pb);
  if (d && d.gating) return !!d.gating.pursuit;
  return ME_AI_PURSUIT_PLAYBOOKS.has(pb);
}
function _meAiIsCodePlaybook(pb) {
  const d = _meAiPlaybookDef(pb);
  if (d && d.gating) return !!d.gating.code;
  return ME_AI_CODE_PLAYBOOKS.has(pb);
}
function _meAiResolveAssistantAction(a, ctx) {
  if (!a || typeof a !== 'object') return null;
  const type = String(a.type || '').trim();
  if (!ME_AI_ASSISTANT_ACTIONS.has(type)) return null;
  const clip = (s, n) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().slice(0, n);
  const okHm = (v) => _hmToMin(v) != null;
  switch (type) {
    case 'add_block': {
      if (!okHm(a.start) || !okHm(a.end) || _hmToMin(a.end) <= _hmToMin(a.start)) return null;
      const t = clip(a.title, 200) || 'Blocked time';
      const sub = String(a.blocktype || a.blockType || a.kind || '').trim();
      const bt = ME_AI_BLOCK_TYPES.has(sub) ? sub : 'personal';
      return { type, start: String(a.start), end: String(a.end), title: t, blkType: bt, detail: clip(a.detail, 500),
        label: 'Add block', preview: `${a.start}–${a.end} · ${t}` };
    }
    case 'add_recurring': {
      const every = Math.max(15, Math.min(480, +a.everyMin || 60));
      const dur = Math.max(5, Math.min(240, +a.durMin || 10));
      const t = clip(a.title, 200) || 'Break';
      const sub = String(a.blocktype || a.blockType || a.kind || '').trim();
      const bt = ME_AI_BLOCK_TYPES.has(sub) ? sub : 'break';
      return { type, everyMin: every, durMin: dur, title: t, blkType: bt,
        from: okHm(a.from) ? String(a.from) : '', to: okHm(a.to) ? String(a.to) : '',
        label: 'Add recurring block', preview: `${t} — ${dur} min every ${every} min` };
    }
    case 'split_item':
    case 'remove_item':
    case 'dismiss_item': {
      const key = clip(a.key || a.link || a.title, 300);
      if (!key) return null;
      const lbl = type === 'split_item' ? 'Split into separate items' : type === 'remove_item' ? 'Remove from its block' : 'Not mine (dismiss)';
      const out = { type, key, label: lbl, preview: clip(a.title || key, 160) };
      if (type === 'dismiss_item') out.note = clip(a.note, 300);
      return out;
    }
    case 'set_mode': {
      const modes = new Set(['balanced', 'focused', 'unblock-team', 'relaxed', 'low-sleep']);
      const m = String(a.mode || '').trim();
      if (!modes.has(m)) return null;
      return { type, mode: m, label: 'Change day mode', preview: m };
    }
    case 'set_time_pref': {
      const acts = new Set(['review', 'steward', 'focus', 'comms', 'admin', 'prep']);
      const act = String(a.activity || '').trim();
      let when = String(a.when || '').trim().toLowerCase();
      if (when === 'any' || when === 'none') when = '';
      if (!acts.has(act) || !['', 'morning', 'afternoon'].includes(when)) return null;
      return { type, activity: act, when, label: 'Set time-of-day preference', preview: `${act} → ${when || 'any time'}` };
    }
    case 'set_hours': {
      const patch = {};
      for (const k of ['workStart', 'workEnd', 'lunchStart', 'lunchEnd']) if (a[k] != null && okHm(a[k])) patch[k] = String(a[k]);
      if (!Object.keys(patch).length) return null;
      return { type, patch, label: 'Adjust working hours', preview: Object.entries(patch).map(([k, v]) => `${k}=${v}`).join(', ') };
    }
    case 'set_grid': {
      const g = +a.grid; if (![5, 10, 15].includes(g)) return null;
      return { type, grid: g, label: 'Set minimum block size', preview: `${g}-minute minimum block` };
    }
    case 'set_work_days': {
      if (!Array.isArray(a.days)) return null;
      const days = [...new Set(a.days.map(d => +d).filter(d => d >= 0 && d <= 6))].sort();
      if (!days.length) return null;
      const names = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
      return { type, days, label: 'Set work days', preview: days.map(d => names[d]).join(', ') };
    }
    case 'add_todo': {
      const t = clip(a.title, 200); if (!t) return null;
      const scope = a.scope === 'personal' ? 'personal' : 'work';
      return { type, title: t, scope, label: 'Add to-do', preview: t + (scope === 'personal' ? ' (personal)' : '') };
    }
    case 'remove_todo': {
      const t = clip(a.title, 200); if (!t) return null;
      return { type, title: t, label: 'Remove to-do', preview: t };
    }
    case 'triage_inbox': {
      const key = clip(a.key || a.link || a.title, 300); if (!key) return null;
      const act = String(a.action || '').trim();
      if (!['later', 'now', 'today', 'dismiss', 'wontfix'].includes(act)) return null;
      const lbl = { later: 'Move to backlog', now: 'Handle now', today: 'Fit into today', dismiss: 'Not mine', wontfix: "Won't fix" }[act];
      return { type, key, act, label: lbl, preview: clip(a.title || key, 160) };
    }
    case 'regenerate':
      return { type, label: 'Regenerate the day', preview: 'Re-plan with the latest signals' };
    case 'launch_me_agent': {
      let pb = String(a.playbook || a.kind || '').trim().toLowerCase();
      if (pb === 'focus') pb = 'implement';
      if (pb === 'meeting') pb = 'prep';
      if (!ME_AI_ASSISTANT_PLAYBOOKS.has(pb) && !_meAiPlaybookDef(pb)) pb = 'adhoc';
      const goal = clip(a.goal || a.title || a.detail, 600);
      if (!goal) return null;
      const link = clip(a.link || a.prLink || a.url, 400);
      const scope = a.scope === 'personal' ? 'personal' : 'work';
      const pursue = _meAiIsPursuitPlaybook(pb);
      const title = clip(a.title || goal, 120);
      const kindLabel = { review: 'review', comms: 'reply', prep: 'prep', steward: 'stewardship',
        implement: 'implementation', admin: 'admin', adhoc: 'task' }[pb] || 'task';
      return { type, playbook: pb, goal, link, scope, pursue, title,
        label: pursue ? `Launch a ${kindLabel} pursuit` : `Launch a Me agent (${kindLabel})`,
        preview: (pursue ? 'Fans out on the canvas · ' : '') + title };
    }
    case 'set_constraint': {
      const kind = ['before', 'after', 'at'].includes(String(a.kind)) ? String(a.kind) : 'before';
      if (!okHm(a.time)) return null;
      const subject = clip(a.subject || a.title, 200);
      if (!subject) return null;
      const when = kind === 'after' ? 'after' : kind === 'at' ? 'at' : 'before';
      return { type, subject, kind, time: String(a.time), text: clip(a.text, 300),
        label: 'Set a timing constraint', preview: `"${subject}" ${when} ${a.time}` };
    }
    case 'clear_constraint': {
      const subject = clip(a.subject || a.title, 200);
      const id = clip(a.id, 60);
      if (!subject && !id) return null;
      return { type, subject, id, label: 'Remove a timing constraint', preview: subject || id };
    }
    default: return null;
  }
}
async function runMeAiAgendaAssistant({ message, history, date } = {}) {
  const msg = String(message || '').trim();
  if (!msg) throw new Error('Tell me what you would like to change about your day.');
  const s = settings.getSettings();
  const cfg = _meAiConfig(s);
  const day = String(date || '').slice(0, 10) || _meAiLocalDay();
  const agenda = loadAgendaForDate(day) || { blocks: [], backlog: [], needsAttention: [], todos: [] };
  const inbox = (() => { try { return loadInboxForDate(day).items || []; } catch { return []; } })();
  const clip = (s2, n) => String(s2 == null ? '' : s2).replace(/\s+/g, ' ').trim().slice(0, n);

  const blocks = [];
  const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  blocks.push('## CURRENT SETTINGS\n' +
    `Working hours: ${cfg.workStart}–${cfg.workEnd} (lunch ${cfg.lunchStart}–${cfg.lunchEnd})\n` +
    `Work days: ${(cfg.workDays || []).map(d => dayNames[d]).join(', ') || '(none)'}\n` +
    `Minimum block size: ${cfg.grid}-minute · Day mode: ${cfg.mode || 'balanced'}\n` +
    `Time-of-day prefs: ${Object.entries(cfg.timePrefs || {}).filter(([, v]) => v).map(([k, v]) => `${k}=${v}`).join(', ') || '(none set)'}`);
  const bl = (agenda.blocks || []).map((b, i) => {
    const key = _meAiBlockKey(b);
    const items = Array.isArray(b.items) && b.items.length ? ` [${b.items.length} items: ${b.items.map(it => clip(it.title, 40)).join(' · ')}]` : '';
    const man = b.meta && b.meta.manual ? ' (manual)' : '';
    return `- #${i} ${b.start}–${b.end} [${b.type}]${man} ${clip(b.title, 120)}${items}${key ? `  {key: ${clip(key, 120)}}` : ''}`;
  }).join('\n') || '(no blocks planned yet)';
  blocks.push(`## TODAY'S BLOCKS (${(agenda.blocks || []).length})\n` + bl);
  const backlog = (agenda.backlog || []).slice(0, 20).map(x => `- ${clip(x.title, 100)}${x.link ? `  {key: ${clip(x.link, 100)}}` : ''}`).join('\n');
  if (backlog) blocks.push('## BACKLOG (not scheduled today)\n' + backlog);
  const todos = (agenda.todos || []).map(t => `- ${t.done ? '[x]' : '[ ]'} ${clip(t.title, 100)}${t.scope === 'personal' ? ' (personal)' : ''}`).join('\n');
  if (todos) blocks.push('## TO-DOS\n' + todos);
  const inb = inbox.filter(it => it && it.triage !== 'dismissed' && it.triage !== 'wontfix').slice(0, 12)
    .map(it => `- ${clip(it.title, 100)}${it.link ? `  {key: ${clip(it.link, 100)}}` : ''}`).join('\n');
  if (inb) blocks.push('## ATTENTION INBOX (asks awaiting triage)\n' + inb);
  try {
    const cons = _meAiNormConstraints(loadMeAiOverrides(day));
    if (cons.length) blocks.push('## TIMING CONSTRAINTS (already set)\n' +
      cons.map(c => `- ${_meAiConstraintText(c)}  {id: ${c.id}}`).join('\n'));
  } catch (_) { /* best-effort */ }

  const histLines = (Array.isArray(history) ? history : []).slice(-8).map(h => {
    const role = h && h.role === 'assistant' ? 'Assistant' : 'User';
    return `${role}: ${clip((h && h.content) || '', 500)}`;
  }).filter(Boolean).join('\n') || '(none)';

  const sys = [
    'You are the Agenda assistant embedded in a personal "Me.AI" daily-planning workspace.',
    'You help the user shape their day: add protected/break/workout blocks, split or remove',
    'agenda items, reshape the day (mode, working hours, work days, minimum block size, time-of-day prefs),',
    'manage to-dos, and triage attention-inbox asks.',
    'You ALWAYS propose changes for the user to confirm — you NEVER claim a change was already made.',
    '',
    'Respond with ONLY a single JSON object (no prose outside it, no markdown code fence):',
    '{ "reply": "<a short, friendly message>", "actions": [ <zero or more action objects> ] }',
    '',
    'Action objects (propose only the ones the user actually needs):',
    '- Add a one-off block: {"type":"add_block","start":"HH:MM","end":"HH:MM","title":"...","blocktype":"break|workout|focus|deep-focus|personal|admin|prep|comms|review|meeting","detail":"..."}',
    '- Add a recurring block: {"type":"add_recurring","everyMin":60,"durMin":10,"title":"Break","type":"break","from":"HH:MM","to":"HH:MM"} (from/to optional = working hours)',
    '- Split a merged item into separate blocks: {"type":"split_item","key":"<block key>"}',
    '- Remove one item from its block (keeps the rest): {"type":"remove_item","key":"<item/PR link or title>"}',
    "- Dismiss an item as not yours: {\"type\":\"dismiss_item\",\"key\":\"<link or title>\",\"note\":\"...\"}",
    '- Change day mode: {"type":"set_mode","mode":"balanced|focused|unblock-team|relaxed|low-sleep"}',
    '- Set when you are sharpest for an activity: {"type":"set_time_pref","activity":"review|steward|focus|comms|admin|prep","when":"morning|afternoon|any"}',
    '- Adjust working hours: {"type":"set_hours","workStart":"HH:MM","workEnd":"HH:MM","lunchStart":"HH:MM","lunchEnd":"HH:MM"} (any subset)',
    '- Set the minimum block size for flexible work (does NOT move fixed meetings): {"type":"set_grid","grid":5|10|15}',
    '- Set work days: {"type":"set_work_days","days":[1,2,3,4,5]} (0=Sun … 6=Sat)',
    '- Add a to-do: {"type":"add_todo","title":"...","scope":"work|personal"}',
    '- Remove a to-do: {"type":"remove_todo","title":"<exact title>"}',
    '- Triage an inbox ask: {"type":"triage_inbox","key":"<link or title>","action":"today|now|later|dismiss|wontfix"}',
    '- Re-plan the day with the latest signals: {"type":"regenerate"}',
    '- Set a hard timing constraint: {"type":"set_constraint","subject":"<the work, e.g. self-epic review>","kind":"before|after|at","time":"HH:MM","text":"<optional note>"} — e.g. "I need self-epic review to happen before 1:30 PM" → subject "self-epic review", kind "before", time "13:30".',
    '- Clear a timing constraint: {"type":"clear_constraint","subject":"<the work>"} (or "id":"<constraint id>")',
    '- Hand work to a Me agent (it does the actual work — reviewing a PR, drafting a reply, prepping for a meeting, stewarding a PR, or any ad-hoc goal): {"type":"launch_me_agent","playbook":"review|comms|prep|steward|implement|admin|adhoc","goal":"<what the agent should accomplish>","link":"<optional PR/item URL>","scope":"work|personal"}',
    '',
    'Rules:',
    '- Reference blocks/items by the {key: …} shown in the context. Use exact HH:MM 24-hour times.',
    '- To "protect 2–3pm for deep work", propose add_block 14:00–15:00 type deep-focus.',
    '- To "break the PR review of A, B, C into separate items", propose split_item on that block key.',
    '- To "remove PR 62392 from today\'s review", propose remove_item with that PR\'s link/title.',
    '- When the user states a hard deadline for a piece of work ("I need X before 1:30 PM", "do the',
    '  budget review after standup", "start the demo prep at 3"), propose set_constraint — it is',
    '  remembered and enforced across every re-plan, not just a one-time nudge.',
    '- When the user asks you to actually DO something (review a PR, reply to an email, prep me for a',
    '  meeting, steward/unblock a PR, or a free-form task), propose launch_me_agent — do NOT just add a',
    '  block. A Me agent works in the background, shows its thinking/tools, and asks before any external',
    '  send. Pick the closest playbook (review/comms/prep/steward/implement/admin) or "adhoc" for anything',
    '  else. review/comms/prep/steward fan out into a live pursuit on the canvas; the rest run as one agent.',
    '- Keep "reply" concise and friendly. If nothing needs changing, return "actions": [] and just answer.',
    '- Propose at most a handful of actions per turn.',
    '',
    blocks.join('\n\n'),
    '',
    '## CONVERSATION',
    histLines,
    '',
    '## USER MESSAGE',
    msg,
  ].join('\n');

  let acc = '';
  const result = await sdkRunner.runChat({
    config: _systemAgentCfg('agenda-assistant', null), prompt: sys + _systemAgentInstr('agenda-assistant'), sessionId: require('crypto').randomUUID(),
    resume: false, cwd: __dirname, availableTools: [], onChunk: (c) => { acc += c; },
    meta: { source: 'me-ai', category: 'me-ai-assistant' },
  });
  let raw = (acc.trim() || (result && result.output) || '').trim();
  const parseModel = (text) => {
    let t = String(text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    const a = t.indexOf('{'), b = t.lastIndexOf('}');
    if (a < 0 || b <= a) return null;
    try { return JSON.parse(t.slice(a, b + 1)); } catch { return null; }
  };
  const parsed = parseModel(raw);
  if (!parsed || typeof parsed !== 'object') {
    return { reply: raw || 'Sorry, I could not put that together — try rephrasing.', actions: [] };
  }
  const proposed = Array.isArray(parsed.actions) ? parsed.actions : [];
  const actions = proposed.map(a => _meAiResolveAssistantAction(a, { agenda })).filter(Boolean).slice(0, 8);
  return { reply: String(parsed.reply || (actions.length ? 'Here is what I can do.' : 'Done.')).slice(0, 1200), actions };
}

// GET /api/me-ai → config + whether today already has an agenda snapshot.
app.get('/api/me-ai', (req, res) => {
  try {
    const cfg = _meAiConfig();
    const today = _meAiLocalDay();
    _meAiLastActive = Date.now();
    res.json({ ok: true, config: cfg, today, hasAgendaToday: !!loadAgendaForDate(today) });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// PUT /api/me-ai/settings → persist consent + working hours + grid.
app.put('/api/me-ai/settings', (req, res) => {
  try {
    const b = req.body || {};
    const patch = {};
    if (typeof b.consent === 'boolean') patch.meAiConsent = b.consent;
    const validHm = v => typeof v === 'string' && _hmToMin(v) != null;
    if (validHm(b.workStart)) patch.meAiWorkStart = b.workStart;
    if (validHm(b.workEnd)) patch.meAiWorkEnd = b.workEnd;
    if (b.lunchStart === '' || validHm(b.lunchStart)) patch.meAiLunchStart = b.lunchStart;
    if (b.lunchEnd === '' || validHm(b.lunchEnd)) patch.meAiLunchEnd = b.lunchEnd;
    if ([5, 10, 15].includes(Number(b.grid))) patch.meAiGrid = Number(b.grid);
    if ([10, 15, 30, 45, 60].includes(Number(b.imminentWindow))) patch.meAiImminentWindow = Number(b.imminentWindow);
    if (b.workDays !== undefined) patch.meAiWorkDays = _meAiSanitizeWorkDays(b.workDays);
    if (b.weeklyHours !== undefined) patch.meAiWeeklyHours = _meAiSanitizeWeeklyHours(b.weeklyHours);
    const MODES = ['balanced', 'relaxed', 'focused', 'low-sleep', 'unblock-team'];
    if (MODES.includes(String(b.mode))) patch.meAiMode = String(b.mode);
    if (b.timePrefs && typeof b.timePrefs === 'object' && !Array.isArray(b.timePrefs)) {
      const allowT = ['review', 'steward', 'focus', 'comms', 'admin', 'prep'];
      const allowV = ['', 'morning', 'afternoon'];
      const clean = {};
      for (const [k, v] of Object.entries(b.timePrefs)) {
        if (allowT.includes(k) && allowV.includes(String(v))) { if (v) clean[k] = String(v); }
      }
      patch.meAiTimePrefs = clean;
    }
    // Phase 2: auto-triage config.
    if (typeof b.autoTriage === 'boolean') patch.meAiAutoTriage = b.autoTriage;
    const clampPct = v => { const n = Math.round(Number(v)); return Number.isFinite(n) ? Math.max(0, Math.min(100, n)) : null; };
    if (b.autoTriageSafe !== undefined) { const n = clampPct(b.autoTriageSafe); if (n != null) patch.meAiAutoTriageSafe = n; }
    if (b.autoTriageAgenda !== undefined) { const n = clampPct(b.autoTriageAgenda); if (n != null) patch.meAiAutoTriageAgenda = n; }
    if (b.groupingMin !== undefined) { const n = clampPct(b.groupingMin); if (n != null) patch.meAiGroupingMin = n; }
    if (b.conflictAutoReport !== undefined) patch.meAiConflictAutoReport = !!b.conflictAutoReport;
    if (b.actionTiers && typeof b.actionTiers === 'object' && !Array.isArray(b.actionTiers)) {
      const allowAct = ['later', 'dismiss', 'wontfix', 'today']; // 'now' is locked → never persisted
      const allowTier = ['safe', 'agenda', 'off'];
      const clean = {};
      for (const [k, v] of Object.entries(b.actionTiers)) {
        if (allowAct.includes(k) && allowTier.includes(String(v))) clean[k] = String(v);
      }
      patch.meAiActionTiers = clean;
    }
    // Stricter triage bar.
    if (typeof b.strictTriage === 'boolean') patch.meAiStrictTriage = b.strictTriage;
    if (b.strictMinUrgency !== undefined && [3, 4, 5].includes(Number(b.strictMinUrgency))) patch.meAiStrictMinUrgency = Number(b.strictMinUrgency);
    if (typeof b.strictAllowMentions === 'boolean') patch.meAiStrictAllowMentions = b.strictAllowMentions;
    if (typeof b.strictAllowReviews === 'boolean') patch.meAiStrictAllowReviews = b.strictAllowReviews;
    // Backlog work-item defaults.
    if (b.workItem && typeof b.workItem === 'object' && !Array.isArray(b.workItem)) {
      const wi = b.workItem;
      const s40 = v => String(v == null ? '' : v).trim().slice(0, 120);
      if ('org' in wi) patch.meAiWorkItemOrg = s40(wi.org);
      if ('project' in wi) patch.meAiWorkItemProject = s40(wi.project);
      if ('type' in wi) patch.meAiWorkItemType = s40(wi.type) || 'DNCeng Task';
      if ('state' in wi) patch.meAiWorkItemState = s40(wi.state);
      if ('areaPath' in wi) patch.meAiWorkItemArea = String(wi.areaPath || '').trim().slice(0, 300);
      if ('iterationPath' in wi) patch.meAiWorkItemIteration = String(wi.iterationPath || '').trim().slice(0, 300);
      if ('tags' in wi) patch.meAiWorkItemTags = String(wi.tags || '').trim().slice(0, 300);
    }
    settings.updateSettings(patch);
    res.json({ ok: true, config: _meAiConfig() });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// GET /api/me-ai/agenda?date=YYYY-MM-DD → cached snapshot (or null).
app.get('/api/me-ai/agenda', (req, res) => {
  try {
    const date = String(req.query.date || '').slice(0, 10) || _meAiLocalDay();
    res.json({ ok: true, date, agenda: loadAgendaForDate(date), config: _meAiConfig(), building: _meAiIsBuilding(date) });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// GET /api/me-ai/conflict-report?date= → status of the auto-reporter for the day's current
// conflict clash. Reads the persisted snapshot (its meta.conflicts + meta.conflictReport stamp)
// and the per-day conflict-report store, so the banner can show "auto-filed #N ↗" or explain
// why it didn't file. Cheap + read-only.
app.get('/api/me-ai/conflict-report', (req, res) => {
  try {
    const date = String(req.query.date || '').slice(0, 10) || _meAiLocalDay();
    const agenda = loadAgendaForDate(date);
    const pairs = (agenda && agenda.meta && agenda.meta.conflicts) || [];
    if (!pairs.length) return res.json({ ok: true, date, status: 'none', conflicts: 0 });
    const sig = _meAiConflictSignature(pairs);
    const store = loadConflictReports(date);
    const rec = store[sig];
    // Prefer a concrete filed record; else fall back to the stamp the builder left on meta.
    let report = (agenda.meta && agenda.meta.conflictReport) || null;
    if (rec && rec.issue) report = { status: 'filed', sig, issue: rec.issue, url: rec.url || null };
    else if (rec && rec.pending && (!report || report.status !== 'filed')) report = { status: 'filing', sig };
    if (!report) report = { status: 'unknown', sig };
    res.json({ ok: true, date, conflicts: pairs.length, sig, report, canFile: report.status !== 'filed' });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/conflict-report/file { date } → manually file the anonymized scheduling-conflict
// issue for the day on demand. Bypasses the leader/setting/today gates (the user explicitly asked)
// but keeps dedup (returns the existing issue if already filed) + full anonymization. Lets the owner
// file a report even when auto-reporting was off or another instance was the designated filer.
app.post('/api/me-ai/conflict-report/file', async (req, res) => {
  try {
    const date = String((req.body && req.body.date) || '').slice(0, 10) || _meAiLocalDay();
    const agenda = loadAgendaForDate(date);
    const pairs = (agenda && agenda.meta && agenda.meta.conflicts) || [];
    if (!pairs.length) return res.status(400).json({ error: 'No scheduling conflicts on this day to report.' });
    const sig = _meAiConflictSignature(pairs);
    const store = loadConflictReports(date);
    if (store[sig] && store[sig].issue) {
      return res.json({ ok: true, already: true, issue: store[sig].issue, url: store[sig].url || null });
    }
    const prior = null; // manual file has no diff pair; the issue still captures the settled clash + telemetry
    const issue = await _meAiFileConflictIssue(date, prior, agenda, _meAiConfig(), 'manual');
    // Reflect the filed state onto the live snapshot so a reload shows the link immediately.
    try { if (agenda && agenda.meta) { agenda.meta.conflictReport = { status: 'filed', sig, issue: issue && issue.number, url: (issue && (issue.webUrl || issue.url)) || null }; saveAgendaForDate(date, agenda); } } catch {}
    res.json({ ok: true, issue: issue && issue.number, url: (issue && (issue.webUrl || issue.url)) || null });
  } catch (err) { res.status(500).json({ error: err.message }); }
});


// POST /api/me-ai/agenda/generate { date, todos:[{title}] } → build + persist.
app.post('/api/me-ai/agenda/generate', async (req, res) => {
  try {
    const b = req.body || {};
    const cause = ME_AI_INTENTIONAL_CAUSES.has(b.cause) ? b.cause : 'manual';
    const agenda = await generateMeAiAgenda({ date: b.date, todos: Array.isArray(b.todos) ? b.todos : [], reindex: b.reindex !== false, cause });
    res.json({ ok: true, agenda });
    // Item E — auto-ripple: a fresh TODAY plan is the anchor every forward day builds on,
    // so after a successful today regenerate, rebuild the forward horizon in the background
    // (fire-and-forget; leader + consent gated inside; never blocks the response). This
    // replaces the manual "Regenerate next days" button — future days now update on their own
    // whenever today changes.
    try {
      const genDate = String(b.date || '').slice(0, 10) || _meAiLocalDay();
      if (genDate === _meAiLocalDay()) _meAiGenerateFutureDays({ force: true }).catch(() => {});
    } catch (_) { /* best-effort */ }
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/agenda/todos { date, todos } → persist the day's todo list. Writes the
// durable todo store (authoritative across restarts + background regenerates, so a removed
// todo never comes back) AND mirrors onto the snapshot if one exists, without a re-plan
// (REQ-3). Keeps done/scope/carry-over durable across navigation and server restarts.
app.post('/api/me-ai/agenda/todos', (req, res) => {
  try {
    const b = req.body || {};
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    const todos = _meAiNormTodos(Array.isArray(b.todos) ? b.todos : []);
    // Maintain the removed-title tombstone so a deleted todo can't be re-folded by a later
    // generate: any title that was in the prior store but is absent now is a deliberate
    // removal; any title present again (re-added by the user) lifts its tombstone.
    const prior = loadMeAiTodoStore(date) || [];
    const nextTitles = new Set(todos.map(t => t.title.toLowerCase()));
    const tomb = new Set(loadMeAiTodoTomb(date));
    for (const t of prior) { const k = t.title.toLowerCase(); if (!nextTitles.has(k)) tomb.add(k); }
    for (const k of nextTitles) tomb.delete(k);
    saveMeAiTodoTomb(date, Array.from(tomb));
    saveMeAiTodoStore(date, todos);
    const snap = loadAgendaForDate(date);
    if (snap) { snap.todos = todos; _meAiCleanSnapshotBlocks(snap); saveAgendaForDate(date, snap); }
    res.json({ ok: true, date, todos, persisted: true });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/agenda/goals/regenerate { date? } → realign today's GOALS to the current
// agenda on demand. Goals normally freeze after the morning seed so background churn can't
// refill a cleared board; this is the explicit escape hatch for when the owner feels the
// open goals no longer match what's actually on the agenda. It is conservative by design:
//   • Every HANDLED goal (done / partial=need-more-time / missed=didn't-get-to) is kept
//     verbatim — this never erases a record of what you did or decided.
//   • Any non-goal todo you added by hand is kept too.
//   • Only the still-OPEN, agenda-derived goals are dropped and re-derived from the current
//     agenda's work blocks, deduped against everything kept (so a handled item never comes
//     back as a fresh open goal, and the per-day tombstone of removed items is respected).
// Nothing is re-planned — the agenda itself is untouched; only the goal checklist changes.
app.post('/api/me-ai/agenda/goals/regenerate', (req, res) => {
  try {
    const b = req.body || {};
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    const snap = loadAgendaForDate(date);
    const store = loadMeAiTodoStore(date) || (snap && Array.isArray(snap.todos) ? snap.todos : []) || [];
    if (!snap || !Array.isArray(snap.blocks) || !snap.blocks.length) {
      // No agenda to derive goals from yet — leave the store exactly as-is.
      return res.json({ ok: true, date, todos: _meAiNormTodos(store), regenerated: false, added: 0, dropped: 0, reason: 'no-agenda' });
    }
    const isHandled = (t) => !!(t && (t.done || (t.status && t.status !== 'open')));
    const isGoal = (t) => !!(t && t.kind === 'checklist');
    const normed = _meAiNormTodos(store);
    // Snapshot the open-goal set BEFORE realigning so we can report the TRUE net change.
    // A realign fully re-derives every open goal, so a raw kept-length delta would always
    // churn (drop N, re-add N) even when the resulting list is identical. Diff by title so
    // a no-op click honestly reports "nothing changed".
    const openKey = (t) => String((t && t.title) || '').trim().toLowerCase();
    const beforeOpen = new Set(normed.filter(t => isGoal(t) && !isHandled(t)).map(openKey).filter(Boolean));
    // Keep every handled item (audit record) and every hand-added non-goal todo; drop only
    // the open, agenda-derived goals so they can be freshly re-derived below.
    const kept = normed.filter(t => isHandled(t) || !isGoal(t));
    _meAiSeedChecklist(snap, kept, date, { force: true });
    const next = _meAiNormTodos(kept);
    const afterOpen = new Set(next.filter(t => isGoal(t) && !isHandled(t)).map(openKey).filter(Boolean));
    let added = 0, dropped = 0;
    afterOpen.forEach(k => { if (!beforeOpen.has(k)) added++; });
    beforeOpen.forEach(k => { if (!afterOpen.has(k)) dropped++; });
    saveMeAiTodoStore(date, next);
    snap.todos = next; _meAiCleanSnapshotBlocks(snap); saveAgendaForDate(date, snap);
    res.json({ ok: true, date, todos: next, regenerated: true, added, dropped });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/suggestion/dismiss { date, id } → §12 dismiss a nudge for the day
// (persisted so it stays hidden across regenerates). Strips it from the live snapshot
// too. Returns the remaining suggestions.
app.post('/api/me-ai/suggestion/dismiss', (req, res) => {
  try {
    const b = req.body || {};
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    const id = String(b.id || '').slice(0, 300);
    if (!id) return res.status(400).json({ error: 'id required' });
    const store = loadSuggDismiss(date);
    store[id] = { at: new Date().toISOString() };
    saveSuggDismiss(date, store);
    let suggestions = [];
    const snap = loadAgendaForDate(date);
    if (snap && Array.isArray(snap.suggestions)) {
      snap.suggestions = snap.suggestions.filter(sg => sg.id !== id);
      _meAiCleanSnapshotBlocks(snap);
      saveAgendaForDate(date, snap);
      suggestions = snap.suggestions;
    }
    res.json({ ok: true, date, suggestions });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// GET /api/me-ai/agenda/changes?date= → REQ-7 change log + churn summary for a day.
app.get('/api/me-ai/agenda/changes', (req, res) => {
  try {
    const date = String(req.query.date || '').slice(0, 10) || _meAiLocalDay();
    const log = loadChangesForDate(date);
    res.json({ ok: true, date, events: log.events.slice(-100), churn: _meAiChurnSummary(log.events) });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/agenda/dayshape { date? } → REQ-7 end-of-day "day shape" note to
// the Diary (consent-gated, deduped). Returns the summary even if already logged.
app.post('/api/me-ai/agenda/dayshape', (req, res) => {
  try {
    const date = String((req.body && req.body.date) || '').slice(0, 10) || _meAiLocalDay();
    const r = _meAiWriteDayShape(date);
    res.json({ ok: true, date, ...r });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// M5 look-back / retro — planned-vs-actual for any (past) date. Read-only, cheap
// (no signal gather / no LLM): pairs the frozen agenda snapshot with what actually
// got recorded — Me.AI task completions in the Diary, todo done/carried state, and
// the day's organic churn — and derives a short retro so the user can see how the
// day really went vs how it was planned.
// GET /api/me-ai/lookback?date=YYYY-MM-DD
app.get('/api/me-ai/lookback', (req, res) => {
  try {
    const date = String(req.query.date || '').slice(0, 10) || _meAiLocalDay();
    const data = _meAiEodData(date);
    // Preserve the existing lookback response shape (client depends on planned.todos).
    res.json({
      ok: true, date: data.date, today: data.today, isPast: data.isPast, hasAgenda: data.hasAgenda,
      planned: { blocks: data.planned.blocks, focusPlanned: data.planned.focusPlanned, todos: data.planned.goals, backlogCount: data.planned.backlogCount },
      actual: data.actual, retro: data.retro,
    });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// GET /api/me-ai/eod?date=&ai=1 → the richer End-of-day report (folds the old rhythm
// chip). Always returns the deterministic planned-vs-actual data + rhythm cheaply. AI
// commentary is on-demand + cached: if ai=1 (and the cache is stale/missing) we run ONE
// LLM turn and cache it keyed by an input fingerprint; otherwise we return any cached
// narrative plus an `aiStale` flag so the client can offer "Generate AI commentary".
app.get('/api/me-ai/eod', async (req, res) => {
  try {
    const date = String(req.query.date || '').slice(0, 10) || _meAiLocalDay();
    const wantAi = req.query.ai === '1' || req.query.ai === 'true';
    const data = _meAiEodData(date);
    const fp = _meAiEodFingerprint(data);
    const cached = _meAiLoadEodCache(date);
    const fresh = cached && cached.fp === fp;
    if (wantAi) {
      const narrative = await _meAiEodNarrative(date, data, { force: !fresh });
      return res.json({ ok: true, ...data, narrative, aiStale: false });
    }
    return res.json({
      ok: true, ...data,
      narrative: fresh ? { ...cached.narrative, cached: true, fp } : null,
      aiStale: !fresh,
    });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// GET /api/me-ai/reports?days=N → per-day daily-activity + fragmentation rollup for the
// Reports page (REQ-12). Read-only + cheap: reuses the frozen agenda snapshots, the
// change log (day-shape churn), the diary (task completions), the Me-agent task store
// (agents launched) and the dismiss store (Not-mine vs Won't-fix). Planning adjustments
// (day-mode/timeprefs/manual/triage) are recorded as `planned` and NEVER counted as
// fragmentation.
app.get('/api/me-ai/reports', (req, res) => {
  try {
    const today = _meAiLocalDay();
    let days = Number(req.query.days) || 30;
    days = Math.max(1, Math.min(180, Math.round(days)));
    // Diary completions indexed by date once (avoids re-scanning per day).
    let ev = [];
    try { ev = connect.listEvidence({ includeHidden: true }) || []; } catch (_) { ev = []; }
    const doneByDate = {};
    for (const e of ev) {
      if (!e) continue;
      const d = String(e.date || '').slice(0, 10);
      if (!d) continue;
      if (!(e.tags || []).some(t => String(t) === 'me-ai')) continue;
      if ((e.tags || []).some(t => String(t).startsWith('ext:me-ai:dayshape'))) continue; // the note itself
      doneByDate[d] = (doneByDate[d] || 0) + 1;
    }
    // Me-agent tasks indexed by creation date, with playbook + outcome + wall-clock time
    // so we can derive impact metrics (delegated / unblocked / agent-hours multiplied).
    const taskByDate = {};
    try {
      for (const t of meAiTasks.values()) {
        if (!t || t._ephemeral) continue;
        const d = String((t.createdAt || t.updatedAt) || '').slice(0, 10);
        if (!d) continue;
        const agg = taskByDate[d] || (taskByDate[d] = { launched: 0, done: 0, unblock: 0, comms: 0, agentMs: 0 });
        agg.launched++;
        const done = t.stage === 'done' || t.status === 'done';
        if (done) agg.done++;
        // review + steward = moving someone else's work / a PR forward = "unblocked".
        if (t.playbook === 'review' || t.playbook === 'steward') agg.unblock++;
        if (t.playbook === 'comms') agg.comms++;
        // Wall-clock time the agent worked for you (only count finished runs).
        const st = Date.parse(t.startedAt || t.createdAt || '');
        const fi = Date.parse(t.finishedAt || t.updatedAt || '');
        if (done && st && fi && fi > st) agg.agentMs += Math.min(fi - st, 4 * 3600000); // cap 4h/task
      }
    } catch (_) { /* best-effort */ }
    const out = [];
    const base = new Date(today + 'T00:00:00');
    for (let i = 0; i < days; i++) {
      const dt = new Date(base.getTime() - i * 86400000);
      const date = dt.toISOString().slice(0, 10);
      const churn = _meAiChurnSummary(loadChangesForDate(date).events);
      const agenda = loadAgendaForDate(date);
      const blocks = (agenda && Array.isArray(agenda.blocks)) ? agenda.blocks : [];
      const workBlocks = blocks.filter(b => b && b.type !== 'personal' && b.type !== 'lunch' && b.type !== 'open' && !_meAiIsPersonal(b));
      const focus = blocks.filter(b => b && b.type === 'focus' && !_meAiIsPersonal(b)).length;
      const meetings = blocks.filter(b => b && b.type === 'meeting' && !_meAiIsPersonal(b)).length;
      // Minutes by block type (blocks carry HH:MM start/end) → time spent / protected.
      const minOf = (b) => { try { const a = _hmToMin(b.start), z = _hmToMin(b.end); return (z > a) ? (z - a) : 0; } catch (_) { return 0; } };
      let focusMin = 0, meetingMin = 0, commsMin = 0, reviewMin = 0, stewardMin = 0, prepMin = 0, adminMin = 0, personalMin = 0;
      for (const b of blocks) {
        if (!b) continue;
        const m = minOf(b);
        // Personal-labeled (or personal-type) time is reported ONLY as "personal time" — no
        // work-type breakdown, no title/detail leaks into the report.
        if (_meAiIsPersonal(b)) { personalMin += m; continue; }
        if (b.type === 'focus') focusMin += m;
        else if (b.type === 'meeting') meetingMin += m;
        else if (b.type === 'comms') commsMin += m;
        else if (b.type === 'review') reviewMin += m;
        else if (b.type === 'steward') stewardMin += m;
        else if (b.type === 'prep') prepMin += m;
        else if (b.type === 'admin') adminMin += m;
      }
      // review + steward blocks = time spent moving others / PRs forward.
      const unblockBlocks = blocks.filter(b => b && (b.type === 'review' || b.type === 'steward')).length;
      const todos = (agenda && Array.isArray(agenda.todos)) ? agenda.todos.filter(t => t && t.scope !== 'personal') : [];
      const todosDone = todos.filter(t => t && t.done).length;
      const todosCarried = todos.filter(t => t && t.carried).length;
      const backlog = (agenda && Array.isArray(agenda.backlog)) ? agenda.backlog.length : 0;
      // Not-mine vs Won't-fix from the dismiss store (reason field; legacy = not-mine).
      let notMine = 0, wontFix = 0;
      try {
        const dm = loadDismissForDate(date) || {};
        for (const v of Object.values(dm)) {
          if (v && v.reason === 'wontfix') wontFix++; else notMine++;
        }
      } catch (_) { /* best-effort */ }
      // Manual vs auto triage — how many attention-inbox items you dispositioned by
      // hand vs. how many Me.AI's learned rules handled automatically. Powers the
      // Reports "Triage automation" trend (is the auto share climbing, and how much
      // manual review did it save). Counts by the inbox file's own date, consistent
      // with how notMine/wontFix are counted above.
      let autoTriaged = 0, manualTriaged = 0;
      try {
        const inbx = loadInboxForDate(date);
        const RESOLVED = new Set(['later', 'now', 'today', 'dismissed', 'wontfix', 'done']);
        for (const it of (inbx.items || [])) {
          if (!it) continue;
          if (it.auto) autoTriaged++;                                   // handled for you
          else if (RESOLVED.has(String(it.triage || ''))) manualTriaged++; // you decided
        }
      } catch (_) { /* best-effort */ }
      const ta = taskByDate[date] || { launched: 0, done: 0, unblock: 0, comms: 0, agentMs: 0 };
      const agentsLaunched = ta.launched;
      const agentDone = ta.done;
      const agentMin = Math.round(ta.agentMs / 60000);
      const tasksDone = doneByDate[date] || 0;
      // Derived impact metrics (honest aggregates of real signals).
      const delivered = tasksDone + todosDone + agentDone; // things brought to done
      const unblocked = unblockBlocks + ta.unblock;         // others / PRs moved forward
      const responded = commsMin > 0 ? Math.round(commsMin) : 0; // reply/thread time
      const hasActivity = !!agenda || churn.total > 0 || churn.planned > 0 || agentsLaunched > 0 || tasksDone > 0 || notMine > 0 || wontFix > 0;
      out.push({
        date, isToday: date === today, hasAgenda: !!agenda, hasActivity,
        shape: agenda ? churn.shape : '', score: churn.score,
        reschedule: churn.reschedule, slip: churn.slip, add: churn.add, planned: churn.planned,
        blocks: workBlocks.length, focus, meetings,
        focusMin, meetingMin, commsMin, reviewMin, stewardMin, prepMin, adminMin, personalMin,
        todos: todos.length, todosDone, todosCarried, backlog,
        agentsLaunched, agentDone, agentMin, tasksDone, notMine, wontFix,
        autoTriaged, manualTriaged,
        delivered, unblocked, responded,
      });
    }
    // Chronological (oldest → newest) for charting.
    out.reverse();
    const active = out.filter(d => d.hasActivity);
    const shapeCounts = { Calm: 0, Steady: 0, Reactive: 0, Fragmented: 0 };
    let reschedule = 0, slip = 0, add = 0, planned = 0, agentsLaunched = 0, agentDone = 0, agentMin = 0, tasksDone = 0, todosDone = 0, todosCarried = 0, notMine = 0, wontFix = 0, focusDays = 0;
    let focusMin = 0, meetingMin = 0, commsMin = 0, reviewMin = 0, stewardMin = 0, prepMin = 0, adminMin = 0, personalMin = 0;
    let delivered = 0, unblocked = 0;
    let autoTriaged = 0, manualTriaged = 0;
    for (const d of active) {
      if (d.shape && shapeCounts[d.shape] != null) shapeCounts[d.shape]++;
      reschedule += d.reschedule; slip += d.slip; add += d.add; planned += d.planned;
      agentsLaunched += d.agentsLaunched; agentDone += d.agentDone; agentMin += d.agentMin;
      tasksDone += d.tasksDone; todosDone += d.todosDone; todosCarried += d.todosCarried;
      notMine += d.notMine; wontFix += d.wontFix;
      autoTriaged += d.autoTriaged; manualTriaged += d.manualTriaged;
      focusMin += d.focusMin; meetingMin += d.meetingMin; commsMin += d.commsMin;
      reviewMin += d.reviewMin; stewardMin += d.stewardMin; prepMin += d.prepMin; adminMin += d.adminMin;
      personalMin += d.personalMin || 0;
      delivered += d.delivered; unblocked += d.unblocked;
      if (d.shape === 'Calm' || d.shape === 'Steady') focusDays++;
    }
    const workMin = focusMin + meetingMin + commsMin + reviewMin + stewardMin + prepMin + adminMin;
    // Forward-planning coverage — how much of the upcoming work-day horizon the
    // background planner has already laid down (so Reports shows the look-ahead is real).
    const future = { horizon: 0, planned: 0, days: [] };
    try {
      const cfgF = _meAiConfig(settings.getSettings());
      const fdays = _meAiFutureWorkDays(cfgF, ME_AI_FUTURE_DAYS);
      future.horizon = fdays.length;
      future.days = fdays.map(d => {
        const a = loadAgendaForDate(d);
        const isPlanned = !!(a && Array.isArray(a.blocks) && a.blocks.length);
        if (isPlanned) future.planned++;
        return { date: d, planned: isPlanned };
      });
    } catch (_) { /* best-effort */ }
    // End-of-day AI narratives already cached within the window (no LLM here — cheap
    // collation only). Surfaces recent reflections + an aggregate view of the tips the
    // chief-of-staff has been giving, so the Reports page can show "what to improve".
    const eod = { days: [], tips: [], count: 0 };
    try {
      const tipCounts = {};
      for (const d of out) {
        const c = _meAiLoadEodCache(d.date);
        if (!c || !c.narrative) continue;
        eod.count++;
        eod.days.push({ date: d.date, shape: d.shape, summary: c.narrative.summary || '', howItWent: c.narrative.howItWent || '', tips: c.narrative.tips || [] });
        for (const t of (c.narrative.tips || [])) {
          const key = String(t || '').trim();
          if (key) tipCounts[key] = (tipCounts[key] || 0) + 1;
        }
      }
      eod.tips = Object.entries(tipCounts).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([text, n]) => ({ text, count: n }));
    } catch (_) { /* best-effort */ }
    const focusRatio = active.length ? focusDays / active.length : 0;
    // Triage automation roll-up. Each hand-triaged item costs ~40s of read-decide-click;
    // an auto-handled one saves that. autoRate = share of triaged items handled for you.
    const TRIAGE_SAVED_SECS = 40;
    const triageTotal = autoTriaged + manualTriaged;
    const triageAutoRate = triageTotal ? autoTriaged / triageTotal : 0;
    const triageSavedMin = Math.round((autoTriaged * TRIAGE_SAVED_SECS) / 60);
    // A short, honest prose summary of the window — "summarize the findings" (owner).
    const hrs = (m) => Math.round((m / 60) * 10) / 10;
    const findings = [];
    if (active.length) {
      findings.push(`${focusDays} of ${active.length} tracked day${active.length === 1 ? '' : 's'} stayed calm or steady` +
        (focusRatio >= 0.6 ? ' — a mostly focused stretch.' : focusRatio <= 0.34 ? ' — a reactive stretch.' : '.'));
      const churnMoves = reschedule + slip;
      findings.push(`${churnMoves} unplanned schedule move${churnMoves === 1 ? '' : 's'} from the day randomizing, kept separate from ${planned} deliberate planning change${planned === 1 ? '' : 's'}.`);
      if (todosCarried) findings.push(`${todosCarried} todo${todosCarried === 1 ? '' : 's'} carried across days without getting done.`);
      if (agentsLaunched) findings.push(`Me-agents ran ${agentsLaunched} task${agentsLaunched === 1 ? '' : 's'}${agentMin ? ` (~${hrs(agentMin)}h of delegated work)` : ''}.`);
      if (notMine || wontFix) findings.push(`You set aside ${notMine} ask${notMine === 1 ? '' : 's'} as not yours and declined ${wontFix} as won't-fix.`);
      if (triageTotal) findings.push(`${autoTriaged} of ${triageTotal} attention item${triageTotal === 1 ? '' : 's'} auto-handled (${Math.round(triageAutoRate * 100)}%)${triageSavedMin ? `, saving ~${triageSavedMin}m of manual triage` : ''}.`);
    }
    if (future.horizon) findings.push(`${future.planned} of the next ${future.horizon} work day${future.horizon === 1 ? '' : 's'} already pre-planned ahead.`);
    const summary = {
      activeDays: active.length,
      focusDays, focusRatio,
      shapeCounts, reschedule, slip, add, planned,
      agentsLaunched, agentDone, agentMin, tasksDone, todosDone, todosCarried, notMine, wontFix,
      autoTriaged, manualTriaged, triageTotal, triageAutoRate, triageSavedMin,
      focusMin, meetingMin, commsMin, reviewMin, stewardMin, prepMin, adminMin, personalMin, workMin,
      // Impact roll-ups
      delivered, unblocked,
      multipliedMin: agentMin,                                  // agent wall-clock working for you
      protectedMin: focusMin,                                   // deep-work time you held
      respondedMin: commsMin,                                   // reply/thread time
      focusShare: workMin ? focusMin / workMin : 0,             // share of work time in deep focus
      meetingShare: workMin ? meetingMin / workMin : 0,         // share lost to meetings
      future, findings,
    };
    res.json({ ok: true, today, days, series: out, summary, eod });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// GET /api/me-ai/lookahead?days=5 → the next N WORK days (today first if today is a
// work day, then skipping non-work days), each with a light summary from its already
// cached agenda. Read-only + cheap: it never generates (generation is slow), so a day
// with no cached agenda comes back planned:false and the user clicks to plan/view it.
// This is the "see my agenda 5 days out" horizon; the retrospective /reports endpoint
// is where the was-I-distracted / on-track signals live.
app.get('/api/me-ai/lookahead', (req, res) => {
  try {
    const s = settings.getSettings();
    const cfg = _meAiConfig(s);
    const workDays = (cfg.workDays || []);
    const today = _meAiLocalDay();
    let n = Number(req.query.days) || 5;
    n = Math.max(1, Math.min(10, Math.round(n)));
    // Build the next n work-day dates, starting at today when today is a work day.
    const dates = [];
    const todayDow = new Date(today + 'T00:00:00').getDay();
    if (!workDays.length || workDays.includes(todayDow)) dates.push(today);
    let cursor = today;
    while (dates.length < n) {
      const nx = _meAiNextWorkDay(cfg, cursor);
      if (!nx || dates.includes(nx)) break;
      dates.push(nx);
      cursor = nx;
    }
    const minOf = (b) => { try { const a = _hmToMin(b.start), z = _hmToMin(b.end); return (z > a) ? (z - a) : 0; } catch (_) { return 0; } };
    const days = dates.slice(0, n).map(date => {
      const dt = new Date(date + 'T00:00:00');
      const agenda = loadAgendaForDate(date);
      const notWork = !!(agenda && agenda.meta && agenda.meta.notWorkDay);
      const blocks = (agenda && Array.isArray(agenda.blocks)) ? agenda.blocks : [];
      const workBlocks = blocks.filter(b => b && b.type !== 'personal' && b.type !== 'lunch' && b.type !== 'open');
      let focusMin = 0, meetingMin = 0, commsMin = 0, reviewMin = 0, stewardMin = 0;
      for (const b of blocks) {
        if (!b) continue;
        const m = minOf(b);
        if (b.type === 'focus') focusMin += m;
        else if (b.type === 'meeting') meetingMin += m;
        else if (b.type === 'comms') commsMin += m;
        else if (b.type === 'review') reviewMin += m;
        else if (b.type === 'steward') stewardMin += m;
      }
      const todos = (agenda && Array.isArray(agenda.todos)) ? agenda.todos.filter(t => t && t.scope !== 'personal') : [];
      const top = workBlocks.find(b => b.type === 'focus') || workBlocks[0] || null;
      return {
        date, dow: dt.getDay(), isToday: date === today,
        planned: !!agenda && !notWork,
        blocks: workBlocks.length,
        focusMin, meetingMin, commsMin, reviewMin, stewardMin,
        // Planned reactive/interrupt time (meetings + comms + PR reviews) vs deep focus —
        // an early read on how "distractable" the day is shaping up to be.
        distractMin: commsMin + reviewMin + meetingMin,
        topItem: top ? String(top.title || '').slice(0, 90) : '',
        todos: todos.length, todosDone: todos.filter(t => t && t.done).length,
      };
    });
    res.json({ ok: true, today, days });
  } catch (err) { res.status(500).json({ error: err.message }); }
});


app.get('/api/me-ai/inbox', (req, res) => {
  try {
    const date = String(req.query.date || '').slice(0, 10) || _meAiLocalDay();
    const inbox = loadInboxForDate(date);
    // Composite-urgency backfill: items persisted before the composite scorer landed carry
    // the flat collector urgency and no urgencyBase/facets/why, so they'd re-stamp only on a
    // full (slow) gather. Score them here — a cheap, bounded regex pass, no AI — so the client
    // always sees the composite label + tooltip. Display/sorting only; the agenda is untouched.
    let backfilled = 0;
    for (const it of inbox.items) {
      if (it && typeof it.urgencyBase !== 'number') {
        try {
          const u = _meAiUrgencyScore(it);
          it.urgencyBase = u.base;
          it.urgency = u.score;
          it.urgencyFacets = u.facets;
          it.urgencyWhy = u.why;
          backfilled++;
        } catch (_) { /* keep flat urgency on any failure */ }
      }
    }
    if (backfilled) { try { saveInboxForDate(date, inbox); } catch (_) { /* best-effort */ } }
    // Gather-free cross-day heal: demote rows the user already handled on a prior day so they
    // stop showing as NEW the moment the inbox is opened (no wait for the next poll).
    try {
      const h = _meAiHealInboxRows(inbox, date, new Date().toISOString());
      if (h.healed) saveInboxForDate(date, inbox);
    } catch (_) { /* best-effort */ }
    const newCount = inbox.items.filter(i => i.triage === 'new').length;
    res.json({ ok: true, date, items: inbox.items, newCount, polledAt: inbox.polledAt || '' });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/inbox/refresh { date? } → poll M365 now and merge new asks in.
app.post('/api/me-ai/inbox/refresh', async (req, res) => {
  try {
    const date = String((req.body && req.body.date) || '').slice(0, 10) || _meAiLocalDay();
    const s = settings.getSettings();
    const cfg = _meAiConfig(s);
    _meAiLastActive = Date.now();
    const r = await _meAiRefreshInbox(s, cfg, date, { force: true });
    const newCount = r.inbox.items.filter(i => i.triage === 'new').length;
    res.json({ ok: true, date, items: r.inbox.items, newCount, added: r.added, autoHandled: r.autoHandled || 0, consent: r.consent, polledAt: r.inbox.polledAt || '' });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/inbox/reeval { date? } → recompute confidence scores (base-only, no
// AI, instant) for every item and auto-apply any that now clear their tier's threshold.
// Called after a settings/threshold change so the inbox reflects the new gate live.
app.post('/api/me-ai/inbox/reeval', async (req, res) => {
  try {
    const date = String((req.body && req.body.date) || '').slice(0, 10) || _meAiLocalDay();
    const s = settings.getSettings();
    const cfg = _meAiConfig(s);
    const inbox = loadInboxForDate(date);
    const now = new Date().toISOString();
    let autoHandled = 0;
    // Reversibility: if the stricter triage bar was just turned OFF, lift the items that
    // strict (and only strict) had set aside so they flow back into triage. We only touch
    // items strict itself auto-dismissed (autoReason.strict) — manual not-mine / won't-fix
    // and confidence-model auto decisions are left untouched.
    const strict = cfg.strictTriage || { enabled: false };
    let lifted = 0, dmMut = false, dm = null;
    if (!strict.enabled) {
      try { dm = loadDismissForDate(date); } catch (_) { dm = null; }
      for (const it of inbox.items) {
        if (it && it.auto && it.autoReason && it.autoReason.strict && it.triage === 'dismissed') {
          it.triage = 'seen'; it.auto = false; it.autoReason = null; it.triagedAt = now; lifted++;
          if (dm) { const k = _meAiDismissKey(it); if (dm[k] && dm[k].reason === 'strict') { delete dm[k]; dmMut = true; } }
        }
      }
      if (dmMut) { try { saveDismissForDate(date, dm); } catch (_) { /* best-effort */ } }
    }
    for (const it of inbox.items) {
      if (it && typeof it.urgencyBase !== 'number') {
        try {
          const u = _meAiUrgencyScore(it);
          it.urgencyBase = u.base; it.urgency = u.score; it.urgencyFacets = u.facets; it.urgencyWhy = u.why;
        } catch (_) { /* keep flat urgency */ }
      }
      try { if (await _meAiScoreAndMaybeAuto(it, cfg, date, now, { allowAi: false })) autoHandled++; } catch (_) { /* best-effort */ }
    }
    saveInboxForDate(date, inbox);
    const newCount = inbox.items.filter(i => i.triage === 'new').length;
    res.json({ ok: true, date, items: inbox.items, newCount, autoHandled, lifted });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/inbox/triage { date?, id, action } → record a triage decision.
// action: 'seen' (clear the new flag), 'later' (park on rail), 'now' (handling it —
// client launches a comms Me-agent), 'today' (fit into the agenda → re-plan),
// 'dismiss' (not mine → also excluded from the agenda). Returns the updated inbox,
// plus a freshly re-planned agenda when the decision was "today".
app.post('/api/me-ai/inbox/triage', async (req, res) => {
  try {
    const b = req.body || {};
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    const id = String(b.id || '').trim();
    const action = String(b.action || '').trim();
    const ALLOWED = ['seen', 'later', 'now', 'today', 'dismiss', 'wontfix', 'done', 'todo'];
    if (!id || !ALLOWED.includes(action)) return res.status(400).json({ error: 'bad request' });
    const inbox = loadInboxForDate(date);
    const now = new Date().toISOString();
    let it = inbox.items.find(x => x.id === id);
    if (!it) {
      // Terminal / idempotent actions must ALWAYS succeed even if the item isn't in the
      // persisted store (it can be a synthesized reminder-style entry, or the store was
      // re-merged since the client loaded it). Upsert a minimal stub so "Mark as done" /
      // "Remove" never fail with a confusing "Triage failed: not found" toast. Actions
      // that need real signal data to schedule ('today'/'now'/'later') still 404.
      if (action === 'done' || action === 'dismiss' || action === 'wontfix' || action === 'seen' || action === 'todo') {
        it = { id, title: String(b.title || '').trim() || 'Item', link: String(b.link || '').trim() || '', triage: 'seen', firstSeen: now, stub: true };
        inbox.items.push(it);
      } else {
        return res.status(404).json({ error: 'not found' });
      }
    }
    // REQ-9: if the user is overriding a prior AUTO decision, remember which one so we
    // can penalize the rule (learn the exception) and lift any auto dismissal.
    const wasAuto = !!it.auto;
    const overridden = (wasAuto && it.autoReason && it.autoReason.action) ? it.autoReason.action : null;
    if (action === 'dismiss' || action === 'wontfix') {
      // Both remove the item from the agenda. 'dismiss' = "not mine" (someone else
      // owns it); 'wontfix' = "mine, but I'm consciously declining to act". We keep
      // the distinction on the item (triage) and in the dismiss store (reason) so
      // the Reports page can tell an ignored ask from a deliberate no-op.
      try {
        const dm = loadDismissForDate(date);
        dm[_meAiDismissKey(it)] = { title: it.title, note: it.note || '', at: now, reason: action, manual: true };
        saveDismissForDate(date, dm);
      } catch (_) { /* best-effort */ }
      it.triage = action === 'wontfix' ? 'wontfix' : 'dismissed';
    } else if (action === 'done') {
      // "Mark as done" = the ask has already been handled (I replied / resolved it).
      // Recorded POSITIVELY — NOT as a dismissal/wontfix — so Reports count it as
      // completed, not declined. It drops off the inbox like any resolved item.
      it.triage = 'done';
      it.doneAt = now;
    } else if (action === 'todo') {
      // "Make a to-do" = I own this and want to track it on my to-do list rather than
      // schedule it today. It leaves the attention inbox AND the backlog (tracked via the
      // to-do dock instead), but a curation record keeps it in the dedupe index so a
      // reworded re-arrival folds in as "already tracked" instead of re-surfacing.
      it.triage = 'todo';
      it.todoAt = now;
      try {
        _meAiSetCuration({
          key: _meAiBacklogKey(it), title: it.title, link: it.link || it.prLink || '',
          kind: _meAiBacklogKind(it), source: it.source || 'inbox', todo: true,
        });
      } catch (_) { /* best-effort */ }
    } else if (action === 'seen') {
      if (it.triage === 'new') it.triage = 'seen';
    } else {
      it.triage = action; // 'later' | 'now' | 'today'
    }
    // If the user moved an auto-dismissed item back into play, lift the auto dismissal.
    if (overridden && (overridden === 'dismiss' || overridden === 'wontfix') && action !== 'dismiss' && action !== 'wontfix') {
      try { const dm = loadDismissForDate(date); delete dm[_meAiDismissKey(it)]; saveDismissForDate(date, dm); } catch (_) { /* best-effort */ }
    }
    it.auto = false; // now an explicit user decision
    it.triagedAt = now;
    saveInboxForDate(date, inbox);
    // REQ-9: learn from the explicit triage decision. 'seen' just clears the flag;
    // 'done' is a situational completion (already replied) and 'todo' is a personal
    // tracking choice, not a routing preference — none feed the learned routing model.
    if (action !== 'seen' && action !== 'done' && action !== 'todo') {
      try { _meAiRecordTriage(it, action, { corrective: overridden }); } catch (_) { /* best-effort */ }
    }
    // Phase 6 Layer-1: a manual dismiss/wontfix seeds a durable topic so the same subject
    // stops resurfacing across title variants + days (one-item topic). But an in-group
    // "Triage on its own" pick (scope:'item') is EXPLICITLY about that single member, not
    // the cluster — minting a title-token topic there would auto-suppress the sibling PR
    // items on the next merge and collapse the whole group. Skip the topic in that case;
    // the per-item decision below still carries this exact identity forward. Cluster-wide
    // topic learning stays on the "All together" group action (triage-batch route).
    const inGroupSingle = String(b.scope || '') === 'item';
    if (!inGroupSingle && (action === 'dismiss' || action === 'wontfix')) {
      try { _meAiRecordTopic(it, action, { label: it.title }); } catch (_) { /* best-effort */ }
    }
    // Layer-2: record the durable per-item decision (later/dismiss/wontfix persist; a
    // re-engagement now/today/done/seen clears it) so this exact identity stays decided
    // across title drift + day boundaries — or stops re-parking once you act on it.
    try { _meAiRecordDecision(it, action); } catch (_) { /* best-effort */ }
    let agenda = null;
    if (action === 'today') {
      // Fit-into-today → re-plan immediately (reuse warm cache) so it lands now.
      try {
        const prev = loadAgendaForDate(date);
        const todos = (prev && Array.isArray(prev.todos)) ? prev.todos.map(t => ({ title: t.title, scope: t.scope })) : [];
        agenda = await generateMeAiAgenda({ date, todos, reindex: false, cause: 'triage' });
      } catch (_) { /* best-effort */ }
    }
    const newCount = inbox.items.filter(i => i.triage === 'new').length;
    res.json({ ok: true, date, items: inbox.items, newCount, agenda });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// Item 3: apply a triage decision to one item IN-PLACE (mutates it + dismiss store +
// learned model) without saving/replanning — shared by the single + batch routes.
function _meAiTriageItemInPlace(date, it, action, now, opts = {}) {
  const wasAuto = !!it.auto;
  const overridden = (wasAuto && it.autoReason && it.autoReason.action) ? it.autoReason.action : null;
  if (action === 'dismiss' || action === 'wontfix') {
    try {
      const dm = loadDismissForDate(date);
      dm[_meAiDismissKey(it)] = { title: it.title, note: it.note || '', at: now, reason: action, manual: true };
      saveDismissForDate(date, dm);
    } catch (_) { /* best-effort */ }
    it.triage = action === 'wontfix' ? 'wontfix' : 'dismissed';
  } else if (action === 'done') {
    it.triage = 'done'; it.doneAt = now;
  } else if (action === 'todo') {
    it.triage = 'todo'; it.todoAt = now;
    try {
      _meAiSetCuration({
        key: _meAiBacklogKey(it), title: it.title, link: it.link || it.prLink || '',
        kind: _meAiBacklogKind(it), source: it.source || 'inbox', todo: true,
      });
    } catch (_) { /* best-effort */ }
  } else if (action === 'seen') {
    if (it.triage === 'new') it.triage = 'seen';
  } else {
    it.triage = action; // 'later' | 'now' | 'today'
  }
  if (overridden && (overridden === 'dismiss' || overridden === 'wontfix') && action !== 'dismiss' && action !== 'wontfix') {
    try { const dm = loadDismissForDate(date); delete dm[_meAiDismissKey(it)]; saveDismissForDate(date, dm); } catch (_) { /* best-effort */ }
  }
  it.auto = false;
  it.triagedAt = now;
  if (action !== 'seen' && action !== 'done' && action !== 'todo') {
    try { _meAiRecordTriage(it, action, { corrective: overridden }); } catch (_) { /* best-effort */ }
  }
  // Phase 6 Layer-1: seed a durable topic on a suppressive triage. The batch route passes
  // skipTopic and records ONE group topic across all members instead (broader fingerprint).
  if (!opts.skipTopic && (action === 'dismiss' || action === 'wontfix')) {
    try { _meAiRecordTopic(it, action, { label: it.title }); } catch (_) { /* best-effort */ }
  }
  // Layer-2: record the durable per-item decision for THIS identity (also covers the batch
  // route, which calls this per member). later/dismiss/wontfix persist; a re-engagement
  // (now/today/done/seen) clears it so the item can surface again once you act on it.
  try { _meAiRecordDecision(it, action); } catch (_) { /* best-effort */ }
}

// POST /api/me-ai/inbox/group { date? } → AI-group the still-actionable inbox items so
// related ones can be triaged together. Read-only (no mutation); returns [{id,label,
// reason,ids,suggested}]. Bounded AI refine with a deterministic fallback.
app.post('/api/me-ai/inbox/group', async (req, res) => {
  try {
    const b = req.body || {};
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    const inbox = loadInboxForDate(date);
    const groups = await _meAiGroupInbox(inbox.items, { allowAi: b.allowAi !== false });
    // Ask 1: persist the computed clusters so a later arrival can inherit a resolved member's
    // triage decision without spending a fresh model call (see _meAiAiClusterMatch).
    try { _meAiRecordAiGroups(date, groups, inbox.items); } catch (_) { /* best-effort */ }
    res.json({ ok: true, date, groups });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/inbox/triage-batch { date?, ids[], action } → apply one triage action
// to a group of items at once. Learns from each. Re-plans once if action is 'today'.
app.post('/api/me-ai/inbox/triage-batch', async (req, res) => {
  try {
    const b = req.body || {};
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    const ids = Array.from(new Set((b.ids || []).map(x => String(x).trim()).filter(Boolean)));
    const action = String(b.action || '').trim();
    const ALLOWED = ['seen', 'later', 'now', 'today', 'dismiss', 'wontfix', 'done', 'todo'];
    if (!ids.length || !ALLOWED.includes(action)) return res.status(400).json({ error: 'bad request' });
    const inbox = loadInboxForDate(date);
    const now = new Date().toISOString();
    let applied = 0;
    const triaged = [];
    for (const id of ids) {
      const it = inbox.items.find(x => x.id === id);
      if (!it) continue;
      _meAiTriageItemInPlace(date, it, action, now, { skipTopic: true });
      triaged.push(it);
      applied++;
    }
    // Phase 6 Layer-1: THE fix for "I dismissed the group and it came back". Record ONE
    // durable topic spanning the whole cluster's vocabulary + channels, so any later
    // same-topic arrival (any title variant, any day, email OR Teams) is auto-suppressed.
    if ((action === 'dismiss' || action === 'wontfix') && triaged.length) {
      try { _meAiRecordTopic(triaged, action, { group: true }); } catch (_) { /* best-effort */ }
    }
    saveInboxForDate(date, inbox);
    let agenda = null;
    if (action === 'today' && applied) {
      try {
        const prev = loadAgendaForDate(date);
        const todos = (prev && Array.isArray(prev.todos)) ? prev.todos.map(t => ({ title: t.title, scope: t.scope })) : [];
        agenda = await generateMeAiAgenda({ date, todos, reindex: false, cause: 'triage' });
      } catch (_) { /* best-effort */ }
    }
    const newCount = inbox.items.filter(i => i.triage === 'new').length;
    res.json({ ok: true, date, items: inbox.items, newCount, applied, agenda });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/inbox/undo-auto { date?, id } → undo a REQ-9 auto-handled decision.
// Lifts any auto dismissal, penalizes the learned rule so it stops auto-applying, and
// resets the item to 'seen' so the user can triage it themselves.
app.post('/api/me-ai/inbox/undo-auto', async (req, res) => {
  try {
    const b = req.body || {};
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    const id = String(b.id || '').trim();
    if (!id) return res.status(400).json({ error: 'bad request' });
    const inbox = loadInboxForDate(date);
    const it = inbox.items.find(x => x.id === id);
    if (!it) return res.status(404).json({ error: 'not found' });
    const prev = (it.autoReason && it.autoReason.action) ? it.autoReason.action : null;
    if (prev === 'dismiss' || prev === 'wontfix') {
      try { const dm = loadDismissForDate(date); delete dm[_meAiDismissKey(it)]; saveDismissForDate(date, dm); } catch (_) { /* best-effort */ }
    }
    if (prev) { try { _meAiPenalizeTriage(it, prev); } catch (_) { /* best-effort */ } }
    // Phase 6 Layer-1: if this auto-decision came from a durable topic, weaken/forget it so
    // a mistakenly-learned topic self-corrects instead of nagging in reverse.
    if (it.topicMem && it.topicMem.id) { try { _meAiForgetTopic(it.topicMem.id); } catch (_) { /* best-effort */ } }
    it.topicMem = null;
    it.triage = it.triage === 'new' ? 'new' : 'seen';
    it.auto = false; it.autoReason = null; it.triagedAt = new Date().toISOString();
    saveInboxForDate(date, inbox);
    const newCount = inbox.items.filter(i => i.triage === 'new').length;
    res.json({ ok: true, date, items: inbox.items, newCount });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// ── Backlog: the curated future-work queue ───────────────────────────────────
// Classify a candidate into the mockup's four lanes (action / review / comms / dev)
// from its type/kind/source so the client can group + colour it.
function _meAiBacklogKind(c) {
  const t = String((c && (c.type || c.kind)) || '').toLowerCase();
  const src = String((c && c.source) || '').toLowerCase();
  if (t.includes('meeting-action') || t === 'action') return 'action';
  if (t.includes('review') || t === 'pr' || src === 'github' || src === 'ado' || src === 'codeflow') return 'review';
  if (t === 'comms' || src === 'meeting' || src === 'm365' || src === 'email' || src === 'teams') return 'comms';
  if (t === 'focus' || t === 'dev' || t === 'implement' || t === 'work') return 'dev';
  return 'action';
}
// --- #5 Backlog auto-resolve: drop items whose underlying work is already done ------
// A backlog ask stops being relevant once its dev card's PR merges (or the linked
// work item / PR reaches a terminal state). We infer completion from OUR OWN system —
// the global dev-store cards and their stored PR / work-item status — and auto-mark
// such backlog items done (recording WHY, so it's transparent + auditable + undoable),
// so finished work stops nagging as noise. Conservative: only unambiguous
// merged / closed / done states auto-resolve; anything uncertain is left alone.
const _ME_AI_WI_DONE = new Set(['closed', 'done', 'resolved', 'completed', 'removed', 'merged']);

function _meAiNormLink(u) {
  let s = String(u || '').trim().toLowerCase();
  if (!s) return '';
  const q = s.search(/[?#]/); if (q >= 0) s = s.slice(0, q);
  return s.replace(/\/+$/, '');
}
// Pull a stable "<host-ish>|pr|<n>" / "…|wi|<n>" identity out of a PR / work-item URL
// so a signal link and a dev card link for the SAME entity match even when the exact
// URL shape differs (e.g. _workitems/edit/N vs _apis/wit/workItems/N). Best-effort;
// returns '' when it can't confidently identify the entity. Org/owner tokens are kept
// in the key so ids don't collide across projects.
function _meAiLinkId(u) {
  const s = _meAiNormLink(u);
  if (!s) return '';
  let m;
  if ((m = s.match(/github\.com\/([^/]+\/[^/]+)\/pull\/(\d+)/))) return `gh:${m[1]}|pr|${m[2]}`;
  if ((m = s.match(/github\.com\/([^/]+\/[^/]+)\/issues\/(\d+)/))) return `gh:${m[1]}|wi|${m[2]}`;
  if ((m = s.match(/dev\.azure\.com\/([^/]+).*?\/pullrequests?\/(\d+)/))) return `azdo:${m[1]}|pr|${m[2]}`;
  if ((m = s.match(/([^/.]+)\.visualstudio\.com.*?\/pullrequests?\/(\d+)/))) return `azdo:${m[1]}|pr|${m[2]}`;
  if ((m = s.match(/\/pullrequests?\/(\d+)/))) return `azdo|pr|${m[1]}`;
  if ((m = s.match(/dev\.azure\.com\/([^/]+).*?_workitems\/edit\/(\d+)/))) return `azdo:${m[1]}|wi|${m[2]}`;
  if ((m = s.match(/([^/.]+)\.visualstudio\.com.*?_workitems\/edit\/(\d+)/))) return `azdo:${m[1]}|wi|${m[2]}`;
  if ((m = s.match(/_workitems\/edit\/(\d+)/)) || (m = s.match(/\/wit\/workitems\/(\d+)/))) return `azdo|wi|${m[1]}`;
  return '';
}
// Does a dev card show the work is finished? Reads only STORED provider status
// (cheap, no network). PR status is normalized to active|completed|abandoned by both
// forges (github: open→active, merged_at→completed, closed-unmerged→abandoned).
function _meAiDevCardDone(d) {
  if (!d) return null;
  const prs = [];
  if (d.pr) prs.push(d.pr);
  for (const r of (Array.isArray(d.repos) ? d.repos : [])) { if (r && r.pr) prs.push(r.pr); }
  for (const pr of prs) {
    const st = String(pr.status || '').toLowerCase();
    if (st === 'completed' || st === 'merged') return 'its pull request merged';
    if (st === 'abandoned') return 'its pull request was closed';
  }
  const wi = d.workItem;
  const ws = String((wi && wi.state) || '').toLowerCase();
  if (ws && _ME_AI_WI_DONE.has(ws)) return `its work item is ${wi.state}`;
  return null;
}
// Index every dev card's identity links (work item + PR urls, direct + id-based) so a
// backlog item can be matched to the card that tracks it, with the card's completion
// reason attached. Scans ALL cards INCLUDING archived — a finished dev card is usually
// archived, and that's exactly the case we want to resolve.
function _meAiDevCardIndex() {
  const byLink = new Map();
  const byId = new Map();
  let cards = [];
  try { cards = devStore.all() || []; } catch (_) { cards = []; }
  for (const d of cards) {
    const entry = { done: _meAiDevCardDone(d), title: d.title || '', card: d };
    const links = [];
    if (d.workItem && d.workItem.url) links.push(d.workItem.url);
    if (d.link) links.push(d.link);
    if (d.pr && d.pr.url) links.push(d.pr.url);
    for (const r of (Array.isArray(d.repos) ? d.repos : [])) { if (r && r.pr && r.pr.url) links.push(r.pr.url); }
    for (const u of links) {
      const n = _meAiNormLink(u); if (n && !byLink.has(n)) byLink.set(n, entry);
      const id = _meAiLinkId(u); if (id && !byId.has(id)) byId.set(id, entry);
    }
  }
  return { byLink, byId };
}
// Find the dev-card index entry that tracks a given backlog item (by link, then id).
function _meAiMatchDevCard(idx, link) {
  if (!idx || !link) return null;
  const n = _meAiNormLink(link);
  let hit = (n && idx.byLink.get(n)) || null;
  if (!hit) { const id = _meAiLinkId(link); if (id) hit = idx.byId.get(id) || null; }
  return hit;
}
// Auto-mark backlog items done when OUR dev cards show the work is finished. Writes are
// idempotent (curation done-flag) and mirror the manual done path exactly (durable
// decision so a re-derived signal doesn't re-nag + Diary gap-fill), so the audit trail
// is identical. Returns { items:<remaining>, autoResolved:[{key,title,reason}] } — the
// resolved items land in Done / history (never silently vanish).
function _meAiBacklogAutoResolve(date, items) {
  const list = Array.isArray(items) ? items : _meAiAssembleBacklog(date);
  let idx;
  try { idx = _meAiDevCardIndex(); } catch (_) { return { items: list, autoResolved: [] }; }
  const autoResolved = [];
  const remaining = [];
  for (const it of list) {
    const hit = _meAiMatchDevCard(idx, it && it.link);
    const reason = (hit && hit.done) || null;
    if (reason) {
      try {
        const note = `Auto-resolved: ${reason}.`;
        const rec = _meAiSetCuration({ key: it.key, title: it.title, done: true, doneNote: note });
        try { _meAiRecordDecisionByKey(it.key, 'done', it.title); } catch (_) {}
        try { _meAiBacklogDoneToDiary(rec || { title: it.title, doneNote: note }, it.key); } catch (_) {}
      } catch (_) {}
      autoResolved.push({ key: it.key, title: it.title, reason });
    } else {
      remaining.push(it);
    }
  }
  return { items: remaining, autoResolved };
}
// LIVE variant: before resolving, re-pull PR / work-item status from the provider for the
// dev cards a current backlog item points at (and that aren't already terminal), so an
// explicit Refresh reflects the authoritative latest status. Bounded + best-effort so a
// slow/unreachable API never blocks the refresh.
async function _meAiBacklogRefreshDevStatus(items) {
  let cards = [];
  try { cards = devStore.all() || []; } catch (_) { return; }
  const links = new Set(), ids = new Set();
  for (const it of (items || [])) {
    if (!it || !it.link) continue;
    const n = _meAiNormLink(it.link); if (n) links.add(n);
    const id = _meAiLinkId(it.link); if (id) ids.add(id);
  }
  const matched = cards.filter(d => {
    if (_meAiDevCardDone(d)) return false; // already terminal — nothing to refresh
    const us = [];
    if (d.workItem && d.workItem.url) us.push(d.workItem.url);
    if (d.link) us.push(d.link);
    if (d.pr && d.pr.url) us.push(d.pr.url);
    for (const r of (Array.isArray(d.repos) ? d.repos : [])) { if (r && r.pr && r.pr.url) us.push(r.pr.url); }
    for (const u of us) { if (links.has(_meAiNormLink(u))) return true; const id = _meAiLinkId(u); if (id && ids.has(id)) return true; }
    return false;
  }).slice(0, 12);
  // Resilience: a slow/unreachable provider (gh/az shells out per card) must never hang
  // the refresh. Cap each call (~7s) and the whole pass (~25s budget); return with
  // whatever landed. Best-effort throughout — a timeout yields null, not a throw.
  const deadline = Date.now() + 25000;
  const withTimeout = (p, ms) => Promise.race([
    Promise.resolve(p).catch(() => null),
    new Promise(r => setTimeout(() => r(null), ms)),
  ]);
  for (const d of matched) {
    if (Date.now() > deadline) break;
    const patch = {};
    try { if (d.prId && d.org && d.repo && (d.provider === 'github' || d.project)) { const pr = await withTimeout(_devPullRequest(_devDesc(d), d.prId), 7000); if (pr) patch.pr = pr; } } catch (_) {}
    if (Date.now() > deadline) { if (Object.keys(patch).length) { try { devStore.patch(d.id, patch); } catch (_) {} } break; }
    try { if (d.workItemId && d.org && (d.provider === 'github' ? d.repo : d.project)) { const wi = await withTimeout(_devWorkItem(_devDesc(d), d.workItemId), 7000); if (wi) patch.workItem = wi; } } catch (_) {}
    if (Object.keys(patch).length) { try { devStore.patch(d.id, patch); } catch (_) {} }
  }
}
// Assemble the durable backlog candidate set for a date from every future-work source —
// the built agenda's spillover backlog, inbox items the user parked ('later') or hasn't
// resolved, and prior-day deferrals ("didn't fit today") rolled forward — then overlay
// the user's curation so the view reflects week/aside/urgency/group/workItem decisions.
function _meAiAssembleBacklog(date) {
  const curation = loadBacklogCuration();
  const curItems = (curation && curation.items) || {};
  const byKey = new Map();
  const add = (raw, origin) => {
    const key = _meAiBacklogKey(raw);
    if (!key) return;
    const title = String((raw && (raw.title || raw.label)) || '').trim();
    if (!title) return;
    if (byKey.has(key)) { // merge sources; keep the strongest urgency
      const ex = byKey.get(key);
      ex.urgency = Math.max(Number(ex.urgency) || 0, Number(raw.urgency) || 0);
      if (!ex.sources.includes(origin)) ex.sources.push(origin);
      if (!ex.detail && raw.detail) ex.detail = String(raw.detail).slice(0, 400);
      if (!ex.recordingUrl && raw.recordingUrl) ex.recordingUrl = String(raw.recordingUrl).slice(0, 600);
      if (!ex.meetingLink && raw.meetingLink) ex.meetingLink = String(raw.meetingLink).slice(0, 600);
      return;
    }
    byKey.set(key, {
      key, title: title.slice(0, 240),
      kind: _meAiBacklogKind(raw),
      source: String((raw && raw.source) || origin).slice(0, 40),
      link: String((raw && (raw.link || raw.prLink)) || '').slice(0, 600),
      recordingUrl: String((raw && raw.recordingUrl) || '').slice(0, 600),
      meetingLink: String((raw && raw.meetingLink) || '').slice(0, 600),
      detail: String((raw && raw.detail) || '').slice(0, 400),
      urgency: Math.max(0, Math.min(5, Number(raw && raw.urgency) || 0)),
      repo: String((raw && raw.meta && raw.meta.repo) || '').slice(0, 80),
      when: String((raw && (raw.ts || raw.at || raw.fromLabel)) || '').slice(0, 40),
      sources: [origin],
    });
  };
  // 1. Agenda spillover backlog (didn't fit / bumped).
  try { const a = loadAgendaForDate(date); if (a && Array.isArray(a.backlog)) a.backlog.forEach(b => add(b, 'agenda')); } catch (_) {}
  // 2. Inbox items the user parked or hasn't resolved (skip dismissed / done / wontfix).
  try {
    const inbox = loadInboxForDate(date);
    for (const it of (inbox.items || [])) {
      const tr = String(it.triage || '');
      if (tr === 'dismissed' || tr === 'done' || tr === 'wontfix' || tr === 'now' || tr === 'today' || tr === 'todo') continue;
      add(it, 'inbox');
    }
  } catch (_) {}
  // 3. Deferrals rolled forward onto this day ("didn't fit today").
  try { loadMeAiDeferrals(date).forEach(d => add({ ...d, urgency: d.urgency || 3 }, 'deferral')); } catch (_) {}
  // Overlay curation onto each candidate + surface set-aside items (they stay visible
  // in the Backlog even though the planner drops them).
  const out = [];
  for (const c of byKey.values()) {
    const cur = curItems[c.key] || {};
    if (cur.done || cur.todo || cur.duplicateOf) continue; // completed / pulled into to-dos / folded → hidden here
    // Purge PR/review items with no actionable link — you can't open or review a PR
    // without a URL, so a linkless entry is noise. They resurface automatically once a
    // fresh gather produces a real PR URL. Preserve anything the user has explicitly
    // curated (aside / grouped / promoted / annotated) so no decision silently vanishes.
    if (c.kind === 'review') {
      const curated = !!(cur.aside || cur.group || cur.workItem || cur.week || cur.note ||
        (cur.urgencyOverride != null) || (Array.isArray(cur.duplicates) && cur.duplicates.length));
      const actionable = /^https?:\/\//i.test(String(c.link || '').trim());
      if (!actionable && !curated) continue;
    }
    out.push({
      ...c,
      week: !!cur.week,
      aside: !!cur.aside,
      group: cur.group || null,
      urgency: (cur.urgencyOverride != null && Number.isFinite(Number(cur.urgencyOverride))) ? Number(cur.urgencyOverride) : c.urgency,
      urgencyOverride: (cur.urgencyOverride != null) ? Number(cur.urgencyOverride) : null,
      workItem: cur.workItem || null,
      note: cur.note || '',
      done: false,
      duplicates: Array.isArray(cur.duplicates) ? cur.duplicates : [],
      duplicateCount: Array.isArray(cur.duplicates) ? cur.duplicates.length : 0,
      notDuplicate: Array.isArray(cur.notDuplicate) ? cur.notDuplicate : [],
    });
  }
  // Also surface curated items that are ONLY known via curation (e.g. a set-aside item
  // whose source has since gone quiet, or a primary that has absorbed duplicates) so a
  // decision never silently vanishes.
  for (const [k, cur] of Object.entries(curItems)) {
    if (byKey.has(k)) continue;
    if (!cur || cur.done || cur.todo || cur.duplicateOf) continue;
    const hasDups = Array.isArray(cur.duplicates) && cur.duplicates.length;
    if (!cur.aside && !cur.group && !cur.workItem && !cur.week && cur.urgencyOverride == null && !hasDups) continue;
    out.push({
      key: k, title: String(cur.title || k).slice(0, 240), kind: 'action',
      source: 'curation', link: cur.link || '', recordingUrl: '', meetingLink: '', detail: '', repo: '', when: '',
      sources: ['curation'], week: !!cur.week, aside: !!cur.aside, group: cur.group || null,
      urgency: (cur.urgencyOverride != null) ? Number(cur.urgencyOverride) : 3,
      urgencyOverride: (cur.urgencyOverride != null) ? Number(cur.urgencyOverride) : null,
      workItem: cur.workItem || null, note: cur.note || '',
      done: false,
      duplicates: Array.isArray(cur.duplicates) ? cur.duplicates : [],
      duplicateCount: hasDups ? cur.duplicates.length : 0,
      notDuplicate: Array.isArray(cur.notDuplicate) ? cur.notDuplicate : [],
    });
  }
  out.sort((a, b) => (Number(b.urgency) || 0) - (Number(a.urgency) || 0) || String(a.title).localeCompare(String(b.title)));
  return out;
}

// GET /api/me-ai/backlog?date= → the assembled + curated future-work queue.
app.get('/api/me-ai/backlog', (req, res) => {
  try {
    const date = String(req.query.date || '').slice(0, 10) || _meAiLocalDay();
    const assembled = _meAiAssembleBacklog(date);
    // Cheap LOCAL auto-resolve: drop items whose dev card already shows the work is done
    // (reads only stored PR / work-item status, no network). Resolved items move to Done.
    const ar = _meAiBacklogAutoResolve(date, assembled);
    const items = ar.items;
    const groups = {};
    for (const it of items) { if (it.group) (groups[it.group] = groups[it.group] || []).push(it.key); }
    res.json({ ok: true, date, items, count: items.length, groups, autoResolved: ar.autoResolved });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/backlog/item { key, title?, link?, kind?, source?, week?, aside?, urgency?, group?, note? }
// Upsert one curation decision (week / set-aside / urgency override / grouping / note).
app.post('/api/me-ai/backlog/item', (req, res) => {
  try {
    const b = req.body || {};
    const key = String(b.key || '').trim();
    if (!key) return res.status(400).json({ error: 'key required' });
    const patch = { key };
    if (b.title != null) patch.title = String(b.title).slice(0, 240);
    if (b.link != null) patch.link = String(b.link).slice(0, 600);
    if (b.kind != null) patch.kind = String(b.kind).slice(0, 20);
    if (b.source != null) patch.source = String(b.source).slice(0, 40);
    if (b.note != null) patch.note = String(b.note).slice(0, 400);
    if ('week' in b) patch.week = !!b.week;
    if ('aside' in b) patch.aside = !!b.aside;
    if ('group' in b) patch.group = (b.group == null || b.group === '') ? null : String(b.group).slice(0, 120);
    if ('urgency' in b) patch.urgencyOverride = (b.urgency == null || b.urgency === '') ? null : Number(b.urgency);
    if ('done' in b) patch.done = !!b.done;
    if ('todo' in b) patch.todo = !!b.todo;
    if (b.doneNote != null) patch.doneNote = String(b.doneNote).slice(0, 400);
    const rec = _meAiSetCuration(patch);
    if (!rec) return res.status(400).json({ error: 'bad request' });
    // Mark-as-done side effects: remember it durably (so a re-derived signal doesn't re-nag)
    // and gap-fill the Diary with the completion. Un-done clears the durable decision.
    if ('done' in b) {
      const title = rec.title || key;
      if (rec.done) {
        try { _meAiRecordDecisionByKey(key, 'done', title); } catch (_) {}
        try { _meAiBacklogDoneToDiary(rec, key); } catch (_) {}
      } else {
        try { _meAiRecordDecisionByKey(key, 'seen', title); } catch (_) {}
      }
    }
    // Make-a-to-do side effects: record a durable 'todo' decision so a re-derived signal folds
    // into the tracked to-do (stays in the dedupe index) instead of re-surfacing on the backlog.
    // Clearing it restores the item.
    if ('todo' in b) {
      const title = rec.title || key;
      try { _meAiRecordDecisionByKey(key, rec.todo ? 'todo' : 'seen', title); } catch (_) {}
    }
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    res.json({ ok: true, item: rec, items: _meAiAssembleBacklog(date) });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/backlog/group { keys:[], name } → collapse several items into ONE unit
// of work the planner schedules as a single block. Empty name / <1 key ungroups them.
app.post('/api/me-ai/backlog/group', (req, res) => {
  try {
    const b = req.body || {};
    const keys = Array.isArray(b.keys) ? b.keys.map(k => String(k || '').trim()).filter(Boolean) : [];
    const name = String(b.name || '').trim().slice(0, 120) || null;
    if (!keys.length) return res.status(400).json({ error: 'keys required' });
    for (const key of keys) _meAiSetCuration({ key, group: name });
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    res.json({ ok: true, items: _meAiAssembleBacklog(date) });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/backlog/merge { primary, keys:[], date } → manually fold one or more backlog
// items onto a primary as duplicates (first-selected item is the primary if `primary` omitted).
app.post('/api/me-ai/backlog/merge', (req, res) => {
  try {
    const b = req.body || {};
    let keys = Array.isArray(b.keys) ? b.keys.map(k => String(k || '').trim()).filter(Boolean) : [];
    let primary = String(b.primary || '').trim();
    if (!primary && keys.length) { primary = keys[0]; }
    keys = keys.filter(k => k !== primary);
    if (!primary || !keys.length) return res.status(400).json({ error: 'primary + keys required' });
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    // Recover each arrival's display fields from the assembled set (pre-fold) so the stored
    // duplicate entry keeps the original title/source/link.
    const assembled = _meAiAssembleBacklog(date);
    const byKey = new Map(assembled.map(it => [it.key, it]));
    for (const k of keys) {
      const src = byKey.get(k) || { title: k };
      _meAiFoldBacklogDuplicate(primary, src, k, false);
    }
    res.json({ ok: true, items: _meAiAssembleBacklog(date) });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/backlog/unmerge { primary, key, date } → "this one was NOT a duplicate".
// Splits a folded item back out: removes it from the primary's duplicates, records it in the
// primary's notDuplicate guard (blocks future auto-merge), and restores it as a standalone item.
app.post('/api/me-ai/backlog/unmerge', (req, res) => {
  try {
    const b = req.body || {};
    const primary = String(b.primary || '').trim();
    const key = String(b.key || '').trim();
    if (!primary || !key) return res.status(400).json({ error: 'primary + key required' });
    const store = loadBacklogCuration();
    const prim = store.items[primary];
    if (prim) {
      const dups = (Array.isArray(prim.duplicates) ? prim.duplicates : []).filter(d => d && d.key !== key);
      const nd = Array.from(new Set([...(prim.notDuplicate || []), key]));
      _meAiSetCuration({ key: primary, duplicates: dups, notDuplicate: nd });
    }
    // Restore the split-out item to standalone (clear its duplicateOf pointer).
    _meAiSetCuration({ key, duplicateOf: null });
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    res.json({ ok: true, items: _meAiAssembleBacklog(date) });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// GET /api/me-ai/backlog/history?date=&limit= → completed backlog items (done), newest first.
app.get('/api/me-ai/backlog/history', (req, res) => {
  try {
    const limit = Math.max(1, Math.min(500, Number(req.query.limit) || 100));
    const store = loadBacklogCuration();
    const items = Object.entries((store && store.items) || {})
      .filter(([, cur]) => cur && cur.done)
      .map(([k, cur]) => ({
        key: k, title: String(cur.title || k).slice(0, 240), doneAt: cur.doneAt || cur.updatedAt || '',
        doneNote: cur.doneNote || '', kind: cur.kind || _meAiBacklogKind(cur), source: cur.source || '',
        link: cur.link || '', workItem: cur.workItem || null,
        duplicateCount: Array.isArray(cur.duplicates) ? cur.duplicates.length : 0,
      }))
      .sort((a, b) => String(b.doneAt).localeCompare(String(a.doneAt)))
      .slice(0, limit);
    res.json({ ok: true, items, count: items.length });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// ── Silenced / parked items (durable triage decisions) ───────────────────────
// The durable decision memory (triage-decisions.json) is what keeps a dismissed /
// done / won't-fix / deferred item from resurfacing across days. The user had no way
// to SEE what's been silenced or to purge stale ones (e.g. a long-addressed "follow up
// with Alex" that kept re-parking from forward-copied inbox fixtures). These three
// routes expose that store: view it, un-silence one (Restore), or purge it from the
// data stores entirely (decision + every inbox snapshot copy) for the extreme case.
const ME_AI_PARK_TRIAGE = { dismissed: 'Dismissed', wontfix: "Won't fix", done: 'Done', later: 'Deferred', todo: 'On my list' };
// Count how many inbox snapshot files carry an item whose stable key matches `key`.
function _meAiParkedOccurrences(key) {
  let n = 0;
  try {
    if (!fs.existsSync(ME_AI_INBOX_DIR)) return 0;
    for (const f of fs.readdirSync(ME_AI_INBOX_DIR)) {
      if (!f.endsWith('.json')) continue;
      try {
        const v = JSON.parse(fs.readFileSync(path.join(ME_AI_INBOX_DIR, f), 'utf-8'));
        const items = (v && Array.isArray(v.items)) ? v.items : [];
        if (items.some(it => _meAiStableKey(it) === key)) n++;
      } catch (_) { /* skip corrupt file */ }
    }
  } catch (_) { /* best-effort */ }
  return n;
}
// Strip every inbox item whose stable key matches one of `keys` from ALL snapshot files.
// Returns { files, items } removed. This is the "purge from data stores" half — after it,
// the item leaves no trace and can only reappear if the source genuinely surfaces it anew.
function _meAiPurgeInboxItems(keys) {
  const set = new Set(keys.filter(Boolean));
  let files = 0, items = 0;
  try {
    if (!set.size || !fs.existsSync(ME_AI_INBOX_DIR)) return { files, items };
    for (const f of fs.readdirSync(ME_AI_INBOX_DIR)) {
      if (!f.endsWith('.json')) continue;
      const p = path.join(ME_AI_INBOX_DIR, f);
      let v; try { v = JSON.parse(fs.readFileSync(p, 'utf-8')); } catch (_) { continue; }
      const arr = (v && Array.isArray(v.items)) ? v.items : null;
      if (!arr) continue;
      const kept = arr.filter(it => !set.has(_meAiStableKey(it)));
      if (kept.length !== arr.length) { items += (arr.length - kept.length); v.items = kept; try { fs.writeFileSync(p, JSON.stringify(v, null, 2)); files++; } catch (_) { /* keep going */ } }
    }
  } catch (_) { /* best-effort */ }
  return { files, items };
}

// GET /api/me-ai/parked → the durable triage-decision store (silenced items), newest first.
app.get('/api/me-ai/parked', (req, res) => {
  try {
    const store = loadDecisionMemory();
    const items = Object.values((store && store.decisions) || {})
      .filter(d => d && d.key)
      .map(d => ({
        key: d.key, triage: d.triage || 'dismissed',
        label: ME_AI_PARK_TRIAGE[d.triage] || 'Silenced',
        title: String(d.title || d.key).slice(0, 240),
        note: d.note || '', reason: d.reason || '', at: d.at || '',
        occurrences: _meAiParkedOccurrences(d.key),
      }))
      .sort((a, b) => String(b.at).localeCompare(String(a.at)));
    res.json({ ok: true, items, count: items.length });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/parked/restore { key } → un-silence: drop the durable decision so the item
// behaves as brand-new the next time its source surfaces it. Inbox history is left intact.
app.post('/api/me-ai/parked/restore', (req, res) => {
  try {
    const key = String((req.body && req.body.key) || '').trim();
    if (!key) return res.status(400).json({ error: 'key required' });
    const store = loadDecisionMemory();
    if (store.decisions && store.decisions[key]) { delete store.decisions[key]; saveDecisionMemory(store); }
    res.json({ ok: true, restored: key });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/parked/purge { key? | keys?[] | all? } → the extreme case: remove the
// durable decision(s) AND strip every matching item from all inbox snapshot files so the
// silenced item leaves no residue anywhere. Returns purged decision + inbox-strip counts.
app.post('/api/me-ai/parked/purge', (req, res) => {
  try {
    const b = req.body || {};
    const store = loadDecisionMemory();
    store.decisions = store.decisions || {};
    let keys;
    if (b.all) keys = Object.keys(store.decisions);
    else if (Array.isArray(b.keys)) keys = b.keys.map(k => String(k || '').trim()).filter(Boolean);
    else if (b.key) keys = [String(b.key).trim()];
    else return res.status(400).json({ error: 'key, keys[] or all required' });
    let purged = 0;
    for (const k of keys) { if (store.decisions[k]) { delete store.decisions[k]; purged++; } }
    if (purged) saveDecisionMemory(store);
    const stripped = _meAiPurgeInboxItems(keys);
    res.json({ ok: true, purged, inboxFiles: stripped.files, inboxItems: stripped.items });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/backlog/workitem { key, title?, link?, type?, org?, project? } → create a
// real ADO work item for a backlog entry (or the whole group) and record it on the curation.
app.post('/api/me-ai/backlog/workitem', async (req, res) => {
  try {
    const b = req.body || {};
    const key = String(b.key || '').trim();
    if (!key) return res.status(400).json({ error: 'key required' });
    const s = settings.getSettings();
    const cfg = _meAiConfig(s);
    const wi = (cfg && cfg.workItem) || {};
    const org = String(b.org || wi.org || '').trim();
    const project = String(b.project || wi.project || '').trim();
    const type = String(b.type || wi.type || 'Task').trim();
    if (!org || !project) return res.status(400).json({ error: 'work-item org/project not configured' });
    const azdo = require('./azdo');
    const title = String(b.title || '').trim().slice(0, 250) || 'Backlog item';
    const created = await azdo.createWorkItem(org, project, type, {
      title,
      description: String(b.description || '').slice(0, 4000),
      areaPath: wi.areaPath || undefined,
      iterationPath: wi.iterationPath || undefined,
      state: wi.state || undefined,
      tags: wi.tags || undefined,
    });
    const rec = _meAiSetCuration({ key, title, workItem: { id: created.id, url: created.url, org, project, type } });
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    res.json({ ok: true, workItem: created, item: rec, items: _meAiAssembleBacklog(date) });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/backlog/refresh { date? } → re-poll the inbox, LIVE-refresh the status of
// dev cards linked to current backlog items, then auto-resolve + re-assemble (so newly
// arrived asks land and finished work drops off with the authoritative latest status).
app.post('/api/me-ai/backlog/refresh', async (req, res) => {
  try {
    const date = String((req.body && req.body.date) || '').slice(0, 10) || _meAiLocalDay();
    const s = settings.getSettings();
    const cfg = _meAiConfig(s);
    // Resilience: the heavy live re-pull (inbox re-poll + per-card PR/work-item status,
    // each shelling out to gh/az) can be slow or wedge on an unreachable provider. Race it
    // against an overall budget so the request ALWAYS returns promptly. If it overruns, we
    // respond with the freshest locally-assembled + auto-resolved backlog and let the
    // re-pull finish in the background (its writes land for the next load). Never blocks,
    // never throws — a stalled provider degrades to "slightly stale", not a hung refresh.
    const live = (async () => {
      try { await _meAiRefreshInbox(s, cfg, date, { force: true }); } catch (_) {}
      try { await _meAiBacklogRefreshDevStatus(_meAiAssembleBacklog(date)); } catch (_) {}
    })();
    live.catch(() => {}); // detach: keep running past the budget without an unhandled rejection
    await Promise.race([live, new Promise(r => setTimeout(r, 20000))]);
    const ar = _meAiBacklogAutoResolve(date);
    res.json({ ok: true, date, items: ar.items, autoResolved: ar.autoResolved });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// GET /api/me-ai/triage-rules → transparency: the learned auto-handle rules ("why did
// you auto-handle this"). Returns rules sorted by confidence.
app.get('/api/me-ai/triage-rules', (req, res) => {
  try {
    const store = loadTriageRules();
    const rules = Object.entries(store.rules || {}).map(([sig, r]) => {
      const total = Number(r.total) || 0;
      let best = null, bestN = 0;
      for (const [a, n] of Object.entries(r.counts || {})) { if (n > bestN) { best = a; bestN = n; } }
      return { sig, sample: r.sample || '', best, share: total ? bestN / total : 0, total, counts: r.counts || {}, lastAction: r.lastAction || '', lastAt: r.lastAt || '', auto: ME_AI_TRIAGE_AUTO.has(best) && total >= 3 && bestN >= 3 && (total ? bestN / total : 0) >= 0.8 };
    }).sort((a, b) => (b.share - a.share) || (b.total - a.total));
    res.json({ ok: true, rules });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// --- Phase 4: user-defined CLASS RULES (ignore whole classes regardless of confidence) ---
// GET  /api/me-ai/class-rules            → list the user's class rules
// POST /api/me-ai/class-rules            → create ({ fromItem, action } OR { label, action, match })
// PATCH/PUT /api/me-ai/class-rules/:id   → toggle enabled / edit label|action|match
// DELETE /api/me-ai/class-rules/:id      → remove
app.get('/api/me-ai/class-rules', (req, res) => {
  try {
    const store = loadClassRules();
    res.json({ ok: true, rules: (store.rules || []).slice().sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt))) });
  } catch (err) { res.status(500).json({ error: err.message }); }
});
app.post('/api/me-ai/class-rules', (req, res) => {
  try {
    const b = req.body || {};
    const action = ME_AI_CLASS_ACTIONS.has(String(b.action || '').toLowerCase()) ? String(b.action).toLowerCase() : 'dismiss';
    const store = loadClassRules();
    let rule;
    if (b.fromItem && typeof b.fromItem === 'object') {
      rule = _meAiClassRuleFromItem(b.fromItem, action);
    } else {
      const label = String(b.label || '').trim().slice(0, 120);
      const m = (b.match && typeof b.match === 'object') ? b.match : {};
      const match = {};
      if (Array.isArray(m.sources)) match.sources = m.sources.map(x => String(x).toLowerCase().slice(0, 20)).filter(Boolean).slice(0, 12);
      if (Array.isArray(m.kinds)) match.kinds = m.kinds.map(x => String(x).toLowerCase().slice(0, 20)).filter(Boolean).slice(0, 12);
      if (Array.isArray(m.titleIncludes)) match.titleIncludes = m.titleIncludes.map(x => String(x).trim().slice(0, 60)).filter(Boolean).slice(0, 12);
      if (m.directMention === true) match.directMention = true;
      if (m.reviewRequest === true) match.reviewRequest = true;
      const hasCond = (match.sources && match.sources.length) || (match.kinds && match.kinds.length) || match.directMention || match.reviewRequest || (match.titleIncludes && match.titleIncludes.length);
      if (!label) return res.status(400).json({ error: 'label required' });
      if (!hasCond) return res.status(400).json({ error: 'at least one match condition required' });
      rule = { id: 'cr:' + require('crypto').randomUUID().slice(0, 8), label, enabled: true, action, match, createdAt: new Date().toISOString(), hits: 0, sample: '' };
    }
    store.rules = store.rules || [];
    store.rules.push(rule);
    saveClassRules(store);
    res.json({ ok: true, rule, rules: store.rules });
  } catch (err) { res.status(500).json({ error: err.message }); }
});
function _meAiUpdateClassRule(req, res) {
  try {
    const id = String(req.params.id || '');
    const b = req.body || {};
    const store = loadClassRules();
    const rule = (store.rules || []).find(r => r && r.id === id);
    if (!rule) return res.status(404).json({ error: 'rule not found' });
    if (typeof b.enabled === 'boolean') rule.enabled = b.enabled;
    if (typeof b.label === 'string' && b.label.trim()) rule.label = b.label.trim().slice(0, 120);
    if (b.action !== undefined && ME_AI_CLASS_ACTIONS.has(String(b.action).toLowerCase())) rule.action = String(b.action).toLowerCase();
    if (b.match && typeof b.match === 'object') {
      const m = b.match; const match = {};
      if (Array.isArray(m.sources)) match.sources = m.sources.map(x => String(x).toLowerCase().slice(0, 20)).filter(Boolean).slice(0, 12);
      if (Array.isArray(m.kinds)) match.kinds = m.kinds.map(x => String(x).toLowerCase().slice(0, 20)).filter(Boolean).slice(0, 12);
      if (Array.isArray(m.titleIncludes)) match.titleIncludes = m.titleIncludes.map(x => String(x).trim().slice(0, 60)).filter(Boolean).slice(0, 12);
      if (m.directMention === true) match.directMention = true;
      if (m.reviewRequest === true) match.reviewRequest = true;
      rule.match = match;
    }
    saveClassRules(store);
    res.json({ ok: true, rule, rules: store.rules });
  } catch (err) { res.status(500).json({ error: err.message }); }
}
app.patch('/api/me-ai/class-rules/:id', _meAiUpdateClassRule);
app.put('/api/me-ai/class-rules/:id', _meAiUpdateClassRule);
app.delete('/api/me-ai/class-rules/:id', (req, res) => {
  try {
    const id = String(req.params.id || '');
    const store = loadClassRules();
    const before = (store.rules || []).length;
    store.rules = (store.rules || []).filter(r => r && r.id !== id);
    saveClassRules(store);
    res.json({ ok: true, removed: before - store.rules.length, rules: store.rules });
  } catch (err) { res.status(500).json({ error: err.message }); }
});
// --- Me.AI topic memory (Phase 6) transparency routes ---------------------------------------
// GET    /api/me-ai/topic-memory        → list learned topics (what future look-alikes get suppressed)
// DELETE /api/me-ai/topic-memory/:id     → forget a single topic
// DELETE /api/me-ai/topic-memory         → forget ALL topics (clear the memory)
app.get('/api/me-ai/topic-memory', (req, res) => {
  try {
    const store = loadTopicMemory();
    const topics = (store.topics || []).slice()
      .sort((a, b) => String(b.lastAt || '').localeCompare(String(a.lastAt || '')))
      .map(t => ({
        id: t.id, label: t.label, action: t.action, actionLabel: _meAiActionLabel(_meAiTopicAction(t.action) || t.action),
        tokens: t.tokens || [], sources: t.sources || [], kinds: t.kinds || [],
        sample: t.sample || '', group: !!t.group, hits: Number(t.hits) || 0,
        decidedAt: t.decidedAt || null, lastAt: t.lastAt || null,
      }));
    res.json({ ok: true, topics });
  } catch (err) { res.status(500).json({ error: err.message }); }
});
app.delete('/api/me-ai/topic-memory/:id', (req, res) => {
  try {
    const id = String(req.params.id || '');
    const store = loadTopicMemory();
    const before = (store.topics || []).length;
    store.topics = (store.topics || []).filter(t => t && t.id !== id);
    saveTopicMemory(store);
    res.json({ ok: true, removed: before - store.topics.length, topics: store.topics });
  } catch (err) { res.status(500).json({ error: err.message }); }
});
app.delete('/api/me-ai/topic-memory', (req, res) => {
  try {
    const store = loadTopicMemory();
    const removed = (store.topics || []).length;
    store.topics = [];
    saveTopicMemory(store);
    res.json({ ok: true, removed, topics: [] });
  } catch (err) { res.status(500).json({ error: err.message }); }
});
// a later generate/re-plan is fast (#3). Fire-and-forget; consent-gated inside.
app.post('/api/me-ai/preindex', (req, res) => {
  try {
    const day = String((req.body && req.body.date) || '').slice(0, 10) || _meAiLocalDay();
    _meAiLastActive = Date.now();
    const cached = ME_AI_SIGNAL_CACHE.get(day);
    const started = _meAiPreindex(day);
    res.json({ ok: true, day, started, warm: !!cached, indexedAt: cached ? new Date(cached.at).toISOString() : null });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/agenda/dismiss { date, key?, title?, link?, note? }
// #7 "Not mine" — persist a per-day dismissal so regeneration excludes the item,
// and immediately strip it from the current snapshot (regenerate is slow) so the
// UI reflects the removal at once. Returns the updated agenda.
app.post('/api/me-ai/agenda/dismiss', (req, res) => {
  try {
    const b = req.body || {};
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    const key = _meAiDismissKey({ link: b.link, title: b.title }) || String(b.key || '').trim().slice(0, 300);
    if (!key) return res.status(400).json({ error: 'key or title required' });
    // reason distinguishes a deliberate no-op ('wontfix') from handing it off to
    // its real owner ('dismissed' / "not mine") — Reports (REQ-12) splits the two.
    const reason = String(b.reason || '').trim().toLowerCase() === 'wontfix' ? 'wontfix' : 'dismissed';
    const map = loadDismissForDate(date);
    map[key] = { note: String(b.note || '').trim().slice(0, 500), title: String(b.title || key).slice(0, 300), at: new Date().toISOString(), reason, manual: true };
    saveDismissForDate(date, map);
    // Strip from the live snapshot so the change is instant.
    const agenda = loadAgendaForDate(date);
    if (agenda) {
      const keep = it => _meAiDismissKey(it) !== key;
      agenda.blocks = (agenda.blocks || []).filter(keep);
      agenda.backlog = (agenda.backlog || []).filter(keep);
      agenda.needsAttention = (agenda.needsAttention || []).filter(keep);
      agenda.dismissed = Object.keys(map).filter(k => map[k] && map[k].manual && String(map[k].at || '').slice(0, 10) === date).map(k => ({ key: k, title: map[k] && map[k].title || k, note: map[k] && map[k].note || '', at: map[k] && map[k].at || '', reason: map[k] && map[k].reason || 'dismissed' }));
      _meAiCleanSnapshotBlocks(agenda);
      saveAgendaForDate(date, agenda);
    }
    res.json({ ok: true, date, agenda });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/agenda/undismiss { date, key } → restore a dismissed item.
// (The item returns on the next generate; we just drop the dismissal record.)
app.post('/api/me-ai/agenda/undismiss', (req, res) => {
  try {
    const b = req.body || {};
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    const key = String(b.key || '').trim().slice(0, 300);
    const map = loadDismissForDate(date);
    if (key && map[key]) { delete map[key]; saveDismissForDate(date, map); }
    const agenda = loadAgendaForDate(date);
    if (agenda) {
      agenda.dismissed = Object.keys(map).filter(k => map[k] && map[k].manual && String(map[k].at || '').slice(0, 10) === date).map(k => ({ key: k, title: map[k] && map[k].title || k, note: map[k] && map[k].note || '', at: map[k] && map[k].at || '', reason: map[k] && map[k].reason || 'dismissed' }));
      _meAiCleanSnapshotBlocks(agenda);
      saveAgendaForDate(date, agenda);
    }
    res.json({ ok: true, date, agenda, dismissed: agenda ? agenda.dismissed : [] });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// REQ-13 Agenda Assistant chat → { reply, actions[] }. Read-only proposal turn; the
// client confirms + applies each action via the endpoints below (or existing ones).
app.post('/api/me-ai/agenda/assistant', async (req, res) => {
  try {
    const b = req.body || {};
    const out = await runMeAiAgendaAssistant({ message: b.message, history: Array.isArray(b.history) ? b.history : [], date: b.date });
    res.json({ ok: true, ...out });
  } catch (err) { res.status(400).json({ error: err.message }); }
});

// REQ-13 structural overrides — a single endpoint mutates the per-day override store
// then re-plans the live day so custom/recurring blocks, splits and item-removals take
// effect immediately and survive future regenerates. Body: { date, op, ... }.
app.post('/api/me-ai/agenda/override', async (req, res) => {
  try {
    const b = req.body || {};
    const date = String(b.date || '').slice(0, 10) || _meAiLocalDay();
    const op = String(b.op || '').trim();
    const ov = loadMeAiOverrides(date);
    const uid = () => 'ov-' + Math.random().toString(36).slice(2, 9);
    if (op === 'add_block') {
      if (_hmToMin(b.start) == null || _hmToMin(b.end) == null || _hmToMin(b.end) <= _hmToMin(b.start)) return res.status(400).json({ error: 'valid start/end required' });
      ov.addBlocks.push({ id: uid(), start: String(b.start), end: String(b.end), title: String(b.title || 'Blocked time').slice(0, 200), type: ME_AI_BLOCK_TYPES.has(b.blockType) ? b.blockType : 'personal', detail: String(b.detail || '').slice(0, 500), why: String(b.why || 'Added by you').slice(0, 200) });
    } else if (op === 'add_recurring') {
      ov.recurring.push({ id: uid(), everyMin: Math.max(15, Math.min(480, +b.everyMin || 60)), durMin: Math.max(5, Math.min(240, +b.durMin || 10)), title: String(b.title || 'Break').slice(0, 200), type: ME_AI_BLOCK_TYPES.has(b.blockType) ? b.blockType : 'break', from: _hmToMin(b.from) != null ? String(b.from) : '', to: _hmToMin(b.to) != null ? String(b.to) : '' });
    } else if (op === 'split') {
      const key = String(b.key || '').trim().slice(0, 300); if (!key) return res.status(400).json({ error: 'key required' });
      if (!ov.splits.includes(key)) ov.splits.push(key);
    } else if (op === 'remove_item') {
      const key = String(b.key || '').trim().slice(0, 300); if (!key) return res.status(400).json({ error: 'key required' });
      if (!ov.removedItems.includes(key)) ov.removedItems.push(key);
    } else if (op === 'set_day_window') {
      // Quick per-day work window ("started early/late today"). Supersedes the standing
      // schedule for this date only; saved preferences are untouched.
      const hasS = _hmToMin(b.dayStart) != null, hasE = _hmToMin(b.dayEnd) != null;
      if (!hasS && !hasE) return res.status(400).json({ error: 'dayStart and/or dayEnd required' });
      const ns = hasS ? _hmToMin(b.dayStart) : _hmToMin(ov.dayStart);
      const ne = hasE ? _hmToMin(b.dayEnd) : _hmToMin(ov.dayEnd);
      if (ns != null && ne != null && ne <= ns) return res.status(400).json({ error: 'end must be after start' });
      if (hasS) ov.dayStart = String(b.dayStart);
      if (hasE) ov.dayEnd = String(b.dayEnd);
    } else if (op === 'clear_day_window') {
      ov.dayStart = ''; ov.dayEnd = '';
    } else if (op === 'clear_block') {
      // Remove a manual custom/recurring block by its overrideId.
      const id = String(b.overrideId || '').trim(); if (!id) return res.status(400).json({ error: 'overrideId required' });
      ov.addBlocks = ov.addBlocks.filter(x => x.id !== id);
      ov.recurring = ov.recurring.filter(x => x.id !== id);
    } else if (op === 'unsplit') {
      const key = String(b.key || '').trim().slice(0, 300);
      ov.splits = ov.splits.filter(k => k !== key);
    } else if (op === 'restore_item') {
      const key = String(b.key || '').trim().slice(0, 300);
      ov.removedItems = ov.removedItems.filter(k => k !== key);
    } else if (op === 'reschedule_later') {
      // "Do it later today." Find the earliest free slot from now (rounded to the grid)
      // to work-end and drop a block there. If nothing fits, carry it to the next work
      // day's rollover instead (deferred=true) so it isn't silently lost.
      const key = String((b.key || b.link || b.title) || '').trim().slice(0, 300);
      const title = String(b.title || 'Follow-up').slice(0, 200);
      if (!key) return res.status(400).json({ error: 'key or title required' });
      const durMin = Math.max(10, Math.min(240, +b.durMin || 30));
      const cfg = _meAiConfig();
      const snap = loadAgendaForDate(date) || {};
      const grid = Math.max(5, (snap.config && snap.config.grid) || cfg.grid || 10);
      const ws = _hmToMin((snap.config && snap.config.workStart) || ov.dayStart || cfg.workStart) ?? 480;
      const we = _hmToMin((snap.config && snap.config.workEnd) || ov.dayEnd || cfg.workEnd) ?? 1020;
      const today = _meAiLocalDay();
      let from = ws;
      if (date === today) { const d = new Date(); from = Math.max(ws, Math.ceil((d.getHours() * 60 + d.getMinutes()) / grid) * grid); }
      const occupied = ((snap.blocks) || [])
        .map(bl => [_hmToMin(bl.start), _hmToMin(bl.end)])
        .filter(([s2, e2]) => s2 != null && e2 != null && e2 > s2)
        .concat(_meAiReservationsFromOverrides(ov, snap.config || cfg).map(r => [r.start, r.end]))
        .sort((x, y) => x[0] - y[0]);
      let slot = null;
      for (let t = from; t + durMin <= we; t += grid) {
        const clash = occupied.some(([s2, e2]) => t < e2 && (t + durMin) > s2);
        if (!clash) { slot = t; break; }
      }
      if (slot != null) {
        ov.addBlocks.push({ id: uid(), start: _minToHm(slot), end: _minToHm(slot + durMin), title, type: ME_AI_BLOCK_TYPES.has(b.blockType) ? b.blockType : 'personal', detail: String(b.detail || '').slice(0, 500), why: 'Rescheduled later today by you', link: String(b.link || '').slice(0, 500) });
        if (!ov.removedItems.includes(key)) ov.removedItems.push(key);
        saveMeAiOverrides(date, ov);
        const agenda = await _meAiRegenLive(date);
        return res.json({ ok: true, date, agenda, overrides: ov, deferred: false, at: _minToHm(slot) });
      }
      // No room left today → carry to the next work day.
      const target = _meAiNextWorkDay(cfg, date);
      if (target) _meAiPushDeferral(target, { key, title, link: b.link, from: date, fromLabel: _meAiDateLabel(date), reason: 'no-room' });
      if (!ov.removedItems.includes(key)) ov.removedItems.push(key);
      saveMeAiOverrides(date, ov);
      const agenda = await _meAiRegenLive(date);
      return res.json({ ok: true, date, agenda, overrides: ov, deferred: true, toLabel: target ? _meAiDateLabel(target) : '' });
    } else if (op === 'add_to_today') {
      // Add an external item (typically a pull request) into TODAY's agenda.
      // Rules: honor a 30-minute look-ahead buffer (never schedule something
      // imminent), take the first free slot for the rest of the day, and if the
      // day is packed, append it AFTER normal business hours rather than bumping
      // it to another day. Carries the item's link so it stays clickable.
      const key = String((b.key || b.link || b.title) || '').trim().slice(0, 300);
      const title = String(b.title || 'Pull request review').slice(0, 200);
      if (!key) return res.status(400).json({ error: 'key or title required' });
      const durMin = Math.max(10, Math.min(240, +b.durMin || 30));
      const cfg = _meAiConfig();
      const snap = loadAgendaForDate(date) || {};
      const grid = Math.max(5, (snap.config && snap.config.grid) || cfg.grid || 10);
      const ws = _hmToMin((snap.config && snap.config.workStart) || ov.dayStart || cfg.workStart) ?? 480;
      const we = _hmToMin((snap.config && snap.config.workEnd) || ov.dayEnd || cfg.workEnd) ?? 1020;
      const today = _meAiLocalDay();
      const BUFFER_MIN = 30; // never schedule inside the next half hour
      let from = ws;
      if (date === today) {
        const d = new Date();
        const nowMin = d.getHours() * 60 + d.getMinutes();
        from = Math.max(ws, Math.ceil((nowMin + BUFFER_MIN) / grid) * grid);
      }
      const occupied = ((snap.blocks) || [])
        .map(bl => [_hmToMin(bl.start), _hmToMin(bl.end)])
        .filter(([s2, e2]) => s2 != null && e2 != null && e2 > s2)
        .concat(_meAiReservationsFromOverrides(ov, snap.config || cfg).map(r => [r.start, r.end]))
        .sort((x, y) => x[0] - y[0]);
      let slot = null, afterHours = false;
      for (let t = from; t + durMin <= we; t += grid) {
        const clash = occupied.some(([s2, e2]) => t < e2 && (t + durMin) > s2);
        if (!clash) { slot = t; break; }
      }
      if (slot == null) {
        // Day is full for the remainder → place it after hours, past the last
        // commitment (and never before the 30-min buffer), stacking cleanly.
        const tail = occupied.reduce((m, [, e2]) => Math.max(m, e2), Math.max(from, we));
        slot = Math.max(we, tail, from);
        afterHours = true;
      }
      ov.addBlocks.push({
        id: uid(), start: _minToHm(slot), end: _minToHm(slot + durMin),
        title, type: ME_AI_BLOCK_TYPES.has(b.blockType) ? b.blockType : 'review',
        detail: String(b.detail || '').slice(0, 500),
        why: afterHours ? 'Added to today after hours — the day was full' : 'Added to today by you',
        link: String(b.link || '').slice(0, 500),
      });
      saveMeAiOverrides(date, ov);
      const agenda = await _meAiRegenLive(date);
      return res.json({ ok: true, date, agenda, overrides: ov, at: _minToHm(slot), afterHours });
    } else if (op === 'defer_future') {
      // "Not done — move to a future day." Carry the item to the next work day's rollover
      // digest and drop it from today.
      const key = String((b.key || b.link || b.title) || '').trim().slice(0, 300);
      const title = String(b.title || 'Follow-up').slice(0, 200);
      if (!key) return res.status(400).json({ error: 'key or title required' });
      const cfg = _meAiConfig();
      const target = _meAiNextWorkDay(cfg, date);
      if (target) _meAiPushDeferral(target, { key, title, link: b.link, from: date, fromLabel: _meAiDateLabel(date), reason: 'not-done' });
      if (!ov.removedItems.includes(key)) ov.removedItems.push(key);
      saveMeAiOverrides(date, ov);
      const agenda = await _meAiRegenLive(date);
      return res.json({ ok: true, date, agenda, overrides: ov, toLabel: target ? _meAiDateLabel(target) : '' });
    } else if (op === 'rollover_today') {
      // "Do today" on a rolled-over item: drop it from this day's deferral store and
      // reschedule it into the day via the reschedule-later slot logic.
      const key = String((b.key || b.link || b.title) || '').trim().slice(0, 300);
      const title = String(b.title || 'Follow-up').slice(0, 200);
      if (!key) return res.status(400).json({ error: 'key or title required' });
      const remaining = loadMeAiDeferrals(date).filter(x => String((x.key || x.link || x.title) || '').trim().slice(0, 300) !== key);
      saveMeAiDeferrals(date, remaining);
      ov.removedItems = ov.removedItems.filter(k => k !== key); // allow it back onto the day
      const cfg = _meAiConfig();
      const snap = loadAgendaForDate(date) || {};
      const grid = Math.max(5, (snap.config && snap.config.grid) || cfg.grid || 10);
      const ws = _hmToMin((snap.config && snap.config.workStart) || ov.dayStart || cfg.workStart) ?? 480;
      const we = _hmToMin((snap.config && snap.config.workEnd) || ov.dayEnd || cfg.workEnd) ?? 1020;
      const today = _meAiLocalDay();
      let from = ws;
      if (date === today) { const d = new Date(); from = Math.max(ws, Math.ceil((d.getHours() * 60 + d.getMinutes()) / grid) * grid); }
      const durMin = 30;
      const occupied = ((snap.blocks) || [])
        .map(bl => [_hmToMin(bl.start), _hmToMin(bl.end)])
        .filter(([s2, e2]) => s2 != null && e2 != null && e2 > s2)
        .concat(_meAiReservationsFromOverrides(ov, snap.config || cfg).map(r => [r.start, r.end]))
        .sort((x, y) => x[0] - y[0]);
      let slot = null;
      for (let t = from; t + durMin <= we; t += grid) {
        const clash = occupied.some(([s2, e2]) => t < e2 && (t + durMin) > s2);
        if (!clash) { slot = t; break; }
      }
      // "Do today" is an explicit commitment — if the day is packed, append it at the end
      // of the last block (past work-end if need be) rather than dropping it silently.
      if (slot == null) {
        const lastEnd = occupied.reduce((m, [, e2]) => Math.max(m, e2), from);
        slot = Math.max(from, lastEnd);
      }
      ov.addBlocks.push({ id: uid(), start: _minToHm(slot), end: _minToHm(slot + durMin), title, type: 'personal', detail: '', why: 'Brought into today by you', link: String(b.link || '').slice(0, 500) });
      saveMeAiOverrides(date, ov);
      const agenda = await _meAiRegenLive(date);
      return res.json({ ok: true, date, agenda, overrides: ov, at: _minToHm(slot) });
    } else if (op === 'rename') {
      // I3: change an agenda item's title. Keyed by the block's STABLE identity (link ||
      // ORIGINAL title) so the override re-applies across regenerates even though the
      // displayed title changes.
      const key = String((b.key || b.link || b.origTitle || b.title) || '').trim().slice(0, 300);
      const title = String(b.title || '').trim().slice(0, 200);
      if (!key || !title) return res.status(400).json({ error: 'key and title required' });
      ov.renames = (ov.renames || []).filter(r => String((r && r.key) || '').trim().toLowerCase() !== key.toLowerCase());
      ov.renames.push({ key, title });
    } else if (op === 'lock') {
      // I2: pin a block to a specific time. It becomes a fixed reservation the pre-pass
      // lays other work around. Store the full block so it can be re-materialised on every
      // regenerate; keyed by link || title.
      const key = String((b.key || b.link || b.title) || '').trim().slice(0, 300);
      if (!key) return res.status(400).json({ error: 'key required' });
      let s = _hmToMin(b.start), e = _hmToMin(b.end);
      if (s == null) return res.status(400).json({ error: 'valid start required' });
      if (e == null || e <= s) {
        const dur = Math.max(10, Math.min(480, +b.durMin || 30));
        e = s + dur;
      }
      ov.locks = (ov.locks || []).filter(l => String((l && (l.key || l.link || l.title)) || '').trim().toLowerCase() !== key.toLowerCase());
      ov.locks.push({
        key, start: _minToHm(s), end: _minToHm(e),
        type: ME_AI_BLOCK_TYPES.has(b.blockType) ? b.blockType : (ME_AI_BLOCK_TYPES.has(b.type) ? b.type : 'focus'),
        title: String(b.title || 'Locked block').slice(0, 200), detail: String(b.detail || '').slice(0, 500),
        link: String(b.link || '').slice(0, 500), why: String(b.why || '').slice(0, 200), urgency: Number(b.urgency) || 0,
        meta: (b.meta && typeof b.meta === 'object' && !Array.isArray(b.meta)) ? b.meta : {},
        at: new Date().toISOString(),
      });
    } else if (op === 'unlock') {
      const key = String((b.key || b.link || b.title) || '').trim().slice(0, 300);
      if (!key) return res.status(400).json({ error: 'key required' });
      ov.locks = (ov.locks || []).filter(l => String((l && (l.key || l.link || l.title)) || '').trim().toLowerCase() !== key.toLowerCase());
    } else if (op === 'add_constraint') {
      // A hard timing constraint the user stated ("X before 1:30 PM"). Persisted so it's
      // honored across every re-plan (LLM prompt + deterministic enforce/verify pass).
      const kind = ['before', 'after', 'at'].includes(String(b.kind)) ? String(b.kind) : 'before';
      if (_hmToMin(b.time) == null) return res.status(400).json({ error: 'valid time required' });
      const subject = String(b.subject || b.title || '').trim().slice(0, 200);
      if (!subject) return res.status(400).json({ error: 'subject required' });
      ov.constraints = Array.isArray(ov.constraints) ? ov.constraints : [];
      ov.constraints = ov.constraints.filter(c => String((c && c.subject) || '').trim().toLowerCase() !== subject.toLowerCase());
      ov.constraints.push({ id: uid(), kind, time: String(b.time), subject, text: String(b.text || '').slice(0, 300), createdAt: new Date().toISOString() });
    } else if (op === 'clear_constraint') {
      ov.constraints = Array.isArray(ov.constraints) ? ov.constraints : [];
      const id = String(b.id || '').trim();
      const subject = String(b.subject || b.title || '').trim().toLowerCase();
      ov.constraints = ov.constraints.filter(c => {
        if (id) return String((c && c.id) || '') !== id;
        if (subject) return String((c && c.subject) || '').trim().toLowerCase() !== subject;
        return true;
      });
    } else if (op === 'set_label') {
      // Tag an agenda item as personal or work (orthogonal to its type). Persisted per-day
      // and re-applied across regenerates by stable key so reporting can mask personal items.
      const key = String((b.key || b.link || b.title) || '').trim().slice(0, 300);
      const label = String(b.label || '').trim().toLowerCase();
      if (!key) return res.status(400).json({ error: 'key required' });
      if (label !== 'personal' && label !== 'work') return res.status(400).json({ error: 'label must be personal or work' });
      ov.labels = Array.isArray(ov.labels) ? ov.labels : [];
      ov.labels = ov.labels.filter(l => String((l && l.key) || '').trim().toLowerCase() !== key.toLowerCase());
      ov.labels.push({ key, label });
    } else if (op === 'clear_label') {
      const key = String((b.key || b.link || b.title) || '').trim().slice(0, 300);
      if (!key) return res.status(400).json({ error: 'key required' });
      ov.labels = Array.isArray(ov.labels) ? ov.labels : [];
      ov.labels = ov.labels.filter(l => String((l && l.key) || '').trim().toLowerCase() !== key.toLowerCase());
    } else {
      return res.status(400).json({ error: 'unknown op' });
    }
    saveMeAiOverrides(date, ov);
    const agenda = await _meAiRegenLive(date);
    res.json({ ok: true, date, agenda, overrides: ov });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST /api/me-ai/todo/classify { title } → { scope: 'work'|'personal' }.
app.post('/api/me-ai/todo/classify', async (req, res) => {
  try {
    const title = String((req.body && req.body.title) || '').trim();
    if (!title) return res.json({ ok: true, scope: 'work' });
    const scope = await _meAiClassifyTodo(title);
    res.json({ ok: true, scope });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// ===== Me.AI M2 — the Me-agent console (dispatch → stream → decide → complete) =====
// A per-task drawer where a background "Me agent" does a playbook (M2 = code review),
// streaming its thinking/tools/report to the SPA over the shared `/api/events` SSE bus
// (event type `me-ai-task`). After each report the agent proposes AI-generated
// nextActions; the user steers via allowed intents; completion writes a dedup-aware
// diary entry (§9.1). Runtime is REUSED (sdkRunner.runChat streaming), no new engine.
const ME_AI_TASKS_DIR = path.join(dataPath('me-ai'), 'tasks');
const meAiTasks = new Map();            // taskId -> live task object
const meAiQueue = [];                   // queued run fns waiting for a concurrency slot
let meAiActive = 0;                     // in-flight background runs
const ME_AI_MAX_CONCURRENT = 3;         // locked decision #5
// Allowed intent vocabulary — generated actions must map to one of these (§7.2).
const ME_AI_INTENTS = ['apply-fix', 'comment', 'push', 'approve', 'request-review', 'retry', 'change-approach', 'hand-to-me', 'continue', 'summarize', 'ask-user', 'abandon', 'converse'];

function _meAiTaskPath(id) { return path.join(ME_AI_TASKS_DIR, String(id).replace(/[^a-z0-9_-]/gi, '') + '.json'); }
function _meAiSaveTask(t) {
  try {
    fs.mkdirSync(ME_AI_TASKS_DIR, { recursive: true });
    // Persist a serializable snapshot (drop nothing — events are plain objects).
    const { _timer, ...snap } = t;
    fs.writeFileSync(_meAiTaskPath(t.id), JSON.stringify(snap, null, 2));
  } catch (_) { /* best-effort */ }
}
function _meAiLoadTask(id) {
  if (meAiTasks.has(id)) return meAiTasks.get(id);
  try {
    const p = _meAiTaskPath(id);
    if (!fs.existsSync(p)) return null;
    const t = JSON.parse(fs.readFileSync(p, 'utf-8'));
    return (t && t.id) ? t : null;
  } catch { return null; }
}
// Rehydrate persisted tasks into the live Map on boot so the "at work" lane and
// GET /tasks survive a restart. Any task that was mid-run when the process died
// is neutralized (the SDK session is gone) so it doesn't show a phantom spinner.
function _meAiHydrateTasks() {
  try {
    if (!fs.existsSync(ME_AI_TASKS_DIR)) return;
    const cutoff = Date.now() - 14 * 24 * 60 * 60 * 1000; // keep ~2 weeks
    const files = fs.readdirSync(ME_AI_TASKS_DIR).filter(f => f.endsWith('.json'));
    for (const f of files) {
      try {
        const p = path.join(ME_AI_TASKS_DIR, f);
        const t = JSON.parse(fs.readFileSync(p, 'utf-8'));
        if (!t || !t.id) continue;
        const when = Date.parse(t.updatedAt || t.createdAt || 0) || 0;
        if (when && when < cutoff) continue;
        if (t.status === 'running' || t.status === 'queued') {
          // Interrupted by the restart — the in-memory run was lost. Surface it as a clear,
          // recoverable state (never silently stuck or gone) so there's no confusion about
          // what a background Me agent is doing. A queued task never got its slot; a running
          // one lost its session. Both are one click from resuming.
          const wasQueued = t.status === 'queued';
          t.status = 'error'; t.stage = 'error';
          t.error = t.error || (wasQueued
            ? 'Interrupted by a server restart before it started. Resume to run it.'
            : 'Interrupted by a server restart. Resume to pick up where it left off.');
          t.nextActions = [
            // A pursuit ("tree") must re-arm the fan-out orchestrator (intent 'continue'),
            // not the flat single-turn runner ('retry') which would ignore the canvas.
            { label: 'Resume', intent: t.mode === 'tree' ? 'continue' : 'retry', primary: true, risk: 'none' },
            { label: 'Abandon', intent: 'abandon', primary: false, risk: 'none' },
          ];
        }
        meAiTasks.set(t.id, t);
      } catch (_) { /* skip corrupt file */ }
    }
  } catch (_) { /* best-effort */ }
}
_meAiHydrateTasks();

// ============================================================================
// Me-agent P0 backbone — durable fan-out task tree (event journal + outbox)
// ----------------------------------------------------------------------------
// Additive + backward compatible. Legacy tasks (mode !== 'tree') keep using the
// flat me-ai/tasks/<id>.json store above and the single-loop runner untouched.
// Fan-out tasks (mode 'tree') additionally get a per-task directory:
//   me-ai/tasks/<id>/journal.ndjson    append-only SOURCE OF TRUTH (fold -> tree)
//   me-ai/tasks/<id>/state.json        derived snapshot cache (fast cold load)
//   me-ai/tasks/<id>/outbox/<key>.json two-phase side-effect intents (idempotent)
// The in-memory tree is a FOLD over the journal; state.json is only a cache; the
// outbox lets a crash-resume verify a side effect before retrying (no double post).
// This block defines the data model, journal writer/fold, outbox, and rehydrate.
// The orchestrator that USES it (fan-out) is the P0 vertical slice, wired next.
// ============================================================================
const meAiTrees = new Map();  // taskId -> in-memory folded tree state
function _meAiTreeDir(id) { return path.join(ME_AI_TASKS_DIR, String(id).replace(/[^a-z0-9_-]/gi, '') + '.tree'); }
function _meAiJournalPath(id) { return path.join(_meAiTreeDir(id), 'journal.ndjson'); }
function _meAiTreeStatePath(id) { return path.join(_meAiTreeDir(id), 'state.json'); }
function _meAiOutboxDir(id) { return path.join(_meAiTreeDir(id), 'outbox'); }

// ---- Data-shape factories (§9). Plain serializable objects. ----
function _meAiNewLeg(o = {}) {
  return {
    id: o.id || ('leg-' + Math.random().toString(36).slice(2, 9)),
    parentId: o.parentId || null,      // spine leg has null; branches point at their fork
    kind: o.kind || 'branch',          // spine | branch | scout | reroute
    title: o.title || 'Leg',
    goal: o.goal || '',
    status: o.status || 'planned',     // planned|running|blocked|needs-auth|needs-decision|needs-info|merging|done|invalidated|cancelled|error
    baseEpoch: (o.baseEpoch != null ? o.baseEpoch : 0),  // task epoch this leg started from (§5a staleness)
    lane: o.lane || null,              // UI lane hint (spine/l1/l2/r1..) — presentation only
    confidence: (o.confidence != null ? o.confidence : null),
    invalidated: false,
    sessionId: o.sessionId || null,    // SDK session for durable resume
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
}
function _meAiNewCheckpoint(o = {}) {
  return {
    id: o.id || ('ckpt-' + Math.random().toString(36).slice(2, 9)),
    legId: o.legId || null, epoch: (o.epoch != null ? o.epoch : 0),
    title: o.title || 'Checkpoint', summary: o.summary || '',
    confidence: o.confidence || null,  // low|medium|high
    interesting: !!o.interesting, at: new Date().toISOString(),
  };
}
function _meAiNewArtifact(o = {}) {
  return {
    id: o.id || ('art-' + Math.random().toString(36).slice(2, 9)),
    legId: o.legId || null, kind: o.kind || 'report',   // report|chart|table|diff|link
    title: o.title || 'Artifact', path: o.path || null, link: o.link || null,
    body: o.body || null, format: o.format || null, at: new Date().toISOString(),
  };
}
function _meAiNewStop(o = {}) {
  // Three stop types (§4): needs-info | needs-auth | needs-decision.
  return {
    id: o.id || ('stop-' + Math.random().toString(36).slice(2, 9)),
    type: o.type || 'needs-decision', legId: o.legId || null,
    prompt: o.prompt || '', options: o.options || null,   // for needs-decision
    risk: o.risk || null,                                 // for needs-auth: write|external|spend|destructive
    delivery: !!o.delivery,                               // needs-auth: approve runs the local delivery pipeline (not an external outbox act)
    action: o.action || null,                             // the gated action payload
    status: o.status || 'open',                           // open|resolved|denied|expired
    resolution: o.resolution || null, note: o.note || null,
    createdAt: new Date().toISOString(), resolvedAt: null,
  };
}
function _meAiNewMergeCandidate(o = {}) {
  return {
    id: o.id || ('merge-' + Math.random().toString(36).slice(2, 9)),
    legId: o.legId || null, baseEpoch: (o.baseEpoch != null ? o.baseEpoch : 0),
    findings: o.findings || [],           // [{claim,evidenceRefs,source,freshness,confidence,contradiction?}]
    constraints: o.constraints || [], artifacts: o.artifacts || [],
    proposedActions: o.proposedActions || [], invalidatesLegIds: o.invalidatesLegIds || [],
    confidence: o.confidence || null, cost: o.cost || null,
    requiresUserDecision: !!o.requiresUserDecision, at: new Date().toISOString(),
  };
}
// Normalize a finding's subject into a stable slug so sibling legs that touch the
