// Exhaustive usage + cost reporting backed by the canonical usage_events ledger.
// Returns aggregate totals plus per-day, per-model and per-source breakdowns for
// a time window (default: last 30 days). Every billable run path (agent, task,
// chat) writes exactly one ledger row, so nothing is double-counted.
app.get('/api/reports', (req, res) => {
  try {
    const reqDays = parseInt(req.query.days, 10);
    const days = Math.min(Math.max(Number.isFinite(reqDays) ? reqDays : 30, 1), 365);
    const now = new Date();
    let to = req.query.to ? String(req.query.to) : now.toISOString();
    let from = req.query.from ? String(req.query.from) : new Date(now.getTime() - days * 86400000).toISOString();
    const rate = settings.getCostPerPremiumRequest();
    const decorate = (rows) => rows.map(r => ({ ...r, cost: +(((r.premiumRequests || 0) * rate).toFixed(4)) }));

    const SUMS = `
        SUM(CASE WHEN COALESCE(deliverable,0)=1 THEN 0 ELSE 1 END) AS runs,
        COALESCE(SUM(deliverable),0) AS deliverables,
        COALESCE(SUM(premium_requests),0) AS premiumRequests,
        COALESCE(SUM(api_duration_ms),0) AS apiDurationMs,
        COALESCE(SUM(input_tokens),0) AS inputTokens,
        COALESCE(SUM(output_tokens),0) AS outputTokens,
        COALESCE(SUM(cache_read_tokens),0) AS cacheReadTokens,
        COALESCE(SUM(cache_write_tokens),0) AS cacheWriteTokens`;

    const agg = db.prepare(`SELECT ${SUMS},
        SUM(CASE WHEN status='success' THEN 1 ELSE 0 END) AS success,
        SUM(CASE WHEN status='error' THEN 1 ELSE 0 END) AS error
      FROM usage_events WHERE ts >= ? AND ts <= ?`).get(from, to) || {};

    const bySource = db.prepare(`SELECT source, ${SUMS}
      FROM usage_events WHERE ts >= ? AND ts <= ? GROUP BY source ORDER BY premiumRequests DESC`).all(from, to);

    // Activity buckets for the Productivity report (PRs, newsletter, connect, dev
    // cards, agent authoring, …). `category` is the finer axis; untagged rows
    // (legacy or generic system calls) collapse into 'system'.
    const byCategory = db.prepare(`SELECT COALESCE(NULLIF(category,''),'system') AS category, ${SUMS}
      FROM usage_events WHERE ts >= ? AND ts <= ? GROUP BY category ORDER BY apiDurationMs DESC, premiumRequests DESC`).all(from, to);

    const byModel = db.prepare(`SELECT COALESCE(NULLIF(model,''),'(runtime default)') AS model, ${SUMS}
      FROM usage_events WHERE ts >= ? AND ts <= ? GROUP BY model ORDER BY premiumRequests DESC, runs DESC`).all(from, to);

    const daily = db.prepare(`SELECT substr(ts,1,10) AS day, ${SUMS}
      FROM usage_events WHERE ts >= ? AND ts <= ? GROUP BY day ORDER BY day ASC`).all(from, to);

    // Zero-fill every day in the window so the chart renders a continuous
    // time axis instead of collapsing to a single bar when activity is sparse.
    const emptyDay = (day) => ({ day, runs: 0, premiumRequests: 0, apiDurationMs: 0,
      inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 });
    const dailyMap = new Map(daily.map(r => [r.day, r]));
    const filledDaily = [];
    const fillCursor = new Date(from.slice(0, 10) + 'T00:00:00Z');
    const fillEnd = new Date(to.slice(0, 10) + 'T00:00:00Z');
    for (let d = fillCursor; d <= fillEnd; d.setUTCDate(d.getUTCDate() + 1)) {
      const key = d.toISOString().slice(0, 10);
      filledDaily.push(dailyMap.get(key) || emptyDay(key));
    }

    const dailyBySource = db.prepare(`SELECT substr(ts,1,10) AS day, source,
        SUM(CASE WHEN COALESCE(deliverable,0)=1 THEN 0 ELSE 1 END) AS runs,
        COALESCE(SUM(premium_requests),0) AS premiumRequests
      FROM usage_events WHERE ts >= ? AND ts <= ? GROUP BY day, source ORDER BY day ASC`).all(from, to);

    const dailyByCategory = db.prepare(`SELECT substr(ts,1,10) AS day, COALESCE(NULLIF(category,''),'system') AS category,
        SUM(CASE WHEN COALESCE(deliverable,0)=1 THEN 0 ELSE 1 END) AS runs, COALESCE(SUM(premium_requests),0) AS premiumRequests,
        COALESCE(SUM(api_duration_ms),0) AS apiDurationMs,
        COALESCE(SUM(input_tokens),0) + COALESCE(SUM(output_tokens),0) AS totalTokens
      FROM usage_events WHERE ts >= ? AND ts <= ? GROUP BY day, category ORDER BY day ASC`).all(from, to);

    // Per-source counts for the headline cards.
    const srcCount = {};
    for (const r of bySource) srcCount[r.source] = r.runs;

    // Flows: chain_runs is a separate table (not in the ledger).
    let flowsRun = 0;
    try { flowsRun = db.prepare(`SELECT COUNT(*) AS c FROM chain_runs WHERE started_at >= ? AND started_at <= ?`).get(from, to)?.c || 0; } catch {}

    // Total conversations (all-time): SPA chat files + mobile threads.
    let spaChats = 0;
    try { spaChats = fs.readdirSync(CHATS_DIR).filter(f => f.endsWith('.json')).length; } catch {}
    let mobileThreads = 0;
    try { mobileThreads = db.prepare(`SELECT COUNT(*) AS c FROM mobile_chat_threads`).get()?.c || 0; } catch {}

    const totals = {
      runs: agg.runs || 0,
      success: agg.success || 0,
      error: agg.error || 0,
      premiumRequests: +(agg.premiumRequests || 0).toFixed(4),
      apiDurationMs: agg.apiDurationMs || 0,
      inputTokens: agg.inputTokens || 0,
      outputTokens: agg.outputTokens || 0,
      cacheReadTokens: agg.cacheReadTokens || 0,
      cacheWriteTokens: agg.cacheWriteTokens || 0,
      totalTokens: (agg.inputTokens || 0) + (agg.outputTokens || 0),
      cost: +(((agg.premiumRequests || 0) * rate).toFixed(2)),
    };

    res.json({
      window: { from, to, days },
      rate,
      totals,
      counts: {
        agentRuns: srcCount.agent || 0,
        taskRuns: srcCount.task || 0,
        chatTurns: srcCount.chat || 0,
        flowsRun,
        totalConversations: spaChats + mobileThreads,
        spaChats,
        mobileThreads,
      },
      bySource: decorate(bySource),
      byCategory: decorate(byCategory),
      byModel: decorate(byModel),
      daily: decorate(filledDaily),
      dailyBySource,
      dailyByCategory,
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Email a rendered report. The client sends an HTML fragment (the report it is
// already showing) plus a subject/recipient; we wrap it in a self-contained
// .eml (RFC 2822) and open it in the default mail client for review — matching
// the Connect/newsletter email flow (no SMTP send).
app.post('/api/reports/email', (req, res) => {
  try {
    const html = (req.body && typeof req.body.html === 'string') ? req.body.html : '';
    const text = (req.body && typeof req.body.text === 'string') ? req.body.text : '';
    if (!html.trim() && !text.trim()) {
      return res.status(400).json({ error: 'Nothing to email — the report is empty.' });
    }
    const s = settings.getSettings();
    const to = (req.body && req.body.to) || s.reportEmailTo || s.connectEmailTo || '';
    const subject = (req.body && req.body.subject) || 'Report';

    const htmlEmail = `<html><head><meta charset="utf-8"><style>
body { font-family: Segoe UI, Arial, sans-serif; font-size: 14px; color: #1f2328; padding: 20px; background:#ffffff; }
h1 { font-size: 20px; margin: 0 0 4px; }
h2 { font-size: 15px; margin: 20px 0 8px; color:#333; }
p.sub { color:#6b7280; margin:0 0 16px; }
table { border-collapse: collapse; width: 100%; margin: 8px 0 4px; font-size: 13px; }
th, td { text-align: left; padding: 7px 10px; border-bottom: 1px solid #e5e7eb; }
th { color:#6b7280; font-weight: 600; font-size: 12px; text-transform: uppercase; letter-spacing:.02em; }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
.cards { margin: 0 0 8px; }
.cardrow { display:block; }
.stat { display:inline-block; margin:0 24px 12px 0; }
.stat .l { color:#6b7280; font-size:12px; }
.stat .v { font-size:20px; font-weight:700; }
.foot { color:#9ca3af; font-size:12px; margin-top:20px; }
</style></head><body>${html}</body></html>`;

    const boundary = `----=_Part_${Date.now()}`;
    const headers = [`Subject: ${subject}`];
    if (to) headers.push(`To: ${to}`);
    const plain = text.trim() || subject;
    const eml = [
      ...headers,
      `MIME-Version: 1.0`,
      `Content-Type: multipart/alternative; boundary="${boundary}"`,
      `X-Unsent: 1`,
      ``,
      `--${boundary}`,
      `Content-Type: text/plain; charset="utf-8"`,
      `Content-Transfer-Encoding: 8bit`,
      ``,
      plain,
      ``,
      `--${boundary}`,
      `Content-Type: text/html; charset="utf-8"`,
      `Content-Transfer-Encoding: 8bit`,
      ``,
      htmlEmail,
      ``,
      `--${boundary}--`,
    ].join('\r\n');

    const draftDir = path.join(__dirname, '.share-drafts');
    fs.mkdirSync(draftDir, { recursive: true });
    const emlPath = path.join(draftDir, `report-${Date.now()}.eml`);
    fs.writeFileSync(emlPath, eml, 'utf8');
    const { exec } = require('child_process');
    const opener = process.platform === 'darwin' ? `open "${emlPath}"`
      : process.platform === 'win32' ? `start "" "${emlPath}"`
      : `xdg-open "${emlPath}"`;
    exec(opener);
    try { recordActivity({ kind: 'email', category: 'email', title: 'Emailed report', detail: to ? `Draft opened for ${to}.` : 'Draft opened in mail client.', status: 'success', route: '#/reports', meta: { subject } }); } catch (_) {}
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

