app.post(['/api/teams', '/api/organizations'], (req, res) => {
  const { id, name, emoji, color, description, memberIds, theme } = req.body || {};
  if (!name || !String(name).trim()) {
    return res.status(400).json({ error: 'Missing required field: name' });
  }
  const teams = loadTeams();
  const teamId = id || ('team-' + String(name).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') + '-' + Date.now().toString(36).slice(-4));
  const existingIdx = teams.findIndex(o => o.id === teamId);
  const base = existingIdx >= 0 ? teams[existingIdx] : { createdAt: new Date().toISOString(), memberIds: [] };
  const team = {
    ...base,
    id: teamId,
    name: String(name).trim(),
    emoji: emoji || base.emoji || '🏢',
    color: color || base.color || '#b11f4b',
    description: description != null ? description : (base.description || ''),
    theme: theme || base.theme || 'default',
    memberIds: Array.isArray(memberIds) ? [...new Set(memberIds.filter(_employeeExists))] : (base.memberIds || []),
    updatedAt: new Date().toISOString(),
  };
  if (existingIdx >= 0) teams[existingIdx] = team; else teams.push(team);
  saveTeams(teams);
  broadcastSSE('teams-changed', { id: teamId });
  res.json({ ok: true, team });
});

// Update a team (partial)
app.put(['/api/teams/:id', '/api/organizations/:id'], (req, res) => {
  const teams = loadTeams();
  const idx = teams.findIndex(o => o.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Team not found' });
  const { name, emoji, color, description, memberIds, theme } = req.body || {};
  const team = teams[idx];
  if (name != null) team.name = String(name).trim();
  if (emoji != null) team.emoji = emoji;
  if (color != null) team.color = color;
  if (description != null) team.description = description;
  if (theme != null) team.theme = theme;
  if (Array.isArray(memberIds)) team.memberIds = [...new Set(memberIds.filter(_employeeExists))];
  team.updatedAt = new Date().toISOString();
  teams[idx] = team;
  saveTeams(teams);
  broadcastSSE('teams-changed', { id: team.id });
  res.json({ ok: true, team });
});

// Delete a team
app.delete(['/api/teams/:id', '/api/organizations/:id'], (req, res) => {
  let teams = loadTeams();
  if (!teams.some(o => o.id === req.params.id)) return res.status(404).json({ error: 'Team not found' });
  teams = teams.filter(o => o.id !== req.params.id);
  saveTeams(teams);
  broadcastSSE('teams-changed', { id: req.params.id, deleted: true });
  res.json({ ok: true });
});

// Add a member (employee) to a team
app.post(['/api/teams/:id/members', '/api/organizations/:id/members'], (req, res) => {
  const { employeeId } = req.body || {};
  if (!employeeId) return res.status(400).json({ error: 'Missing required field: employeeId' });
  if (!_employeeExists(employeeId)) return res.status(404).json({ error: 'Employee not found' });
  const teams = loadTeams();
  const idx = teams.findIndex(o => o.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Team not found' });
  if (!Array.isArray(teams[idx].memberIds)) teams[idx].memberIds = [];
  if (!teams[idx].memberIds.includes(employeeId)) teams[idx].memberIds.push(employeeId);
  teams[idx].updatedAt = new Date().toISOString();
  saveTeams(teams);
  broadcastSSE('teams-changed', { id: req.params.id });
  res.json({ ok: true, team: teams[idx] });
});

// Remove a member (employee) from a team. The employee's operations
// within this team are disabled (not deleted) by the cascade below.
app.delete(['/api/teams/:id/members/:employeeId', '/api/organizations/:id/members/:employeeId'], (req, res) => {
  const teams = loadTeams();
  const idx = teams.findIndex(o => o.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Team not found' });
  teams[idx].memberIds = (teams[idx].memberIds || []).filter(m => m !== req.params.employeeId);
  teams[idx].updatedAt = new Date().toISOString();
  saveTeams(teams);
  // Cascade: disable (don't delete) this employee's operations in this team so they
  // stay on record but go inert without a valid team context.
  const disabled = disableOperationsForEmployeeInTeam(req.params.employeeId, req.params.id);
  broadcastSSE('teams-changed', { id: req.params.id });
  res.json({ ok: true, team: teams[idx], disabled });
});

// Disable (not delete) every operation tied to this employee within this team.
// Invoked when an employee is removed from a team: tasks the agent owns,
// flows that reference the agent — all stamped with this team — are flipped
// to enabled:false and unscheduled, preserving the
// record while stopping them from firing without a valid team context.
function disableOperationsForEmployeeInTeam(employeeId, teamId) {
  const result = { tasks: [], flows: [] };
  if (!teamId) return result;
  const opTeam = (x) => (x && (x.teamId !== undefined ? x.teamId : x.orgId)) || null;

  // Tasks: agent-owned and stamped with this team.
  const tasks = loadTasks();
  let tasksChanged = false;
  for (const t of tasks) {
    if (t.agentId === employeeId && opTeam(t) === teamId && t.enabled !== false) {
      t.enabled = false; t.updatedAt = new Date().toISOString();
      try { unscheduleTask(t.id); } catch {}
      tasksChanged = true;
      result.tasks.push({ id: t.id, name: t.name || t.id });
    }
  }
  if (tasksChanged) {
    saveTasks(tasks);
    for (const dt of result.tasks) { const t = tasks.find(x => x.id === dt.id); if (t) broadcastSSE('task-updated', t); }
  }

  // Flows: stamped with this team and referencing this agent (via a step's task or an AI edge).
  try {
    const allTasks = loadTasks();
    for (const c of chainEngine.list()) {
      if (opTeam(c) !== teamId || c.enabled === false) continue;
      const viaStep = (c.steps || []).some(s => s.agentId === employeeId || allTasks.some(t => t.agentId === employeeId && (t.id === s.taskId || ('task-' + t.id) === s.taskId)));
      const viaCond = (c.edges || []).some(e => e.condition && e.condition.type === 'ai' && e.condition.agentId === employeeId);
      if (viaStep || viaCond) {
        try { chainEngine.update(c.id, { enabled: false }); result.flows.push({ id: c.id, name: c.name || c.id }); } catch {}
      }
    }
  } catch {}

  return result;
}

// ===================== BOARDS =====================
// A board is a personal pinboard for actively-tracked work. It groups pinned
// references to CLI sessions, chats, tasks, flows, and agents, plus
// freeform notes and checklists. Boards are team-scoped (teamId) or global (teamId
// null). Stored wholesale in boards.json.
const BOARD_KINDS = ['session', 'chat', 'comment', 'task', 'flow', 'agent', 'location', 'pr'];

function _boardId(name) {
  return 'board-' + String(name || 'board').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 32) + '-' + Date.now().toString(36).slice(-4);
}
function _genId(prefix) {
  return prefix + '-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}
// Server-owned runtime fields on a dev card. These are set ONLY by the dedicated
// /dev-items/* action endpoints (worktree/refresh/sync/summary/dev-agent/pr/
// remove-worktree, via ctx.save). The generic board PUT carries the client's whole
// devItems array, which may be STALE (a tab that missed the async worktree update,
// or a second client) — so a wholesale replace would clobber a ready worktreePath
// back to empty on the next unrelated edit. _mergeDevItems keeps the server
// authoritative for these fields: existing items preserve them regardless of what
// the client echoes; only client-editable metadata (title/org/project/repo/
// baseBranch/branch/workItemId/prId) is taken from the incoming array. New items
// (no matching id) keep their defaults; deleted items (dropped from the array) go away.
const DEV_RUNTIME_FIELDS = ['worktreePath', 'worktreeStatus', 'worktreeError', 'git', 'workItem', 'pr', 'summary', 'devAgentName', 'devAgentFile', 'reports', 'links', 'repos'];
function _mergeDevItems(existing, incoming) {
  const prev = new Map((Array.isArray(existing) ? existing : []).map(d => [d.id, d]));
  return (Array.isArray(incoming) ? incoming : []).map(item => {
    const old = item && item.id ? prev.get(item.id) : null;
    if (!old) return item;
    const merged = { ...item };
    for (const f of DEV_RUNTIME_FIELDS) merged[f] = old[f];
    return merged;
  });
}
// Mirror a legacy board PUT's devItems[] into the GLOBAL dev store. Runtime fields
// stay server-authoritative (never taken from the client echo): existing cards are
// patched with client-editable metadata only; brand-new cards are inserted homed on
// this board; cards the client dropped are removed (+ their report cache cleared).
function _syncBoardDevItemsToStore(boardId, teamId, incoming) {
  const list = Array.isArray(incoming) ? incoming : [];
  const keep = new Set(list.map(d => d && d.id).filter(Boolean));
  for (const card of devStore.forBoard(boardId)) {
    if (!keep.has(card.id)) {
      devStore.remove(card.id);
      try { devitems.clearReportCache(boardId, card.id); } catch {}
    }
  }
  for (const item of list) {
    if (!item) continue;
    const existing = item.id ? devStore.find(item.id) : null;
    if (existing) {
      const partial = _pickDevClientFields(item);
      partial.archived = !!item.archived;
      devStore.patch(item.id, partial);
    } else {
      // New card (created inline in the SPA): keep whatever the client built, but
      // home it on this board and scope it to the board's team.
      devStore.upsert({
        ...item,
        homeBoardId: item.homeBoardId || boardId,
        teamId: (item.teamId !== undefined ? item.teamId : teamId) || null,
      });
    }
  }
}
function _normalizeBoard(b) {
  return {
    id: b.id,
    name: b.name,
    emoji: b.emoji || '📌',
    // Accent colour for the workspace banner gradient (hex like '#6ea8fe'). Optional;
    // null => neutral banner. Replaces the old per-workspace emoji as the identity cue.
    color: (typeof b.color === 'string' && /^#[0-9a-fA-F]{6}$/.test(b.color)) ? b.color : null,
    teamId: (b.teamId !== undefined ? b.teamId : b.orgId) || null,
    items: Array.isArray(b.items) ? b.items : [],
    notes: Array.isArray(b.notes) ? b.notes : [],
    checklists: Array.isArray(b.checklists) ? b.checklists : [],
    // Dev cards: { id, title, org, project, repo, baseBranch, branch, workItemId,
    // prId, worktreePath, worktreeStatus, git, workItem, pr, summary, ... }. Group an
    // AzDo work item + PR + a git worktree; metadata persists here, heavy git/AzDo/AI
    // work runs through the dedicated /dev-items action endpoints.
    // Dev cards now live in the GLOBAL store (dev-store.js), not per-board. We
    // project the store's cards for this board here so the SPA render path (which
    // reads b.devItems -> type:'dev' panels) is unchanged. Membership = cards homed
    // on this board (provenance) plus any pinned via a board item of kind 'dev'
    // (Phase 3). The raw b.devItems on disk is a backup and is intentionally ignored.
    devItems: devStore.forBoard(
      b.id,
      (Array.isArray(b.items) ? b.items : []).filter(it => it && it.kind === 'dev').map(it => it.refId)
    ),
    layout: (b.layout && typeof b.layout === 'object' && !Array.isArray(b.layout)) ? b.layout : {},
    // Stashed items: { '<panelBaseId>': true }. Stashed pins/notes/checklists are hidden
    // from the board grid but still feed the AI context (where-was-i, assistant). Display-only.
    hidden: (b.hidden && typeof b.hidden === 'object' && !Array.isArray(b.hidden)) ? b.hidden : {},
    // Per-panel locks: { '<panelBaseId>': { vis?:true, size?:true, pos?:true } }. A lock
    // blocks that aspect from being changed by the user OR the AI/auto-layout tools, so
    // the AI is told about them and must not stash/move/resize a locked panel.
    locks: (b.locks && typeof b.locks === 'object' && !Array.isArray(b.locks)) ? b.locks : {},
    summary: (b.summary && typeof b.summary === 'object' && !Array.isArray(b.summary)) ? b.summary : null,
    archived: !!b.archived,
    enabled: b.enabled !== false,
    starred: !!b.starred,
    autoWidth: b.autoWidth !== false,
    pinView: !!b.pinView,
    autoArrange: !!b.autoArrange,
    // Named saved layouts the user can restore: [{ id, name, layout:{}, canvas:{}, createdAt }].
    // Each captures a full visual snapshot (panel grid positions/sizes + zoom/font/canvas).
    savedLayouts: Array.isArray(b.savedLayouts) ? b.savedLayouts : [],
    // User-defined briefing guidance prompts: [{ id, name, text }]. The active one (by
    // activeBriefingPromptId) is injected into the "Where was I?" LLM prompt to steer what
    // the briefing focuses on / includes. null active id => default (no extra guidance).
    briefingPrompts: Array.isArray(b.briefingPrompts) ? b.briefingPrompts.filter(p => p && p.id).map(p => ({ id: String(p.id), name: String(p.name || 'Prompt'), text: String(p.text || '') })) : [],
    activeBriefingPromptId: (b.activeBriefingPromptId != null ? String(b.activeBriefingPromptId) : null),
    lastViewedAt: b.lastViewedAt || null,
    // Last headless (AI / MCP) layout transaction, for causality-bounded undo:
    // { id, actor, at, prev:{layout,hidden}, sig } where sig is the layout
    // signature AFTER the transaction. Undo reverts only if the live board still
    // matches sig (i.e. no conflicting user edit landed since).
    layoutTxn: (b.layoutTxn && typeof b.layoutTxn === 'object' && !Array.isArray(b.layoutTxn)) ? b.layoutTxn : null,
    // Board Map: the free-canvas "map" view of this board. Persisted per-board so named
    // group frames + "you are here" highlights survive reloads/restarts.
    // { nodes:{ '<panelBaseId>':{x,y,z} }, edges:[{id,from,to,dir:'uni'|'bi'}],
    //   groups:[{id,name,x,y,w,h,members:[panelBaseId]}], highlights:{ '<panelBaseId>':true },
    //   view:{zoom,panX,panY} }. Presence of a node key = "on the map".
    map: (b.map && typeof b.map === 'object' && !Array.isArray(b.map)) ? b.map : null,
    // Per-section map store: { '<sectionId>': { nodes, edges, groups, highlights } }.
    // The current map view is section-scoped (one free-canvas per board tab); this is
    // where node positions, links, groups and "you are here" highlights persist. Must
    // round-trip through load + PUT or the map silently resets on every save.
    maps: (b.maps && typeof b.maps === 'object' && !Array.isArray(b.maps)) ? b.maps : {},
    createdAt: b.createdAt || new Date().toISOString(),
    updatedAt: b.updatedAt || new Date().toISOString(),
  };
}

// ---- Board layout intents — the single lock-aware, versioned applier --------
// One headless writer that AI Layout, the board assistant, and the board MCP all
// speak to with a FIXED, versioned vocabulary. Locks are enforced HERE (not just
// hinted in a prompt), so an external caller that targets a locked panel is
// refused and told why — locks are real, not theatre. Operates purely on the
// persisted board model (layout grid + hidden map under the locks map); no DOM,
// so it is safe to run server-side. Panel ids match the SPA's keys exactly:
// 'wherewasi' (the summary), 'pin:<itemId>', 'note:<noteId>', 'cl:<clId>'.
const BOARD_INTENT_VERSION = 1;
const BOARD_INTENT_TYPES = ['collapse', 'expand', 'stash', 'unstash', 'move', 'resize'];
const BOARD_GRID_COLS = 12;

function _boardLockFor(b, id, which) {
  const locks = (b && b.locks && typeof b.locks === 'object') ? b.locks : {};
  const l = locks[String(id || '').replace(/^pv:/, '')];
  return !!(l && l[which]);
}

// Stable signature of a board's layout + stash state, used to detect whether a
// conflicting edit landed after a headless transaction (the undo causality gate).
function _boardLayoutSig(b) {
  const L = (b && b.layout && typeof b.layout === 'object' && !Array.isArray(b.layout)) ? b.layout : {};
  const parts = Object.keys(L).sort().map(k => {
    const g = L[k] || {};
    return k + ':' + (g.x || 0) + ',' + (g.y || 0) + ',' + (g.w || 0) + ',' + (g.h || 0)
      + ',' + (g.collapsed ? 1 : 0) + ',' + (g.mh == null ? '-' : g.mh) + ',' + (g.chip ? 1 : 0);
  });
  const hidden = (b && b.hidden && typeof b.hidden === 'object') ? Object.keys(b.hidden).filter(k => b.hidden[k]).sort().join(',') : '';
  return parts.join('|') + '#' + hidden;
}

// Canonical read serialization of a board's layout state for a model / MCP. The
// panel list is built from board CONTENT (never the legacy pv: keys), so a
// headless caller addresses real panels by their stable ids and sees the live
// collapsed / stashed / locked / geometry state for each.
function boardLayoutDigest(b) {
  const layout = (b && b.layout && typeof b.layout === 'object' && !Array.isArray(b.layout)) ? b.layout : {};
  const hidden = (b && b.hidden && typeof b.hidden === 'object') ? b.hidden : {};
  const locks = (b && b.locks && typeof b.locks === 'object') ? b.locks : {};
  const panels = [];
  const push = (id, kind, title) => {
    const g = layout[id] || {};
    const base = String(id).replace(/^pv:/, '');
    const lk = locks[base] || {};
    panels.push({
      id, kind,
      title: String(title == null ? '' : title).replace(/\s+/g, ' ').trim().slice(0, 120),
      collapsed: !!g.collapsed,
      chip: !!g.chip,
      fixed: !!g.fixed,
      hidden: !!hidden[base],
      x: Number.isFinite(g.x) ? g.x : null,
      y: Number.isFinite(g.y) ? g.y : null,
      w: Number.isFinite(g.w) ? g.w : null,
      h: Number.isFinite(g.h) ? g.h : null,
      locks: { vis: !!lk.vis, size: !!lk.size, pos: !!lk.pos },
    });
  };
  push('wherewasi', 'summary', 'Where was I?');
  for (const it of (Array.isArray(b && b.items) ? b.items : [])) push('pin:' + it.id, it.kind, it.label || it.refId || it.kind);
  for (const n of (Array.isArray(b && b.notes) ? b.notes : [])) push('note:' + n.id, 'note', (n.text || '').slice(0, 80));
  for (const cl of (Array.isArray(b && b.checklists) ? b.checklists : [])) push('cl:' + cl.id, 'checklist', cl.title || 'Checklist');
  return { version: BOARD_INTENT_VERSION, cols: BOARD_GRID_COLS, panels };
}

function _summarizeBoardIntents(applied, refused) {
  const byType = {};
  for (const a of applied) byType[a.type] = (byType[a.type] || 0) + 1;
  const order = ['collapse', 'expand', 'stash', 'unstash', 'move', 'resize'];
  const verb = { collapse: 'collapsed', expand: 'expanded', stash: 'stashed', unstash: 'restored', move: 'moved', resize: 'resized' };
  const nice = order.filter(t => byType[t]).map(t => byType[t] + ' ' + verb[t]);
  let s = nice.length ? nice.join(', ') : 'no changes';
  if (refused.length) s += ` · ${refused.length} refused`;
  return s;
}

// Apply a versioned intent payload to a board's layout/hidden maps, enforcing
// locks. Returns { ok, version, layout, hidden, applied, refused, summary, changed }
// WITHOUT persisting — the caller decides whether to save + stamp an undo txn.
function applyBoardLayoutIntents(b, payload) {
  const v = payload && payload.version;
  if (v !== BOARD_INTENT_VERSION) return { ok: false, error: `Unsupported intent version (expected ${BOARD_INTENT_VERSION})` };
  const intents = Array.isArray(payload && payload.intents) ? payload.intents : [];
  if (!intents.length) return { ok: false, error: 'No intents' };
  const layout = { ...((b && b.layout) || {}) };
  const hidden = { ...((b && b.hidden) || {}) };
  const cols = BOARD_GRID_COLS;
  const known = new Set(boardLayoutDigest(b).panels.map(p => p.id));
  const applied = [], refused = [];
  // Write a patch to a panel's grid entry, mirroring to a legacy pv: twin if one
  // still exists on older boards (current boards have none).
  const patchGrid = (id, patch) => {
    layout[id] = { ...(layout[id] || { x: 0, y: 0, w: cols, h: 3 }), ...patch };
    const pv = 'pv:' + id;
    if (layout[pv]) layout[pv] = { ...layout[pv], ...patch };
  };
  for (const raw of intents.slice(0, 80)) {
    const t = raw && String(raw.type || '').toLowerCase();
    const id = raw && String(raw.target || raw.id || '');
    if (!BOARD_INTENT_TYPES.includes(t)) { refused.push({ id, type: t || '?', reason: 'unknown-intent' }); continue; }
    if (!known.has(id)) { refused.push({ id, type: t, reason: 'unknown-target' }); continue; }
    const base = id.replace(/^pv:/, '');
    if (t === 'collapse' || t === 'expand') {
      patchGrid(id, { collapsed: t === 'collapse' });
      applied.push({ id, type: t });
    } else if (t === 'stash' || t === 'unstash') {
      if (id === 'wherewasi') { refused.push({ id, type: t, reason: 'summary-cannot-stash' }); continue; }
      if (_boardLockFor(b, id, 'vis')) { refused.push({ id, type: t, reason: 'vis-locked' }); continue; }
      if (t === 'stash') hidden[base] = true; else delete hidden[base];
      applied.push({ id, type: t });
    } else if (t === 'move') {
      if (_boardLockFor(b, id, 'pos')) { refused.push({ id, type: t, reason: 'pos-locked' }); continue; }
      const patch = {};
      if (Number.isFinite(raw.x)) patch.x = Math.max(0, Math.min(cols - 1, Math.round(raw.x)));
      if (Number.isFinite(raw.y)) patch.y = Math.max(0, Math.round(raw.y));
      if (!Object.keys(patch).length) { refused.push({ id, type: t, reason: 'no-coords' }); continue; }
      patchGrid(id, patch);
      applied.push({ id, type: t, ...patch });
    } else if (t === 'resize') {
      if (_boardLockFor(b, id, 'size')) { refused.push({ id, type: t, reason: 'size-locked' }); continue; }
      const patch = {};
      if (Number.isFinite(raw.w)) patch.w = Math.max(2, Math.min(cols, Math.round(raw.w)));
      if (Number.isFinite(raw.h)) patch.h = Math.max(2, Math.round(raw.h));
      if (!Object.keys(patch).length) { refused.push({ id, type: t, reason: 'no-size' }); continue; }
      // Keep the panel on-grid: if a wider width would overflow the right edge at
      // the current x, shift x left (unless position is locked).
      const cur = layout[id] || {};
      if (patch.w && Number.isFinite(cur.x) && cur.x + patch.w > cols && !_boardLockFor(b, id, 'pos')) {
        patch.x = Math.max(0, cols - patch.w);
      }
      patchGrid(id, patch);
      applied.push({ id, type: t, ...patch });
    }
  }
  return {
    ok: true, version: BOARD_INTENT_VERSION, layout, hidden, applied, refused,
    summary: _summarizeBoardIntents(applied, refused), changed: applied.length > 0,
  };
}

app.get('/api/boards', (req, res) => {
  res.json(loadBoards().map(_normalizeBoard));
});

app.get('/api/boards/:id', (req, res) => {
  const board = loadBoards().find(b => b.id === req.params.id);
  if (!board) return res.status(404).json({ error: 'Board not found' });
  res.json(_normalizeBoard(board));
});

// ---- Layout intents API (shared by AI Layout / Ask board / board MCP) --------
// Canonical, lock-aware, versioned layout surface. Read the digest, post a batch
// of intents (locks enforced server-side → refusals are real), or undo the last
// headless transaction (only if no conflicting user edit landed since).

// Read the layout digest a model / MCP should reason over.
app.get('/api/boards/:id/layout', (req, res) => {
  const board = loadBoards().find(b => b.id === req.params.id);
  if (!board) return res.status(404).json({ error: 'Board not found' });
  res.json({ ok: true, ...boardLayoutDigest(_normalizeBoard(board)) });
});

// Apply a versioned batch of layout intents. Persists + stamps an undo txn when
// anything changed, and broadcasts so any open client reflows invisibly.
app.post('/api/boards/:id/layout/intents', (req, res) => {
  const boards = loadBoards();
  const idx = boards.findIndex(b => b.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Board not found' });
  const b = _normalizeBoard(boards[idx]);
  const actor = String((req.body && req.body.actor) || 'ai');
  const result = applyBoardLayoutIntents(b, req.body || {});
  if (!result.ok) return res.status(400).json({ ok: false, error: result.error });
  if (result.changed) {
    const prev = { layout: b.layout || {}, hidden: b.hidden || {} };
    b.layout = result.layout;
    b.hidden = result.hidden;
    b.updatedAt = new Date().toISOString();
    b.layoutTxn = { id: 'txn-' + Date.now().toString(36), actor, at: b.updatedAt, prev, sig: _boardLayoutSig(b) };
    boards[idx] = b;
    saveBoards(boards);
    broadcastSSE('boards-changed', { id: b.id });
  }
  res.json({
    ok: true, applied: result.applied, refused: result.refused,
    summary: result.summary, changed: result.changed,
    txnId: result.changed ? b.layoutTxn.id : null,
  });
});

// Undo the last headless layout transaction — but only if the live board still
// matches the post-transaction signature (i.e. the user hasn't edited since).
app.post('/api/boards/:id/layout/undo', (req, res) => {
  const boards = loadBoards();
  const idx = boards.findIndex(b => b.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Board not found' });
  const b = _normalizeBoard(boards[idx]);
  const txn = b.layoutTxn;
  if (!txn) return res.status(404).json({ ok: false, error: 'Nothing to undo' });
  if (req.body && req.body.txnId && req.body.txnId !== txn.id) {
    return res.status(409).json({ ok: false, error: 'A newer layout change exists' });
  }
  if (_boardLayoutSig(b) !== txn.sig) {
    return res.status(409).json({ ok: false, error: 'Board changed since — undo skipped' });
  }
  b.layout = (txn.prev && txn.prev.layout) || {};
  b.hidden = (txn.prev && txn.prev.hidden) || {};
  b.layoutTxn = null;
  b.updatedAt = new Date().toISOString();
  boards[idx] = b;
  saveBoards(boards);
  broadcastSSE('boards-changed', { id: b.id });
  res.json({ ok: true, undone: txn.id });
});

// Board layout writer-lease. action: 'acquire' (claim/renew if free or mine),
// 'steal' (force-claim — most-recently-active client becomes master), 'release'.
// Broadcasts 'board-lease' on any holder change so other clients drop to listener.
app.post('/api/boards/:id/lease', (req, res) => {
  const { clientId, action } = req.body || {};
  if (!clientId) return res.status(400).json({ ok: false, error: 'clientId required' });
  const boardId = req.params.id;
  const cur = boardLeaseHolder(boardId);
  if (action === 'release') {
    if (cur && cur.holderId === clientId) {
      boardLeases.delete(boardId);
      broadcastSSE('board-lease', { boardId, holderId: null });
    }
    return res.json({ ok: true, holderId: cur && cur.holderId !== clientId ? cur.holderId : null, isHolder: false });
  }
  const force = action === 'steal';
  let holderId, expiresAt = Date.now() + BOARD_LEASE_TTL_MS;
  if (!cur || cur.holderId === clientId || force) {
    const changed = !cur || cur.holderId !== clientId;
    holderId = clientId;
    boardLeases.set(boardId, { holderId, expiresAt });
    if (changed) broadcastSSE('board-lease', { boardId, holderId, expiresAt });
  } else {
    holderId = cur.holderId; // someone else holds a live lease; politely decline
    expiresAt = cur.expiresAt;
  }
  res.json({ ok: true, holderId, isHolder: holderId === clientId, ttlMs: BOARD_LEASE_TTL_MS });
});


app.post('/api/boards', (req, res) => {
  const { name, emoji, color, teamId, orgId } = req.body || {};
  if (!name || !String(name).trim()) return res.status(400).json({ error: 'Missing required field: name' });
  const boards = loadBoards();
  const board = _normalizeBoard({
    id: _boardId(name),
    name: String(name).trim(),
    emoji: emoji || '📌',
    color: color || null,
    teamId: (teamId !== undefined ? teamId : orgId) || null,
    items: [], notes: [], checklists: [],
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  });
  boards.push(board);
  saveBoards(boards);
  broadcastSSE('boards-changed', { id: board.id });
  res.json({ ok: true, board });
});

// Update a board (partial: name/emoji/teamId and/or wholesale items/notes/checklists)
app.put('/api/boards/:id', (req, res) => {
  const boards = loadBoards();
  const idx = boards.findIndex(b => b.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Board not found' });
  const b = _normalizeBoard(boards[idx]);
  const { name, emoji, color, teamId, orgId, items, notes, checklists, devItems, layout, archived, enabled, autoWidth, pinView, autoArrange, savedLayouts, starred, hidden, locks, clientId, briefingPrompts, activeBriefingPromptId, map, maps } = req.body || {};
  // Writer-lease guard: only the current lease holder may persist LAYOUT. A stale /
  // background client whose clientId != holder is rejected (409) so it cannot clobber
  // the focused client's layout. Non-layout updates (notes/checklists/items/star/...)
  // are unrestricted. No holder, or no clientId supplied, => unrestricted (back-compat).
  if (layout && typeof layout === 'object' && !Array.isArray(layout)) {
    const holder = boardLeaseHolder(req.params.id);
    if (holder && clientId && holder.holderId !== clientId) {
      return res.status(409).json({ ok: false, error: 'Not the board layout writer', holderId: holder.holderId });
    }
  }
  if (name != null) b.name = String(name).trim();
  if (emoji != null) b.emoji = emoji;
  if (color !== undefined) b.color = (typeof color === 'string' && /^#[0-9a-fA-F]{6}$/.test(color)) ? color : null;
  const teamScope = teamId !== undefined ? teamId : orgId;
  if (teamScope !== undefined) b.teamId = teamScope || null;
  if (Array.isArray(items)) b.items = items;
  if (Array.isArray(notes)) b.notes = notes;
  if (Array.isArray(checklists)) b.checklists = checklists;
  if (Array.isArray(devItems)) {
    // Detect dev cards that this PUT removes, and drop their durable report cache.
    try {
      const keepIds = new Set(devItems.map(d => d && d.id).filter(Boolean));
      for (const old of (Array.isArray(b.devItems) ? b.devItems : [])) {
        if (old && old.id && !keepIds.has(old.id)) devitems.clearReportCache(b.id, old.id);
      }
    } catch {}
    b.devItems = _mergeDevItems(b.devItems, devItems);
    // Dev cards now live in the GLOBAL store. Mirror this legacy client PUT (inline
    // metadata edits / adds / removes from the SPA) into the store so the projected
    // devItems the client reads back reflect the change.
    try { _syncBoardDevItemsToStore(b.id, b.teamId, devItems); } catch (e) { console.error('[dev-store] board PUT sync failed:', e && e.message); }
  }
  if (layout && typeof layout === 'object' && !Array.isArray(layout)) b.layout = layout;
  if (hidden && typeof hidden === 'object' && !Array.isArray(hidden)) b.hidden = hidden;
  if (locks && typeof locks === 'object' && !Array.isArray(locks)) b.locks = locks;
  if (archived !== undefined) b.archived = !!archived;
  if (enabled !== undefined) b.enabled = !!enabled;
  if (starred !== undefined) b.starred = !!starred;
  if (autoWidth !== undefined) b.autoWidth = !!autoWidth;
  if (pinView !== undefined) b.pinView = !!pinView;
  if (autoArrange !== undefined) b.autoArrange = !!autoArrange;
  if (Array.isArray(savedLayouts)) b.savedLayouts = savedLayouts;
  if (Array.isArray(briefingPrompts)) b.briefingPrompts = briefingPrompts.filter(p => p && p.id).map(p => ({ id: String(p.id), name: String(p.name || 'Prompt'), text: String(p.text || '') }));
  if (activeBriefingPromptId !== undefined) b.activeBriefingPromptId = (activeBriefingPromptId != null ? String(activeBriefingPromptId) : null);
  if (map && typeof map === 'object' && !Array.isArray(map)) b.map = map;
  if (maps && typeof maps === 'object' && !Array.isArray(maps)) b.maps = maps;
  b.updatedAt = new Date().toISOString();
  boards[idx] = b;
  saveBoards(boards);
  broadcastSSE('boards-changed', { id: b.id });
  res.json({ ok: true, board: b });
});

// Delete a board
app.delete('/api/boards/:id', (req, res) => {
  let boards = loadBoards();
  if (!boards.some(b => b.id === req.params.id)) return res.status(404).json({ error: 'Board not found' });
  boards = boards.filter(b => b.id !== req.params.id);
  saveBoards(boards);
  broadcastSSE('boards-changed', { id: req.params.id, deleted: true });
  res.json({ ok: true });
});

// Pin an item to a board
app.post('/api/boards/:id/items', (req, res) => {
  const { kind, refId, label, sublabel, meta } = req.body || {};
  if (!kind || !BOARD_KINDS.includes(kind)) return res.status(400).json({ error: 'Invalid kind' });
  if (!refId) return res.status(400).json({ error: 'Missing refId' });
  const boards = loadBoards();
  const idx = boards.findIndex(b => b.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Board not found' });
  const b = _normalizeBoard(boards[idx]);
  if (b.items.some(it => it.kind === kind && it.refId === refId)) {
    return res.json({ ok: true, board: b, alreadyPinned: true });
  }
  const item = { id: _genId('pin'), kind, refId, label: label || refId, sublabel: sublabel || '', addedAt: new Date().toISOString() };
  // PR pins carry an identity snapshot (exact-case org/project/repo + prId/url/view/title)
  // so the board can drive Code Flow PR actions (worktree/review/sync/push/comments)
  // without a live AzDo lookup. Stored as-is and preserved by _normalizeBoard.
  if (meta && typeof meta === 'object' && !Array.isArray(meta)) {
    const m = {};
    for (const k of ['org', 'project', 'repo', 'prId', 'url', 'view', 'title', 'role', 'ts', 'branch', 'provider']) {
      if (meta[k] != null) m[k] = String(meta[k]);
    }
    // Comment pins snapshot the full message body so each pin renders ITS OWN
    // text — never re-resolved by a fragile timestamp match that could collapse
    // two distinct comment pins to the chat's latest message. Capped to keep
    // boards.json lean.
    if (meta.content != null) m.content = String(meta.content).slice(0, 8000);
    if (Object.keys(m).length) item.meta = m;
  }
  b.items.unshift(item);
  b.updatedAt = new Date().toISOString();
  boards[idx] = b;
  saveBoards(boards);
  broadcastSSE('boards-changed', { id: b.id });
  res.json({ ok: true, board: b });
});

// Unpin an item from a board
app.delete('/api/boards/:id/items/:itemId', (req, res) => {
  const boards = loadBoards();
  const idx = boards.findIndex(b => b.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Board not found' });
  const b = _normalizeBoard(boards[idx]);
  b.items = b.items.filter(it => it.id !== req.params.itemId);
  b.updatedAt = new Date().toISOString();
  boards[idx] = b;
  saveBoards(boards);
  broadcastSSE('boards-changed', { id: b.id });
  res.json({ ok: true, board: b });
});

// Update a pinned item's metadata (currently: excludeFromSummary toggle). The item
// stays on the board either way; excludeFromSummary only controls whether it feeds
// the "Where was I?" briefing and the insights derived from it.
app.patch('/api/boards/:id/items/:itemId', (req, res) => {
  const boards = loadBoards();
  const idx = boards.findIndex(b => b.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Board not found' });
  const b = _normalizeBoard(boards[idx]);
  const it = b.items.find(x => x.id === req.params.itemId);
  if (!it) return res.status(404).json({ error: 'Item not found' });
  if (req.body && 'excludeFromSummary' in req.body) {
    if (req.body.excludeFromSummary) it.excludeFromSummary = true;
    else delete it.excludeFromSummary;
  }
  b.updatedAt = new Date().toISOString();
  boards[idx] = b;
  saveBoards(boards);
  broadcastSSE('boards-changed', { id: b.id });
  res.json({ ok: true, board: b });
});

// ===================== SOURCE LOCATIONS (folder pins) =====================
// Helpers + endpoints backing the "pin a source location" board feature: derive a
// README summary, open the folder in an editor / CLI / file explorer, and search it.
function _validDir(p) {
  try { const s = fs.statSync(p); return s.isDirectory(); } catch { return false; }
}
// True when the folder is (or sits inside) a git repo. A worktree/submodule uses a
// .git file rather than a directory, so accept either; walk up to catch subfolders.
function _isGitRepo(p) {
  try {
    let dir = path.resolve(p);
    for (let i = 0; i < 40; i++) {
      if (fs.existsSync(path.join(dir, '.git'))) return true;
      const parent = path.dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
  } catch {}
  return false;
}
// Current git branch for a folder (or the repo it sits in), or '' if not a repo /
// indeterminable. Reads .git/HEAD directly (no shelling out): a normal repo has a
// .git directory; a worktree/submodule has a .git FILE containing "gitdir: <path>".
// HEAD is either "ref: refs/heads/<branch>" or a raw SHA when detached.
function _gitBranch(p) {
  try {
    let dir = path.resolve(p), gitPath = null;
    for (let i = 0; i < 40; i++) {
      const cand = path.join(dir, '.git');
      if (fs.existsSync(cand)) { gitPath = cand; break; }
      const parent = path.dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
    if (!gitPath) return '';
    let gitDir = gitPath;
    const st = fs.statSync(gitPath);
    if (st.isFile()) {
      const m = fs.readFileSync(gitPath, 'utf8').match(/gitdir:\s*(.+)\s*/);
      if (!m) return '';
      gitDir = path.resolve(dir, m[1].trim());
    }
    const head = fs.readFileSync(path.join(gitDir, 'HEAD'), 'utf8').trim();
    const ref = head.match(/^ref:\s*refs\/heads\/(.+)$/);
    if (ref) return ref[1].trim();
    return head.length >= 7 ? `(detached @ ${head.slice(0, 8)})` : '';
  } catch { return ''; }
}
// Directories we never descend into when summarizing / searching a source folder.
const FS_SKIP_DIRS = new Set(['.git', 'node_modules', '.vs', '.vscode', 'bin', 'obj', 'dist', 'build', 'out', '.next', '.cache', '__pycache__', '.venv', 'venv', 'target', 'packages']);

// Brief summary of a folder, sourced from its README when present.
app.post('/api/fs/folder-summary', (req, res) => {
  const dir = String((req.body && req.body.path) || '').trim();
  if (!dir) return res.status(400).json({ error: 'path required' });
  if (!_validDir(dir)) return res.status(404).json({ error: 'Folder not found', path: dir });
  const rs = _readmeSummary(dir, 320);
  res.json({ ok: true, path: dir, name: path.basename(dir.replace(/[\\/]+$/, '')) || dir, summary: rs.summary, hasReadme: rs.hasReadme, readmePath: rs.readmePath, isGit: _isGitRepo(dir) });
});

// List immediate child directories of a path, for the source-location folder
// browser. With no path (or path === ''), returns the available roots — drive
// letters on Windows plus a few convenient starting points (home, repos). Files
// are omitted; we only browse folders since a pinned location is always a folder.
app.post('/api/fs/list', (req, res) => {
  const raw = String((req.body && req.body.path) || '').trim();
  try {
    // Root view: drives + handy shortcuts.
    if (!raw) {
      const roots = [];
      const seen = new Set();
      const add = (p, label) => {
        if (!p || seen.has(p) || !_validDir(p)) return;
        seen.add(p);
        roots.push({ name: label || p, path: p, isGit: false });
      };
      if (process.platform === 'win32') {
        for (let c = 67 /* C */; c <= 90 /* Z */; c++) {
          const drive = String.fromCharCode(c) + ':\\';
          if (_validDir(drive)) roots.push({ name: drive, path: drive, isGit: false, drive: true });
        }
        add(process.env.USERPROFILE, '🏠 ' + (process.env.USERNAME || 'Home'));
        add(process.env.USERPROFILE ? path.join(process.env.USERPROFILE, 'repos') : '', '📦 repos');
        add('C:\\repos', '📦 C:\\repos');
      } else {
        add(process.env.HOME, '🏠 Home');
        add('/', '/');
      }
      return res.json({ ok: true, path: '', parent: null, dirs: roots });
    }
    if (!_validDir(raw)) return res.status(404).json({ error: 'Folder not found', path: raw });
    const dir = path.resolve(raw);
    const parentDir = path.dirname(dir);
    const parent = parentDir && parentDir !== dir ? parentDir : '';
    let entries = [];
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (e) {
      return res.status(403).json({ error: 'Cannot read folder', path: dir });
    }
    const dirs = entries
      .filter(e => { try { return e.isDirectory(); } catch { return false; } })
      .map(e => e.name)
      .filter(name => !name.startsWith('$') && name !== 'node_modules')
      .sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }))
      .slice(0, 500)
      .map(name => {
        const full = path.join(dir, name);
        return { name, path: full, hidden: name.startsWith('.'), isGit: fs.existsSync(path.join(full, '.git')) };
      });
    res.json({ ok: true, path: dir, parent, isGit: _isGitRepo(dir), dirs });
  } catch (e) {
    res.status(500).json({ error: (e && e.message) || 'list failed' });
  }
});

// Open a folder in an editor (VS Code Insiders → VS Code), a Copilot CLI session, or
// the OS file explorer.
app.post('/api/fs/open', (req, res) => {
  const dir = String((req.body && req.body.path) || '').trim();
  const target = String((req.body && req.body.target) || 'editor').trim();
  if (!dir) return res.status(400).json({ error: 'path required' });
  if (!_validDir(dir)) return res.status(404).json({ error: 'Folder not found', path: dir });
  const { spawn, spawnSync, exec } = require('child_process');
  try {
    if (target === 'explorer') {
      // explorer returns exit code 1 even on success; ignore it.
      spawn('explorer.exe', [dir], { detached: true, stdio: 'ignore' }).unref();
      return res.json({ ok: true, target });
    }
    if (target === 'diff') {
      // Open VS Code's native side-by-side diff editor for the branch's changes. We diff
      // against the merge-base with the repo's default branch (so it's the branch's own
      // work, not unrelated upstream commits), include working-tree edits, and open one
      // real diff tab per changed file (base version on the left, the live worktree file on
      // the right) in a single reused window — a proper "review like a PR" experience.
      const os = require('os');
      const git = (args, opts) => spawnSync('git', args, Object.assign({ cwd: dir, maxBuffer: 96 * 1024 * 1024 }, opts || {}));
      const gitText = (args) => { const r = git(args, { encoding: 'utf-8' }); return r.status === 0 ? (r.stdout || '') : ''; };
      const headRef = gitText(['rev-parse', '--abbrev-ref', 'HEAD']).trim();
      // Resolve the default branch: prefer origin/HEAD, then common fallbacks.
      let base = '';
      const oh = git(['symbolic-ref', '-q', 'refs/remotes/origin/HEAD'], { encoding: 'utf-8' });
      if (oh.status === 0 && oh.stdout.trim()) base = oh.stdout.trim().replace(/^refs\/remotes\//, '');
      if (!base) {
        for (const cand of ['origin/main', 'origin/master', 'main', 'master']) {
          if (git(['rev-parse', '--verify', '--quiet', cand], { encoding: 'utf-8' }).status === 0) { base = cand; break; }
        }
      }
      let from = base || '';
      if (base) { const mb = git(['merge-base', base, 'HEAD'], { encoding: 'utf-8' }); if (mb.status === 0 && mb.stdout.trim()) from = mb.stdout.trim(); }
      if (!from) return res.status(422).json({ error: 'Could not determine a base branch to diff against.' });
      const baseLabel = base || from.slice(0, 12);
      // Changed files vs the base (rename/copy aware), including uncommitted working changes.
      const ns = gitText(['diff', '--name-status', '-M', '--no-color', from]);
      const rows = ns.split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
      // Also include brand-new untracked files (git diff omits them) as add-diffs.
      const untracked = gitText(['ls-files', '--others', '--exclude-standard'])
        .split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
      for (const u of untracked) rows.push(`A\t${u}`);
      if (!rows.length) return res.json({ ok: true, target, empty: true, base: baseLabel });
      const CAP = 40;
      const safe = (headRef || 'branch').replace(/[^A-Za-z0-9._-]+/g, '-').slice(0, 50) || 'branch';
      const tmpRoot = path.join(os.tmpdir(), `devdiff-${safe}-${Date.now().toString(36)}`);
      const baseDir = path.join(tmpRoot, 'base');
      fs.mkdirSync(baseDir, { recursive: true });
      // Materialize a file's base-revision content into a temp file (empty if it didn't
      // exist at the base). Mirrors the repo path so VS Code applies the right language.
      const writeBlob = (relPosix, idx) => {
        const safeRel = relPosix.replace(/[<>:"|?*]/g, '_');
        const dest = path.join(baseDir, String(idx), safeRel.split('/').join(path.sep));
        fs.mkdirSync(path.dirname(dest), { recursive: true });
        const r = git(['show', `${from}:${relPosix}`], { encoding: 'buffer' });
        fs.writeFileSync(dest, r.status === 0 ? r.stdout : Buffer.alloc(0));
        return dest;
      };
      const emptyFor = (relPosix, idx) => {
        const safeRel = relPosix.replace(/[<>:"|?*]/g, '_');
        const dest = path.join(tmpRoot, 'gone', String(idx), safeRel.split('/').join(path.sep));
        fs.mkdirSync(path.dirname(dest), { recursive: true });
        fs.writeFileSync(dest, '');
        return dest;
      };
      const pairs = [];
      for (const row of rows) {
        const parts = row.split('\t');
        const status = (parts[0] || '')[0];
        const oldRel = parts[1];
        const newRel = (status === 'R' || status === 'C') ? (parts[2] || parts[1]) : parts[1];
        if (!oldRel) continue;
        const idx = pairs.length;
        let left, right;
        if (status === 'A') { left = emptyFor(newRel, idx); right = path.join(dir, newRel.split('/').join(path.sep)); }
        else if (status === 'D') { left = writeBlob(oldRel, idx); right = emptyFor(oldRel, idx); }
        else { left = writeBlob(oldRel, idx); right = path.join(dir, newRel.split('/').join(path.sep)); }
        pairs.push({ left, right });
        if (pairs.length >= CAP) break;
      }
      if (!pairs.length) return res.json({ ok: true, target, empty: true, base: baseLabel });
      // Resolve the editor's full launcher path (more robust than relying on PATH inside the
      // shell). `where` can return several lines — take the first.
      let editor = '';
      const whichIns = spawnSync('where', ['code-insiders'], { shell: true, encoding: 'utf-8' });
      if (whichIns.status === 0 && whichIns.stdout.trim()) editor = whichIns.stdout.split(/\r?\n/)[0].trim();
      if (!editor) {
        const whichCode = spawnSync('where', ['code'], { shell: true, encoding: 'utf-8' });
        if (whichCode.status === 0 && whichCode.stdout.trim()) editor = whichCode.stdout.split(/\r?\n/)[0].trim();
      }
      if (!editor) editor = 'code';
      const editorName = path.basename(editor).replace(/\.(cmd|exe|bat)$/i, '');
      // Run the editor launcher via `cmd /c` with an args array so Node quotes each path
      // (spaces survive). Always open a brand-new window for this diff session so it never
      // co-mingles with other VS Code work — the first file opens the new window, and the
      // rest attach to it via --reuse-window (staggered so they land in the new window).
      const cmdExe = process.env.ComSpec || 'cmd.exe';
      const launchDiff = (pr, fresh) => {
        const winArg = fresh ? '--new-window' : '--reuse-window';
        spawn(cmdExe, ['/c', editor, winArg, '--diff', pr.left, pr.right], { detached: true, stdio: 'ignore' }).unref();
      };
      launchDiff(pairs[0], true);
      pairs.slice(1).forEach((pr, i) => {
        // Give the new window time to come up before the first reuse, then space the rest out.
        setTimeout(() => launchDiff(pr, false), 1100 + i * 350);
      });
      return res.json({ ok: true, target, editor: editorName, base: baseLabel, files: pairs.length, total: rows.length, truncated: rows.length > pairs.length });
    }
    if (target === 'devcmd') {
      // Open a Visual Studio Developer Command Prompt in the worktree. Locate
      // VsDevCmd.bat via vswhere (the well-known installer path); if VS isn't
      // installed, fall back to a plain command prompt at the folder.
      let vsDevCmd = '';
      try {
        const pf86 = process.env['ProgramFiles(x86)'] || 'C:\\Program Files (x86)';
        const vswhere = path.join(pf86, 'Microsoft Visual Studio', 'Installer', 'vswhere.exe');
        if (fs.existsSync(vswhere)) {
          const r = spawnSync(vswhere, ['-latest', '-prerelease', '-products', '*', '-property', 'installationPath'], { encoding: 'utf-8' });
          const installPath = (r.status === 0 ? (r.stdout || '') : '').split(/\r?\n/)[0].trim();
          if (installPath) {
            const cand = path.join(installPath, 'Common7', 'Tools', 'VsDevCmd.bat');
            if (fs.existsSync(cand)) vsDevCmd = cand;
          }
        }
      } catch { /* best-effort; fall back to a plain prompt */ }
      const lines = ['@echo off', `if not exist "${dir}" goto nodir`];
      if (vsDevCmd) lines.push(`call "${vsDevCmd}" -startdir=none`);
      else lines.push('echo Visual Studio Developer Command Prompt not found - opening a plain prompt.');
      lines.push(
        `cd /d "${dir}"`,
        'cmd /k',
        'exit /b 0',
        ':nodir', `echo ERROR: Working directory not found: ${dir}`, 'pause', 'exit /b 1'
      );
      const batPath = path.join(__dirname, `temp-loc-devcmd-${Date.now().toString(36)}.bat`);
      fs.writeFileSync(batPath, lines.join('\r\n'));
      exec(`start "Developer Command Prompt" "${batPath}"`);
      return res.json({ ok: true, target, vsDevCmd: vsDevCmd || null });
    }
    if (target === 'cli') {
      const copilotCmd = process.env.COPILOT_PATH || 'copilot';
      const copilotIsPath = /[\\/:]/.test(copilotCmd);
      const guardLines = copilotIsPath
        ? [`if not exist "${copilotCmd}" goto nocopilot`]
        : [`where "${copilotCmd}" >nul 2>&1`, 'if errorlevel 1 goto nocopilot'];
      // Optional: pre-select a project agent (e.g. a dev card's dev agent).
      const agentName = String((req.body && req.body.agent) || '').trim().replace(/"/g, '');
      const agentFlag = agentName ? ` --agent "${agentName}"` : '';
      const batContent = [
        '@echo off',
        `if not exist "${dir}" goto nodir`,
        `cd /d "${dir}"`,
        ...guardLines,
        `"${copilotCmd}"${agentFlag} --yolo`,
        'pause', 'exit /b 0',
        ':nodir', `echo ERROR: Working directory not found: ${dir}`, 'pause', 'exit /b 1',
        ':nocopilot', 'echo ERROR: copilot not found in PATH', 'echo PATH=%PATH%', 'pause', 'exit /b 1',
      ].join('\r\n');
      const batPath = path.join(__dirname, `temp-loc-cli-${Date.now().toString(36)}.bat`);
      fs.writeFileSync(batPath, batContent);
      exec(`start "Copilot Session" "${batPath}"`);
      return res.json({ ok: true, target });
    }
    // default: editor (Insiders preferred). target 'code' forces stable VS Code.
    if (target === 'code') {
      spawn('code', [dir], { shell: true, detached: true, stdio: 'ignore' }).unref();
      return res.json({ ok: true, target, editor: 'code' });
    }
    const insiders = spawnSync('where', ['code-insiders'], { shell: true, encoding: 'utf-8' });
    const editor = insiders.status === 0 ? 'code-insiders' : 'code';
    spawn(editor, [dir], { shell: true, detached: true, stdio: 'ignore' }).unref();
    return res.json({ ok: true, target, editor });
  } catch (e) {
    return res.status(500).json({ error: (e && e.message) || 'open failed' });
  }
});

// Open an http/https URL in the user's default browser. This exists mainly for
// the packaged desktop app, whose WebView2 shell has no browser tabs — so the
// SPA's target="_blank" anchors / window.open() calls are routed here instead
// (see the desktop external-link bridge in app.html). Only http(s) is allowed.
app.post('/api/open-external', (req, res) => {
  const url = String((req.body && req.body.url) || '').trim();
  if (!url) return res.status(400).json({ error: 'url required' });
  let parsed;
  try { parsed = new URL(url); } catch { return res.status(400).json({ error: 'invalid url' }); }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    return res.status(400).json({ error: 'only http/https urls are allowed' });
  }
  const { spawn } = require('child_process');
  try {
    if (process.platform === 'win32') {
      // rundll32 FileProtocolHandler opens the default browser without a cmd
      // shell and without mangling '&' in query strings the way `start` does.
      spawn('rundll32', ['url.dll,FileProtocolHandler', parsed.href], {
        detached: true, stdio: 'ignore', windowsHide: true
      }).unref();
    } else if (process.platform === 'darwin') {
      spawn('open', [parsed.href], { detached: true, stdio: 'ignore' }).unref();
    } else {
      spawn('xdg-open', [parsed.href], { detached: true, stdio: 'ignore' }).unref();
    }
    return res.json({ ok: true });
  } catch (e) {
    return res.status(500).json({ error: (e && e.message) || 'open failed' });
  }
});
// REQ-11: open an email link, preferring the DESKTOP mail client, falling back to
// the browser. Unlike /api/open-external (which uses rundll32 FileProtocolHandler and
// therefore always lands in the default *browser*), this uses ShellExecute
// (Start-Process / open / xdg-open) so Windows honours a per-app link claim — e.g.
// the "New Outlook" / classic Outlook "open supported links in Outlook" association —
// and routes outlook.office.com deeplinks straight into the desktop app when present.
// If no desktop handler claims the URL, the OS opens it in the browser, so this is a
// genuine "desktop first, browser fallback" without needing a Tauri rebuild.
// NOTE: only meaningful when the SERVER runs on the user's own machine (desktop shell
// or local browser); the client gates on that so LAN/mobile callers keep using the
// browser directly rather than launching Outlook on a remote host.
app.post('/api/me-ai/open-email', (req, res) => {
  const url = String((req.body && req.body.url) || '').trim();
  if (!url) return res.status(400).json({ error: 'url required' });
  let parsed;
  try { parsed = new URL(url); } catch { return res.status(400).json({ error: 'invalid url' }); }
  const okProto = ['http:', 'https:', 'mailto:', 'ms-outlook:'].includes(parsed.protocol);
  if (!okProto) return res.status(400).json({ error: 'unsupported url scheme' });
  const { spawn } = require('child_process');
  try {
    if (process.platform === 'win32') {
      // Start-Process uses ShellExecute (honours app link-association). PowerShell
      // takes the whole URL as one argument, so '&' in OWA query strings is safe
      // (unlike `start`, which splits on '&'). Single-quote-escape for the -Command.
      const safe = parsed.href.replace(/'/g, "''");
      spawn('powershell', ['-NoProfile', '-WindowStyle', 'Hidden', '-Command',
        `Start-Process -FilePath '${safe}'`], { detached: true, stdio: 'ignore', windowsHide: true }).unref();
    } else if (process.platform === 'darwin') {
      spawn('open', [parsed.href], { detached: true, stdio: 'ignore' }).unref();
    } else {
      spawn('xdg-open', [parsed.href], { detached: true, stdio: 'ignore' }).unref();
    }
    return res.json({ ok: true });
  } catch (e) {
    return res.status(500).json({ error: (e && e.message) || 'open failed' });
  }
});
// bounded Node recursive scan. Returns file/line/snippet matches.
function _fsSearchNode(root, query, maxMatches) {
  const ql = query.toLowerCase();
  const matches = [];
  let scanned = 0;
  const walk = (dir, depth) => {
    if (matches.length >= maxMatches || depth > 12 || scanned > 20000) return;
    let entries = [];
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const ent of entries) {
      if (matches.length >= maxMatches) return;
      const full = path.join(dir, ent.name);
      if (ent.isDirectory()) {
        if (FS_SKIP_DIRS.has(ent.name) || ent.name.startsWith('.')) continue;
        walk(full, depth + 1);
      } else if (ent.isFile()) {
        scanned++;
        let st; try { st = fs.statSync(full); } catch { continue; }
        if (st.size > 1_500_000) continue; // skip large/binary
        let txt; try { txt = fs.readFileSync(full, 'utf-8'); } catch { continue; }
        if (txt.indexOf('\u0000') !== -1) continue; // binary
        const lines = txt.split(/\r?\n/);
        for (let i = 0; i < lines.length; i++) {
          if (lines[i].toLowerCase().includes(ql)) {
            matches.push({ file: path.relative(root, full), line: i + 1, text: lines[i].trim().slice(0, 240) });
            if (matches.length >= maxMatches) return;
          }
        }
      }
    }
  };
  walk(root, 0);
  return matches;
}
// Synchronous "search a folder" used by both the manual /api/fs/search endpoint,
// the confirm-gated /assistant/search, and the board assistant's automatic search.
// Prefers ripgrep, falls back to a bounded Node scan. Returns file/line/snippet rows.
function _locationSearch(dir, query, maxMatches = 80) {
  const { spawnSync } = require('child_process');
  try {
    const rg = spawnSync('rg', ['--no-heading', '--line-number', '--color', 'never', '-i', '--max-count', '3', '-m', String(maxMatches), '--', query, dir], { encoding: 'utf-8', maxBuffer: 8 * 1024 * 1024, timeout: 15000 });
    if (rg.status === 0 || rg.status === 1) {
      const matches = [];
      for (const ln of String(rg.stdout || '').split(/\r?\n/)) {
        if (!ln || matches.length >= maxMatches) break;
        const m = ln.match(/^(.*?):(\d+):(.*)$/);
        if (m) matches.push({ file: path.relative(dir, m[1]), line: parseInt(m[2], 10), text: m[3].trim().slice(0, 240) });
      }
      return matches;
    }
  } catch {}
  return _fsSearchNode(dir, query, maxMatches);
}
app.post('/api/fs/search', (req, res) => {
  const dir = String((req.body && req.body.path) || '').trim();
  const query = String((req.body && req.body.query) || '').trim();
  const maxMatches = Math.min(Math.max(parseInt((req.body && req.body.max), 10) || 60, 1), 200);
  if (!dir || !query) return res.status(400).json({ error: 'path and query required' });
  if (!_validDir(dir)) return res.status(404).json({ error: 'Folder not found', path: dir });
  const { spawnSync } = require('child_process');
  // Try ripgrep first (fast, respects .gitignore, skips binary).
  try {
    const args = ['--no-heading', '--line-number', '--color', 'never', '-i', '--max-count', '3', '-m', String(maxMatches), '--', query, dir];
    const rg = spawnSync('rg', args, { encoding: 'utf-8', maxBuffer: 8 * 1024 * 1024, timeout: 15000 });
    if (rg.status === 0 || rg.status === 1) {
      const matches = [];
      for (const ln of String(rg.stdout || '').split(/\r?\n/)) {
        if (!ln || matches.length >= maxMatches) break;
        // <file>:<line>:<text>
        const m = ln.match(/^(.*?):(\d+):(.*)$/);
        if (!m) continue;
        matches.push({ file: path.relative(dir, m[1]), line: parseInt(m[2], 10), text: m[3].trim().slice(0, 240) });
      }
      return res.json({ ok: true, engine: 'rg', query, count: matches.length, truncated: matches.length >= maxMatches, matches });
    }
  } catch {}
  // Fallback: Node scan.
  try {
    const matches = _fsSearchNode(dir, query, maxMatches);
    return res.json({ ok: true, engine: 'node', query, count: matches.length, truncated: matches.length >= maxMatches, matches });
  } catch (e) {
    return res.status(500).json({ error: (e && e.message) || 'search failed' });
  }
});


// team for the board to be usable. An item belongs when:
//   - operation (task/flow): its own teamId === board.teamId AND each
//     component agent is a member of the team.
//   - employee pin (agent): the employee is a member of the team.
//   - chat/comment: the chat's target employee is a member of the team.
//   - session/note/checklist: always compliant.
// Boards with no team, or whose team was deleted, are never blocked. Pins whose
// underlying item no longer exists are skipped (not a team problem). When any
// item is non-compliant the board is "blocked" in the UI until resolved.

function _teamById(id) { return loadTeams().find(t => t.id === id) || null; }
function _teamName(id) { const t = _teamById(id); return t ? (t.name || id) : (id || null); }
function _employeeNameOf(id) {
  const a = supervisor.agents.get(id); if (a) return a.config.name || a.config.agent || id;
  return id;
}
function _opTeamOf(x) { return (x && (x.teamId !== undefined ? x.teamId : x.orgId)) || null; }
function _findTaskByRef(refId) {
  const tasks = loadTasks();
  const rawId = String(refId).replace(/^task-/, '');
  return tasks.find(x => x.id === rawId || ('task-' + x.id) === refId || x.id === refId) || null;
}
function _chatTargetEmployeeOf(refId, kind) {
  let chatId = String(refId);
  if (kind === 'comment') { const i = chatId.indexOf('~'); if (i >= 0) chatId = chatId.slice(0, i); }
  try { const cf = path.join(CHATS_DIR, `${chatId}.json`); if (fs.existsSync(cf)) { const c = JSON.parse(fs.readFileSync(cf, 'utf-8')); return c.target || null; } } catch {}
  return null;
}
// The "component employees" an operation depends on (must be team members too).
function _opComponentEmployees(item) {
  const out = [];
  if (item.kind === 'task') {
    const t = _findTaskByRef(item.refId);
    if (t && t.agentId) out.push({ employeeId: t.agentId, role: 'agent' });
  } else if (item.kind === 'flow') {
    let c = null; try { c = chainEngine.get(item.refId); } catch {}
    if (c) {
      const tasks = loadTasks();
      const set = new Set();
      for (const s of (c.steps || [])) { if (s.agentId) { set.add(s.agentId); continue; } const t = tasks.find(t => t.id === s.taskId || ('task-' + t.id) === s.taskId); if (t && t.agentId) set.add(t.agentId); }
      for (const e of (c.edges || [])) { if (e.condition && e.condition.type === 'ai' && e.condition.agentId) set.add(e.condition.agentId); }
      for (const id of set) out.push({ employeeId: id, role: 'agent' });
    }
  }
  return out;
}

function computeBoardCompliance(boardRaw) {
  const b = _normalizeBoard(boardRaw);
  // Team feature removed — every agent/task/flow lives in the same (no) team, so a
  // board can never be blocked by team membership. Always fail open.
  return { boardId: b.id, teamId: null, teamName: null, ok: true, blocked: false, issues: [] };
  // eslint-disable-next-line no-unreachable
  const teamId = b.teamId;
  if (!teamId) return { boardId: b.id, teamId: null, teamName: null, ok: true, blocked: false, issues: [] };
  const team = _teamById(teamId);
  if (!team) return { boardId: b.id, teamId, teamName: null, ok: true, blocked: false, issues: [] };
  const teamName = team.name || teamId;
  const members = new Set(team.memberIds || []);
  const inTeam = (id) => members.has(id);
  const OP_KINDS = new Set(['task', 'flow']);
  const EMP_KINDS = new Set(['agent']);
  const EMP_ACTIONS = ['add_member', 'move_member'];
  const issues = [];

  for (const it of b.items) {
    const problems = [];
    if (OP_KINDS.has(it.kind)) {
      let opTeam = null, found = false;
      if (it.kind === 'task') { const t = _findTaskByRef(it.refId); if (t) { found = true; opTeam = _opTeamOf(t); } }
      else if (it.kind === 'flow') { let c = null; try { c = chainEngine.get(it.refId); } catch {} if (c) { found = true; opTeam = _opTeamOf(c); } }
      if (!found) continue; // unresolved pin — not a team problem
      if (opTeam !== teamId) {
        problems.push({ kind: 'op_team', opKind: it.kind, currentTeamId: opTeam, currentTeamName: opTeam ? _teamName(opTeam) : null, actions: ['clone_op', 'move_op'] });
      }
      for (const ce of _opComponentEmployees(it)) {
        if (!inTeam(ce.employeeId)) problems.push({ kind: 'employee', role: ce.role, employeeId: ce.employeeId, employeeName: _employeeNameOf(ce.employeeId), component: true, actions: EMP_ACTIONS });
      }
    } else if (EMP_KINDS.has(it.kind)) {
      if (!_employeeExists(it.refId)) continue;
      if (!inTeam(it.refId)) problems.push({ kind: 'employee', role: 'agent', employeeId: it.refId, employeeName: _employeeNameOf(it.refId), actions: EMP_ACTIONS });
    } else if (it.kind === 'chat' || it.kind === 'comment') {
      const target = _chatTargetEmployeeOf(it.refId, it.kind);
      if (!target) continue;
      if (!inTeam(target)) problems.push({ kind: 'employee', role: 'agent', employeeId: target, employeeName: _employeeNameOf(target), viaChat: true, actions: EMP_ACTIONS });
    }
    if (problems.length) issues.push({ itemId: it.id, kind: it.kind, refId: it.refId, label: it.label || it.refId, sublabel: it.sublabel || '', problems, canRemove: true });
  }
  const blocked = issues.length > 0;
  return { boardId: b.id, teamId, teamName, ok: !blocked, blocked, issues };
}

// ---- compliance mutation helpers ----
function _addEmployeeToTeam(teamId, employeeId) {
  const teams = loadTeams();
  const idx = teams.findIndex(t => t.id === teamId);
  if (idx < 0) return false;
  if (!Array.isArray(teams[idx].memberIds)) teams[idx].memberIds = [];
  if (!teams[idx].memberIds.includes(employeeId)) teams[idx].memberIds.push(employeeId);
  teams[idx].updatedAt = new Date().toISOString();
  saveTeams(teams);
  broadcastSSE('teams-changed', { id: teamId });
  return true;
}
// Move = remove the employee from every OTHER team (with the same disable cascade
// used by the members DELETE route), then add to the target team.
function _moveEmployeeToTeam(teamId, employeeId) {
  const teams = loadTeams();
  const removedFrom = [];
  for (const t of teams) {
    if (t.id !== teamId && (t.memberIds || []).includes(employeeId)) {
      t.memberIds = t.memberIds.filter(m => m !== employeeId);
      t.updatedAt = new Date().toISOString();
      removedFrom.push(t.id);
    }
  }
  const tgt = teams.find(t => t.id === teamId);
  if (tgt) { if (!Array.isArray(tgt.memberIds)) tgt.memberIds = []; if (!tgt.memberIds.includes(employeeId)) tgt.memberIds.push(employeeId); tgt.updatedAt = new Date().toISOString(); }
  saveTeams(teams);
  for (const tid of removedFrom) { try { disableOperationsForEmployeeInTeam(employeeId, tid); } catch {} broadcastSSE('teams-changed', { id: tid }); }
  broadcastSSE('teams-changed', { id: teamId });
  return true;
}
// Re-stamp an operation's team globally (changes the op everywhere it appears).
function _moveOpToTeam(item, teamId) {
  if (item.kind === 'task') {
    const t = _findTaskByRef(item.refId); if (!t) return { ok: false, error: 'Task not found' };
    const tasks = loadTasks(); const idx = tasks.findIndex(x => x.id === t.id);
    tasks[idx].teamId = teamId || null; tasks[idx].updatedAt = new Date().toISOString();
    saveTasks(tasks); try { scheduleTask(tasks[idx]); } catch {}
    broadcastSSE('task-updated', tasks[idx]);
    return { ok: true };
  }
  if (item.kind === 'flow') {
    try { chainEngine.update(item.refId, { teamId: teamId || null }); return { ok: true }; } catch (e) { return { ok: false, error: e.message }; }
  }
  return { ok: false, error: 'Not an operation' };
}
// Create a team-scoped duplicate of an operation; returns the new pin refId so the
// caller can re-point the pin (the original op is left untouched).
function _cloneOpToTeam(item, teamId) {
  const suffix = _teamName(teamId) || 'team';
  if (item.kind === 'task') {
    const t = _findTaskByRef(item.refId); if (!t) return { ok: false, error: 'Task not found' };
    const tasks = loadTasks();
    const base = t.name || 'task';
    let name = `${base} (${suffix})`, n = 2;
    while (tasks.some(x => String(x.name).toLowerCase() === name.toLowerCase())) name = `${base} (${suffix} ${n++})`;
    const newId = `task-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
    const clone = { id: newId, name, agentId: t.agentId, prompt: t.prompt || '', schedule: t.schedule || 'never', enabled: t.enabled !== false, teamId: teamId || null, createdAt: new Date().toISOString() };
    tasks.push(clone); saveTasks(tasks); try { scheduleTask(clone); } catch {}
    broadcastSSE('task-created', clone);
    return { ok: true, newRefId: `task-${newId}` };
  }
  if (item.kind === 'flow') {
    let c = null; try { c = chainEngine.get(item.refId); } catch {}
    if (!c) return { ok: false, error: 'Flow not found' };
    const newId = 'chain-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
    const clone = { id: newId, name: `${c.name} (${suffix})`, description: c.description || '', teamId: teamId || null, schedule: c.schedule || 'never', enabled: c.enabled !== false, steps: (c.steps || []).map(s => ({ ...s })), edges: (c.edges || []).map(e => ({ ...e })) };
    try { chainEngine.create(clone); } catch (e) { return { ok: false, error: e.message }; }
    return { ok: true, newRefId: newId };
  }
  return { ok: false, error: 'Not an operation' };
}

// Compliance for a single board.
app.get('/api/boards/:id/compliance', (req, res) => {
  const board = loadBoards().find(b => b.id === req.params.id);
  if (!board) return res.status(404).json({ error: 'Board not found' });
  res.json(computeBoardCompliance(board));
});

// Resolve a single migration action, then return refreshed compliance.
app.post('/api/boards/:id/migrate', (req, res) => {
  const { itemId, action, employeeId } = req.body || {};
  const boards = loadBoards();
  const idx = boards.findIndex(b => b.id === req.params.id);
  if (idx < 0) return res.status(404).json({ error: 'Board not found' });
  const b = _normalizeBoard(boards[idx]);
  if (!b.teamId) return res.status(400).json({ error: 'Board has no team' });
  const item = b.items.find(it => it.id === itemId);
  if (!item) return res.status(404).json({ error: 'Pinned item not found' });
  let changedBoard = false;
  try {
    if (action === 'remove_pin') {
      b.items = b.items.filter(it => it.id !== itemId); changedBoard = true;
    } else if (action === 'add_member') {
      if (!employeeId) return res.status(400).json({ error: 'employeeId required' });
      _addEmployeeToTeam(b.teamId, employeeId);
    } else if (action === 'move_member') {
      if (!employeeId) return res.status(400).json({ error: 'employeeId required' });
      _moveEmployeeToTeam(b.teamId, employeeId);
    } else if (action === 'move_op') {
      const r = _moveOpToTeam(item, b.teamId); if (!r.ok) return res.status(400).json({ error: r.error || 'move failed' });
    } else if (action === 'clone_op') {
      const r = _cloneOpToTeam(item, b.teamId); if (!r.ok) return res.status(400).json({ error: r.error || 'clone failed' });
      item.refId = r.newRefId; changedBoard = true;
    } else {
      return res.status(400).json({ error: 'Unknown action' });
    }
  } catch (e) { return res.status(500).json({ error: e.message }); }
  if (changedBoard) {
    b.updatedAt = new Date().toISOString();
    boards[idx] = b; saveBoards(boards); broadcastSSE('boards-changed', { id: b.id });
  }
  const compliance = computeBoardCompliance(b);
  res.json({ ok: true, board: b, compliance });
});

// "Where was I" — summarize the most recent state across a board's pinned items.
// Best-effort, deterministic (no LLM): resolves each pinned reference to its
// latest activity and returns items sorted by recency plus a text digest.
// Resolve a board's pinned items into (a) per-item digests `out` for the UI list
// and (b) richer per-item `contextBlocks` (transcripts / run output / messages)
// fed to the LLM for the "Where was I?" briefing.
// ---- Pinned source-location (folder) helpers ----
// A location pin's refId is an absolute folder path. We surface a brief summary
// derived from a README in that folder (if present) and let the board/assistant
// open, search, and reason about the folder's contents.
const README_NAMES = ['README.md', 'readme.md', 'Readme.md', 'README.markdown', 'README.rst', 'README.txt', 'README'];
function _findReadme(dir) {
  try {
    for (const n of README_NAMES) { const p = path.join(dir, n); if (fs.existsSync(p) && fs.statSync(p).isFile()) return p; }
    // Case-insensitive fallback for odd casings.
    const entries = fs.readdirSync(dir);
    const hit = entries.find(e => /^readme(\.(md|markdown|rst|txt))?$/i.test(e));
    if (hit) { const p = path.join(dir, hit); if (fs.statSync(p).isFile()) return p; }
  } catch {}
  return null;
}
// Strip markdown/badge noise and pull the first meaningful prose paragraph.
function _readmeSummary(dir, maxLen = 280) {
  const rp = _findReadme(dir);
  if (!rp) return { summary: '', readmePath: null, hasReadme: false };
  let raw = '';
  try { raw = fs.readFileSync(rp, 'utf-8'); } catch { return { summary: '', readmePath: rp, hasReadme: true }; }
  const lines = raw.split(/\r?\n/);
  const para = [];
  for (const ln of lines) {
    const t = ln.trim();
    if (!t) { if (para.length) break; else continue; }
    if (/^#{1,6}\s/.test(t)) { if (para.length) break; else continue; } // heading
    if (/^!\[/.test(t) || /^\[!\[/.test(t)) continue;                    // badge/image line
    if (/^[-=*_]{3,}$/.test(t)) continue;                                // hr
    if (/^<.*>$/.test(t)) continue;                                      // bare html
    para.push(t);
    if (para.join(' ').length > maxLen * 1.5) break;
  }
  let summary = para.join(' ')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '')          // images
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')       // links → text
    .replace(/[`*_>#]+/g, '')                       // md punctuation
    .replace(/\s+/g, ' ').trim();
  if (summary.length > maxLen) summary = summary.slice(0, maxLen - 1).trimEnd() + '…';
  return { summary, readmePath: rp, hasReadme: true };
}

function _resolveBoardItems(b, opts = {}) {
  // When forSummary is set, items the user flagged with excludeFromSummary are
  // skipped entirely — they stay pinned on the board but contribute nothing to the
  // "Where was I?" briefing or the cross-board insights derived from it.
  const forSummary = !!opts.forSummary;
  // Board AI (the assistant) passes { full: true } so it sees the COMPLETE content of
  // every pinned item — full run output / transcripts, not the tight clips the
  // briefing uses. This lets it find details buried deep in a pinned task's output
  // (e.g. a work-item id partway down an epic-status table). The "Where was I?"
  // briefing keeps the tighter budgets so it stays fast and cheap.
  const full = !!opts.full;
  const TURN_CLIP = full ? 8000 : 500;     // per transcript turn (user/assistant message)
  const CTX_CLIP = full ? 40000 : 1200;    // per pinned item run output / result
  const JOIN_CAP = full ? 120000 : 2400;   // per-item assembled transcript/context cap
  const out = [];
  const contextBlocks = [];
  const tasks = loadTasks();
  const clip = (s, n) => String(s || '').replace(/\s+/g, ' ').trim().slice(0, n);
  for (const it of b.items) {
    if (forSummary && it.excludeFromSummary) continue;
    let when = it.addedAt || null, status = '', detail = '', route = '', context = '';
    try {
      if (it.kind === 'agent') {
        route = '#/agents/' + encodeURIComponent(it.refId);
        const runs = supervisor.getRunHistory(it.refId, 1) || [];
        if (runs[0]) { when = runs[0].finished_at || runs[0].started_at || when; status = runs[0].exit_code === 0 ? 'success' : (runs[0].status || 'error'); detail = clip(runs[0].output || runs[0].error || '', 240); context = clip(runs[0].output || runs[0].error || '', CTX_CLIP); }
      } else if (it.kind === 'task') {
        route = '#/tasks/' + encodeURIComponent(it.refId);
        const rawId = String(it.refId).replace(/^task-/, '');
        const t = tasks.find(x => x.id === rawId || ('task-' + x.id) === it.refId);
        if (t) {
          const runs = (supervisor.getRunHistory(t.agentId, 10) || []).filter(r => !r.task_id || r.task_id === t.id);
          const r0 = runs[0];
          if (r0) { when = r0.finished_at || r0.started_at || when; status = r0.exit_code === 0 ? 'success' : (r0.status || 'error'); detail = clip(r0.output || r0.error || '', 240); context = clip(r0.output || r0.error || '', CTX_CLIP); }
          else { status = t.enabled === false ? 'disabled' : 'idle'; }
        }
      } else if (it.kind === 'flow') {
        route = '#/chains/' + encodeURIComponent(it.refId);
        try { const c = chainEngine.get(it.refId); if (c) { status = c.enabled === false ? 'disabled' : 'idle'; if (c.lastRunAt) when = c.lastRunAt; detail = c.description || ''; context = clip(c.description || '', 600); } } catch {}
      } else if (it.kind === 'chat') {
        route = '#/chat/' + encodeURIComponent(it.refId);
        const cf = path.join(CHATS_DIR, `${it.refId}.json`);
        if (fs.existsSync(cf)) {
          try {
            const c = JSON.parse(fs.readFileSync(cf, 'utf-8'));
            when = c.updatedAt || when;
            const msgs = c.messages || [];
            const last = msgs[msgs.length - 1];
            if (last) { status = last.role; detail = clip(last.content || '', 240); }
            context = msgs.slice(-6).map(mm => (mm.role === 'assistant' ? 'ASSISTANT: ' : 'USER: ') + clip(mm.content || '', TURN_CLIP)).join('\n').slice(0, JOIN_CAP);
          } catch {}
        }
      } else if (it.kind === 'comment') {
        // A pinned comment: refId is "<chatId>~<messageTimestamp>". Locate the exact
        // message and surround it with a few neighbouring turns so the summary/assistant
        // has the conversational context around the pinned remark.
        const sep = String(it.refId).indexOf('~');
        const chatId = sep < 0 ? String(it.refId) : String(it.refId).slice(0, sep);
        const stamp = sep < 0 ? '' : String(it.refId).slice(sep + 1);
        route = '#/chat/' + encodeURIComponent(chatId);
        const cf = path.join(CHATS_DIR, `${chatId}.json`);
        if (fs.existsSync(cf)) {
          try {
            const c = JSON.parse(fs.readFileSync(cf, 'utf-8'));
            const msgs = Array.isArray(c.messages) ? c.messages : [];
            let idx = stamp ? msgs.findIndex(m => m.timestamp === stamp) : -1;
            if (idx < 0 && msgs.length) idx = msgs.length - 1; // fall back to the latest
            if (idx >= 0) {
              const pinned = msgs[idx];
              when = pinned.timestamp || c.updatedAt || when;
              status = pinned.role || 'comment';
              detail = clip(pinned.content || '', 240);
              const start = Math.max(0, idx - 3), end = Math.min(msgs.length, idx + 3);
              const lines = [];
              for (let i = start; i < end; i++) {
                const mm = msgs[i];
                const who = mm.role === 'assistant' ? 'ASSISTANT' : 'USER';
                const mark = i === idx ? ' «PINNED»' : '';
                // The pinned message is the point of interest — include it in full so the
                // board assistant sees the same complete comment the board now displays;
                // neighbouring turns stay clipped for context only.
                const body = i === idx ? clip(mm.content || '', full ? 40000 : 6000) : clip(mm.content || '', TURN_CLIP);
                lines.push(`${who}${mark}: ${body}`);
              }
              context = lines.join('\n').slice(0, JOIN_CAP);
            }
          } catch {}
        }
      } else if (it.kind === 'location') {
        // A pinned source folder. Status reflects whether the path still exists;
        // the README summary feeds both the card and the AI context so the board
        // assistant knows what lives there (and can be asked to search it).
        const dir = String(it.refId);
        try {
          if (fs.existsSync(dir) && fs.statSync(dir).isDirectory()) {
            status = 'location';
            try { when = new Date(fs.statSync(dir).mtimeMs).toISOString(); } catch {}
            const rs = _readmeSummary(dir, 600);
            detail = rs.summary ? clip(rs.summary, 240) : clip(it.sublabel || '', 240);
            context = (rs.summary ? rs.summary : 'A pinned source folder (no README found).')
              + `\n(path: ${dir}${rs.hasReadme ? '' : ' — no README'})`;
          } else {
            status = 'missing';
            detail = 'Folder not found';
            context = `Pinned folder no longer exists: ${dir}`;
          }
        } catch {}
      } else if (it.kind === 'pr') {
        // A pinned pull request. Its meta carries the identity snapshot
        // (org/project/repo/prId + url/view/title); the local worktree store (no AzDo
        // network) supplies live worktree/drift/review state. Route deep-links to the
        // PR's Code Flow card (the pin refId IS the codeflow key).
        const m = it.meta || {};
        route = '#/codeflow/' + encodeURIComponent(it.refId);
        let wt = null;
        try { wt = _getCfWt(_cfWtKey({ provider: m.provider, org: m.org, project: m.project, repo: m.repo, prId: m.prId })); } catch {}
        const bits = _cfWtBits(wt);
        if (wt && wt.updatedAt) when = wt.updatedAt;
        status = wt ? (wt.reviewStatus || wt.worktreeStatus || 'pr') : 'pr';
        const head = `${m.repo || ''} #${m.prId || '?'} [${m.view || 'mine'}]`;
        const live = _cfPrLive(m);
        const detailBits = live ? live.lines.slice(0, 2).join(', ') : bits.join(', ');
        detail = clip(head + ' — ' + detailBits, 240);
        const lines = [head];
        if (m.title) lines.unshift('title: ' + clip(m.title, 200));
        // Live PR pieces (state/age/comments/reviewers/checks/AI) from the codeflow
        // cache so the briefing can "see all the pieces", not just the worktree state.
        if (live && live.lines.length) lines.push(...live.lines);
        lines.push('worktree: ' + bits.join(', '));
        if (m.url) lines.push('url: ' + m.url);
        if (wt && wt.worktreePath) lines.push('worktree path: ' + wt.worktreePath);
        if (wt && wt.reviewError) lines.push('review error: ' + clip(wt.reviewError, 200));
        context = clip(lines.join('\n'), CTX_CLIP);
      } else if (it.kind === 'session') {
        route = '#/sessions';
        try {
          const dir = path.join(SESSION_STATE_DIR, it.refId);
          if (fs.existsSync(dir)) {
            const ep = path.join(dir, 'events.jsonl');
            try { when = new Date(fs.statSync(ep).mtimeMs).toISOString(); } catch { try { when = new Date(fs.statSync(dir).mtimeMs).toISOString(); } catch {} }
            status = 'session';
            const sp = path.join(dir, SPA_SUMMARY_FILE);
            try { if (fs.existsSync(sp)) detail = clip(JSON.parse(fs.readFileSync(sp, 'utf-8')).summary || '', 240); } catch {}
            // Build a multi-turn transcript for the LLM (last 8 turns), falling back
            // to a raw events.jsonl scan for agent-run sessions whose prompts arrive
            // via file (so readSessionConversation yields no turns).
            const tl = [];
            try {
              const conv = readSessionConversation(dir);
              for (const t of (conv.turns || []).slice(-8)) {
                if (t.content) tl.push('USER: ' + clip(t.content, TURN_CLIP));
                if (t.assistant) tl.push('ASSISTANT: ' + clip(t.assistant, TURN_CLIP));
              }
            } catch {}
            if (!tl.length && fs.existsSync(ep)) {
              try {
                let agentName = '';
                const tools = [];
                for (const ln of fs.readFileSync(ep, 'utf-8').split('\n')) {
                  if (!ln) continue;
                  let ev; try { ev = JSON.parse(ln); } catch { continue; }
                  const d = ev.data || {};
                  if (ev.type === 'user.message' && d.content) tl.push('USER: ' + clip(d.content, TURN_CLIP));
                  else if (ev.type === 'assistant.message' && d.content) tl.push('ASSISTANT: ' + clip(d.content, TURN_CLIP));
                  else if (ev.type === 'subagent.selected' && (d.agentDisplayName || d.agentName)) agentName = d.agentDisplayName || d.agentName;
                  else if (ev.type === 'session.start' && d.context && d.context.agentName && !agentName) agentName = d.context.agentName;
                  else if (ev.type === 'tool.execution_start' && d.toolName) tools.push(d.toolName);
                }
                if (!tl.length && agentName) {
                  const counts = {};
                  for (const t of tools) counts[t] = (counts[t] || 0) + 1;
                  const topt = Object.entries(counts).sort((a, c) => c[1] - a[1]).slice(0, 8).map(([k, v]) => v > 1 ? `${k}×${v}` : k);
                  tl.push('AGENT: ' + agentName + (topt.length ? ' — used ' + topt.join(', ') : ''));
                }
                while (tl.length > 16) tl.shift();
              } catch {}
            }
            if (!detail && tl.length) {
              for (let i = tl.length - 1; i >= 0; i--) { if (tl[i].startsWith('ASSISTANT: ')) { detail = clip(tl[i].slice(11), 240); break; } }
              if (!detail) detail = clip(tl[tl.length - 1], 240);
            }
            context = tl.join('\n').slice(0, JOIN_CAP);
          }
        } catch {}
      }
    } catch {}
    out.push({ id: it.id, kind: it.kind, refId: it.refId, label: it.label, sublabel: it.sublabel, route, when, status, detail });
    if (context) contextBlocks.push(`### ${String(it.kind).toUpperCase()}: ${it.label || it.refId}${route ? ` [source link: ${route}]` : ''}\n${context}`);
  }
  out.sort((a, c) => new Date(c.when || 0) - new Date(a.when || 0));
  return { out, contextBlocks };
}

// AI-powered "Where was I?" briefing. Reviews the recent conversation/run context
// of every pinned item and produces a short prose summary + optional next steps.
// The result is cached on board.summary; a <30s cache is served unless {force:true}.
app.post('/api/boards/:id/where-was-i', async (req, res) => {
  const raw = loadBoards().find(b => b.id === req.params.id);
  if (!raw) return res.status(404).json({ error: 'Board not found' });
  const b = _normalizeBoard(raw);
  const force = !!(req.body && req.body.force);

  if (!force && b.summary && b.summary.generatedAt) {
    const age = Date.now() - new Date(b.summary.generatedAt).getTime();
    if (age >= 0 && age < 30000) {
      return res.json({ ok: true, generatedAt: b.summary.generatedAt, summary: b.summary.text, items: b.summary.items || [], deltas: b.summary.deltas || [], cached: true });
    }
  }

  const { out, contextBlocks } = _resolveBoardItems(b, { forSummary: true });
  const clip = (s, n) => String(s || '').replace(/\s+/g, ' ').trim().slice(0, n);

  // Notes, checklists and dev cards are first-class board context too — surface them
  // as briefing Sources (each with its own type + last-updated time) alongside the
  // pinned items, then re-sort so the merged list stays most-recent-first.
  const manualSources = [];
  for (const n of (Array.isArray(b.notes) ? b.notes : [])) {
    const text = clip(n.text, 240);
    if (!text) continue;
    manualSources.push({ id: 'note:' + n.id, kind: 'note', refId: n.id, label: clip(n.text, 80) || 'Note', sublabel: 'Note', route: '', when: n.updatedAt || n.createdAt || null, status: '', detail: text });
  }
  for (const cl of (Array.isArray(b.checklists) ? b.checklists : [])) {
    const items = Array.isArray(cl.items) ? cl.items : [];
    const done = items.filter(i => i.done).length;
    manualSources.push({ id: 'cl:' + cl.id, kind: 'checklist', refId: cl.id, label: clip(cl.title, 120) || 'Checklist', sublabel: `${done}/${items.length} done`, route: '', when: cl.updatedAt || cl.createdAt || null, status: (items.length && done === items.length) ? 'success' : '', detail: items.map(i => `${i.done ? '✓' : '○'} ${clip(i.text, 80)}`).join(' · ') });
  }
  for (const d of devStore.forBoard(b.id)) {
    if (d && d.archived) continue;
    const sub = [d.repo, d.branch].filter(Boolean).join(' @ ') || (d.workItemId ? 'WI #' + d.workItemId : 'Dev card');
    manualSources.push({ id: 'dev:' + d.id, kind: 'dev', refId: d.id, label: clip(d.title || d.repo || 'Dev card', 120), sublabel: sub, route: '', when: d.updatedAt || d.createdAt || null, status: '', detail: clip((d.summary && d.summary.text) || sub, 240) });
  }
  if (manualSources.length) {
    out.push(...manualSources);
    out.sort((a, c) => new Date(c.when || 0) - new Date(a.when || 0));
  }

  // Deltas: what changed since the user last viewed (generated a briefing for) this
  // board. Pinned items whose latest activity timestamp is newer than lastViewedAt,
  // flagged for attention when the latest run errored/failed.
  const prevViewed = b.lastViewedAt ? new Date(b.lastViewedAt).getTime() : 0;
  const deltas = prevViewed
    ? out.filter(o => o.when && new Date(o.when).getTime() > prevViewed).map(o => ({
        label: o.label || o.refId, kind: o.kind, status: o.status || '', when: o.when, route: o.route,
        attention: ['error', 'failed'].includes(String(o.status).toLowerCase())
      }))
    : [];
  if (deltas.length) {
    const dl = deltas.map(d => `- ${d.attention ? '⚠ ' : ''}${d.label}${d.status ? ' [' + d.status + ']' : ''}`).join('\n');
    contextBlocks.unshift('### SINCE LAST VIEWED\n' + dl);
  }

  // Fold the board's own notes and checklists (with item status) into the context
  // so the briefing reflects what the user jotted down and what's still unchecked.
  const notes = (Array.isArray(b.notes) ? b.notes : []).map(n => clip(n.text, 300)).filter(Boolean);
  const checklists = (Array.isArray(b.checklists) ? b.checklists : []).map(cl => {
    const items = Array.isArray(cl.items) ? cl.items : [];
    const done = items.filter(i => i.done).length;
    return { title: clip(cl.title, 120), done, total: items.length, items };
  });
  if (notes.length) {
    contextBlocks.push('### NOTES\n' + notes.map(t => '- ' + t).join('\n'));
  }
  for (const cl of checklists) {
    const lines = cl.items.map(i => `- [${i.done ? 'x' : ' '}] ${clip(i.text, 200)}`);
    contextBlocks.push(`### CHECKLIST: ${cl.title || 'Untitled'} (${cl.done}/${cl.total} done)${lines.length ? '\n' + lines.join('\n') : ''}`);
  }
  const openChecklistItems = checklists.reduce((n, cl) => n + cl.items.filter(i => !i.done).length, 0);

  // Fold in any Dev cards (work item + PR + git worktree trackers). These represent
  // active development work, so they belong in the briefing — show each one's work
  // item / PR / worktree state and its AI status summary if present.
  const devItems = devStore.forBoard(b.id);
  if (devItems.length) {
    contextBlocks.push('### DEV CARDS (active development — one repo per card: work item + PR + git worktree; the card shows its title, repo/branch, and stage; notes + artifacts shown per card; reference by devId)\n' + _devCardContextLines(devItems).join('\n'));
  }

  // Deterministic fallback used when the board is empty, has no usable context, or
  // the LLM call fails.
  const top = out.slice(0, 6).map(o => {
    const rel = o.when ? new Date(o.when).toLocaleString() : 'no recent activity';
    const st = o.status ? ` [${o.status}]` : '';
    return `• ${o.label}${st} — ${rel}${o.detail ? `\n    ${clip(o.detail, 160)}` : ''}`;
  }).join('\n');
  const manualLine = [
    notes.length ? `${notes.length} note${notes.length === 1 ? '' : 's'}` : '',
    checklists.length ? `${openChecklistItems} open checklist item${openChecklistItems === 1 ? '' : 's'}` : '',
    devItems.length ? `${devItems.length} dev card${devItems.length === 1 ? '' : 's'}` : ''
  ].filter(Boolean).join(', ');
  let digest;
  if (out.length) {
    digest = `Here's where you left off across ${out.length} pinned item${out.length === 1 ? '' : 's'} on "${b.name}", most recent first:\n\n${top}`;
    if (manualLine) digest += `\n\nAlso on this board: ${manualLine}.`;
  } else if (notes.length || checklists.length || devItems.length) {
    digest = `Board "${b.name}" has no pinned operations yet, but you have ${manualLine} here.`;
  } else {
    digest = `Board "${b.name}" has no pinned items yet. Pin a CLI session, chat, task, flow, or agent to track it here.`;
  }
  if (deltas.length) {
    const dl = deltas.map(d => `${d.attention ? '⚠ ' : ''}${d.label}${d.status ? ' [' + d.status + ']' : ''}`).join(', ');
    digest = `Since you last looked: ${dl}.\n\n` + digest;
  }

  // Persist the briefing onto the board record and notify SPA clients. Also advances
  // lastViewedAt so the next briefing's deltas are measured from this point.
  const persist = (text) => {
    const generatedAt = new Date().toISOString();
    const summary = { text, generatedAt, items: out, deltas };
    try {
      const all = loadBoards();
      const idx = all.findIndex(x => x.id === b.id);
      if (idx >= 0) { all[idx].summary = summary; all[idx].lastViewedAt = generatedAt; saveBoards(all); broadcastSSE('boards-changed', { id: b.id }); }
    } catch {}
    return summary;
  };

  if (!contextBlocks.length) {
    const saved = persist(digest);
    return res.json({ ok: true, generatedAt: saved.generatedAt, summary: saved.text, items: out, deltas, cached: false });
  }

  // User-supplied briefing guidance: an explicit per-request `guidance` (from the active
  // briefing prompt) takes precedence; otherwise fall back to the board's active prompt.
  let guidance = (req.body && typeof req.body.guidance === 'string') ? req.body.guidance.trim() : '';
  if (!guidance && b.activeBriefingPromptId) {
    const ap = (b.briefingPrompts || []).find(p => p.id === b.activeBriefingPromptId);
    if (ap && ap.text) guidance = String(ap.text).trim();
  }

  const prompt = [
    `You are reviewing a workspace named "${b.name}". Below is recent context: items the user pinned (conversation transcripts, run output, or messages), plus the user's own NOTES and CHECKLIST sections, and any DEV CARDS (active development work — an Azure DevOps work item + pull request + git worktree, with a status summary). Checklist lines marked "[x]" are done and "[ ]" are still open.`,
    'Each pinned-item section is headed "### KIND: Name [source link: <route>]". The route after "source link:" is the primary source for everything in that section.',
    ...(guidance ? [
      '',
      `IMPORTANT — the user has provided specific guidance for THIS briefing. Follow it closely, shaping what you focus on, include, and emphasize (while still grounding everything in the context below): ${guidance}`,
      ''
    ] : []),
    'Write a "Where was I?" briefing that reorients the user:',
    '- If a "SINCE LAST VIEWED" section is present, begin with one sentence highlighting what changed since the user last looked (call out any items marked ⚠ as needing attention).',
    '- 3 to 6 sentences of plain prose summarizing what is going on across these items, the current state, and what the notes/checklists indicate.',
    '- CITE YOUR PRIMARY SOURCES: when a statement draws on a specific pinned item, attribute it inline as a markdown link using that item\'s Name and its source link, e.g. "the latest run failed ([Autoscaler agent](#/agents/autoscaler))". Only cite items that actually have a source link in their heading; never invent a route. Notes/checklists are the user\'s own input and do not need a citation.',
    '- Then, only if there are concrete pending actions, add a line "Next steps:" followed by a short bullet list (each line starting with "- "). Treat unchecked checklist items as pending actions.',
    '- Finally, add a line "Sources:" followed by a short bullet list of the primary pinned items you actually drew from, each as a markdown link "[Name](route)" using its source link. Omit this line only if no pinned item had a source link.',
    'Be specific and concrete. No preamble, no headings other than "Next steps:" and "Sources:", no surrounding quotes.',
    '',
    contextBlocks.join('\n\n').slice(0, 9000),
    '',
    'Briefing:'
  ].join('\n');

  try {
    let acc = '';
    const result = await sdkRunner.runChat({ config: null, prompt, sessionId: require('crypto').randomUUID(), cwd: __dirname, onChunk: (c) => { acc += c; } });
    const text = (acc.trim() || (result && result.output) || '').trim() || digest;
    const saved = persist(text);
    res.json({ ok: true, generatedAt: saved.generatedAt, summary: saved.text, items: out, deltas, cached: false });
  } catch (e) {
    const saved = persist(digest);
    res.json({ ok: true, generatedAt: saved.generatedAt, summary: saved.text, items: out, deltas, cached: false, error: (e && e.message) || 'llm failed' });
  }
});

// ============================================================================
// DEV CARDS — group an AzDo work item + PR + a git worktree on a board. Metadata
// lives on board.devItems[] (persisted via PUT /api/boards/:id); the heavy git /
// AzDo / AI work runs through these dedicated action endpoints. Opening the
// worktree in an editor/CLI reuses POST /api/fs/open (a worktree is just a
// folder), so no new launch code is needed here.
// ============================================================================

// Build the DEV CARDS context lines shared by the where-was-i briefing and the
// board assistant. Includes the devId plus the card's LINKS, extra REPOS and
// REPORTS so the AI can SEE and TARGET them (e.g. "replace the dev card link"
// means the Links section, not a work-item markdown link in a checklist).
function _devCardContextLines(devItems) {
  const clip = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
  const slug = (o, p, r) => [o, p, r].filter(Boolean).join('/') || '?';
  return (Array.isArray(devItems) ? devItems : []).map(d => {
    const gh = String(d.provider || 'azdo').toLowerCase() === 'github';
    const wt = d.worktreePath ? (d.worktreeStatus || 'ready') : 'none';
    const wi = d.workItemId ? `${gh ? 'Issue' : 'WI'} #${d.workItemId}${d.workItem && d.workItem.state ? ' (' + d.workItem.state + ')' : ''}` : (gh ? 'no issue' : 'no work item');
    const pr = d.prId ? `PR ${gh ? '#' : '!'}${d.prId}${d.pr && d.pr.status ? ' (' + d.pr.status + ')' : ''}` : 'no PR';
    const git = d.git ? ` | git ahead ${d.git.ahead || 0}/behind ${d.git.behind || 0}${d.git.dirty ? '/dirty' : ''}` : '';
    const agent = d.devAgentName ? ` | dev-agent ${d.devAgentName}` : '';
    const head = `- (${d.id}) "${clip(d.title || d.repo || 'Dev card', 100)}" — ${gh ? 'GitHub ' : ''}${slug(d.org, d.project, d.repo)} @ ${d.branch || '?'} | ${wi} | ${pr} | worktree ${wt}${git}${agent}`;
    const extra = [];
    const repos = Array.isArray(d.repos) ? d.repos : [];
    // ARTIFACTS on a Dev card = user-attached LINKS (editable via *_dev_link) plus
    // agent-generated REPORTS (read-only). Surface both so the assistant/briefing can
    // reference them and, for links, offer to change them.
    const links = Array.isArray(d.links) ? d.links : [];
    if (links.length) extra.push('    artifact links (editable): ' + links.map(l => `[${clip(l.label || l.url, 60)} → ${clip(l.url, 160)} (${l.id})]`).join(', '));
    else extra.push('    artifact links: none');
    if (repos.length) extra.push('    extra repos: ' + repos.map(r => `[${slug(r.org, r.project, r.repo)} @ ${r.branch || '?'} (${r.id})${r.worktreeStatus ? ' ' + r.worktreeStatus : ''}]`).join(', '));
    const reports = Array.isArray(d.reports) ? d.reports : [];
    if (reports.length) extra.push('    artifact reports (read-only, agent-generated): ' + reports.map(r => `[${clip(r.name || r.rel, 80)} (${r.rel})]`).join(', '));
    // NOTES — freeform status jots. A note is GENERAL (card-level) or scoped to ONE
    // repo section via note.slot ('primary' or a repo-id). The assistant can add / edit /
    // delete / check / uncheck these, so each is shown with its (note-id) + done state,
    // grouped by the repo it belongs to.
    const notes = Array.isArray(d.notes) ? d.notes : [];
    if (notes.length) {
      const slotLabel = (sid) => {
        if (!sid || sid === 'primary') return slug(d.org, d.project, d.repo);
        const rr = repos.find(r => r && r.id === sid);
        return rr ? slug(rr.org, rr.project, rr.repo) : sid;
      };
      const fmt = (n) => `[${n.done ? '✓done' : 'open'}] ${clip(n.text, 200)} (${n.id})`;
      const general = notes.filter(n => !(n && n.slot));
      if (general.length) extra.push('    notes (general): ' + general.map(fmt).join(' · '));
      const bySlot = {};
      for (const n of notes) if (n && n.slot) (bySlot[n.slot] = bySlot[n.slot] || []).push(n);
      for (const sid of Object.keys(bySlot)) {
        extra.push(`    notes (repo ${slotLabel(sid)}, slot ${sid}): ` + bySlot[sid].map(fmt).join(' · '));
      }
    }
    if (d.summary && d.summary.text) extra.push('    summary: ' + clip(d.summary.text, 400));
    return [head, ...extra].join('\n');
  });
}

// Namespace used for report-cache dirs of dev cards not homed on any board.
const DEV_NS = '_dev';

// Locate a dev card in the GLOBAL store; persist a mutated copy back. Returns
// helpers. `boardId` is now only a cache-namespace hint (kept for signature
// compatibility with the board-scoped routes); the card is resolved by devId.
function _devItemCtx(boardId, devId) {
  const dev = devStore.find(devId);
  if (!dev) return null;
  // Cache dirs live under the card's home board (continuity with pre-migration
  // on-disk caches); board-less cards fall back to a fixed namespace.
  const cacheBoardId = dev.homeBoardId || boardId || DEV_NS;
  return {
    board: null, dev, boardId: cacheBoardId,
    // Merge a partial onto the dev card, persist to the store, broadcast.
    save(partial) {
      const updated = devStore.patch(devId, partial);
      if (!updated) return null;
      // Carry the dev id + updated card so a viewing client can surgically patch
      // just this card (auto-summary reconciler / worktree status flip). Use the
      // card's home board id so an open board view updates the right panel; the
      // Dev page listens on devId regardless of board.
      broadcastSSE('boards-changed', { id: updated.homeBoardId || null, devId, dev: updated });
      return updated;
    }
  };
}

// ---- Multi-repo dev cards -------------------------------------------------
// A dev card groups ONE work item across one primary repo (top-level fields) and
// any number of EXTRA repos in d.repos[]. Every repo gets its own git worktree
// (keyed by repo + devId, so paths never collide). These helpers present a unified
// view of all repo "slots" and persist per-repo runtime fields (worktreePath, …).
function _devExtraRepos(d) { return Array.isArray(d.repos) ? d.repos : []; }
// Unified list: the primary repo (id 'primary') followed by every extra repo.
function _devRepoSlots(d) {
  const slots = [];
  if (d.org && d.project && d.repo) {
    slots.push({
      id: 'primary', primary: true, provider: d.provider || 'azdo',
      org: d.org, project: d.project, repo: d.repo,
      branch: d.branch, baseBranch: d.baseBranch,
      prId: d.prId || '', prBranch: d.prBranch || '', prWorktreePath: d.prWorktreePath || '', prSeq: d.prSeq || 0,
      worktreePath: d.worktreePath || '', worktreeStatus: d.worktreeStatus || null,
      worktreeError: d.worktreeError || null, git: d.git || null,
      devs: Array.isArray(d.devs) ? d.devs : null, activeDevId: d.activeDevId || null
    });
  }
  for (const r of _devExtraRepos(d)) if (r && r.id) slots.push({ ...r, provider: r.provider || 'azdo', primary: false });
  return slots;
}
// Find a repo slot by id ('primary' or an extra's id), or by org/project/repo.
function _findRepoSlot(d, sel) {
  if (!sel) return null;
  const slots = _devRepoSlots(d);
  if (typeof sel === 'string') return slots.find(s => s.id === sel) || null;
  const key = (x) => [x.org, x.project, x.repo].map(v => String(v || '').toLowerCase()).join('/');
  if (sel.id) { const byId = slots.find(s => s.id === sel.id); if (byId) return byId; }
  return slots.find(s => key(s) === key(sel)) || null;
}
// Persist a partial of runtime fields onto a repo slot. For the primary slot the
// fields live at the top level; for an extra they live inside d.repos[].
function _saveRepoSlot(ctx, slotId, partial) {
  if (slotId === 'primary') return ctx.save(partial);
  const repos = _devExtraRepos(ctx.dev).map(r => (r && r.id === slotId) ? { ...r, ...partial } : r);
  return ctx.save({ repos });
}

// ---- Dev worktrees ("approaches") per repo slot ---------------------------
// A repo slot may hold MULTIPLE dev worktrees — each an independent "approach" or
// "aspect" of the work, a real workshop where agents implement. Each has its own
// dev/<slug>-<n> branch + worktree + agent + reports. When happy with one, the user
// PROMOTES it into the slot's single PR (promote-only).
//
// Source of truth: slot.devs[] + slot.activeDevId. Legacy cards stored a single dev
// worktree in the slot's top-level fields (worktreePath/branch/git/…); we migrate
// that into devs[0] (aspect "Main") on read, so old cards keep working. The slot's
// top-level fields always MIRROR the active dev worktree (see _saveDevWorktree), so
// every existing route/reader (createWorktree, commits, summary, cleanup, /pr,
// promote, report scanning, client devSlots) keeps operating on the active approach
// with zero changes — only the new multi-worktree flows read/write devs[] directly.
function _slotDevWorktrees(slot) {
  const list = Array.isArray(slot && slot.devs) ? slot.devs.filter(Boolean).map(w => ({ ...w })) : [];
  if (list.length) return list;
  // Migrate a legacy single-worktree slot into devs[0].
  return [{
    id: 'main', aspect: 'Main', scope: '',
    branch: (slot && slot.branch) || '',
    worktreePath: (slot && slot.worktreePath) || '',
    worktreeStatus: (slot && slot.worktreeStatus) || null,
    worktreeError: (slot && slot.worktreeError) || null,
    git: (slot && slot.git) || null,
    agentName: (slot && (slot.agentName || slot.devAgentName)) || '',
    promotedPrId: (slot && slot.prId && slot.prBranch) ? String(slot.prId) : '',
    createdAt: (slot && slot.createdAt) || null
  }];
}
// The active (mirrored-to-top-level) dev worktree id for a slot.
function _activeDevWtId(slot) {
  const list = _slotDevWorktrees(slot);
  const want = slot && slot.activeDevId;
  if (want && list.some(w => w.id === want)) return want;
  return (list[0] && list[0].id) || 'main';
}
// Resolve a dev worktree on a slot by id (defaults to the active one). Returns the
// migrated devs[] entry or null.
function _resolveDevWt(slot, wtId) {
  const list = _slotDevWorktrees(slot);
  if (!list.length) return null;
  if (!wtId) wtId = _activeDevWtId(slot);
  return list.find(w => w.id === wtId) || null;
}
// Runtime fields that mirror between an active dev worktree entry and the slot's
// legacy top-level fields, so passive readers never need to know about devs[].
const _DEV_WT_MIRROR = ['branch', 'worktreePath', 'worktreeStatus', 'worktreeError', 'git', 'agentName'];
// Persist the full devs[] array (and optionally activeDevId) onto a slot, then
// re-mirror the active entry's runtime fields to the slot top level.
function _saveDevWorktrees(ctx, slotId, devs, activeDevId) {
  const slotBefore = _findRepoSlot(ctx.dev, slotId);
  const list = (Array.isArray(devs) ? devs.filter(Boolean) : []).map(w => ({ ...w }));
  const active = (activeDevId && list.some(w => w.id === activeDevId))
    ? activeDevId
    : ((slotBefore && slotBefore.activeDevId && list.some(w => w.id === slotBefore.activeDevId))
      ? slotBefore.activeDevId
      : ((list[0] && list[0].id) || 'main'));
  const activeWt = list.find(w => w.id === active) || list[0] || null;
  const partial = { devs: list, activeDevId: active };
  // Mirror the active worktree's runtime fields to the slot top level. For the
  // primary slot the mirror lives at the card top level; devAgentName is the
  // legacy primary agent field, agentName the extra-slot field — set both.
  if (activeWt) {
    for (const k of _DEV_WT_MIRROR) partial[k] = activeWt[k] != null ? activeWt[k] : (k === 'git' ? null : (k === 'worktreeStatus' || k === 'worktreeError' ? null : ''));
    if (slotId === 'primary') partial.devAgentName = activeWt.agentName || '';
  }
  return _saveRepoSlot(ctx, slotId, partial);
}
// Update ONE dev worktree entry (by id) with a partial, then persist + re-mirror.
// Creates the devs[] array from the legacy migration on first write.
function _saveDevWorktree(ctx, slotId, wtId, partial) {
  const slot = _findRepoSlot(ctx.dev, slotId);
  if (!slot) return null;
  const list = _slotDevWorktrees(slot);
  const id = wtId || _activeDevWtId(slot);
  let found = false;
  const next = list.map(w => (w.id === id ? (found = true, { ...w, ...partial }) : w));
  if (!found) next.push({ id, aspect: 'Main', scope: '', branch: '', worktreePath: '', worktreeStatus: null, worktreeError: null, git: null, agentName: '', promotedPrId: '', createdAt: null, ...partial });
  return _saveDevWorktrees(ctx, slotId, next, slot.activeDevId);
}
// Slug base for a dev worktree branch, shared with the client _cfSlug.
function _devSlug(d) {
  const raw = String((d && (d.branch || d.workItemId || d.title || d.id)) || '');
  return raw.replace(/^refs\/heads\//, '').replace(/^(dev|pr)\//, '').replace(/[^a-z0-9]+/gi, '-').replace(/^-+|-+$/g, '').toLowerCase().slice(0, 40) || 'work';
}
// Flip which dev worktree is the active (mirrored) approach on a slot.
function _setActiveDevWt(ctx, slotId, wtId) {
  const slot = _findRepoSlot(ctx.dev, slotId);
  if (!slot) return null;
  const list = _slotDevWorktrees(slot);
  if (!list.some(w => w.id === wtId)) return null;
  return _saveDevWorktrees(ctx, slotId, list, wtId);
}
// Mark which approach fed the slot's single PR. Only ONE approach promotes at a
// time, so we set promotedPrId on the chosen worktree and clear it on every other
// (a later promote of a different approach re-points the single PR). Requires a
// FRESH ctx so ctx.dev reflects the latest devs[].
function _markPromotedApproach(ctx, slotId, wtId, prId) {
  const slot = _findRepoSlot(ctx.dev, slotId);
  if (!slot) return null;
  const list = _slotDevWorktrees(slot).map(w => ({ ...w, promotedPrId: (w.id === wtId ? String(prId || '') : '') }));
  return _saveDevWorktrees(ctx, slotId, list, slot.activeDevId);
}

// Human-readable label for a dev worktree ("approach"), matching the client's
// approachLabel(): the explicit aspect, else "Main" for the legacy migrated
// worktree, else its branch.
function _approachLabel(w) {
  const a = String((w && w.aspect) || '').trim();
  if (a) return a;
  if (!w || w.id === 'main') return 'Main';
  return (w && w.branch) || 'approach';
}
// Expand each repo slot into ONE report-slot per dev worktree ("approach"), so
// reports are surfaced + cached per approach (not just the active/mirrored one).
// The cache namespace is stable per approach: the legacy 'main' worktree keeps
// the slot's base namespace (root for primary, repoId for extras) so existing
// cached reports survive; every other approach caches under `<base>~<wtId>`.
// Each report-slot also carries { wtId, aspect, active, promotedPrId } tags that
// devitems copies onto every report it finds/caches for that slot.
function _devReportSlots(d) {
  const out = [];
  for (const s of _devRepoSlots(d)) {
    const active = _activeDevWtId(s);
    for (const w of _slotDevWorktrees(s)) {
      const base = s.id;
      const pid = (!w.id || w.id === 'main') ? base : (base + '~' + w.id);
      out.push({
        id: pid, repo: s.repo, worktreePath: w.worktreePath || '',
        wtId: w.id || 'main', aspect: _approachLabel(w), active: (w.id === active),
        promotedPrId: w.promotedPrId || ''
      });
    }
  }
  return out;
}

// Re-scan status reports across ALL of a dev card's repo slots + approaches and
// merge in the durably-cached reports from approaches whose worktree is gone.
// This makes d.reports the aggregate across every repo AND approach — reports are
// tagged with their source repo ({repoId, repo}) AND approach ({wtId, aspect,
// approachActive}) so identically-named reports are disambiguable, and cached
// copies survive worktree removal (like PR cards).
function _rescanDevReports(boardId, devId, d) {
  const slots = _devReportSlots(d);
  const live = slots.filter(s => s.worktreePath);
  const dead = slots.filter(s => !s.worktreePath);
  let reports = [];
  try { reports = devitems.findAndCacheReportsForSlots(boardId, devId, live) || []; } catch {}
  let cached = [];
  try { cached = devitems.listCachedReportsForSlots(boardId, devId, dead) || []; } catch {}
  const seen = new Set(reports.map(r => r.cacheRel || r.rel));
  for (const c of cached) { const k = c.cacheRel || c.rel; if (!seen.has(k)) { seen.add(k); reports.push(c); } }
  reports.sort((a, b) => (b.mtime || 0) - (a.mtime || 0));
  return reports.slice(0, 32);
}

// ---- Provider dispatch for dev cards -------------------------------------
// A dev card (or repo slot) may target Azure DevOps (default) or GitHub. These
// helpers build a provider descriptor and dispatch the work-item / PR calls that
// diverge by provider signature. Missing provider ⇒ azdo, so existing AzDo dev
// cards behave byte-identically (no provider field on legacy records).
function _devDesc(x) {
  if (!x) return { provider: 'azdo' };
  return { provider: x.provider || 'azdo', org: x.org, project: x.project, repo: x.repo };
}
// Work items diverge: azdo.getWorkItem(org, project, id) vs
// github.getWorkItem(owner, repo, number) — position 2 differs (project vs repo).
async function _devWorkItem(desc, id) {
  const f = forge(desc);
  return desc.provider === 'github'
    ? f.getWorkItem(desc.org, desc.repo, id)
    : f.getWorkItem(desc.org, desc.project, id);
}
async function _devWorkItemComments(desc, id, opts) {
  const f = forge(desc);
  return desc.provider === 'github'
    ? f.getWorkItemComments(desc.org, desc.repo, id, opts)
    : f.getWorkItemComments(desc.org, desc.project, id, opts);
}
async function _devUpdateWorkItemState(desc, id, state) {
  const f = forge(desc);
  return desc.provider === 'github'
    ? f.updateWorkItemState(desc.org, desc.repo, id, state)
    : f.updateWorkItemState(desc.org, desc.project, id, state);
}
// PR create/get are positionally clean across providers (github ignores the
// middle project slot), so a single positional dispatch works for both.
async function _devPullRequest(desc, prId) {
  return forge(desc).getPullRequest(desc.org, desc.project, desc.repo, prId);
}
async function _devCreatePullRequest(desc, body) {
  const pr = await forge(desc).createPullRequest(desc.org, desc.project, desc.repo, body);
  // Normalize the id field: azdo returns { pullRequestId }, github returns { id }.
  // Downstream server code reads pr.pullRequestId, so guarantee it for both.
  if (pr && pr.pullRequestId == null && pr.id != null) pr.pullRequestId = pr.id;
  return pr;
}

// ---- Dev-card auto-creation from Azure DevOps work-item conditions ---------
// (Part A) When settings.devAutoCreate is on, a leader-gated poller queries ADO
// for work items matching each enabled rule and creates a dev card for any match
// that doesn't already have one (deduped by the shared _meAiDevKey identity). A
// rule's optional area/tag→repo mappings assign a repo; unmatched cards land in a
// clear "no repo assigned" state. Scoped to ADO work items (WIQL has no GitHub
// equivalent). Routes use a /api/dev-auto-create/* prefix so they don't collide
// with the /api/dev-items/:devId/:op alias middleware below.
function _devAutoNormRule(r, i, s) {
  r = (r && typeof r === 'object') ? r : {};
  const str = (v, d) => { const x = String(v == null ? '' : v).trim(); return x || d; };
  const def = _connectAdoTargets(s)[0] || {};
  const defOrg = def.org || 'dnceng';
  const defProject = (def.projects && def.projects[0]) || 'internal';
  const freq = (() => { const n = Number(r.frequencyMin); return (Number.isFinite(n) && n >= 5) ? Math.min(1440, Math.round(n)) : 30; })();
  const mappings = (Array.isArray(r.repoMappings) ? r.repoMappings : []).map(m => {
    m = (m && typeof m === 'object') ? m : {};
    return {
      match: str(m.match, ''),
      field: (String(m.field || 'area').toLowerCase() === 'tag') ? 'tag' : 'area',
      repo: str(m.repo, ''),
      provider: (() => { const p = String(m.provider || '').toLowerCase(); return (p === 'github' || p === 'azdo') ? p : ''; })()
    };
  }).filter(m => m.match && m.repo);
  return {
    id: str(r.id, 'devrule-' + i),
    enabled: r.enabled !== false,
    name: str(r.name, ''),
    org: str(r.org, defOrg),
    project: str(r.project, defProject),
    workItemType: str(r.workItemType || r.type, 'DNCeng Task'),
    state: str(r.state, 'Dev'),
    areaPath: str(r.areaPath || r.area, ''),
    frequencyMin: freq,
    repoMappings: mappings
  };
}
function _devAutoRules(s) {
  s = s || settings.getSettings();
  if (!s.devAutoCreate) return [];
  const raw = Array.isArray(s.devAutoCreateRules) ? s.devAutoCreateRules : [];
  return raw.map((r, i) => _devAutoNormRule(r, i, s)).filter(r => r.enabled && r.org && r.project);
}
// Parse a free-form repo spec. 3 segments ⇒ azdo org/project/repo; 2 ⇒ github owner/repo.
function _devParseRepoSpec(spec, provider) {
  const parts = String(spec || '').split('/').map(p => p.trim()).filter(Boolean);
  if (parts.length >= 3) return { provider: provider || 'azdo', org: parts[0], project: parts[1], repo: parts.slice(2).join('/') };
  if (parts.length === 2) return { provider: provider || 'github', org: parts[0], project: '', repo: parts[1] };
  return null;
}
// First area/tag mapping whose match substring is in the work item's area/tags.
function _devAutoRepoFor(rule, wi) {
  for (const m of (rule.repoMappings || [])) {
    const hay = String((m.field === 'tag' ? wi.tags : wi.areaPath) || '').toLowerCase();
    if (hay && hay.includes(m.match.toLowerCase())) {
      const spec = _devParseRepoSpec(m.repo, m.provider);
      if (spec) return spec;
    }
  }
  return null;
}
// Build devStore.create fields for a matched work item. Top-level org/project always
// stay the WORK ITEM's (they double as the work-item fetch location — see _devWorkItem),
// so an assigned repo goes primary ONLY when it's the same azdo org/project; a
// cross-provider/cross-org repo attaches as an extra slot instead (provider coupling).
function _devAutoBuildFields(rule, wi) {
  const fields = {
    title: wi.title || ('Work item ' + wi.id),
    provider: 'azdo',
    org: rule.org,
    project: rule.project,
    workItemId: String(wi.id),
    workItem: { id: wi.id, url: wi.url, title: wi.title, type: wi.type, state: wi.state, provider: 'azdo' },
    source: 'azdo-auto',
    autoRuleId: rule.id
  };
  const spec = _devAutoRepoFor(rule, wi);
  if (spec) {
    const sameAzdo = spec.provider === 'azdo'
      && spec.org.toLowerCase() === rule.org.toLowerCase()
      && spec.project.toLowerCase() === rule.project.toLowerCase();
    if (sameAzdo) fields.repo = spec.repo;
    else fields.repos = [{
      id: 'r-' + _meAiHash([spec.provider, spec.org, spec.project, spec.repo].join('|')),
      provider: spec.provider, org: spec.org, project: spec.project, repo: spec.repo
    }];
  }
  return fields;
}
function _devAutoExistingKeys() {
  const set = new Set();
  for (const c of devStore.all()) {
    if (!c || c.archived) continue;
    const k = _meAiDevCardKey(c);
    if (k) set.add(k);
  }
  return set;
}
async function _runDevAutoCreateRule(rule, { manual = false } = {}) {
  let items = [];
  try {
    items = await azdo.queryWorkItems(rule.org, rule.project, {
      type: rule.workItemType, state: rule.state, areaPath: rule.areaPath, assignedToMe: true, top: 100
    });
  } catch (e) {
    return { rule: rule.id, matched: 0, created: 0, error: (e && e.message) || 'query failed' };
  }
  const existing = _devAutoExistingKeys();
  const cards = [];
  for (const wi of items) {
    const key = _meAiDevKey('azdo', rule.org, rule.project, wi.id);
    if (existing.has(key)) continue;
    existing.add(key);
    try {
      const card = devStore.create(_devAutoBuildFields(rule, wi));
      cards.push(card);
      broadcastSSE('boards-changed', { id: card.homeBoardId || null, devId: card.id, dev: card });
    } catch (_) { /* keep going */ }
  }
  return { rule: rule.id, matched: items.length, created: cards.length, cards: cards.map(c => c.id) };
}
async function _previewDevAutoCreateRule(rule) {
  let items = [];
  try {
    items = await azdo.queryWorkItems(rule.org, rule.project, {
      type: rule.workItemType, state: rule.state, areaPath: rule.areaPath, assignedToMe: true, top: 100
    });
  } catch (e) {
    return { rule: rule.id, matched: 0, wouldCreate: 0, error: (e && e.message) || 'query failed' };
  }
  const existing = _devAutoExistingKeys();
  const fresh = items.filter(wi => !existing.has(_meAiDevKey('azdo', rule.org, rule.project, wi.id)));
  return {
    rule: rule.id,
    matched: items.length,
    wouldCreate: fresh.length,
    samples: fresh.slice(0, 8).map(wi => {
      const spec = _devAutoRepoFor(rule, wi);
      return {
        id: wi.id, title: wi.title, state: wi.state, areaPath: wi.areaPath,
        repo: spec ? [spec.org, spec.project, spec.repo].filter(Boolean).join('/') : null,
        repoProvider: spec ? spec.provider : null
      };
    })
  };
}
const _devAutoLastRun = new Map();
let _devAutoBusy = false;
setInterval(async () => {
  if (_devAutoBusy) return;
  if (!leaderCheck()) return;
  const s = settings.getSettings();
  if (!s.devAutoCreate) return;
  const rules = _devAutoRules(s);
  if (!rules.length) return;
  _devAutoBusy = true;
  try {
    const now = Date.now();
    for (const rule of rules) {
      const last = _devAutoLastRun.get(rule.id) || 0;
      if (now - last < rule.frequencyMin * 60 * 1000) continue;
      _devAutoLastRun.set(rule.id, now);
      await _runDevAutoCreateRule(rule, { manual: false });
    }
  } catch (_) { /* leader-gated background sweep, never throw */ }
  finally { _devAutoBusy = false; }
}, 5 * 60 * 1000);

// GET saved rules (normalized) + on/off state.
app.get('/api/dev-auto-create', (req, res) => {
  const s = settings.getSettings();
  const raw = Array.isArray(s.devAutoCreateRules) ? s.devAutoCreateRules : [];
  res.json({
    enabled: !!s.devAutoCreate,
    rules: raw.map((r, i) => _devAutoNormRule(r, i, s))
  });
});
// Preview a rule (defaults to the first saved rule; or pass { rule } to preview an
// unsaved edit). Read-only — reports match + would-create counts, no cards created.
app.post('/api/dev-auto-create/preview', async (req, res) => {
  try {
    const s = settings.getSettings();
    let rule;
    if (req.body && req.body.rule && typeof req.body.rule === 'object') rule = _devAutoNormRule(req.body.rule, 0, s);
    else rule = _devAutoRules(s)[0];
    if (!rule) return res.status(400).json({ error: 'no rule to preview' });
    res.json(await _previewDevAutoCreateRule(rule));
  } catch (e) { res.status(500).json({ error: (e && e.message) || 'preview failed' }); }
});
// Run all enabled saved rules now (manual), regardless of per-rule frequency.
app.post('/api/dev-auto-create/run', async (req, res) => {
  if (_devAutoBusy) return res.status(409).json({ error: 'auto-create already running' });
  const s = settings.getSettings();
  const rules = _devAutoRules(s);
  if (!rules.length) return res.status(400).json({ error: 'no enabled rules' });
  _devAutoBusy = true;
  try {
    const results = [];
    const now = Date.now();
    for (const rule of rules) { _devAutoLastRun.set(rule.id, now); results.push(await _runDevAutoCreateRule(rule, { manual: true })); }
    res.json({ ran: results.length, created: results.reduce((n, r) => n + (r.created || 0), 0), results });
  } catch (e) { res.status(500).json({ error: (e && e.message) || 'run failed' }); }
  finally { _devAutoBusy = false; }
});

// ---- Global dev-card store routes ----------------------------------------
// Dev cards are first-class objects in dev-store.js (not owned by a board). These
// routes serve the store directly; the per-op action routes below (worktree/
// refresh/sync/…) are still registered under /api/boards/:id/dev-items/:devId/* and
// reused for board-less cards via the alias middleware at the end of this block.
const DEV_CLIENT_FIELDS = ['title', 'provider', 'org', 'project', 'repo', 'baseBranch', 'branch', 'workItemId', 'prId', 'teamId', 'homeBoardId'];
function _pickDevClientFields(body) {
  const out = {};
  for (const k of DEV_CLIENT_FIELDS) if (body[k] !== undefined) out[k] = body[k];
  return out;
}

// List all dev cards (client filters by team/status/etc).
app.get('/api/dev-items', (req, res) => {
  res.json(devStore.all());
});

// Create a new dev card in the global store (may be board-less).
app.post('/api/dev-items', (req, res) => {
  const fields = _pickDevClientFields(req.body || {});
  if (!fields.title || !String(fields.title).trim()) return res.status(400).json({ error: 'A title is required' });
  const card = devStore.create(fields);
  broadcastSSE('boards-changed', { id: card.homeBoardId || null, devId: card.id, dev: card });
  res.json({ ok: true, dev: card });
});

// Read one dev card.
app.get('/api/dev-items/:devId', (req, res) => {
  const card = devStore.find(req.params.devId);
  if (!card) return res.status(404).json({ error: 'Dev card not found' });
  res.json(card);
});

// Edit a dev card's client-editable metadata.
app.patch('/api/dev-items/:devId', (req, res) => {
  const card = devStore.find(req.params.devId);
  if (!card) return res.status(404).json({ error: 'Dev card not found' });
  const updated = devStore.patch(req.params.devId, _pickDevClientFields(req.body || {}));
  broadcastSSE('boards-changed', { id: updated.homeBoardId || null, devId: updated.id, dev: updated });
  res.json({ ok: true, dev: updated });
});

// Delete a dev card from the store (and drop its durable report cache).
app.delete('/api/dev-items/:devId', (req, res) => {
  const card = devStore.find(req.params.devId);
  if (!card) return res.status(404).json({ error: 'Dev card not found' });
  const gone = devStore.remove(req.params.devId);
  try { devitems.clearReportCache(card.homeBoardId || DEV_NS, card.id); } catch {}
  broadcastSSE('boards-changed', { id: card.homeBoardId || null, devId: card.id, removed: true });
  res.json({ ok: true, removed: gone ? gone.id : req.params.devId });
});

// Alias /api/dev-items/:devId/<op> (worktree, refresh, sync, notes/update, …) to the
// board-scoped action handler below, resolving the card's home board (or a fixed
// namespace for board-less cards) so report-cache dirs stay stable. Requires an op
// segment, so bare /api/dev-items/:devId (handled above) is never rewritten.
app.use((req, res, next) => {
  const m = /^\/api\/dev-items\/([^/]+)\/([^?]+)(\?.*)?$/.exec(req.url);
  if (!m) return next();
  const devId = decodeURIComponent(m[1]);
  const card = devStore.find(devId);
  const boardId = (card && card.homeBoardId) || DEV_NS;
  req.url = `/api/boards/${encodeURIComponent(boardId)}/dev-items/${encodeURIComponent(devId)}/${m[2]}${m[3] || ''}`;
  next();
});

// Create (or reuse) the worktree for a dev card repo slot. Runs in the background
// since a first-time clone can be slow; the slot flips worktreeStatus creating→
// ready/error and the SPA re-renders off the boards-changed SSE.
app.post('/api/boards/:id/dev-items/:devId/worktree', async (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const d = ctx.dev;
  // Which repo slot? Defaults to the primary repo; an extra repo is targeted by id.
  const slotId = (req.body && req.body.repoId) || 'primary';
  const slot = _findRepoSlot(d, slotId);
  if (!slot || !slot.org || !slot.project || !slot.repo) {
    return res.status(400).json({ error: 'Dev card repo is missing org/project/repo.' });
  }
  // The dev card ALWAYS works on its OWN `dev/<slug>` branch and must never borrow a
  // PR's branch — that borrowing was the original dev↔PR worktree collision. PR review
  // has its own separate worktree (see the PR-worktree routes), so a PR is opened there,
  // not here. Any legacy `source:'pr'` request is intentionally ignored.
  const branch = slot.branch;
  res.json({ ok: true, status: 'creating', repoId: slot.id });
  // Fire-and-forget; persist the outcome. createWorktreeAsync runs the blocking
  // clone in a worker thread so this server stays responsive during a big clone.
  (async () => {
    try {
      const r = await devitems.createWorktreeAsync({
        org: slot.org, project: slot.project, repo: slot.repo, provider: slot.provider || 'azdo',
        baseBranch: slot.baseBranch, branch, devId: d.id
      });
      const fresh = _devItemCtx(req.params.id, req.params.devId);
      if (!fresh) return;
      const save = { worktreePath: r.worktreePath, branch: r.branch, worktreeStatus: 'ready', worktreeError: null, git: r.git || null };
      _saveRepoSlot(fresh, slot.id, save);
      // Re-aggregate reports across EVERY repo slot (this newly-ready worktree plus
      // any siblings), tagging each with its source repo. Re-read the context so the
      // freshly-persisted worktree path for this slot is included in the scan.
      try {
        const withWt = _devItemCtx(req.params.id, req.params.devId);
        if (withWt) { const reports = _rescanDevReports(req.params.id, req.params.devId, withWt.dev); withWt.save({ reports }); }
      } catch {}
      // Per-worktree agents: seed this slot's ACTIVE worktree with its OWN default
      // implementer (the intrinsic "worktree agent" the CLI auto-selects) when it has
      // no roster yet, so opening the CLI always has an agent to launch.
      try {
        const after = _devItemCtx(req.params.id, req.params.devId);
        if (after) {
          const s2 = _findRepoSlot(after.dev, slot.id);
          const wt2 = s2 && _resolveDevWt(s2, undefined);
          if (s2 && wt2) await _seedWtImplementer(after, s2, wt2);
        }
      } catch {}
    } catch (e) {
      const fresh = _devItemCtx(req.params.id, req.params.devId);
      if (fresh) _saveRepoSlot(fresh, slot.id, { worktreeStatus: 'error', worktreeError: (e && e.message) || 'Worktree failed' });
    }
  })();
});

// Create a NEW dev worktree ("approach"/"aspect") on a repo slot. A slot may hold
// many independent approaches — each its own dev/<slug>-<n> branch + worktree +
// agent + reports, a real workshop where agents implement. Seeds off the slot's
// base branch by default, or off another approach's tip (fromWtId). Appends to
// devs[] as 'creating', then (on success) makes it the ACTIVE approach — we do NOT
// flip active until it's ready, so the in-flight empty path never blanks the
// mirror of the currently-active approach.
app.post('/api/boards/:id/dev-items/:devId/dev-worktree', async (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const d = ctx.dev;
  const slotId = (req.body && req.body.repoId) || 'primary';
  const slot = _findRepoSlot(d, slotId);
  if (!slot || !slot.org || !slot.project || !slot.repo) {
    return res.status(400).json({ error: 'Dev card repo is missing org/project/repo.' });
  }
  const aspect = String((req.body && req.body.aspect) || '').trim() || 'Worktree';
  const scope = String((req.body && req.body.scope) || '').trim();
  const fromWtId = (req.body && req.body.fromWtId) || '';

  const existing = _slotDevWorktrees(slot);
  const slug = _devSlug(d);
  // Next approach sequence: past the highest existing -N suffix and the count.
  let seq = existing.length + 1;
  for (const w of existing) { const m = String(w.branch || '').match(/-(\d+)$/); if (m) seq = Math.max(seq, parseInt(m[1], 10) + 1); }
  if (seq < 2) seq = 2;
  const wtId = 'dev' + seq;
  const branch = 'dev/' + slug + '-' + seq;
  const wtKey = String(d.id) + '--dev' + seq;
  // Seed off another approach's local branch tip, or off the base branch.
  let seedBase = slot.baseBranch || 'main';
  if (fromWtId) { const src = existing.find(w => w.id === fromWtId); if (src && src.branch) seedBase = src.branch; }

  // Optimistically append the pending approach WITHOUT changing the active one.
  const pending = { id: wtId, aspect, scope, branch, worktreePath: '', worktreeStatus: 'creating', worktreeError: null, git: null, agentName: '', promotedPrId: '', createdAt: new Date().toISOString() };
  const withPending = _saveDevWorktrees(ctx, slot.id, existing.concat([pending]), _activeDevWtId(slot));
  res.json({ ok: true, status: 'creating', repoId: slot.id, wtId, dev: withPending });

  (async () => {
    try {
      const r = await devitems.createWorktreeAsync({
        org: slot.org, project: slot.project, repo: slot.repo, provider: slot.provider || 'azdo',
        baseBranch: seedBase, branch, devId: wtKey
      });
      const fresh = _devItemCtx(req.params.id, req.params.devId);
      if (!fresh) return;
      // Mark ready and flip active to the new approach (its path is now real, so
      // mirroring it to the slot top level is safe).
      _saveDevWorktree(fresh, slot.id, wtId, { worktreePath: r.worktreePath, branch: r.branch, worktreeStatus: 'ready', worktreeError: null, git: r.git || null, aspect, scope });
      const afterSet = _devItemCtx(req.params.id, req.params.devId);
      if (afterSet) _setActiveDevWt(afterSet, slot.id, wtId);
      // Per-worktree agents: seed the newly-active aspect worktree with its OWN
      // brief-steered implementer (the intrinsic "worktree agent" the CLI auto-selects).
      // Every new aspect gets one so the brief (wt.scope) becomes a real, launchable
      // agent — additional specialised personas are added per-worktree from the SPA.
      try {
        const after = _devItemCtx(req.params.id, req.params.devId);
        if (after) {
          const s2 = _findRepoSlot(after.dev, slot.id);
          const wt2 = s2 && _resolveDevWt(s2, wtId);
          if (s2 && wt2) await _seedWtImplementer(after, s2, wt2);
        }
      } catch {}
      // Re-aggregate reports across every slot now that a new worktree is live.
      try { const withWt = _devItemCtx(req.params.id, req.params.devId); if (withWt) { const reports = _rescanDevReports(req.params.id, req.params.devId, withWt.dev); withWt.save({ reports }); } } catch {}
    } catch (e) {
      const fresh = _devItemCtx(req.params.id, req.params.devId);
      if (fresh) _saveDevWorktree(fresh, slot.id, wtId, { worktreeStatus: 'error', worktreeError: (e && e.message) || 'Worktree failed' });
    }
  })();
});

// Switch which dev worktree ("approach") is active on a repo slot. The active
// approach is the one mirrored to the slot's top-level fields, so commits / PR /
// summary target it.
app.post('/api/boards/:id/dev-items/:devId/dev-worktree/activate', (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const slotId = (req.body && req.body.repoId) || 'primary';
  const wtId = (req.body && req.body.wtId) || '';
  if (!wtId) return res.status(400).json({ error: 'wtId is required' });
  const updated = _setActiveDevWt(ctx, slotId, wtId);
  if (!updated) return res.status(404).json({ error: 'Approach not found on this repo.' });
  res.json({ ok: true, dev: updated, repoId: slotId, wtId });
});

// Merge one aspect (dev worktree) INTO another on the same repo slot. This is a
// local git merge run inside the TARGET aspect's worktree — the source aspect's
// branch is layered on top of the target's. Aspects can merge into each other
// freely and repeatedly; the target aspect records its merge lineage (mergedFrom)
// so the card can visualize which aspects it now contains. Nothing is pushed
// UNLESS the target aspect is the one currently feeding the repo's single PR
// (active + a PR exists): then the merge is promoted so the open PR updates.
app.post('/api/boards/:id/dev-items/:devId/dev-worktree/merge', async (req, res) => {
  let ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const slotId = (req.body && req.body.repoId) || 'primary';
  const sourceWtId = (req.body && req.body.sourceWtId) || '';
  const targetWtId = (req.body && req.body.targetWtId) || '';
  if (!sourceWtId || !targetWtId) return res.status(400).json({ error: 'sourceWtId and targetWtId are required.' });
  if (sourceWtId === targetWtId) return res.status(400).json({ error: 'An aspect cannot merge into itself.' });
  let slot = _findRepoSlot(ctx.dev, slotId);
  if (!slot || !slot.org || !slot.project || !slot.repo) return res.status(400).json({ error: 'Dev card repo is missing org/project/repo.' });
  const source = _resolveDevWt(slot, sourceWtId);
  const target = _resolveDevWt(slot, targetWtId);
  if (!source) return res.status(404).json({ error: 'Source aspect not found on this repo.' });
  if (!target) return res.status(404).json({ error: 'Target aspect not found on this repo.' });
  if (!source.branch) return res.status(400).json({ error: 'Source aspect has no branch yet.' });
  if (!target.branch) return res.status(400).json({ error: 'Target aspect has no branch yet.' });

  // Self-heal the target worktree if its dir is gone (branch survives in the clone).
  let tgtWtPath = target.worktreePath;
  if (!tgtWtPath || !fs.existsSync(tgtWtPath)) {
    try {
      const wt = devitems.createWorktree({
        org: slot.org, project: slot.project, repo: slot.repo, provider: slot.provider || 'azdo',
        baseBranch: slot.baseBranch, branch: target.branch, devId: String(ctx.dev.id) + '--' + targetWtId
      });
      tgtWtPath = wt.worktreePath;
      _saveDevWorktree(ctx, slot.id, targetWtId, { worktreePath: tgtWtPath });
      ctx = _devItemCtx(req.params.id, req.params.devId); slot = _findRepoSlot(ctx.dev, slotId);
    } catch (e) { return res.status(500).json({ error: 'Failed to restore target aspect worktree: ' + ((e && e.message) || e) }); }
  }

  // Perform the merge.
  let r;
  try { r = devitems.mergeAspectBranch(tgtWtPath, { sourceBranch: source.branch, targetBranch: target.branch, desc: _devDesc(slot) }); }
  catch (e) { return res.status(500).json({ error: 'Merge failed: ' + ((e && e.message) || e) }); }
  if (!r.ok) return res.status(r.conflict ? 409 : 500).json({ error: r.message, dev: ctx.dev, conflict: !!r.conflict });

  // Record merge lineage on the target aspect (dedupe by source wtId, keep latest).
  const srcLabel = _approachLabel(source);
  const prevLineage = Array.isArray(target.mergedFrom) ? target.mergedFrom.filter(x => x && x.wtId !== sourceWtId) : [];
  const mergedFrom = prevLineage.concat([{ wtId: sourceWtId, aspect: srcLabel, branch: source.branch, at: new Date().toISOString() }]);
  let git = target.git;
  try { git = devitems.worktreeStatus(tgtWtPath, { fetch: false, baseBranch: slot.baseBranch, desc: _devDesc(slot) }); } catch {}
  _saveDevWorktree(ctx, slot.id, targetWtId, { mergedFrom, git, worktreePath: tgtWtPath, worktreeStatus: 'ready' });
  ctx = _devItemCtx(req.params.id, req.params.devId); slot = _findRepoSlot(ctx.dev, slotId);

  // If the target aspect is the one feeding the repo's single PR (it's active and a
  // PR exists), promote so the open PR picks up the merged commits.
  let prUpdated = false, prMessage = '';
  const targetIsActive = _activeDevWtId(slot) === targetWtId;
  if (targetIsActive && slot.prId && slot.prBranch && r.merged > 0) {
    let prWtPath = slot.prWorktreePath;
    if (!prWtPath || !fs.existsSync(prWtPath)) {
      try {
        const wt = devitems.createPrWorktree({
          org: slot.org, project: slot.project, repo: slot.repo, provider: slot.provider || 'azdo',
          prBranch: slot.prBranch, fromRef: slot.branch, wtDevId: String(ctx.dev.id) + '--pr' + (slot.prSeq || 1)
        });
        prWtPath = wt.worktreePath;
      } catch (e) { prWtPath = ''; }
    }
    if (prWtPath) {
      try {
        const pr = devitems.promoteToPr(prWtPath, { devBranch: slot.branch, prBranch: slot.prBranch, desc: _devDesc(slot) });
        if (pr && pr.ok && pr.pushed) { prUpdated = true; prMessage = pr.message; }
        else if (pr && !pr.ok) { prMessage = pr.message; }
        const prDivergence = devitems.devPrDivergence({ org: slot.org, project: slot.project, repo: slot.repo, provider: slot.provider || 'azdo', devBranch: slot.branch, prBranch: slot.prBranch });
        _saveRepoSlot(ctx, slot.id, { prWorktreePath: prWtPath, prDivergence });
        ctx = _devItemCtx(req.params.id, req.params.devId);
      } catch (e) { prMessage = (e && e.message) || 'PR update failed'; }
    }
  }

  const message = r.message + (prUpdated ? ' PR updated.' : '');
  res.json({ ok: true, dev: ctx.dev, repoId: slot.id, merged: r.merged, sourceWtId, targetWtId, prUpdated, prMessage, message });
});

// Refresh a dev card's live state: git ahead/behind/dirty + work item + PR.
app.post('/api/boards/:id/dev-items/:devId/refresh', async (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const d = ctx.dev;
  const partial = {};
  // Git status (only if a worktree exists).
  if (d.worktreePath) {
    try { partial.git = devitems.worktreeStatus(d.worktreePath, { baseBranch: d.baseBranch, desc: _devDesc(d) }); } catch (e) { partial.gitError = (e && e.message) || 'git failed'; }
  }
  // Dev<->PR divergence (promote/pull) — local rev-list of dev/<slug> vs pr/<slug>-<N>.
  if (d.branch && d.prBranch) {
    try { partial.prDivergence = devitems.devPrDivergence({ org: d.org, project: d.project, repo: d.repo, provider: d.provider, devBranch: d.branch, prBranch: d.prBranch }); } catch {}
  }
  // Reports: aggregate across every repo slot (live worktrees + cached-from-removed).
  try { partial.reports = _rescanDevReports(req.params.id, req.params.devId, d); } catch {}
  // Work item.
  if (d.workItemId && d.org && d.project) {
    try { partial.workItem = await _devWorkItem(_devDesc(d), d.workItemId); } catch (e) { partial.workItemError = (e && e.message) || 'work item failed'; }
  }
  // Pull request (primary repo — tracked at the top level).
  if (d.prId && d.org && d.project && d.repo) {
    try { partial.pr = await _devPullRequest(_devDesc(d), d.prId); } catch (e) { partial.prError = (e && e.message) || 'PR failed'; }
  }
  // Extra repos: refresh each slot's git status + its own PR (PRs are per repo).
  const extras = _devExtraRepos(d);
  if (extras.length) {
    partial.repos = await Promise.all(extras.map(async (r) => {
      const out = { ...r };
      if (r.worktreePath) { try { out.git = devitems.worktreeStatus(r.worktreePath, { baseBranch: r.baseBranch, desc: _devDesc(r) }); } catch {} }
      if (r.branch && r.prBranch) { try { out.prDivergence = devitems.devPrDivergence({ org: r.org, project: r.project, repo: r.repo, provider: r.provider, devBranch: r.branch, prBranch: r.prBranch }); } catch {} }
      if (r.prId && r.org && r.project && r.repo) { try { out.pr = await _devPullRequest(_devDesc(r), r.prId); } catch {} }
      return out;
    }));
  }
  const updated = ctx.save(partial);
  res.json({ ok: true, dev: updated });
});

// Sync the worktree with origin (fetch + fast-forward).
app.post('/api/boards/:id/dev-items/:devId/sync', async (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const d = ctx.dev;
  const slotId = (req.body && req.body.repoId) || 'primary';
  const slot = _findRepoSlot(d, slotId);
  if (!slot || !slot.worktreePath) return res.status(400).json({ error: 'No worktree to sync — create one first.' });
  let r;
  try { r = devitems.syncWorktree(slot.worktreePath, { baseBranch: slot.baseBranch, desc: _devDesc(slot) }); }
  catch (e) { return res.status(500).json({ ok: false, error: (e && e.message) || 'Sync failed' }); }
  const updated = _saveRepoSlot(ctx, slot.id, { git: r.status || slot.git });
  res.json({ ok: r.ok, message: r.message, dev: updated });
});

// Push local worktree changes up to origin for a dev card's repo slot. Commits any
// uncommitted changes first so the user's full local state lands on the remote
// branch, then refreshes the slot's git status. This is the dev-card counterpart
// to the PR-create push: it lets a user keep an existing PR's branch up to date.
app.post('/api/boards/:id/dev-items/:devId/push', async (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const d = ctx.dev;
  const slotId = (req.body && req.body.repoId) || 'primary';
  const slot = _findRepoSlot(d, slotId);
  if (!slot || !slot.worktreePath || !fs.existsSync(slot.worktreePath)) {
    return res.status(400).json({ error: 'No worktree to push — create one first.' });
  }
  let committed = 0;
  try {
    const c = devitems.commitAll(slot.worktreePath, { message: 'Update ' + (slot.branch || 'branch') });
    if (!c.ok) return res.status(500).json({ ok: false, error: 'Failed to commit local changes: ' + c.message });
    if (c.committed) committed = c.files;
  } catch (e) { return res.status(500).json({ ok: false, error: 'Failed to commit local changes: ' + ((e && e.message) || e) }); }
  let push;
  try { push = devitems.pushBranch(slot.worktreePath, { branch: slot.branch, desc: _devDesc(slot) }); }
  catch (e) { return res.status(500).json({ ok: false, error: 'Failed to push: ' + ((e && e.message) || e) }); }
  if (!push.ok) return res.status(500).json({ ok: false, error: 'Failed to push: ' + push.message });
  let git = slot.git;
  try { git = devitems.worktreeStatus(slot.worktreePath, { fetch: true, baseBranch: slot.baseBranch, desc: _devDesc(slot) }); } catch {}
  const updated = _saveRepoSlot(ctx, slot.id, { git });
  const message = committed
    ? ('Committed ' + committed + ' change' + (committed === 1 ? '' : 's') + ' and pushed to ' + (push.branch || slot.branch) + '.')
    : ('Pushed to ' + (push.branch || slot.branch) + '.');
  res.json({ ok: true, message, committed, dev: updated });
});

// Commit-level branch insight for a dev card repo slot: which commits are local
// (unpushed), which are on the remote/PR branch but missing locally, plus recent
// history tagged pushed/local. Read-only; pass ?fetch=1 to refresh from origin
// first. The slot's upstream is its own origin/<branch> (== the PR source branch
// when a PR exists), so this answers both "vs origin" and "vs PR branch".
app.get('/api/boards/:id/dev-items/:devId/commits', (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const slot = _findRepoSlot(ctx.dev, req.query.repoId || 'primary');
  if (!slot || !slot.worktreePath || !fs.existsSync(slot.worktreePath)) {
    return res.status(400).json({ error: 'No worktree for this repo yet.' });
  }
  let commits;
  try { commits = devitems.branchCommits(slot.worktreePath, { baseBranch: slot.baseBranch, fetch: req.query.fetch === '1', desc: _devDesc(slot) }); }
  catch (e) { return res.status(500).json({ error: (e && e.message) || 'git failed' }); }
  res.json({ ok: true, commits, slot: { id: slot.id, repo: slot.repo, branch: slot.branch, prId: slot.prId || ctx.dev.prId || '' } });
});
// `repos` is the unified slot list, each entry { slot, pr, git, diff } — so a card
// that spans multiple repos (primary + d.repos[]) is summarized across ALL of them,
// each with its own PR, reviewer votes, branch sync state, and diff hunks.
function _buildDevSummaryPrompt(d, { wi, wiComments, repos } = {}) {
  const list = Array.isArray(repos) ? repos.filter(Boolean) : [];
  const multi = list.length > 1;
  const ctxLines = [];
  ctxLines.push(`Dev card: ${d.title || d.repo}`);
  if (wi) ctxLines.push(`Work item #${wi.id} [${wi.type}] "${wi.title}" — state: ${wi.state}${wi.assignedTo ? ', assigned: ' + wi.assignedTo : ''}`);
  // Recent work-item discussion: the headline fields rarely capture the live status,
  // so surface the most recent comments (newest first) as primary status signal.
  const comments = (wiComments && Array.isArray(wiComments.comments)) ? wiComments.comments : [];
  if (comments.length) {
    ctxLines.push('');
    ctxLines.push(`Work item discussion — ${comments.length} most recent comment${comments.length === 1 ? '' : 's'} (newest first; the latest reflects the CURRENT status):`);
    let budget = 4000;
    for (const c of comments) {
      if (budget <= 0) break;
      const when = c.date ? new Date(c.date).toISOString().slice(0, 10) : '';
      const body = String(c.text || '').slice(0, 700);
      const line = `  • ${c.author || 'someone'}${when ? ' (' + when + ')' : ''}: ${body}`;
      ctxLines.push(line);
      budget -= line.length;
    }
  }
  if (multi) ctxLines.push(`This work spans ${list.length} repositories — each has its own PR / branch / diff below.`);
  // Per-repo diff slice: keep the whole prompt bounded regardless of repo count.
  const diffCap = multi ? 18000 : 32000;
  list.forEach((rp, i) => {
    const s = rp.slot || {};
    const pr = rp.pr, git = rp.git, diff = rp.diff;
    ctxLines.push('');
    const head = multi
      ? `── Repository ${i + 1} of ${list.length}${s.primary ? ' (primary)' : ''}: ${s.org}/${s.project}/${s.repo}  Branch: ${s.branch || '(none)'}  Base: ${s.baseBranch || 'main'}`
      : `Repo: ${s.org}/${s.project}/${s.repo}  Branch: ${s.branch || '(none)'}  Base: ${s.baseBranch || 'main'}`;
    ctxLines.push(head);
    if (pr) {
      // Translate the raw AzDO PR status into an unambiguous merged/open phrase.
      // status: active = OPEN (not merged), completed = MERGED, abandoned = CLOSED.
      // mergeStatus (succeeded/conflicts/queued) is only about *mergeability* — it
      // must NOT be read as "the PR was merged", which the summarizer otherwise does.
      const st = String(pr.status || '').toLowerCase();
      const lifecycle = st === 'completed' ? 'MERGED into ' + pr.targetBranch
        : st === 'abandoned' ? 'ABANDONED (closed without merging)'
        : 'OPEN — NOT yet merged';
      const mergeability = st === 'completed' ? '' :
        (pr.mergeStatus ? `, mergeability: ${pr.mergeStatus} (whether it CAN merge cleanly, not whether it has)` : '');
      ctxLines.push(`PR #${pr.id} "${pr.title}" — ${lifecycle}${pr.isDraft ? ' (draft)' : ''}${mergeability}, ${pr.sourceBranch} → ${pr.targetBranch}`);
      // Reviewer votes are a primary "true status" signal: an open PR with all
      // required approvals is one click from merge; one waiting/rejecting required
      // reviewer is the actual blocker. Translate AzDO's numeric vote codes.
      if (Array.isArray(pr.reviewers) && pr.reviewers.length) {
        const vlabel = (v) => v >= 10 ? 'approved' : v === 5 ? 'approved with suggestions' : v <= -10 ? 'REJECTED' : v <= -5 ? 'waiting for author' : 'no vote yet';
        const rv = pr.reviewers.map(r => `${r.name || 'reviewer'}${r.isRequired ? ' (required)' : ''}: ${vlabel(r.vote)}`).join('; ');
        ctxLines.push(`PR reviewers — ${rv}`);
      }
    } else {
      ctxLines.push('No pull request opened for this repo yet.');
    }
    if (git) ctxLines.push(`Local branch vs its own origin remote: ${git.ahead || 0} ahead / ${git.behind || 0} behind${git.dirty ? ', uncommitted changes present' : ', clean working tree'} (this is the feature branch's sync state, NOT a signal that it merged into the base branch)`);
    if (diff) { ctxLines.push(''); ctxLines.push(diff.slice(0, diffCap)); }
    else if (!s.worktreePath) ctxLines.push('No local worktree for this repo (no diff available).');
  });

  const spanNote = multi
    ? 'This one piece of work spans MULTIPLE repositories; each repository section below has its own pull request (with reviewer votes) and local git worktree showing the ACTUAL diff hunks (committed vs base, plus staged/unstaged edits).'
    : 'You are given an Azure DevOps work item, its pull request (including reviewer votes), and the local git worktree with the ACTUAL git diff hunks of what changed (committed vs base, plus staged/unstaged edits).';
  return [
    'You are a dev-work status summarizer. You are given the COMPLETE current state of one piece of work. ' + spanNote + ' Reason directly over that real data. Write a SHORT status briefing (2–4 sentences of plain prose) that tells the developer, at a glance: what this work actually changes, where it truly stands, and what is left to do next.',
    'Reason about the diff content: summarize WHAT the changes do (e.g. "adds X validation", "refactors the Y handler", "wires up the Z endpoint"), not just which files were touched. Ground the status in the real signals: PR lifecycle, reviewer votes, mergeability, and the branch sync/dirty state. If a "Work item discussion" section is present, treat the MOST RECENT comments as authoritative for the current status, blockers, and decisions (they often explain a state change or what is being waited on) — reconcile them with the PR/git signals and prefer the comment thread when it is more current than the work-item state field. If the PR is in draft, has conflicts, is awaiting a required reviewer, or the branch is behind origin or dirty, call that out as the next action. If everything is approved and clean, say it looks ready to merge. If the diff is truncated, base your "what changed" on the hunks you can see plus the file stat. If there is nothing actionable, say so. No preamble, no headings, no surrounding quotes.',
    multi
      ? 'Because this work spans multiple repositories, synthesize ONE cohesive cross-repo status — describe what the change set does as a whole, and call out per-repo blockers where they differ (e.g. "the server PR is approved but the client PR is still in draft"). Only say the whole thing looks ready to merge when EVERY repo\'s PR is mergeable/approved and its branch is clean; if any single repo is blocked, the overall next action is that repo.'
      : '',
    'CRITICAL: Only state that a PR is merged/landed if its lifecycle is explicitly MERGED above. A PR that is OPEN has NOT been merged, regardless of mergeability or how clean/in-sync the local branch is — never infer a merge from "clean working tree", "0 ahead/0 behind", or a "succeeded" mergeability. For an open PR, the next step is review/approval and completing the merge, not closing the work item.',
    'You have NO tools and the full context you need is already provided below. Do NOT run, narrate, or fabricate commands or tool calls. Never emit XML-like tags such as <tool_calls>, <tool_call>, <command>, <stdout>, or <tool_results>. Respond with ONLY the final status-briefing prose — nothing before or after it.',
    '',
    ctxLines.join('\n').slice(0, 48000),
    '',
    'Status briefing:'
  ].filter(Boolean).join('\n');
}

// A compact signature of a dev card's *observable* state. When this changes the
// summary is considered stale and is regenerated by the background reconciler.
// Captures only meaningful, user-visible signals so trivial churn doesn't thrash.
// Spans ALL repos: each repo's PR (incl. reviewer votes) and git sync state are
// folded in, so a vote change on ANY repo's PR re-triggers the summary.
function _devFingerprint({ wi, wiComments, repos } = {}) {
  const parts = [];
  if (wi) parts.push('wi:' + wi.id + '|' + (wi.state || '') + '|' + (wi.title || '') + '|' + (wi.assignedTo || ''));
  // A new (or edited) work-item comment changes the live status, so fold the comment
  // count + latest comment id/date into the fingerprint to re-trigger the summary.
  if (wiComments) {
    const latest = (wiComments.comments && wiComments.comments[0]) || null;
    parts.push('wic:' + (wiComments.count || 0) + '|' + (latest ? (latest.id || '') + '@' + (latest.date || '') : ''));
  }
  for (const rp of (Array.isArray(repos) ? repos : [])) {
    if (!rp) continue;
    const s = rp.slot || {};
    const tag = s.id || s.repo || '?';
    if (rp.pr) {
      const votes = (rp.pr.reviewers || []).map(r => (r.name || '') + '=' + r.vote).sort().join(',');
      parts.push('pr@' + tag + ':' + rp.pr.id + '|' + (rp.pr.status || '') + '|' + (rp.pr.isDraft ? 'd' : '') + '|' + (rp.pr.mergeStatus || '') + '|' + (rp.pr.title || '') + '|' + votes);
    }
    if (rp.git) parts.push('git@' + tag + ':' + (rp.git.head || '') + '|' + (rp.git.ahead || 0) + '|' + (rp.git.behind || 0) + '|' + (rp.git.dirty ? 'dirty' : 'clean'));
  }
  return parts.join('||');
}

// Gather the live work-item + PER-REPO (PR + git) state for a card across ALL repo
// slots (primary + d.repos[]). No diffs here — this is the cheap path used for the
// fingerprint and reused by the generator. PR is best-effort network; git is local
// (network `git fetch` only when fresh:true). Returns { wi, repos:[{slot,pr,git}] }.
async function _devRepoMeta(d, { fresh = false } = {}) {
  let wi = d.workItem;
  let wiComments = null;
  try { if (d.workItemId && d.org && d.project) wi = await _devWorkItem(_devDesc(d), d.workItemId); } catch {}
  // The work-item fields are only the headline; the live status (decisions, blockers,
  // "moved to X because…") lives in the discussion thread, so pull recent comments to
  // ground the summary. Best-effort — never let a comment fetch fail the meta gather.
  try { if (d.workItemId && d.org && d.project) wiComments = await _devWorkItemComments(_devDesc(d), d.workItemId, { top: 12 }); } catch {}
  const slots = _devRepoSlots(d).filter(s => s && s.org && s.project && s.repo);
  const repos = await Promise.all(slots.map(async (s) => {
    let pr = s.primary ? d.pr : s.pr;
    const prId = s.primary ? d.prId : s.prId;
    try { if (prId && s.org && s.project && s.repo) { const p = await _devPullRequest(_devDesc(s), prId); if (p) pr = p; } } catch {}
    let git = s.primary ? d.git : s.git;
    try { if (s.worktreePath) { const g = devitems.worktreeStatus(s.worktreePath, { fetch: !!fresh, baseBranch: s.baseBranch, desc: _devDesc(s) }); if (g) git = g; } } catch {}
    return { slot: s, pr: pr || null, git: git || null };
  }));
  return { wi: wi || null, wiComments: wiComments || null, repos };
}

// Map gathered per-repo meta back into a persistable partial: primary repo's pr/git
// live at the top level; extra repos' pr/git live inside their d.repos[] entry. Used
// to keep every repo slot's badges current alongside a regenerated summary.
function _devLivePartial(d, meta) {
  const partial = { workItem: (meta && meta.wi) || d.workItem };
  const extraById = {};
  for (const rp of ((meta && meta.repos) || [])) {
    if (!rp || !rp.slot) continue;
    if (rp.slot.primary) { partial.pr = rp.pr || d.pr; partial.git = rp.git || d.git; }
    else extraById[rp.slot.id] = rp;
  }
  const extras = _devExtraRepos(d);
  if (extras.length) {
    partial.repos = extras.map(r => {
      const rp = r && extraById[r.id];
      return rp ? { ...r, pr: rp.pr || r.pr || null, git: rp.git || r.git || null } : r;
    });
  }
  return partial;
}

// Strip any hallucinated tool-call transcript a tool-less model may emit before
// its real answer (e.g. <tool_calls>…</tool_calls>, <command>…</command>,
// <stdout>…</stdout>). With no tools available the model sometimes role-plays
// running commands as plain text, then writes the genuine summary at the end —
// so prefer the prose that follows the final transcript block, then scrub any
// residual tags. Returns clean prose.
function _cleanDevSummaryText(raw) {
  let t = String(raw || '');
  const tagRe = /<\/?(tool_calls|tool_call|tool_name|tool_results|tool_call_result|command|stdout|stderr|input)\b[^>]*>/i;
  if (!tagRe.test(t)) return t.trim();
  // The genuine briefing is whatever follows the last closing transcript tag.
  const closeRe = /<\/(tool_results|tool_calls|tool_call_result|tool_call)>/gi;
  let lastEnd = -1, m;
  while ((m = closeRe.exec(t)) !== null) lastEnd = m.index + m[0].length;
  if (lastEnd >= 0) {
    const tail = t.slice(lastEnd).trim();
    if (tail) t = tail;
  }
  // Belt-and-suspenders: drop any remaining transcript blocks / lone tags.
  t = t
    .replace(/<tool_calls>[\s\S]*?<\/tool_calls>/gi, '')
    .replace(/<tool_results>[\s\S]*?<\/tool_results>/gi, '')
    .replace(/<tool_call>[\s\S]*?<\/tool_call>/gi, '')
    .replace(/<tool_call_result>[\s\S]*?<\/tool_call_result>/gi, '')
    .replace(/<\/?(tool_calls|tool_call|tool_name|tool_results|tool_call_result|command|stdout|stderr|input)\b[^>]*>/gi, '');
  return t.replace(/\n{3,}/g, '\n\n').trim();
}

// Resolve the freshest work-item + PER-REPO PR/git/diff for a card (best-effort,
// across ALL repo slots) and run the AI summarizer. Tools are disabled so the model
// emits pure prose from the in-context prompt (no file-exploration leakage). The
// diff budget is split across repos that have a worktree so the prompt stays bounded
// no matter how many repos a card spans. Returns { text, generatedAt, wi, repos, meta }.
// Pass opts.meta (from _devRepoMeta) to avoid re-fetching PR/git.
async function _generateDevSummary(d, opts = {}) {
  const meta = opts.meta || await _devRepoMeta(d, { fresh: !!opts.fresh });
  const total = opts.maxDiffChars || 16000;
  const withWt = meta.repos.filter(rp => rp.slot && rp.slot.worktreePath);
  const per = withWt.length ? Math.max(5000, Math.floor(total / withWt.length)) : total;
  for (const rp of meta.repos) {
    rp.diff = '';
    try { if (rp.slot && rp.slot.worktreePath) rp.diff = devitems.diffSummary(rp.slot.worktreePath, { baseBranch: rp.slot.baseBranch, maxDiffChars: per }); } catch {}
  }
  const prompt = _buildDevSummaryPrompt(d, { wi: meta.wi, wiComments: meta.wiComments, repos: meta.repos });
  // Run from the primary worktree (or the first repo with one) for a sane cwd.
  const cwdSlot = (meta.repos.find(rp => rp.slot && rp.slot.primary && rp.slot.worktreePath)
    || meta.repos.find(rp => rp.slot && rp.slot.worktreePath) || {}).slot;
  let acc = '';
  const result = await sdkRunner.runChat({ config: null, prompt, sessionId: require('crypto').randomUUID(), cwd: (cwdSlot && cwdSlot.worktreePath) || d.worktreePath || __dirname, availableTools: [], onChunk: (c) => { acc += c; }, meta: { source: 'system', category: 'dev_cards' } });
  const text = _cleanDevSummaryText(acc.trim() || (result && result.output) || '');
  if (!text) throw new Error('Empty summary');
  return { text, generatedAt: new Date().toISOString(), wi: meta.wi, repos: meta.repos, meta };
}

// Regenerate the AI summary of where the dev work stands (work item + every repo's
// PR + diff). Manual trigger — always regenerates; the background reconciler keeps it fresh.
app.post('/api/boards/:id/dev-items/:devId/summary', async (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const d = ctx.dev;
  try {
    const gen = await _generateDevSummary(d, { fresh: true });
    const fingerprint = _devFingerprint({ wi: gen.wi, wiComments: gen.meta && gen.meta.wiComments, repos: gen.repos });
    const updated = ctx.save({ summary: { text: gen.text, generatedAt: gen.generatedAt, fingerprint, auto: false }, ..._devLivePartial(d, gen.meta) });
    res.json({ ok: true, dev: updated });
  } catch (e) {
    res.status(500).json({ ok: false, error: (e && e.message) || 'Summary failed' });
  }
});

// ── Auto-summary reconciler ────────────────────────────────────────────────
// Keep dev-card summaries "relatively up to date" without a manual click: on a
// slow cadence, recompute each card's live work-item / PR / git state, and when
// the observable fingerprint changes (or there's no summary yet) regenerate the
// AI briefing. Throttled per-card so it never thrashes, and opt-out per card via
// d.autoSummary === false. Runs regardless of whether any client is connected.
const DEV_SUMMARY_SCAN_MS = 2 * 60 * 1000;       // how often we sweep all cards
const DEV_SUMMARY_MIN_INTERVAL_MS = 90 * 1000;   // min gap between regenerations of one card
const _devSummaryRunning = new Set();            // boardId/devId currently generating
let _devSummaryScanBusy = false;

async function _reconcileDevSummaries() {
  if (_devSummaryScanBusy) return;
  _devSummaryScanBusy = true;
  try {
    // Dev cards live in the global store now (not per-board). Skip cards whose home
    // board is archived; board-less cards are always eligible.
    let archivedBoards = new Set();
    try { archivedBoards = new Set(loadBoards().filter(b => b && b.archived).map(b => b.id)); } catch {}
    {
      const cards = devStore.all();
      for (const d of cards) {
        if (!d || d.autoSummary === false) continue;
        if (d.homeBoardId && archivedBoards.has(d.homeBoardId)) continue;
        const b = { id: d.homeBoardId || DEV_NS };
        // Nothing to summarize if there's no linked work item, PR, or worktree.
        if (!d.worktreePath && !d.workItemId && !d.prId) continue;
        const key = b.id + '/' + d.id;
        if (_devSummaryRunning.has(key)) continue;
        try {
          // Recompute live state across ALL repos (local git is cheap; WI/PR are
          // best-effort network). fetch:false so the reconciler never hammers origin.
          const meta = await _devRepoMeta(d, { fresh: false });

          // Surface any status reports the dev agent wrote into the worktree(s).
          // Cheap fs scan across every repo slot; persist immediately (no LLM) when
          // the set/mtimes change so the card's Artifacts row stays current.
          if (_devRepoSlots(d).some(s => s.worktreePath)) {
            try {
              const reports = _rescanDevReports(b.id, d.id, d);
              const sig = (arr) => (Array.isArray(arr) ? arr : []).map(r => (r.cacheRel || r.rel) + ':' + Math.round(r.mtime)).join('|');
              if (sig(reports) !== sig(d.reports)) {
                const cR = _devItemCtx(b.id, d.id);
                if (cR) cR.save({ reports });
              }
            } catch {}
          }

          const fp = _devFingerprint({ wi: meta.wi, wiComments: meta.wiComments, repos: meta.repos });
          const prevFp = (d.summary && d.summary.fingerprint) || '';
          const haveSummary = !!(d.summary && d.summary.text);
          const lastGen = (d.summary && d.summary.generatedAt) ? Date.parse(d.summary.generatedAt) : 0;
          const changed = fp !== prevFp;
          const throttleOk = (Date.now() - lastGen) > DEV_SUMMARY_MIN_INTERVAL_MS;

          if ((!haveSummary || changed) && throttleOk) {
            _devSummaryRunning.add(key);
            try {
              const gen = await _generateDevSummary(d, { meta });
              const c2 = _devItemCtx(b.id, d.id); // re-locate: board may have been re-saved meanwhile
              if (c2) c2.save({ summary: { text: gen.text, generatedAt: gen.generatedAt, fingerprint: fp, auto: true }, ..._devLivePartial(d, meta) });
            } finally { _devSummaryRunning.delete(key); }
          } else if (changed) {
            // State moved but we're inside the throttle window (or summary is fresh):
            // persist the live state now so the card's badges are current; the next
            // sweep will regenerate the prose once the throttle clears.
            const c2 = _devItemCtx(b.id, d.id);
            if (c2) c2.save(_devLivePartial(d, meta));
          }
        } catch {}
      }
    }
  } finally {
    _devSummaryScanBusy = false;
  }
}
setInterval(() => { _reconcileDevSummaries().catch(() => {}); }, DEV_SUMMARY_SCAN_MS);
// Kick a first sweep shortly after boot so freshly-loaded cards get summaries.
setTimeout(() => { _reconcileDevSummaries().catch(() => {}); }, 20 * 1000);

// Remove a dev card's worktree (best-effort) without deleting the item record.
app.post('/api/boards/:id/dev-items/:devId/remove-worktree', async (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const d = ctx.dev;
  const slot = _findRepoSlot(d, req.body && req.body.repoId ? req.body.repoId : 'primary');
  if (!slot) return res.status(404).json({ error: 'Repo not found' });
  try { devitems.removeWorktree(slot.org, slot.project, slot.repo, d.id, slot.worktreePath, slot.provider); } catch {}
  // Clear this slot's worktree fields (primary lives at top-level; extras in d.repos[]).
  if (slot.primary) ctx.save({ worktreePath: '', worktreeStatus: null, git: null });
  else _saveRepoSlot(ctx, slot.id, { worktreePath: '', worktreeStatus: null, worktreeError: null, git: null });
  // Re-aggregate reports across all slots: the removed repo's reports fall back to
  // their durable cache (findable via listCachedReportsForSlots), and every other
  // repo's live/cached reports are preserved — so nothing is lost on cleanup.
  const fresh = _devItemCtx(req.params.id, req.params.devId) || ctx;
  let updated = fresh.dev;
  try { updated = fresh.save({ reports: _rescanDevReports(req.params.id, req.params.devId, fresh.dev) }); } catch {}
  res.json({ ok: true, dev: updated });
});

// Track ANOTHER repo for this work. Dev cards are strictly ONE repo per card, so
// this no longer appends to d.repos[] — it creates a NEW sibling single-repo dev
// card carrying the same work item / title / team / home board, and mirrors the
// source card's board-map pins so the new card lands on the same board(s).
app.post('/api/boards/:id/dev-items/:devId/repos', async (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const d = ctx.dev;
  const b = req.body || {};
  const provider = (b.provider === 'github') ? 'github' : 'azdo';
  const org = String(b.org || '').trim();
  const project = String(b.project || '').trim();
  const repo = String(b.repo || '').trim();
  // Project is required only for Azure DevOps; GitHub is (owner, repo) scoped.
  if (!org || !repo || (provider !== 'github' && !project)) {
    return res.status(400).json({ error: provider === 'github' ? 'org and repo are required' : 'org, project and repo are required' });
  }
  const baseBranch = String(b.baseBranch || 'main').trim() || 'main';
  const branch = String(b.branch || '').trim();
  // Dedupe: don't create a sibling for a repo this card (or a card sharing its work
  // item) already tracks.
  const key = (x) => [x.org, x.project, x.repo].map(v => String(v || '').toLowerCase()).join('/');
  const wanted = key({ org, project, repo });
  if (key(d) === wanted) {
    return res.status(409).json({ error: 'This card already tracks that repo' });
  }
  const created = devStore.create({
    title: d.title || repo,
    provider, org, project, repo,
    baseBranch, branch,
    workItemId: d.workItemId || '', workItem: d.workItem || null,
    teamId: d.teamId !== undefined ? d.teamId : null,
    homeBoardId: d.homeBoardId || req.params.id || null,
    notes: '', links: [], reports: [], summary: null,
  });
  if (created && !created.branch) { try { devStore.patch(created.id, { branch: `dev/${created.id}` }); } catch {} }
  // Mirror the source card's board-map pins so the new card shows where the old one does.
  try {
    const boards = loadBoards();
    let touched = false;
    for (const bd of boards) {
      if (!bd || !Array.isArray(bd.items)) continue;
      const pinned = bd.items.some(x => x && x.kind === 'dev' && x.refId === d.id);
      const already = bd.items.some(x => x && x.kind === 'dev' && x.refId === created.id);
      if (pinned && !already) {
        bd.items.unshift({ id: _genId('pin'), kind: 'dev', refId: created.id, label: created.title, sublabel: '', addedAt: new Date().toISOString() });
        bd.updatedAt = new Date().toISOString();
        touched = true;
      }
    }
    if (touched) { saveBoards(boards); try { broadcastSSE('boards-changed', {}); } catch {} }
  } catch {}
  const out = devStore.find(created.id) || created;
  res.json({ ok: true, dev: out, created: true, repoId: out.id });
});

// Remove an EXTRA repo from a dev card (and clean up its worktree). The primary
// repo cannot be removed this way — use the card itself for that.
app.post('/api/boards/:id/dev-items/:devId/repos/remove', async (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const d = ctx.dev;
  const slot = _findRepoSlot(d, (req.body && (req.body.repoId || req.body)) || null);
  if (!slot || slot.primary) return res.status(400).json({ error: 'Specify an extra repo to remove' });
  try { devitems.removeWorktree(slot.org, slot.project, slot.repo, d.id, slot.worktreePath, slot.provider); } catch {}
  const repos = _devExtraRepos(d).filter(r => r && r.id !== slot.id);
  ctx.save({ repos });
  // The slot is gone entirely, so its reports should drop out of the aggregate.
  const fresh = _devItemCtx(req.params.id, req.params.devId) || ctx;
  let updated = fresh.dev;
  try { updated = fresh.save({ reports: _rescanDevReports(req.params.id, req.params.devId, fresh.dev) }); } catch {}
  res.json({ ok: true, dev: updated });
});

// Open all of a dev card's ready worktrees together as one VS Code multi-root
// workspace (or a Copilot CLI session at the shared parent). The .code-workspace
// file is written into the dev-worktrees ROOT so deleting any single worktree
// never loses it.
app.post('/api/boards/:id/dev-items/:devId/workspace', async (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const d = ctx.dev;
  const target = (req.body && req.body.target) || 'editor';
  const ready = _devRepoSlots(d).filter(s => s.worktreePath && fs.existsSync(s.worktreePath));
  if (!ready.length) return res.status(400).json({ error: 'No ready worktrees to open' });
  try {
    const result = await devitems.openWorkspace({
      devId: d.id,
      title: d.title || d.name || d.id,
      slots: ready.map(s => ({ repo: s.repo, worktreePath: s.worktreePath })),
      target,
      agent: d.devAgentName || null
    });
    res.json({ ok: true, ...result });
  } catch (e) {
    res.status(500).json({ error: String(e && e.message || e) });
  }
});

// Re-scan a dev card's worktrees for status reports (manual trigger). Scans every
// repo slot and merges in cached reports from any slot whose worktree is gone.
app.post('/api/boards/:id/dev-items/:devId/reports/scan', (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const reports = _rescanDevReports(req.params.id, req.params.devId, ctx.dev);
  const updated = ctx.save({ reports });
  res.json({ ok: true, dev: updated });
});

// Serve a single status report file for a dev card. Reads from the worktree when
// present, and transparently falls back to the durable cache (so a report still
// opens/previews after the worktree is deleted). Path-traversal guarded,
// extension-allowlisted. Drives both the open-in-tab link and the preview iframe.
app.get('/api/boards/:id/dev-items/:devId/report', (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).send('Dev card not found');
  const d = ctx.dev;
  const file = req.query.file;
  try {
    let r;
    // Prefer the durable cache: non-primary repos' reports are cached under a
    // repo-namespaced key (repoId/rel) and are NOT under the primary worktree,
    // and cached copies survive worktree removal. Fall back to a live read of the
    // primary worktree for any report not yet cached.
    try { r = devitems.readReportCached(req.params.id, req.params.devId, file); }
    catch (e1) { r = devitems.readReport(d.worktreePath, file); }
    res.setHeader('Content-Type', r.contentType);
    res.setHeader('Cache-Control', 'no-store');
    res.send(r.content);
  } catch (e) {
    res.status(e && e.status ? e.status : 404).send((e && e.message) || 'Failed to read report');
  }
});

// Attach a manual link to a dev card. If the link points at a local file (a
// file:// URL or an absolute path) that we can read, snapshot it into the durable
// cache so it survives worktree deletion and can be served/previewed in-app.
app.post('/api/boards/:id/dev-items/:devId/links', (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const url = String((req.body && req.body.url) || '').trim();
  let label = String((req.body && req.body.label) || '').trim();
  if (!url) return res.status(400).json({ error: 'A URL is required.' });
  const isAbsPath = /^([A-Za-z]:[\\/]|\\\\|\/)/.test(url);
  if (!/^(https?:|file:|mailto:|vscode:)/i.test(url) && !isAbsPath) {
    return res.status(400).json({ error: 'URL must start with http(s):, file:, mailto:, vscode: or be an absolute file path' });
  }
  if (!label) { try { label = decodeURIComponent(url.split(/[\\/]/).pop() || url); } catch { label = url; } }
  // Resolve a local file path when possible, then cache it.
  let absPath = null;
  if (/^file:/i.test(url)) { try { absPath = require('url').fileURLToPath(url); } catch {} }
  else if (isAbsPath) { absPath = url; }
  let cacheRel = null;
  if (absPath) { try { cacheRel = devitems.cacheLinkFile(req.params.id, req.params.devId, absPath); } catch {} }
  const links = Array.isArray(ctx.dev.links) ? ctx.dev.links.slice() : [];
  const entry = { id: 'lnk-' + Math.random().toString(36).slice(2, 9), label, url, addedAt: new Date().toISOString() };
  if (cacheRel) entry.cacheRel = cacheRel;
  links.push(entry);
  const updated = ctx.save({ links });
  res.json({ ok: true, dev: updated });
});

// Remove a manual link from a dev card (by id or url).
app.post('/api/boards/:id/dev-items/:devId/links/delete', (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const id = (req.body && req.body.id) || '';
  const url = (req.body && req.body.url) || '';
  const links = (Array.isArray(ctx.dev.links) ? ctx.dev.links : []).filter(l => !(id && l.id === id) && !(url && l.url === url));
  const updated = ctx.save({ links });
  res.json({ ok: true, dev: updated });
});

// ---- Dev-card notes ------------------------------------------------------
// Freeform notes let you jot down where you're at / what matters on a dev card.
// Each note: { id, text, done, createdAt, updatedAt }. Stored on d.notes[].
app.post('/api/boards/:id/dev-items/:devId/notes', (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const text = String((req.body && req.body.text) || '').trim();
  if (!text) return res.status(400).json({ error: 'Note text is required.' });
  // Optional per-repo scoping: a note tagged with a slot id belongs to that repo
  // section; an untagged note is a general (card-level) note.
  const slot = (req.body && typeof req.body.slot === 'string' && req.body.slot.trim()) ? req.body.slot.trim() : null;
  const notes = Array.isArray(ctx.dev.notes) ? ctx.dev.notes.slice() : [];
  const now = new Date().toISOString();
  const note = { id: 'note-' + Math.random().toString(36).slice(2, 9), text, done: false, createdAt: now, updatedAt: now };
  if (slot) note.slot = slot;
  notes.push(note);
  const updated = ctx.save({ notes });
  res.json({ ok: true, dev: updated });
});

// Update one note: edit its text and/or toggle its done state. Body: { id, text?, done? }.
app.post('/api/boards/:id/dev-items/:devId/notes/update', (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const id = String((req.body && req.body.id) || '');
  if (!id) return res.status(400).json({ error: 'A note id is required.' });
  const notes = (Array.isArray(ctx.dev.notes) ? ctx.dev.notes : []).slice();
  const i = notes.findIndex(n => n && n.id === id);
  if (i < 0) return res.status(404).json({ error: 'Note not found' });
  const patch = { updatedAt: new Date().toISOString() };
  if (req.body && typeof req.body.text === 'string') {
    const t = req.body.text.trim();
    if (!t) return res.status(400).json({ error: 'Note text cannot be empty.' });
    patch.text = t;
  }
  if (req.body && typeof req.body.done === 'boolean') patch.done = req.body.done;
  notes[i] = { ...notes[i], ...patch };
  const updated = ctx.save({ notes });
  res.json({ ok: true, dev: updated });
});

// Delete one note by id. Body: { id }.
app.post('/api/boards/:id/dev-items/:devId/notes/delete', (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const id = String((req.body && req.body.id) || '');
  const notes = (Array.isArray(ctx.dev.notes) ? ctx.dev.notes : []).filter(n => n && n.id !== id);
  const updated = ctx.save({ notes });
  res.json({ ok: true, dev: updated });
});

// Archive (or restore) a dev card. Archiving keeps the card and ALL of its
// durable state (summary, cached reports, links, repo history) intact for audit;
// it just sets an `archived` flag so the card drops out of its board's grid and
// the Home "active dev work" surface and moves to the dedicated Archive page.
// Body: { archived: true|false }. Restoring clears the flag so the card returns
// to its original board exactly where it left off.
app.post('/api/boards/:id/dev-items/:devId/archive', (req, res) => {
  const ctx = _devItemCtx(req.params.id, req.params.devId);
  if (!ctx) return res.status(404).json({ error: 'Dev card not found' });
  const archived = !(req.body && req.body.archived === false);
  const updated = ctx.save(archived
    ? { archived: true, archivedAt: new Date().toISOString() }
    : { archived: false, archivedAt: null });
  res.json({ ok: true, dev: updated });
});

